using ui64 = uint64_t;

const int MAX_N = 300;
ui64 A[MAX_N][MAX_N];
ui64 d[MAX_N][MAX_N];
int N;

void floyd() {
    for (int k = 0; k < N; ++k) {
        for (int i = 0; i < N; ++i) {
            for (int j = 0; j < N; ++j) {
                d[i][j] = min(d[i][j], d[i][k] + d[k][j]);
            }
        }
    }
}

