const int maxn = 333;
long long f[maxn][maxn], g[maxn][maxn];
int u[maxn];
int find(int x){
  if(x == u[x]) return x;
  return u[x] = find(u[x]);
}
int main(){
  iota(u, u + maxn, 0);
  int n; cin >> n;
  for(int i = 0; i < n; i++) for(int j = 0; j < n; j++) {
    cin >> f[i][j]; g[i][j] = f[i][j];
  }
  for(int k = 0; k < n; k++) for(int i = 0; i < n; i++) for(int j = 0; j < n; j++)
    g[i][j] = min(g[i][j], g[i][k] + g[k][j]);
  bool good = true;
  for(int i = 0; i < n; i++) for(int j = 0; j < n; j++) good &= f[i][j] == g[i][j];
  if(!good) cout << -1 << endl;
  else {
    vector<tuple<long long, int, int> > ed;
    for(int i = 0; i < n; i++) for(int j = 0; j < n; j++) ed.push_back(make_tuple(f[i][j], i, j));
    sort(ed.begin(), ed.end());
    long long ans = 0;
    for(auto e : ed){
      long long w; int u,v; tie(w, u, v) = e;
      if(find(u) ^ find(v)){
      	::u[find(u)] = find(v);
        ans += w;
      }
    }
    cout << ans << endl;
  }
  return 0;
}

