int	main()
{
	int64_t	A[300][300] = {};
	int	N;
	cin >> N;
	for (int i = 0; i < N; ++i) {
		for (int j = 0; j < N; ++j)
			cin >> A[i][j];
	}
	int64_t	removable[300][300] = {};
	int64_t	tmp_cost;
	bool	feasible = true;
	for (int i = 0; i < N; ++i) {
		for (int j = 0; j < N; ++j) {
			for (int k = 0; k < N; ++k) {
				if (k == i || k == j) continue;
				tmp_cost = A[i][k] + A[k][j];
				if (A[i][j] > tmp_cost) {
					feasible = false;
					break;
				}
				if (A[i][j] == tmp_cost)
					removable[i][j] = true;
			}
		}
	}
	if (!feasible) {
		cout << -1 << endl;
		return 0;
	}
	int64_t	sum_cost = 0;
	for (int i = 0; i < N; ++i) {
		for (int j = 0; j < N; ++j) {
			if (!removable[i][j])
				sum_cost += A[i][j];
		}
	}
	sum_cost /= 2;
	cout << sum_cost << endl;
}

#include<bits/stdc++.h>
using namespace std;

vector< vector<int> > warshallFloyd(vector< vector<int> > dist) {
  int n = dist.size();
  for(int k=0;k<n;k++) {
    for(int i=0;i<n;i++) {
      for(int j=0;j<n;j++) {
        dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j]);
      }
    }
  }

  return dist;
}

int main() {
  long long n;
  cin >> n;

  vector< vector<int> > a(n, vector<int>(n));
  for(int i=0;i<n;i++) {
    for(int j=0;j<n;j++) {
      cin >> a[i][j];
    }
  }

  auto dist = warshallFloyd(a);
  for(int i=0;i<n;i++) {
    for(int j=0;j<n;j++) {
      if(a[i][j] != dist[i][j]) {
        cout << -1 << endl;
        return 0;
      }
    }
  }

  long long ans = 0;
  for(int i=0;i<n;i++) {
