    Matrix ori(n, Array(n));

    queue<T> q;

    repeat(i, n) {
        repeat(j, n) {
            cin >> ori[i][j];
            if (i >= j) continue;
            add_edge(g, i, j, ori[i][j]);
            q.emplace(T{i, j, ori[i][j]});
        }
    }
    Matrix dis = warshall_floyd(g);

    lint ans = 0;
    repeat(i, n) {
        repeat(j, n) {
            if (dis[i][j] < ori[i][j]) {
                cout << -1;
                return 0;
            }
            if (i < j) ans += dis[i][j];
        }
    }

    while (!q.empty()) {
        int i, j;
        lint c;
        tie(i, j, c) = q.front();
        q.pop();

        repeat(k, n) {
            if (k == i or k == j) continue;
            if (dis[i][k] + dis[k][j] == dis[i][j]) {
                ans -= dis[i][j];
                break;
            }
        }
    }
    cout << ans << endl;

}

