		for (int j = 0; j < N; ++j) {
			cin >> A[i][j];
		}
	}

	udvgraph_m graph(N);
	for (int i = 0; i < N; ++i) {
		for (int j = i; j < N; ++j) {
			graph.addEgde(i, j, (ull)A[i][j]);
		}
	}

