ll dijkstra(ll from, ll to, ll n){
    rep(i,n)rep(j,n)mat_dij[i][j]=1LL<<60;
    rep(i,n)mat_dij[i][i]=0;
    priority_queue<ll> pq;
    pq.push(from);
    do{
