void solve(long long N, std::vector<std::vector<long long>> A){
    // ワーシャルフロイド
    auto WF = A;
    for(int k=0; k < N; k++){
        for(int i=0; i < N; i++){
            for(int j=0; j < N; j++){
                WF[i][j] = min(WF[i][j], WF[i][k] + WF[k][j]);
            }
        }
    }

    // A=WF?
    vector<Edge> edges;
    for(int i=0; i < N; i++){
        for(int j=0; j < N; j++){
            if(i < j){
                edges.push_back(Edge{i, j, A[i][j]});
            }

            if(A[i][j] != WF[i][j]){
                cout << -1 << endl;
                return;
            }
        }
    }

    sort(edges.begin(), edges.end(), [](Edge a, Edge b){return a.dist > b.dist;});  // aがbより先頭にくるときtrueになるように。これだと大きいほうが先頭。


    ll total = 0;
    ll removed = 0;
    vec2<bool> removeds(N, vec<bool>(N, false));
    for(auto e: edges){
        total += e.dist;
        for(int k=0; k < N; k++){
            if(k == e.from || k == e.to){
                continue;
            }
            if(!removeds[e.from][k] && !removeds[k][e.to] && A[e.from][e.to] >= A[e.from][k] + A[k][e.to]){
                removed += e.dist;
                removeds[e.from][e.to] = true;
                removeds[e.to][e.from] = true;
            }
        }
    }
    // A=WF.  最短路がある。
    // ll total = 0;
    // ll removed = 0;
    // for(int i=0; i < N; i++){
    //     for(int j=i+1; j < N; j++){
    //         total += A[i][j];
    //         // kであってi-k-jがi-jと等しいようなものがあるならi-jはいらない
    //         for(int k=0; k < N; k++){
