void warshall_floyd(vector<vector<long long>>& d, long long V){
    for(int k = 0; k < V; k++)
        for(int i = 0; i < V; i++)
            for(int j = 0; j < V; j++)
                d[i][j] = min(d[i][j], d[i][k] + d[k][j]);
}

void warshall_floyd2(vector<vector<long long>>& d, vector<vector<long long>>& output_d,  long long V){
    for(int k = 0; k < V; k++)
        for(int i = 0; i < V; i++)
            for(int j = 0; j < V; j++)
                if(d[i][j] == d[i][k] + d[k][j] && i != k && j != k)
                    //d[i][j] = min(d[i][j], d[i][k] + d[k][j]);
                    output_d[i][j] = 0;
}

