int main()
{
	std::ios::sync_with_stdio(false);

	int N;
	cin >> N;

	vector<vector<ull>> A;
	resize(A, N, N);
	for (int i = 0; i < N; ++i) {
		for (int j = 0; j < N; ++j) {
			cin >> A[i][j];
		}
	}

	udvgraph_m graph(N);
	for (int i = 0; i < N; ++i) {
		for (int j = i; j < N; ++j) {
			graph.addEgde(i, j, A[i][j]);
		}
	}

	graph.warshallFloyd();
	vector<vector<ull>> distMapOrigin = graph.getMinimumDistMap();

	// 非存在チェック
	for (int i = 0; i < N; ++i) {
		for (int j = i + 1; j < N; ++j) {
			if (distMapOrigin[i][j] < A[i][j]) {
				cout << -1 << endl;
				return 0;
			}
		}
	}

	// 消しても距離が変わらない道の距離総和を計算する
	ull removeSum = 0ull;
	for (int i = 0; i < N; ++i) {
		for (int j = i + 1; j < N; ++j) {
			for (int k = 0; k < N; ++k) {
				if (k == i || k == j) {
					continue;
				}
				if (A[i][j] == A[i][k] + A[k][j]) {
					removeSum += A[i][j];
				}
			}
		}
	}

	//距離の総和を計算
	ull sum = 0ull;
	for (auto a : graph.getNodes()) {
		for (auto b : a.getEgde()) {
			ull cost = b.first.getCost();
			sum += cost;
		}
	}
	sum /= 2ull; // 往復分が入っているので２で割る

	ull result = sum - removeSum;

	cout << result << endl;
	getchar();
	getchar();

}

