template< typename T >
vector< T > dijkstra(WeightedGraph< T > &g, int s) {
  const auto INF = numeric_limits< T >::max();
  vector< T > dist(g.size(), INF);

  using Pi = pair< T, int >;
  priority_queue< Pi, vector< Pi >, greater< Pi > > que;
  dist[s] = 0;
  que.emplace(dist[s], s);
  while(!que.empty()) {
    T cost;
    int idx;
    tie(cost, idx) = que.top();
    que.pop();
    if(dist[idx] < cost) continue;
    for(auto &e : g[idx]) {
      auto next_cost = cost + e.cost;
      if(dist[e.to] <= next_cost) continue;
      dist[e.to] = next_cost;
      que.emplace(dist[e.to], e.to);
    }
  }
  return dist;
}

ll A[400][400];


ll check(ll from, ll to, WeightedGraph<ll> & G){

  priority_queue<pint> pq;
  pq.push(mp(0, from));

  ll dist_min;

  while(!pq.empty()){
    ll d, i;
    tie(d,i) = pq.top(); pq.pop();
    d *= -1;
    if(i == to){
      dist_min = d;
      break;
    }

    for(auto e:G[i]){
      if(i==from && e.to==to) continue;
      pq.push(mp(-(d+e.cost), e.to));
    }
  }

  if(dist_min == A[from][to]){
    return A[from][to];
  }else if(dist_min < A[from][to]){
    return -1;
  }else{
    return 0;
  }
}

