// nCk modを求める
const ll MAX = 510000;
//この値は求める二項計数の値に応じて変える
// MAX=3*10^7のとき1900msほど、ほぼ比例
// MAX= 5* 10^6 程度ならそれほど気にしなくてよい(300ms程)
long long fac[MAX], finv[MAX], inv[MAX];
// テーブルを作る前処理
void cominit() {
	fac[0] = fac[1] = 1;
	finv[0] = finv[1] = 1;
	inv[1] = 1;
	for(ll i = 2; i < MAX; i++) {
		fac[i] = fac[i - 1] * i % mod;
		inv[i] = mod - inv[mod % i] * (mod / i) % mod;
		finv[i] = finv[i - 1] * inv[i] % mod;
	}
}
// 二項係数計算
long long commod(ll n, ll k) {
	if(n < k) return 0;
	if(n < 0 || k < 0) return 0;
	return fac[n] * (finv[k] * finv[n - k] % mod) % mod;
}
//順列計算
long long pmod(ll n, ll k) {
	if(n < k) return 0;
	if(n < 0 || k < 0) return 0;
	return fac[n] * finv[n - k] % mod;
}

/* next combination */
//次の組み合わせをbitで返す
//全探索のloopに使える
long long next_combination(long long sub) {
	long long x = sub & -sub, y = sub + x;
	return (((sub & ~y) / x) >> 1) | y;
}

// 20200617
void warshall(vector<vector<long long>> &v) {
	ll n = v.size();
	rep(i, n) {
		rep(j, n) {
			rep(k, n) {
				// cout << i << " " << j << " " << k << "\n";
				// cout << v[j][k] << " " << v[j][i] << " " << v[i][k] << "\n\n";
				v[j][k] = min(v[j][k], v[j][i] + v[i][k]);
			}
		}
	}
	return;
}

// 20200626
vvll comb(100, vll(100, -1));
long long com(long long n, long long k) {
	if(n < 0 || k < 0) return -1;
	if(n < k) return comb[n][k] = 0;
	if(comb[n][k] != -1) return comb[n][k];
	ll res;
	if(n - k < k)
		res = com(n, n - k);
	else if(k == 0)
		res = 1;
	else
		res = com(n - 1, k - 1) + com(n - 1, k);
	comb[n][k] = res;
	return res;
}

long long com2(long long n, long long k) {
	if(n < 0 || k < 0) return -1;
	if(n < k) return comb[n][k] = 0;
	ll res;
	if(n - k < k)
		res = com(n, n - k);
	else if(k == 0)
		res = 1;
	else
		res = com(n - 1, k - 1) + com(n - 1, k);
	return res;
}
void comset() { rep(i, 100) rep(j, 100) com(i, j); }

// 20200709
string bits(long long n, long long k) {
	// nをk桁のbitで表示したstringを返す
	string s = "";
	rep(i, k) {
		char c = '0' + (n % 2);
		s += c;
		n /= 2;
	}
	reverse(all(s));
	return s;
}
