int main() {
	int N;
	cin >> N;
	ll d[302][302] = {};
	ll d2[302][302] = {};

	FORq(i,1,N){
		FORq(j,1,N){
			cin >> d[i][j];
			d2[i][j] = d[i][j];
		}
	}

	FORq(i,1,N){
		FORq(j,1,N){
			FORq(k,1,N){
				d2[j][k] = min(d2[j][k],d2[j][i]+d2[i][k]);
			}
		}
	}

	FORq(i,1,N){
		FORq(j,1,N){
			if (d[i][j] != d2[i][j]){
				puts("-1");
				return 0;
			}
		}
	}

	ll ans = 0;

	FORq(i,1,N){
		FORq(j,1,N){
			bool useedge = true;
			FORq(k,1,N){
				if (k == i) continue;
				if (k == j) continue;

				if (d[i][j] >= d2[i][k]+d2[k][j]){
					useedge = false;
				}
			}

			if (useedge) ans += d[i][j];
		}
	}

	cout << ans/2 << "\n";
}

