using namespace std;

long long n;
long long memo[305][305] = {0};
bool ch[305][305] = {0};
vector<pair<long long, pair<int, int>>> v;

long long solve();

int main() {
  cin >> n;
  for(int i = 0; i < n; ++i)
    for(int j = 0; j < n; ++j) cin >> memo[i][j];
  for(int i = 0; i < n; ++i)
    for(int j = i + 1; j < n; ++j)
      v.push_back(make_pair(memo[i][j], make_pair(i, j)));
  sort(v.begin(), v.end());
  cout << solve() << endl;
  return 0;
}

long long solve() {
  long long ans = 0;
  for(int k = 0; k < n; ++k)
    for(int i = 0; i < n; ++i)
      for(int j = 0; j < n; ++j)
        if(memo[i][j] > memo[i][k] + memo[k][j]) return -1;
  for(int i = 0; i < v.size(); ++i)
    if(!ch[v[i].se.fi][v[i].se.se]) {
      ch[v[i].se.fi][v[i].se.se] = 1;
      pair<long long, pair<int, int>> now = v[i];
      ans += now.fi;
      for(int j = 0; j < n; ++j)
        if(now.se.fi != j && now.se.se != j) {
          long long dis = now.fi;
          if(dis + memo[j][now.se.fi] == memo[now.se.se][j])
            ch[min(j, now.se.se)][max(j, now.se.se)] = 1;
          if(dis + memo[j][now.se.se] == memo[now.se.fi][j])
            ch[min(j, now.se.fi)][max(j, now.se.fi)] = 1;
        }
    }
  return ans;
}

