const int ddx[8]={1,0,-1,-1,-1,0,1,1};
const int ddy[8]={1,1,1,0,-1,-1,-1,0};

void solve(){
  ll n;cin>>n;
  ll A[n][n];
  rep(i,n)rep(j,n)cin>>A[i][j];

  ll d[n][n];
  rep(i,n)rep(j,n)d[i][j]=INF;
  rep(i,n)d[i][i]=0;
  ll ans=0;
  set<pair<ll,ll>>set;
  rep(i,n){
    //最小
    ll num=INF;
    rep(j,n){
      if(i==j)continue;
      num=min(num,A[i][j]);
    }

    rep(j,n){
      if(num==A[i][j]){
        //辺を追加
        d[i][j]=A[i][j];
        d[j][i]=A[j][i];
        if(set.find(make_pair(i,j))==set.end())ans+=A[i][j];
        set.insert(make_pair(i,j));
        set.insert(make_pair(j,i));
      }
    }
  }


  //ワーシャルフロイド
  rep(k,n)rep(i,n)rep(j,n){
    d[i][j]=min(d[i][k]+d[k][j],d[i][j]);
  }

  /*rep(i,n){
    rep(j,n)cout<<d[i][j]<<" ";
    cout<<endl;
  }*/

  vector<pair<ll,pair<ll,ll>>>v;
  rep(i,n)rep(j,n){
    if(d[i][j]<A[i][j]){
      //アウト
      cout<<-1<<endl;
      return;
    }

    //小さいなら変を追加する?
    if(d[i][j]>A[i][j]){
      v.push_back(make_pair(A[i][j],make_pair(i,j)));
    }
  }

  sort(all(v));

  for(auto&&p:v){
    ll a=p.second.first;
    ll b=p.second.second;
    if(d[a][b]==A[a][b])continue;
    ans+=A[a][b];
    d[a][b]=A[a][b];
    d[b][a]=A[b][a];

    //わーシャルフロイド
    rep(i,n)rep(j,n){
    d[i][j]=min(d[i][a]+d[b][j]+d[a][b],d[i][j]);
    }
    rep(i,n)rep(j,n){
    d[i][j]=min(d[i][b]+d[a][j]+d[a][b],d[i][j]);
    }
    bool isOK=true;
    rep(i,n)rep(j,n){
      if(d[i][j]<A[i][j]){
        //アウト
        cout<<-1<<endl;
        return;
      }
      if(d[i][j]!=A[i][j])isOK=false;
    }
    if(isOK)break;
  }

  //ワーシャルフロイド
  rep(k,n)rep(i,n)rep(j,n){
    d[i][j]=min(d[i][k]+d[k][j],d[i][j]);
  }
  rep(i,n)rep(j,n){
    if(d[i][j]<A[i][j]){
      //アウト
      cout<<-1<<endl;
      return;
    }
  }

  cout<<ans<<endl;
}

