void solve(long long N, std::vector<std::vector<long long>> A){
    // ワーシャルフロイド
    auto WF = A;
    for(int k=0; k < N; k++){
        for(int i=0; i < N; i++){
            for(int j=0; j < N; j++){
                WF[i][j] = min(WF[i][j], WF[i][k] + WF[k][j]);
            }
        }
    }

    // A=WF?
    for(int i=0; i < N; i++){
        for(int j=0; j < N; j++){
            if(A[i][j] != WF[i][j]){
                cout << -1 << endl;
                return;
            }
        }
    }

    // A=WF.  最短路がある。
    ll total = 0;
    ll removed = 0;
    for(int i=0; i < N; i++){
        for(int j=i+1; j < N; j++){
            total += A[i][j];
            // kであってi-k-jがi-jと等しいようなものがあるならi-jはいらない
            for(int k=0; k < N; k++){
                if(k == i || k == j){
                    continue;
                }
                // if(A[i][j] == -1){
                //     // すでに除去されている
                //     continue;
                // }
                if(A[i][j] == A[i][k] + A[k][j]){
                    removed += A[i][j];
                    // A[i][j] = -1;  // removed mark
                    // A[j][i] = -1;
                }
            }
        }
    }

    cout << total - removed << endl;
}

