vl dijkstra(int V, int s) {
  priority_queue<P, vector<P>, greater<P>> que;
  vl d(V, INF);
  d[s] = 0;
  que.push(P(0, s));
  while (!que.empty()) {
    P p = que.top();
    que.pop();
    int v = p.se;
    if (d[v] < p.first) continue;
    rep(i, sz(G[v])) {
      edge e = G[v][i];
      if (d[e.to] > d[v] + e.cost) {
        d[e.to] = d[v] + e.cost;
        que.push(P(d[e.to], e.to));
      }
    }
  }
  return d;
}

