//配列が長さnのものとして0で初期化する
void init(int n) {
    for (int i = 0; i < n; i++) {
        par[i] = i;
        rk[i] = 0;
    }
}
//xの親の要素の番号を返す
int find(int x) {
    if (par[x] == x) {
        return x;
    } else {
        return par[x] = find(par[x]);
    }
}
//要素を併合する
//木の高さrankが低いほうを高いほうの親につなげる
void unite(int x, int y){
    x = find(x);
    y = find(y);
    if (x == y) return;

    if (rk[x] < rk[y]) {
        par[x] = y;
    } else {
        par[y] = x;
        if (rk[x] == rk[y]) rk[x]++;
    }
}
//要素が同じ集合に属しているかどうかを返す
bool same(int x, int y) {
    return find(x) == find(y);
}




