/*
グラフは連結になる
辺の短いほうから選択していく
最短のA[i][j]　をij間のA[i][j]の辺とする unite(i,j) d[i][j]=A[i][j]

uniteされてたら...
d[i][j] > A[i][j] ならij間に辺を追加 d[i][j] < A[i][j]ならだめ

uniteされてなかったら...
問答無用で追加

いずれも最短路を逐次更新

追加を終えたら、最後にワーシャルフロイドで点検
辺の和を出力

*/

int N;

void update(int u, int v) {
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            if (i == j) continue;
            chmin(d[i][j],d[i][u]+G[u][v]+d[v][j]);
            chmin(d[i][j],d[i][v]+G[v][u]+d[u][j]);
        }
    }
}



