struct warshall_floyd {
	static void solve(vector<vector<ll>>& d) {
		int n = d.size();
		rep(k, n) {
			rep(i, n) {
				rep(j, n) {
					d[i][j] = min(d[i][j], d[i][k] + d[k][j]);
				}
			}
		}
	}
};

int main() {
    int n;
    cin >> n;
    vector<vector<ll>> graph(n, vector<ll>(n, 0));
    rep(i, n) {
        rep(j, n) cin >> graph[i][j];
    }
	auto copy = graph;
	warshall_floyd::solve(copy);
	rep(i, n) {
		rep(j, n) {
			if (copy[i][j] != graph[i][j]) {
				cout << -1 << endl;
				return 0;
			}
		}
	}
	//i->jに至る経路に関して、i->k->jとなる代替経路があった場合
	//i->kとk->jはi->jより小さい
	//i->jを削ってもほかの経路に影響しない
	ll sum = 0;
	for (int i = 0; i < n; i++) {
		for (int j = i+1; j < n; j++) {
			ll dist = graph[i][j];
			ll dist2 = INF;
			for (int k = 0; k < n; k++) {
				if (k == i || k == j) continue;
				chmin(dist2, graph[i][k] + graph[k][j]);
			}
			if (dist2 > dist) {
				sum += dist;
			}
		}
	}
	cout << sum << endl;
    return 0;
}

