  for (int i = 0; i < N; i++) {
    for (int j = 0; j < N; j++) {
      cin >> A[i][j];
      if (i > j) {
        es[i].push_back(Edge{j, A[i][j]});
        es[j].push_back(Edge{i, A[i][j]});
        pq.emplace(A[i][j], i, j);
        ret += A[i][j];
      }
    }
  }
  vector<vector<int>> orgA = A;

  for (int k = 0; k < N; k++) {
    for (int i = 0; i < N; i++) {
      for (int j = 0; j < N; j++) {
