using memo = pair<ll, pii>; //min_ cost, from, to

struct edge {
    int to;
    ll cost;
};

int V;
vector<edge> G[301];
ll d[301];

void dijkstra(int s) {
    priority_queue<pii, vector<pii>, greater<pii> > que;
    fill(d, d+V, INF);
    d[s] = 0;
    que.push(pll(0, s)); //コスト、移動先の頂点

    while (!que.empty()) {
        pll p = que.top();
        que.pop();
        int v = p.second;
        if (d[v] < p.first) continue;

        for (int i=0; i<G[v].size(); ++i) {
            edge e = G[v][i];
            if (d[e.to] > d[v] + e.cost) {
                d[e.to] = d[v] + e.cost;
                que.push(pll(d[e.to], e.to));
            }
        }
    }
}

