        ll cost = m.first; int a = m.second.first, b = m.second.second;
        //cout << "a:" << a << " b:" << b << " cost:" << cost << ln;
        dijkstra(a);
        if(d[b] > cost || d[b] == INF){
            res += cost;
            G[a].push_back(edge{b, cost});
            G[b].push_back(edge{a, cost});
        }
        else if(d[b] < cost){
            res = -1;
            break;
        }
    }
    cout << res << ln;
}

