using PLP = pair<LL,PII>;

LL solve(int N,VVLL A){
  VVLL B(A);
  REP(k,N){
    REP(i,N)REP(j,N){
      if(chmin(B.at(i).at(j),B.at(i).at(k)+B.at(k).at(j))){
        return -1;
      }
    }
  }

  VVB used(N,VB(N,false));
  priority_queue<PLP,vector<PLP>,greater<PLP>> pq;

  REP(i,N)FOR(j,i+1,N){
    pq.emplace(A.at(i).at(j),MP(i,j));
  }

  LL res = 0;

  while(!pq.empty()){
    PLP now = pq.top(); pq.pop();
    int x=now.SE.FI ,y= now.SE.SE;
    if(used.at(x).at(y)) continue;
    used.at(x).at(y) = true;
    res += now.FI;

    REP(i,N){
      if(A.at(x).at(i) == now.FI + A.at(y).at(i)){
        used.at(x).at(i) = true;
        used.at(i).at(x) = true;
      }
      if(A.at(y).at(i) == now.FI + A.at(x).at(i)){
        used.at(y).at(i) = true;
        used.at(i).at(y) = true;
      }
    }
  }
  return res;

}


