struct edge{int to,cost;};
struct graph{
    int N;  
    vector< vector<edge> > G;
    VVi dist;
    graph(int n){
        init(n);
    }
    void init(int n){
        N = n;
        G.resize(N);
        dist.resize(N);
        REP(i,0,N) dist[i].resize(N);
        REP(i,0,N){
            REP(j,0,N){
                dist[i][j] = INF;
            }
        }
        REP(i,0,N){
            dist[i][i]=0;
        }
    }
    void add_edge(int s,int t,int cost=1){
        edge e;
        e.to = t, e.cost = cost;
        G[s].push_back(e);
    }
    void dijkstra(int s,int t){
        REP(i,0,N){
            dist[s][i]=INF;
        }
        dist[s][s]=0;
        priority_queue<Pii,vector<Pii>,greater<Pii>> q;
        q.push(mp(0,s));
        while(!q.empty()){
            int now,nowdist;
            tie(nowdist,now) = q.top();q.pop();
            if(dist[s][now]<nowdist) continue;
            if(now==t) return;
            for(auto e : G[now]){
                if(dist[s][e.to]>dist[s][now]+e.cost){
                    dist[s][e.to] = dist[s][now]+e.cost;
                    q.push(mp(dist[s][e.to],e.to));
                }
            }
        }
    }
};

