        return get<2>(a) > get<2>(b);
    };
    priority_queue<Tiii,vector<Tiii>,decltype(compare)> q{compare};
    REP(i,0,n){
        REP(j,i+1,n){
            q.push(mt(i,j,a[i][j]));
        }
    }

    graph G(n);

    int ans=0;
    while(!q.empty()){
        int from,to,cost;
        tie(from,to,cost)=q.top();
        q.pop();
        G.dijkstra(from,to);
//        cout<<from<<" "<<to<<" "<<cost<<endl;
