vll Dijkstra(vector<vector<pll>> &to, ll s){
	ll N = (ll)to.size();
	vll dist(N, INF);
	priority_queue<pll, vpll, greater<pll>> Q;
	Q.push(pll(0, s));
	dist[s] = 0;
	while (!Q.empty()){
		ll d; ll v; tie(d, v) = Q.top(); Q.pop();
		if (d > dist[v]) continue;
		EACH(e, to[v]){
			ll u; ll c;  tie(u, c) = e;
			if (chmin(dist[u], dist[v]+c)) Q.push(pll(dist[u], u));
		}
	}
	return move(dist);
}


