int node[301];

int root(int n) {
	if (node[n] == n) return n;
	else return node[n] = root(node[n]);
}

void unite(int n, int m) {
	if (n > m) swap(n, m);
	n = root(n);
	m = root(m);
	if (n == m) return;
	else node[m] = n;
}
