void solve()
{
	ll N;  cin >> N;
	vector<vector<ll>> A = cinvv<ll>(N, N);

	ll ans = 0;
	rep(i, 0, N-1)rep(j, 0, N-1){
		ll val =A[i][j];
		if (i==j){
			if (val != 0) bye(-1);
			continue;
		}

		bool isFar = true;
		rep(k, 0, N-1){
			if (k==i || k==j) continue;
			ll dd = A[i][k] + A[k][j];
			if (dd < val) bye(-1);
			if (dd == val) isFar = false;
		}
		if (isFar){
			ans += val;
		}
	}
	ans /= 2;
	cout << ans << '\n';
}


int main(){
	solve();
	return 0;
}

