int main() {
    ios::sync_with_stdio(false), cin.tie(0);
    int N;
    cin >> N;
    vector<vector<ll>> V(N, vector<ll>(N));
    vector<unordered_set<int> > G(N, unordered_set<int>());
    REP(i, N) {
        REP(j, N) {
            cin >> V[i][j];
        }
    }
    priority_queue<pair<ll, int>, vector<pair<ll, int>>, greater<pair<ll, int>>> PQ;
    REP(s, N) {
        vector<ll> dist(N, LLONG_MAX);
        VI parent(N);
        PQ.push({0, s});
        dist[s] = 0;
        while (!PQ.empty()) {
            auto top = PQ.top();
            PQ.pop();
            int v = top.second;
            if (top.first > dist[v]) continue;
            REP(i, N) {
                if (i == v) continue;
                ll d = top.first + V[v][i];
                if (d < dist[i]) {
                    PQ.push({d, i});
                    dist[i] = d;
                    parent[i] = v;
                } else if (d == dist[i]) {
                    parent[i] = v;
                }
            }
        }
        REP(i, N) {
            if (i == s) continue;
            if (dist[i] != V[s][i]) {
                cout << -1 << '\n';
                return 0;
            }
            G[parent[i]].insert(i);
            G[i].insert(parent[i]);
        }
    }
    ll ans = 0;
    for (int i = 0; i < N; i++) {
        for (int v : G[i]) {
            ans += V[v][i];
        }
    }
    cout << ans / 2  << '\n';
}

