#include <bits/stdc++.h>
using namespace std;

template<typename T> class Dijkstra {
public:
  struct edge {
    int to; T cost;
  };
  int V;
  vector<vector<edge>> G;
  vector<T> dist;
  using pti = pair<T,int>;
  Dijkstra(int n) : V(n), G(V), dist(V, numeric_limits<T>::max()) {}
  void add(int u, int v, T cost) {
    G.at(u).push_back((edge) {v, cost});
    G.at(v).push_back((edge) {u, cost});
  }
  void solve(int s) {
    priority_queue<pti, vector<pti>, greater<pti>> Q;
    dist.at(s) = 0;
    Q.push(pti(0, s));
    while (!Q.empty()) {
      pti p = Q.top();
      Q.pop();
      int v = p.second;
      if (dist.at(v) < p.first) continue;
      for (auto &w : G.at(v)) {
        if (dist.at(w.to) > dist.at(v) + w.cost) {
          dist.at(w.to) = dist.at(v) + w.cost;
          Q.push(pti(dist.at(w.to), w.to));
        }
      }
    }
  }
};

int main() {
  int N;
  cin >> N;
  vector<vector<int>> A(N, vector<int>(N));
  for (int i = 0; i < N; i++) {
    for (int j = 0; j < N; j++) {
      cin >> A.at(i).at(j);
    }
  }

  vector<vector<int>> C = A;
  for (int i = 0; i < N; i++) {
    for (int j = 0; j < N; j++) {
      for (int k = 0; k < N; k++) {
        C.at(j).at(k) = min(C.at(j).at(k), C.at(j).at(i) + C.at(i).at(k));
      }
    }
  }

  if (A != C) return cout << -1 << "\n", 0;

  vector<tuple<int, int, int>> V;
  for (int i = 0; i < N; i++) {
    for (int j = i + 1; j < N; j++) {
      V.push_back(make_tuple(A.at(i).at(j), i, j));
    }
  }
  sort(V.begin(), V.end());

  int ans = 0;
  Dijkstra<int> D(N);
  for (auto v : V) {
    Dijkstra<int> tmp = D;
    tmp.solve(get<1>(v));
    if (tmp.dist.at(get<2>(v)) > get<0>(v)) {
      D.add(get<1>(v), get<2>(v), get<0>(v));
      ans += get<0>(v);
    }
  }
  cout << ans << "\n";
}

