void solve(long long N, std::vector<std::vector<long long>> A){
    std::vector<std::vector<long long>> d(N, vector<long long>(N));
    std::vector<std::vector<long long>> updated(N, vector<long long>(N, 0));

    for(int i=0; i<N; i++)
        for(int j=0; j<N; j++)
            d[i][j]=A[i][j];

    for(int k=0; k<N; k++)
        for(auto i=0; i<N; i++)
            for(auto j=0; j<N; j++){
                if(i!=k && k!=j && d[i][k]+d[k][j] <= d[i][j])
                    updated[i][j]=1;
                d[i][j]=min(d[i][j], d[i][k]+d[k][j]);
            }


    for(int i=0; i<N; i++) {
        for (int j = 0; j < N; j++) {
            if (d[i][j] != A[i][j]) {
                cout << "-1" << endl;
                return;
            }
        }
    }

    LL ans = 0;
    for(int i=0; i<N; i++)
        for(int j=i+1; j<N; j++)
            if(updated[i][j]!=1)
                ans += d[i][j];

    cout << ans << endl;
}

