struct UnionFind{
    vector<int> parents;
    vector<int> ranks;
    int N;

    UnionFind(int N): N(N){
        parents = vector<int>(N,-1);
        ranks = vector<int>(N,0);
    }

    int find(int a){
        if(parents[a] == -1)return a;
        int root = find(parents[a]);
        parents[a] = root;
        return root;
    }

    bool connect(int a, int b){
        int root_a = find(a);
        int root_b = find(b);
        if(root_a==root_b)return false;
        if(ranks[a]>ranks[b]){
            parents[root_b] = root_a;
        }else if(ranks[a]<ranks[b]){
            parents[root_a] = root_b;
        }else{
            parents[root_a] = root_b;
            ranks[root_b]++;
        }
        return true;
    }
};
