    WarshallFloyd W(N);
    rep(i, N) rep(j, N) {
        cin >> A[i][j];
        sum += A[i][j];
        W.setDist(i, j, A[i][j]);
    }
    W.calc();
    rep(i, N) rep(j, N) {
        if (W.getDist(i, j) != A[i][j]) {
            return puts("-1") & 0;
        }
    }
    sum /= 2;
    rep(i, N) rep(j, N) rep(k, N) {
        if (i >= j) continue;
        if (i == k || j == k) continue;
        if (A[i][k] + A[k][j] <= A[i][j] and A[i][j] != INF) {
            sum -= A[i][j];
            A[i][j] = INF;
        }
    }
    cout << sum << rt;
}

