typedef vector<vector<int> > Matrix;

const int INF = 100000000;
Matrix d; // グラフの距離を格納した2次元配列（隣接行列）
          // d[u][v]は辺e=(u,v)のコスト（辺が存在しない場合はINF、ただしd[i][i]=0）

int warshall_floyd(int n) { // nは頂点数
  for (int i = 0; i < n; i++){      // 経由する頂点
    for (int j = 0; j < n; j++){    // 開始頂点
      for (int k = 0; k < n; k++){  // 終端
        if (d[j][k] != min(d[j][k], d[j][i] + d[i][k])){
          return -1;
        }
      }
    }
  }
  return 0;
}

int main() {
  int n, m;
  cin >> n;

  d = Matrix(n, vector<int>(n, INF));

  for (int i = 0; i < n; i++) {
    for (int j = 0; j < n; j++) {
      int cost;
      cin >> cost;
      d[i][j] = cost;
    }
  }

  int ans = warshall_floyd(n);

  int max = 0;
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < n; j++) {
      if (i != j && max < d[i][j])
      {
        max =  d[i][j];
      }
    }
  }

  if(ans == -1){
    cout<<-1;
  }
  else{
    cout<<max;
  }
  return 0;
}

