/*
the operators regarding bit

     x1: 0000 0001 0010 0101 0110 0111
     x2: xxxx 0001 0011 0100 0101 1000
x1 & x2: 0000 0001 0010 0100 0100 0000

      x: 1001 1010  1100 1011 1101  1111
x & - x: 0001 0010  0100 0001 0001  0001
    sum: 1010 1100 10000 1100 1100 10000

x << y is x * 2 ** y
x >> y is rep(i, y) x = x // 2 
*/

const ll MAX_N = 200005;
bool okay = false;
ll answer = 0;
ll n, a[305][305];
bool m[305][305];

bool exist(ll n){
    rep(k, n) rep(i, n) rep(j, n) {
        if (a[i][j] > a[i][k] + a[k][j]) return false;
        if (i != k && j != k && a[i][j] == a[i][k] + a[k][j]) m[i][j] = true;
    }
    return true;
}

void solve(){
    rep(i, n) rep(j, n) {in1(a[i][j]); answer += a[i][j];}
    if (!exist(n)) {prl(-1); return;}

    rep(i, n) rep(j, n) if (m[i][j]) answer -= a[i][j];
    prl(answer / 2);
}

int main(void){
    in1(n);
    solve();

    return 0;
}

#include<iostream>
#include<algorithm>
#include<cstdint>
using namespace std;

const int MAX = 300;
const int INF = 1073741823;
int main() {
	int N;
	static int A[MAX][MAX], load[MAX][MAX];
	cin >> N;
	for (int i = 0;i < N;i ++) {
		for (int j = 0;j < N;j ++) {
			cin >> A[i][j];
			load[i][j] = A[i][j];
		}
	}
	for (int i = 0;i < N;i ++) {
		for (int j = 0;j < N;j ++) {
			for (int k = 0;k < N;k ++) {
				load[i][j] = min(load[i][j], load[i][k] + load[k][j]); // ワーシャルフロイド法
			}
		}
	}
	int64_t dist = 0;
	bool add;
	for (int i = 0;i < N;i ++) {
		for (int j = 0;j < N;j ++) {
			if (i == j) continue;
			if (A[i][j] > load[i][j]) { // この時点でこんな経路が無いことが分かるよ
				cout << -1;
				return 0;
			}
			add = true;
			for (int k = 0;k < N;k ++) {
				if (i == k || j == k) continue;
				if (load[i][j] == load[i][k] + load[k][j]) add = false; // 要らない辺
			}
			if (add) dist += load[i][j];
		}
	}
	cout << dist / 2; // 同じ辺を行き帰りで2回数えているので
	return 0;
}
