int main(){
    ll n;
    cin >> n;
    VVL a(n+1, VL(n+1));
    map<ll, VP> mp;
    rep(i, 0, n){
        rep(j, 0, n){
            cin >> a[i][j];
            if(i >= j) continue;
            mp[a[i][j]].push_back({i,j});
        }
    }

    VVL G(n+1);
    VVL l(n+1, VL(n+1, 1e15));
    rep(i, 0, n-1){
        rep(j, i+1, n){
            G[i].push_back(j);
            G[j].push_back(i);
        }
    }

    ll ans = 0;
    for(auto p : mp){
        for(auto v : p.second){
            ll srt = v.first;   
            VL d(n+1, 1e12);
            /* dijkstra's scope */{
                priority_queue<pair<ll,ll>, vector<pair<ll,ll>>, greater<pair<ll,ll>>> que;
                que.push({0, srt});
                d[srt] = 0;
                while(!que.empty()){
                    auto q = que.top();
                    que.pop();
                    if(q.first > d[q.second]) continue;
                    for(auto g : G[q.second]){
                        if(d[g] <= q.first + l[g][q.second]) continue;
                        d[g] = q.first + l[g][q.second];
                        que.push({d[g], g});
                    }
                }
            }
            if(d[v.second] == a[v.first][v.second]) continue;
            if(d[v.second] > a[v.first][v.second]){
                l[v.first][v.second] = a[v.first][v.second];
                l[v.second][v.first] = a[v.first][v.second];
                ans += a[v.first][v.second];
            }
            if(d[v.second] < a[v.first][v.second]){
                cout << -1 << endl;
                return 0;
            }
        }
    }

    cout << ans << endl;
    return 0;
}

