short Warshall_Floyd(long V){
	// 頂点は 0 ~ V 
	REP(i,V+1) dist[i][i] = 0;	//初期化
	FOR(i,0,V){
		FOR(j,0,V){
			FOR(k,0,V){
				if (dist[j][i] == loINF || dist[i][k] == loINF) continue;
				if (dist[j][k] > dist[j][i] + dist[i][k]){
					dist[j][k] = dist[j][i] + dist[i][k];
					#ifdef TRACE_ROUTE
						nex[j][k] = nex[j][i];
					#endif
				}
				#ifdef TRACE_ROUTE
				else {
					if (j != i && dist[j][k] == dist[j][i] + dist[i][k])
						nex[j][k] = min({nex[j][i],nex[j][k]});
				}
				#endif
				if (dist[j][j] < 0) return (-1);
			}
		}
	}
	return 0;
}

#ifdef TRACE_ROUTE
string trace_route(long start ,long goal){
	string route("");
	long current;
	for(current = start;current!=goal;current = nex[current][goal])
		route += (to_string(current) + "-");
	route += to_string(goal);
	return route;
}
#endif

int main(void){
	long V;	//頂点数,辺数
	long long ans = 0;
	cin >> V;

	dist = VVL(V+1,VL(V+1,loINF));
	VVL spare(V+1,VL(V+1));
	#ifdef TRACE_ROUTE
	nex = VVL(V+1,VL(V+1,0));
	REP(i,V+1) REP(j,V+1) nex[i][j] = j;
	#endif

	REP(i,V) {
		REP(j,V) {
			long dis;
			cin >> dis;
			dist[i][j] = dis;
			spare[i][j] = dis;
		}
	}

	long retval = Warshall_Floyd(V); //全てに辺があると考える。
	if (retval == (-1)) {
		cerr << "error" << endl;
		exit(0);
	}

	else {
		if (retval == 0){
			REP(i,V) {
				REP(j,V) {
					if (dist[i][j] < spare[i][j]) { //全てに辺があると考えた方が最短
						cout << "-1" << endl;
						exit(0);
					}
					ans += dist[i][j];
				}
			}
		}
	}

	REP(i,V){
		REP(j,V){
			if (i == j) continue;
			REP(k,V){
				if (i == k || j == k) continue;
				if (dist[i][j] == dist[i][k] + dist[k][j]) ans -= spare[i][j]; 
			}
		}
	}
	cout << ans/2 << endl;
}

