    for (j = 0; j < N; j++){
          cin >> d[j][i];
          m[j][i]=d[j][i];
    }
  }

  warshall_floyd(N);

  for(int i = 0; i < N; i++){
    for(int j = 0; j < N; j++){
      if(i<j)ans+=m[j][i];

      //条件の判定
      if(m[j][i]!=d[j][i]){
          cout<<-1<<endl;
          return 0;
      }
      //存在しない道を取り除く
      for(int k = 0; k < N; k++){
        if(k == i || k == j) continue;
