struct edge{int to,cost;};
struct graph{
    int N;  
    vector< vector<edge> > G;
    VVi dist;
    graph(int n){
        init(n);
    }
    void init(int n){
        N = n;
        G.resize(N);
        dist.resize(N);
        REP(i,0,N) dist[i].resize(N);
        REP(i,0,N){
            REP(j,0,N){
                dist[i][j] = INF;
            }
        }
        REP(i,0,N){
            dist[i][i]=0;
        }
    }
    void add_edge(int s,int t,int cost=1){
        edge e;
        e.to = t, e.cost = cost;
        G[s].push_back(e);
    }
    void dijkstra(int s){
        REP(i,0,N){
            dist[s][i]=INF;
        }
        dist[s][s]=0;
        priority_queue<Pii,vector<Pii>,greater<Pii>> q;
        q.push(mp(s,0));
        while(!q.empty()){
            int now,nowdist;
            tie(now,nowdist) = q.top();q.pop();
            if(dist[s][now]<nowdist) continue;
            for(auto e : G[now]){
                if(dist[s][e.to]>dist[s][now]+e.cost){
                    dist[s][e.to] = dist[s][now]+e.cost;
                    q.push(mp(e.to,dist[s][e.to]));
                }
            }
        }
    }
};

