// ダイクストラ法
// http://nocotan.github.io/%E3%82%A2%E3%83%AB%E3%82%B4%E3%83%AA%E3%82%BA%E3%83%A0/2017/01/26/dijkstra-copy.html
struct edge {
    int to;
    int cost;
};
using P = pair<int, int>;	// <最短距離, 頂点の番号>
void dijkstra(vector<vector<ll>> &g, vector<int> &dist, int s) {
    priority_queue<P, vector<P>, greater<P> > que;
    dist.assign(dist.size(), 1001001001);
    dist[s] = 0;
    que.push(P(0, s));
    while (!que.empty()) {
        P p = que.top();
        que.pop();
        int v = p.second;
        if (dist[v] < p.first) continue;
        for (int i=0; i<g[v].size(); ++i) {
            ll cost = g[v][i];
            if (dist[i] > dist[v] + cost) {
                dist[i] = dist[v] + cost;
                que.push(P(dist[i], i));
            }
        }
    }
}

int main() {
	int n;
	cin >> n;
	vector<vector<ll>> a(n, vector<ll>(n));
	vector<vector<ll>> g(n, vector<ll>(n));
	rep(i, n) rep(j, n) cin >> a[i][j];
	bool ok = true;
	ll ans = 0;
	g = a;
	const int INF = 1001001001;
	rep(i, n) {
		rep(j, n) {
			// i to j
			if (i == j) continue;
			ll tmp = g[i][j];
			// g[i][j]の削除
			g[i][j] = INF;
			g[j][i] = INF;
			// 最短距離が変わらなかったら、その辺は不要
			vector<int> dist(n);
			dijkstra(g, dist, i);
			if(dist[j] < tmp) ok = false;
			else if (dist[j] != tmp) ans += tmp;
			g = a;
		}
	}

	if (ok) cout << ans/2 << endl;
	else cout << -1 << endl;
	return 0;
}

