    REP(i, N){
        FOR(j, i + 1, N){
            dist.push_back(PiP(A[i][j], Pii(i, j)));
        }
    }

    SORT(dist);

    int ans = 0;
    REP(i, dist.size()){
        int c = dist[i].first;
