class D {
	int n;
	vvi d;
	vector<vector<bool>> done;

public:
	D()
	{
		cin >> n;
		d.resize(n, vi(n));
		done.resize(n, vector<bool>(n, 0));

		REP(i, n)
			done[i][i] = true;

		REP(i, n)
			REP(j, n)
			cin >> d[i][j];

	}

	bool warshall_froyd()
	{

		REP(k, n)
			REP(i, n)
			REP(j, n)
			if ((d[i][j] > d[i][k] + d[k][j]))
				return false;

		return true;
	}


	void update()
	{
		REP(k, n)
			REP(i, n)
			REP(j, n)
		{
			if (done[i][j])
				continue;

			if (done[i][k] && done[k][j])
				if (d[i][j] == d[i][k] + d[k][j])
				{
					done[i][j] = true;
					done[j][i] = true;
				}
			}
	}

	void solve()
	{

		if (!warshall_froyd())
		{
			cout << "-1" << endl;
			return;
		}

		int ans = 0;

		while (true)
		{
			bool flag = false;
			int mini, minj;
			int mind = INTMAX;

			REP(i, n)
				REP(j, n)
			{
				if (!done[i][j] && chmin(mind, d[i][j]))
				{
					flag = true;
					mini = i;
					minj = j;
				}
			}

			if (flag)
			{
				ans += d[mini][minj];
				done[mini][minj] = done[minj][mini] = true;
				update();
			}
			else
				break;
		}

		cout << ans << endl;
	}
};


int main()
{
	D solution;
	solution.solve();

	return 0;
}

