int main(){
  //input
  cin >> n;
  for(int i=1; i<=n; i++){
    for(int j=1; j<=n; j++){
      cin >> a[i][j];
      b[i][j] = 1LL * a[i][j];
    }
  }

  //まずワーシャルフロイドで全頂点間の最短距離を確定
  for(int k=1; k<=n; k++){
    for(int i=1; i<=n; i++){
      for(int j=1; j<=n; j++){
        b[i][j] = min(b[i][k]+b[k][j], b[i][j]);
      }
    }
  }

  //次に各頂点間の最短距離について削除できる辺がないか調査
  ll cnt=0;

  //辺i-jを全探索
  for(int i=1; i<=n; i++){
    for(int j=i+1; j<=n; j++){
      //もし最短距離が更新されたなら不適
      if(b[i][j]<a[i][j]){
        cnt = -1;
        break;
      }
      //辺i-jが必要かどうか
      bool necessary=true;

      for(int k=1; k<=n; k++){
        if(i==k || k==j) continue;
        if(b[i][j]<a[i][j]){
          cnt=-1;
          break;
        }
        //このような辺はいらないので削除可能
        if(b[i][j]==b[i][k]+b[k][j]) {
          necessary=false;
          break;
        }
      }

      //削除不可能な辺について加算
      if(necessary) cnt+= a[i][j];
    }
    if(cnt==-1)break;
  }

  cout << cnt << endl;

  return 0;

}

