public:
    bool test_bipartite() {
        int N = (*this).size();
        UnionFind uf(N * 2);
        for (int i = 0; i < N; i++) {
            for (auto& e : (*this)[i]) {
                uf.unite(i, e.to + N);
                uf.unite(i + N, e.to);
            }
        }
        for (int i = 0; i < N; i++) {
            if (uf.same(i, i + N))
                return false;
        }
        return true;
    }
