public:
    void reverse() {
        int N = (*this).size();
        vector<pair<int, Edge>> V;
        V.reserve(M);
        for (int i = 0; i < N; i++) {
            for (auto& e : (*this)[i]) {
                V.emplace_back(make_pair(i, e));
            }
        }
        (*this).erase((*this).begin(), (*this).end());
        (*this).resize(N);
        for (auto& p : V)
            (*this)[p.second.to].emplace_back(Edge{p.first, p.second.cost, p.second.id});
    }
