    //--------Dijkstra--------
    //verified
public:
    //pair<vector<T>, vector<int>> Dijkstra(int s) {
    vector<T> Dijkstra(int s) {
        const T INF = numeric_limits<T>::max() / 5;
        using P = pair<T, int>;
        int N = (*this).size();
        vector<T> dist(N, INF);
        //vector<int> bef(N, -1);
        priority_queue<P, vector<P>, greater<P>> que;
        dist[s] = 0;
        que.emplace(dist[s], s);
        while (!que.empty()) {
            P p = que.top();
            que.pop();
            int now = p.second;
            if (dist[now] < p.first)
                continue;
            for (auto& p : (*this)[now]) {
                int nxt = p.to;
                T cost = p.cost;
                if (dist[nxt] > dist[now] + cost) {
                    dist[nxt] = dist[now] + cost;
                    //bef[nxt] = now;
                    que.emplace(dist[nxt], nxt);
                }
            }
        }
        return dist;
        //return make_pair(dist, bef);
    }
    //
    //
    //--------Warshall–Floyd--------
    //verified
public:
    vector<vector<T>> WarshallFloyd() {
        int N = (*this).size();
        const T INF = numeric_limits<T>::max() / 3;
        vector<vector<T>> ret(N, vector<T>(N, INF));
        for (int i = 0; i < N; i++) {
            ret[i][i] = 0;
            for (auto& e : (*this)[i]) {
                ret[i][e.to] = e.cost;
            }
        }
        for (int k = 0; k < N; k++) {
            for (int i = 0; i < N; i++) {
                for (int j = 0; j < N; j++) {
                    if (ret[i][j] > ret[i][k] + ret[k][j])
                        ret[i][j] = ret[i][k] + ret[k][j];
                }
            }
        }
        return ret;
    }
