    //
    //--------Kruskal--------
    //verified
private:
    vector<int> Kruskal_data;
    bool Kruskal_unite(int x, int y) {
        x = Kruskal_root(x), y = Kruskal_root(y);
        if (x == y)
            return (false);
        if (Kruskal_data[x] > Kruskal_data[y])
            swap(x, y);
        Kruskal_data[x] += Kruskal_data[y];
        Kruskal_data[y] = x;
        return (true);
    }
    int Kruskal_root(int k) {
        if (Kruskal_data[k] < 0)
            return (k);
        return (Kruskal_data[k] = Kruskal_root(Kruskal_data[k]));
    }
    bool Kruskal_same(int x, int y) {
        return Kruskal_root(x) == Kruskal_root(y);
    }
    int Kruskal_size(int k) {
        return (-Kruskal_data[Kruskal_root(k)]);
    }
    //
public:
    template <class Compare = less<T>>
    pair<T, vector<bool>> Kruskal(bool flag = false) {
        struct edge2 {
            int from, to;
            T cost;
            bool used;
            int id;
            edge2(int from, int to, T cost, int id) : from(from), to(to), cost(cost), used(false), id(id) {}
        };
        vector<edge2> edges;
        int N = (*this).size();
        Kruskal_data.assign(N, -1);
        for (int i = 0; i < (int)(*this).size(); i++) {
            auto& V = (*this)[i];
            for (auto& e : V) {
                edges.emplace_back(i, e.to, e.cost, e.id);
            }
        }
        sort(edges.begin(), edges.end(), [](const edge2& a, const edge2& b) {
            return Compare()(a.cost, b.cost);
        });
        T ret = 0;
        vector<bool> V;
        if (flag)
            V.resize(M, false);
        for (auto& e : edges) {
            if (Kruskal_unite(e.from, e.to)) {
                ret += e.cost;
                e.used = true;
            }
        }
        if (flag)
            for (auto& e : edges) {
                assert(e.id >= 0 && e.id < M);
                if (e.used)
                    V[e.id] = true;
            }
        if (N == Kruskal_size(0))
            return make_pair(ret, V);
        else
            return make_pair(-1, V);
    }
    //
    //--------StronglyConnectedComponent--------
    //Unverified
public:
    vector<vector<int>> SCC_R, SCC_T;
    //
private:
    bool StronglyConnectedComponent_ready = false;
    vector<int> SCC_cmp, SCC_ord;
    vector<bool> SCC_used;
    //
public:
    int Gbuild_SCC() {
        cerr << "Please Verify" << endl;
        assert(!undirected);
        assert(directed);
        int N = (*this).size();
        SCC_R.resize(N);
        for (int i = 0; i < N; i++) {
            for (int& x : (*this)[i]) {
                SCC_R[x].emplace_back(i);
            }
        }
        SCC_cmp.resize(N);
        fill(SCC_cmp.begin(), SCC_cmp.end(), -1);
        SCC_used.resize(N);
        fill(SCC_used.begin(), SCC_used.end(), false);
        StronglyConnectedComponent_ready = true;
        return build_StronglyConnectedComponent_init();
    }
    int SCC(int k) {
        assert(StronglyConnectedComponent_ready);
        return SCC_cmp[k];
    }
    //
private:
    void build_StronglyConnectedComponent_dfs(int now) {
        if (SCC_used[now])
            return;
        SCC_used[now] = true;
        for (auto nxt : (*this)[now])
            build_StronglyConnectedComponent_dfs(nxt);
        SCC_ord.emplace_back(now);
    }
    void build_StronglyConnectedComponent_rdfs(int now, int count) {
        if (SCC_cmp[now] != -1)
            return;
        SCC_cmp[now] = count;
        for (auto to : SCC_R[now])
            build_StronglyConnectedComponent_rdfs(to, count);
    }
    int build_StronglyConnectedComponent_init() {
        int n = (int)(*this).size();
        for (int i = 0; i < n; i++)
            build_StronglyConnectedComponent_dfs(i);
        reverse(SCC_ord.begin(), SCC_ord.end());
        int group = 0;
        for (auto& i : SCC_ord) {
            if (SCC_cmp[i] == -1) {
                build_StronglyConnectedComponent_rdfs(i, group);
                group++;
            }
        }
        SCC_T.resize(group);
        for (int i = 0; i < n; i++) {
            for (auto& to : (*this)[i]) {
                int s = SCC_cmp[i], t = SCC_cmp[to];
                if (s != t)
                    SCC_T[s].emplace_back(t);
            }
        }
        return group;
    }
    //
    //
    //
    //--------TopologicalSort--------
    //verified
public:
    vector<int> TopologicalSort() {
        assert(!undirected);
        int N = (*this).size();
        vector<int> deg(N);
        for (auto& V : (*this))
            for (auto& e : V)
                deg[e.to]++;
        stack<int> st;
        for (int i = 0; i < N; i++)
            if (deg[i] == 0)
                st.emplace(i);
        vector<int> ret;
        ret.reserve(N);
        while (!st.empty()) {
            auto x = st.top();
            st.pop();
            ret.emplace_back(x);
            for (auto& e : (*this)[x])
                if (--deg[e.to] == 0)
                    st.emplace(e.to);
        }
        return ret;
    }
    //
    //
    //--------Tree--------
    //
    //
    //--------ReRooting--------
public:
    template <typename sum_t>
    pair<vector<sum_t>, vector<vector<sum_t>>>
    Tbuild_ReRooting(
        const function<sum_t(sum_t, sum_t)> f,
        const function<sum_t(sum_t, Edge)> gg,
        sum_t ident) {
        assert(tree);
        int N = (*this).size();
        vector<sum_t> subdp(N, ident), dp(N, ident);
        vector<vector<sum_t>> g_dp(N), g_ndp(N), memo(N);
        vector<vector<bool>> seen(N);
        for (int i = 0; i < N; i++) {
            int S = (*this)[i].size();
            g_dp[i].resize(S, ident);
            g_ndp[i].resize(S, ident);
            memo[i].resize(S);
            seen[i].resize(S, false);
        }
        stack<int> stk;
        stk.push(0);
        vector<int> par(N), ord(N);
        int index = 0;
        par[0] = -1;
        while (!stk.empty()) {
            int node = stk.top();
            stk.pop();
            ord[index++] = node;
            for (auto& e : (*this)[node]) {
                if (e.to == par[node])
                    continue;
                stk.push(e.to);
                par[e.to] = node;
            }
        }
        for (int k = ord.size() - 1; k >= 0; k--) {
            int idx = ord[k];
            for (int i = 0; i < (int)((*this)[idx].size()); i++) {
                auto& e = (*this)[idx][i];
                if (e.to == par[idx])
                    continue;
                if (!seen[idx][i]) {
                    memo[idx][i] = gg(subdp[e.to], e);
                    seen[idx][i] = true;
                }
                subdp[idx] = f(subdp[idx], memo[idx][i]);
            }
        }
        vector<sum_t> top(N, ident);
        for (int k = 0; k < (int)(ord.size()); k++) {
            int idx = ord[k];
            sum_t buff{ident};
            for (int i = 0; i < (int)((*this)[idx].size()); i++) {
                auto& e = (*this)[idx][i];
                g_ndp[idx][i] = buff;
                if (!seen[idx][i]) {
                    memo[idx][i] = gg(par[idx] == e.to ? top[idx] : subdp[e.to], e);
                    seen[idx][i] = true;
                }
                g_dp[idx][i] = memo[idx][i];
                buff = f(buff, g_dp[idx][i]);
            }
            dp[idx] = buff;
            buff = ident;
            for (int i = (*this)[idx].size() - 1; i >= 0; i--) {
                auto& e = (*this)[idx][i];
                if (e.to != par[idx])
                    top[e.to] = f(g_ndp[idx][i], buff);
                g_ndp[idx][i] = f(g_ndp[idx][i], buff);
                buff = f(buff, g_dp[idx][i]);
            }
        }
        return make_pair(dp, memo);
    }
