void solve() {
    int ans = 0;
    while (!que.empty()) {
        auto p = que.top();
        que.pop();
        int x = p.second.first, y = p.second.second, c = p.first;
        int d = G.Dijkstra(x)[y];
        if (d > c) {
            ans += c;
            G.add_edge_directed_weighted(x, y, c);
        } else if (d < c) {
            cout << -1 << endl;
            return;
        }
    }
    ans /= 2;
    cout << ans << endl;
}

