using namespace std;

using VI = vector<int>;
using VVI = vector<VI>;
using PII = pair<int, int>;
using TUP = tuple<long long, int, int, int>;

const long long inf = 1e18;

VVI warshall_floyd(VVI cost) {
	int n = cost.size();
	for (int k = 0; k < n; k++) {
		for (int i = 0; i < n; i++) {
			for (int j = 0; j < n; j++) {
				cost[i][j] = min(cost[i][j], cost[i][k] + cost[k][j]);
			}
		}
	}

	return cost;
}

int main() {
	int n;
	cin >> n;

	VVI cost(n, VI(n));
	for (int i = 0; i < n; i++) {
		for (int j = 0; j < n; j++) {
			cin >> cost[i][j];
		}
	}

	auto cost2 = warshall_floyd(cost);
	for (int i = 0; i < n; i++) {
		for (int j = 0; j < n; j++) {
			if (cost[i][j] != cost2[i][j]) {
				cout << -1 << endl;
				return 0;
			}
		}
	}

	set<PII> need;
	for (int st = 0; st < n; st++) {
		priority_queue<TUP, vector<TUP>, greater<TUP>> que;  // dist, add, pos, from
		vector<long long> dist(n, inf);
		que.emplace(0, 0, st, st);

		int x, from, add;
		long long val;
		while (!que.empty()) {
			tie(val, add, x, from) = que.top();
			que.pop();

			if (val >= dist[x]) {
				continue;
			}

			dist[x] = val;
			need.insert(make_pair(min(from, x), max(from, x)));

			for (int i = 0; i < n; i++) {
				if (dist[i] != inf) {
					continue;
				}
				que.emplace(dist[x] + cost[x][i], cost[x][i], i, x);
			}
		}
	}

	long long ans = 0;
	for (auto p: need) {
		ans += cost[p.first][p.second];
	}
	cout << ans << endl;
	return 0;
}

