int main() {
	int n;
	cin >> n;
	vector<vector<int>> v(n, vector<int>(n, 0));
	vector<tuple<int, int, int>> data;
	for (int i = 0; i < n; ++i) {
		for (int j = 0; j < n; ++j) {
			int a;
			cin >> a;
			v[i][j] = a;
			if (i < j)
				data.push_back(make_tuple(a, j, i));
		}
	}
	sort(data.begin(), data.end());
	int64_t inf = 10000000000000LL;
	vector<vector<int64_t>> u(n, vector<int64_t>(n, inf));
	for (int i = 0; i < n; ++i) {
		u[i][i] = 0;
	}
	int64_t cost=0;
	for (auto item : data) {
		int dist = get<0>(item);
		int n1 = get<1>(item);
		int n2 = get<2>(item);
		if (u[n1][n2] > dist) {
			u[n1][n2] = u[n2][n1] = dist;
			cost += dist;
			for (int i = 0; i < n; ++i) {
				for (int j = 0; j < n; ++j) {
					int64_t nc = u[i][n1] + u[n1][n2] + u[n2][j];
					if (nc < u[i][j]) {
						u[i][j] = u[j][i] = nc;
					}
				}
			}
		}
	}
	bool okay = true;
	for (int i = 0; i < n; ++i) {
		for (int j = i + 1; j < n; ++j) {
			if (u[i][j] != v[i][j]) okay = false;
		}
	}

	if (!okay) cout << -1 << endl;
	else cout << cost << endl;
	return 0;
}

