ll solve(int N, int A[300][300]) {
    ll ans = 0;
    for (int i = 0; i < N; i++) {
        for (int j = i+1; j < N; j++) {
            bool ok = true;
            for (int k = 0; k < N; k++) {
                if (i == k || j == k) continue;

                if (A[i][k] + A[k][j] < A[i][j]) {
                    return -1;
                }

                if (A[i][k] + A[k][j] == A[i][j]) {
                    ok = false;
                }
            }
            if (ok) ans += A[i][j];
        }
    }
    return ans;
}

