    struct union_find_tree {
        vector<int> parent;
        vector<int> rank;

        void init(int n)
        {
            for (int i = 0; i < n; i++)
            {
                parent.push_back(i);
                rank.push_back(0);
            }
        }

        int find(int x)
        {
            if (parent[x] == x)
            {
                return x;
            }
            else
            {
                return parent[x] = find(parent[x]);
            }
        }

        void unite(int x, int y)
        {
            x = find(x);
            y = find(y);

            if (x == y) return;

            if (rank[x] < rank[y])
            {
                parent[x] = y;
            }
            else {
                parent[y] = x;
                if (rank[x] == rank[y]) rank[x]++;
