typedef long long LL;
using Graph = vector<vector<LL>>;
static LL INF = (1LL<<62);
using LLPair = pair<LL, LL>;

void WarshallFloyd(LL N, Graph &G, vector<vector<LL>> &D){
	D.assign(N, vector<LL>(N, INF));
	for(int i=0; i<N; i++){
		for(int j=0; j<N; j++){ D[i][j] = G[i][j]; }
	}

	for(int k=0; k<N; k++){
		for(int i=0; i<N; i++){
			for(int j=0; j<N; j++){
				if(D[i][k] != INF && D[k][j] != INF){
					D[i][j] = min(D[i][j], D[i][k]+D[k][j]);
				}
			}
		}
	}
	return;
}

LL N;
int main(int argc, char* argv[]){
	cin.tie(0);
	ios::sync_with_stdio(false);

	cin >> N;

	Graph G;
	G.assign(N, vector<LL>(N, INF));

	for(int i=0; i<N; i++){
		for(int j=0; j<N; j++){
			LL c; cin >> c;
			G[i][j] = min(G[i][j], c);
			G[j][i] = min(G[j][i], c);
		}
	}

	vector<vector<LL>> D;
	WarshallFloyd(N, G, D);

	LL ans = 0;
	for(int i=0; i<N; i++){
		for(int j=i+1; j<N; j++){
			ans += D[i][j];
			if(G[i][j] != D[i][j]){
				printf("-1\n");
				return 0;
			}
		}
	}

	vector<vector<LL>> F;
	F.assign(N, vector<LL>(N, 0));
	for(int i=0; i<N; i++){
		for(int j=i+1; j<N; j++){
			if(D[i][j] == 0 || F[i][j] == 1) continue;
			for(int k=0; k<N; k++){
				if(k == i || k == j) continue;
				if(D[i][j] == D[i][k] + D[k][j]){
					ans -= D[i][j];
					D[i][j] = 0;
					F[i][k] = 1;
					F[k][j] = 1;
				}
			}
		}
	}
	printf("%lld\n", ans);
	return 0;
}

