int main() {

	int n;
	cin >> n;
	vector<vector<int64_t>>a(n,vector<int64_t>(n));
	vector<tuple<int,int,int>> t;
	for(int i=0; i<n; i++){
		for(int j=0; j<n; j++) {
			cin >> a.at(i).at(j);
			t.push_back(make_tuple(a.at(i).at(j),i,j));
		}
	}
	vector<vector<int64_t>> dp(n,vector<int64_t>(n,INF));
	sort(t.begin(),t.end());
	bool flg = 1;
	int64_t ans{};
	for(int l=0; l<n*n; l++){
		if ( dp.at(get<1>(t.at(l))).at(get<2>(t.at(l))) < get<0>(t.at(l)) ){
			flg = 0;
			break;
		}
		else if ( dp.at(get<1>(t.at(l))).at(get<2>(t.at(l))) == get<0>(t.at(l)) ){
			continue;
		}
		else {
			dp.at(get<1>(t.at(l))).at(get<2>(t.at(l))) = get<0>(t.at(l));
			dp.at(get<2>(t.at(l))).at(get<1>(t.at(l))) = get<0>(t.at(l));
			ans += get<0>(t.at(l));
		}
		if(l<n*2-1) continue;
		for(int k=0; k<n; k++){
			for(int i=0; i<n; i++){
				for(int j=0; j<n; j++){
					dp.at(i).at(j) = min (dp.at(i).at(j), dp.at(i).at(k)+dp.at(k).at(j));
				}
			}
		}
		if(dp==a) break;
	}
	cout << (flg?ans:-1) << endl;

}

