using namespace std;
const int inf=(1<<30)-1;
struct point
{
	int d,x,y;
	bool operator < (const point &a)const
	{
		return d>a.d;
	}
};
int n,a[310][310],d[310][310];
priority_queue<point> q;
int main()
{
	scanf("%d",&n);
	for (int i=1;i<=n;i++)
	{
		for (int j=1;j<=n;j++)
		{
			scanf("%d",&a[i][j]);
			d[i][j]=inf;
		}
		d[i][i]=0;
	}
	long long ans=0;
	for (int i=1;i<n;i++)
	{
		for (int j=i+1;j<=n;j++)
		{
			q.push((point){a[i][j],i,j});
		}
	}
	while (!q.empty())
	{
		int x=q.top().x;
		int y=q.top().y;
		int z=q.top().d;
		q.pop();
		int now=inf;
		for (int i=1;i<=n;i++)
		{
			now=min(now,d[x][i]+d[i][y]);
		}
		if (now<z)
		{
			puts("-1");
			return 0;
		}
		if (now>z)
		{
			d[x][y]=d[y][x]=z;
			ans+=z;
		}
	}
	printf("%lld\n",ans);
	return 0;
}

