void warshall(vector<vector<long long>> &v) {
	ll n = v.size();
	rep(i, n) {
		rep(j, n) {
			rep(k, n) {
				// cout << i << " " << j << " " << k << "\n";
				// cout << v[j][k] << " " << v[j][i] << " " << v[i][k] << "\n\n";
				v[j][k] = min(v[j][k], v[j][i] + v[i][k]);
			}
		}
	}
	return;
}

