int main() {
	ll nagai = POW(10, 11);
	ll n;
	cin >> n;
	vvll gra(n, vll(n));
	rep(i, n) rep(j, n) cin >> gra[i][j];
	auto gra2 = gra;
	warshall(gra2);
	if(gra != gra2) {
		cout << -1 << endl;
		return 0;
	}
	ll ans = 0;
	rep(i, n) rep(j, n) gra2[i][j] = nagai;
	using T = pair<long long, pair<long long, long long>>;
	pq<T, vector<T>, greater<T>> q;
	rep(i, n) {
		Rep(j, i + 1, n) { q.push({gra[i][j], {i, j}}); }
	}
	rep(i, n) { gra2[i][i] = 0; }
	while(!q.empty()) {
		T now = q.top();
		q.pop();
		ll dist = now.first;
		ll from = now.second.first;
		ll to = now.second.second;
		bool f = 1;
		rep(k, n) {
			if(gra2[from][k] + gra2[k][to] <= dist) {
				f = 0;
			}
		}
		if(f) {
			ans += dist;
			gra2[from][to] = dist;
			gra2[to][from] = dist;
			rep(i, n) {
				Rep(j, 0, n) {
					if(j == i) continue;
					if(gra2[i][from] + dist + gra2[to][j] < gra2[i][j]) {
						gra2[j][i] = gra2[i][j] = gra2[i][from] + dist + gra2[to][j];
					}
				}
			}
		}
	}
	cout << ans << endl;
}

