#define FORR(I,A,B) for(ll I = (B-1); I >= (A); --I)
const ll INF=1e18+7;
const ll MOD=1e9+7;

class dijkstra{ 
//0indexed 
public: 
	ll v,startv; 
	vector<ll> d; 
	vector< vector< pair<ll,ll> > > e;

	void initsize(ll n0){ 
		d.resize(n0); 
		for(ll i=0;i<n0;i++)d[i]=INF; 
		vector<pair<ll,ll> > ep;
		for(ll i=0;i<n0;i++)e.push_back(ep); 
		v=n0; 
	} 

	void initstart(ll s){ 
		startv=s;
		d[s]=0;
	}

	void make_edge(ll x,ll y,ll cost){ 
		e[x].push_back(make_pair(y,cost)); 
		e[y].push_back(make_pair(x,cost)); 
	}

	void make_edgedir(ll x,ll y,ll cost){ 
		e[x].push_back(make_pair(y,cost)); 
	}

	void calcdistance(){ 
		// <-cost,x> 
		//cost startv->x 
		priority_queue<pair<ll,ll> > q; 
		pair<ll,ll> p; 
		vector<bool> did; 
		for(ll i=0;i<v;i++)did.push_back(false); 
		did[startv]=true; 
		for(ll i=0;i<e[startv].size();i++){ 
			p.first=-e[startv][i].second; 
			p.second=e[startv][i].first; 
			q.push(p); 
		}
		while(q.size()!=0){
			pair<ll,ll> p;
			p=q.top();
			q.pop();
			ll x,costsx;
			x=p.second;
			costsx=-p.first;
			if(did[x]==true)continue;
			did[x]=true;
			d[x]=costsx;
			for(ll i=0;i<e[x].size();i++){
				p.first=-(d[x]+e[x][i].second);
				p.second=e[x][i].first;
				if(did[p.second]==false)q.push(p);
			}
		}
	}
};

