		rd.push({ -a[i][j], {i,j} });
	}
	dijkstra dk;
	dk.initsize(n);
	ll ans = 0;
	while(not rd.empty()){
		ll st = rd.top().second.first;
		ll go = rd.top().second.second;
		ll len = -rd.top().first;
		FOR(i,0,n)dk.d[i] = INF;
