// ワーシャルフロイド法(全点間距離)
VVL d;//対角0,辺がないところはINF
void warshall_floyd(int n) {
  REP(k,n){       // 経由する頂点
    REP(i,n){    // 始点
      REP(j,n){  // 終点
        d[i][j] = min(d[i][j], d[i][k] + d[k][j]);
      }
    }
  }
}

