const ll MOD = 1e9 + 7;
// const long long INF = 1LL<<60;
void add(long long &a, long long b) { a += b; if (a >= MOD) a -= MOD; }
void sub(long long &a, long long b) { a -= b; if (a < 0) a += MOD; }
void mul(long long &a, long long b) { a *= b; a %= MOD; }
ll llmin(ll a, ll b) { if (a < b) return a; else return b; }
ll llmax(ll a, ll b) { if (a < b) return b; else return a; }
ll llabs(ll a) { if (a >= 0) return a; else return - a; }
ll llmodpow(ll a, ll n) {
   if (n == 0) return 1;
   ll tmp = llmodpow(a, n / 2);
   mul(tmp, tmp);
   if (n & 1) mul(tmp, a);
   return tmp;
}

int main() {
   int N;
   cin >> N;
   ll A[N][N];
   ll dp[N][N];
   vector<ipair> log;
   map<int, ipair> LUT;
   int id = 0;
   for (int i = 0; i < N; i++) {
      for (int j = 0; j < N; j++) {
         cin >> A[i][j];
         dp[i][j] = A[i][j];
         if (i < j) {
            log.push_back(ipair(id, A[i][j]));
            LUT[id] = ipair(i, j);
            id++;
         }
      }
   }
   sort(log.begin(), log.end(), lessPair);

   for (int k = 0; k < N; k++) {
      for (int i = 0; i < N; i++) {
         for (int j = 0; j < N; j++) {
            dp[i][j] = llmin(dp[i][j], dp[i][k] + dp[k][j]);
         }
      }
   }
   ll ans = 0;
   for (auto it = log.begin(); it != log.end(); it++) {
      int ID = it->first;
      int s = LUT[ID].first;
      int e = LUT[ID].second;
      ll dis = dp[s][e];
      ll tmp = it->second;
      // cout << LUT[ID].first << " " << LUT[ID].second << " " << dis << " " << tmp << endl;
      if (dis < tmp) {
         cout << -1 << endl;
         return 0;
      } else if (dis > tmp) ans += tmp;
      else {
         bool flg = false;
         for (int k = 0; k < N; k++) {
            if (k != s && k != e && tmp == dp[s][k] + dp[k][e]) {
               flg = true;
               continue;
            }
         }
         if (!flg) ans += tmp;
      }
   }
   cout << ans << endl;
   return 0;
}

