#include <bits/stdc++.h>
using namespace std;
/* typedef */
typedef long long ll;
typedef pair<int, int> pii;
/* constant */
const int INF = 1 << 30;
const ll LINF = 1LL << 50;
/* global variables */
int N;
/* function */
vector<vector<ll> > floyd(vector<vector<ll> > G) {
    vector<vector<ll> > F = G;
    for (int k = 0; k < N; k++) {
        for (int i = 0; i < N; i++) {
            if (F[i][k] == LINF) continue;
            for (int j = 0; j < N; j++) {
                if (F[k][j] == LINF) continue;
                F[i][j] = min(F[i][j], F[i][k] + F[k][j]);
            }
        }
    }
    return F;
}
void calcAns(vector<vector<ll> > F) {
    ll ans = 0;
    for (int i = 0; i < N - 1; i++) {
        for (int j = i + 1; j < N; j++) {
            ans += F[i][j];
        }
    }
    for (int k = 0; k < N; k++) {
        for (int i = 0; i < N - 1; i++) {
            if (F[i][k] == LINF) continue;
            for (int j = i + 1; j < N; j++) {
                if (F[k][j] == LINF) continue;
                if (F[i][j] == (F[i][k] + F[k][j]) && i != k && j != k) {
                /*
                    cout << i << " to " << j << " == "
                        << i << " to " << k << " to " << j << '\n';
                */
                ans -= F[i][j];
                }
            }
        }
    }
    cout << ans << '\n';
}

/* main */
int main(){
    cin >> N;
    vector<vector<ll> > G(N, vector<ll>(N, LINF));
    for (int i = 0; i < N; i++) for (int j = 0; j < N; j++) cin >> G[i][j];
    vector<vector<ll> > F = floyd(G);

    if (G != F) {
        cout << -1 << '\n';
    }
    else {
        calcAns(F);
    }

}

