        {
            REP(k, N)
            {
                if (i != k && j != k) {
                    if (A[i][j] > A[i][k] + A[k][j]) {
                        cout << -1 << endl;
                        return 0;
                    }

                    if (A[i][j] == A[i][k] + A[k][j]) {
                        use[i][j] = false;
                    }
                }
            }
        }
    }

    ll sum = 0;

    REP(i, N)
    {
        REP(j, N)
        {
            if (use[i][j])
                sum += A[i][j];
        }
    }

    cout << sum / 2 << endl;
    return 0;
}

