// Warshall–Floyd algorithm ワーシャルフロイド法
std::vector<std::vector<long long>> warshallFloyd(const WGraph &G) {
    int n = (int)G.size();
    std::vector<std::vector<long long>> dis(n, std::vector<long long>(n, LINF));
    for (int i=0; i<n; i++) {
        dis.at(i).at(i) = 0;
    }
    for (int i=0; i<n; i++) {
        for (auto e : G.at(i)) {
            dis.at(i).at(e.first) = e.second;
        }
    }

    for (int k=0; k<n; k++) {
        for (int i=0; i<n; i++) {
            for (int j=0; j<n; j++) {
                dis.at(i).at(j) = std::min(dis.at(i).at(j), dis.at(i).at(k) + dis.at(k).at(j));
            }
        }
    }

    return dis;
}

void solve() {
    int n;
    cin >> n;
    vector<vector<int>> a(n, vector<int>(n));
    for (int i=0; i<n; i++) {
        for (int j=0; j<n; j++) {
            cin >> a.at(i).at(j);
        }
    }

    WGraph G(n);
    for (int i=0; i<n; i++) {
        for (int j=i+1; j<n; j++) {
            G.at(i).push_back({j, a.at(i).at(j)});
            G.at(j).push_back({i, a.at(i).at(j)});
        }
    }
    auto dis = warshallFloyd(G);

    for (int i=0; i<n; i++) {
        for (int j=i+1; j<n; j++) {
            if (a.at(i).at(j) > dis.at(i).at(j)) {
                cout << -1 << '\n';
                return;
            }
        }
    }

    ll res = 0;
    for (int i=0; i<n; i++) {
        for (int j=i+1; j<n; j++) {
            bool rem = false;
            for (int k=0; k<n; k++) {
                if (k == i || k == j) continue;
                if (dis.at(i).at(k) + dis.at(k).at(j) == a.at(i).at(j)) {
                    rem = true;
                    break;
                }
            }
            if (!rem) res += a.at(i).at(j);
        }
    }

    cout << res << '\n';
}

