int main() {
    int N;
    cin >> N;
    vector<vector<lint>> dist(N, vector<lint>(N));
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            lint d;
            cin >> d;
            dist[i][j] = d;
        }
    }

    vector<vector<lint>> wf(N, vector<lint>(N));
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            wf[i][j] = dist[i][j];
        }
    }
    for (int k = 0; k < N; k++) {
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                wf[i][j] = min(wf[i][j], wf[i][k] + wf[k][j]);
            }
        }
    }

    bool can = true;
    lint ans = 0;
    for (int i = 0; i < N; i++) {
        for (int j = i + 1; j < N; j++) {
            if (dist[i][j] > wf[i][j]) {
                can = false;
                goto result;
            }

            bool need = true;
            for (int k = 0; k < N; k++) {
                if (k != i and k != j) {
                    if (dist[i][j] == dist[i][k] + dist[k][j]) {
                        need = false;
                        break;
                    }
                }
            }

            if (need) {
                ans += dist[i][j];
            }
        }
    }

result:
    if (can == false) {
        cout << -1 << endl;
    } else {
        cout << ans << endl;
    }

    return 0;
}

