	scanf("%I64d", &n);
	for(int i = 1; i <= n; i++)
	{
		for(int j = 1; j <= n; j++)
		{
			scanf("%I64d", &g[i][j]);
			if(i < j)
				ans += g[i][j];
		}
	}

	for(int i = 1; i <= n; i++)
		for(int j = 1; j <= n; j++)
			dp[i][j] = INF;

	for(int k = 1; k <= n; k++)
	{
		for(int i = 1; i <= n; i++)
		{
			for(int j = 1; j <= n; j++)
			{
				if( g[i][k] + g[k][j] < dp[i][j] || ( dp[i][j] == g[i][k] + g[k][j] && (i != k && j != k && i != j) ) )
				{
					dp[i][j] = g[i][k] + g[k][j];
					p[i][j] = (i != k && j != k && i != j);
				}
			}
		}
	}

	for(int i = 1; i <= n; i++)
	{
		for(int j = i + 1; j <= n; j++)
