	pr<A, B> value;

	in_pr() {
		myInputStream >> value.a >> value.b;
	}
	in_pr(int addA, int addB) {
		myInputStream >> value.a >> value.b;
		value.a += addA;
		value.b += addB;
	}
	in_pr(bool flip) {
		myInputStream >> value.b >> value.a;
	}
	in_pr(int addA, int addB, bool flip) {
		myInputStream >> value.b >> value.a;
		value.a += addB;
		value.b += addA;
	}
	operator pr<A, B>() {
		return value;
	}
};

