struct MyMain {
	int N = in;
	arr2<int> A = in(N, N);

	void Run() {
		arr2<int> B(N, N);

		REP(i, N) {
			REP(j, N) {
				int a = INF;
				int b = INF;
				REP(k, N) {
					if (A(i, k) == INF || A(k, j) == INF) {
						continue;
					}

					chmin(a, A(i, k) + A(k, j));

					if (k != j && i != k) {
						chmin(b, A(i, k) + A(k, j));
					}
				}
				if (a != A(i, j)) {
					output("-1");
					return;
				}
				if (a == b) {
					B(i, j) = INF;
					B(j, i) = INF;
