				else {
					B(i, j) = a;
					B(j, i) = a;
				}
			}
		}

		int ans = 0;
		REP(i, N) {
			FOR(j, i + 1, N) {
				if (B(i, j) == INT64_MAX) {
					continue;
				}
				ans += B(i, j);
			}
		}

