        for(int j=0;j<N;j++){
            cin >> map[i][j];
            dist[i][j]=(i==j?0:-1);
        }
    }

    long long len=0;
    for(int a=0;a<N;a++){
        priority_queue<pair<int,pair<int,int>>> Q;
        bool chk[300];
        for(int i=0;i<N;i++) chk[i]=false;
        Q.push(make_pair(0,make_pair(a,-1)));

        while(!Q.empty()){
            pair<int,pair<int,int>> t=Q.top();
