                if(i==t.second.first || i==t.second.second) continue;
                Q.push(make_pair(t.first-map[t.second.first][i],make_pair(i,t.second.first)));
            }
            if(dist[a][t.second.first]>map[a][t.second.first]) len+=map[a][t.second.first];
