				else {
					if (j != i && dist[j][k] == dist[j][i] + dist[i][k])
						nex[j][k] = min({nex[j][i],nex[j][k]});
				}
				#endif
				if (dist[j][j] < 0) return (-1);
			}
		}
	}
	return 0;
}

