int main(void){
	long V;	//頂点数,辺数
	long long ans = 0;
	cin >> V;

	dist = VVL(V+1,VL(V+1,loINF));
	VVL spare(V+1,VL(V+1));
	#ifdef TRACE_ROUTE
	nex = VVL(V+1,VL(V+1,0));
	REP(i,V+1) REP(j,V+1) nex[i][j] = j;
	#endif

	REP(i,V) {
		REP(j,V) {
			long dis;
			cin >> dis;
			dist[i][j] = dis;
			spare[i][j] = dis;
		}
	}

	long retval = Warshall_Floyd(V); //全てに辺があると考える。
	if (retval == (-1)) {
		cerr << "error" << endl;
		exit(0);
	}

	else {
		if (retval == 0){
			REP(i,V) {
				REP(j,V) {
					if (dist[i][j] < spare[i][j]) { //全てに辺があると考えた方が最短
						cout << "-1" << endl;
						exit(0);
					}
					ans += dist[i][j];
				}
			}
		}
	}

	REP(i,V){
		REP(j,V){
			if (i == j) continue;
			REP(k,V){
				if (i == k || j == k) continue;
				if (dist[i][j] == dist[i][k] + dist[k][j]) ans -= dist[i][j]; 
			}
		}
	}
	cout << ans/2 << endl;
}

