template <typename T>
void warshallFloyd(vector<vector<T>>& d) {
	int N = d.size();
	for (int i = 0; i < N; i++)
		for (int j = 0; j < N; j++)
			for (int k = 0; k < N; k++)
				d[i][j] = min(d[i][j], d[i][k] + d[k][j]);
}

