	/***** ワーシャルフロイド法 *****/

	struct GT_WarshallFloyd
	{
		/**
		@brief 全点対間最短路を求める
		@param mg 重み付きグラフ(隣接行列)
		@param inf 存在しない辺コスト(LLONG_MAX推奨)
		@param res 最小距離
		@note
		 負の閉路がある場合falseを返す。計算量 O(V^3)
		 一般的にはmgとinfで存在しない辺コストはLLONG_MAXが多い。
		**/
		bool Run
		(const vector<vector<long long>>& mg, long long inf, vector<vector<long long>>& res)
		{
			res = mg;
			long long vmax = (long long)mg.size();
			for (long long k = 0; k < vmax; k++)
			{
				for (long long i = 0; i < vmax; i++)
				{
					if (res[i][k] == inf) continue;
					for (long long j = 0; j < vmax; j++)
					{
						if (res[k][j] == inf) continue;
						res[i][j] = min(res[i][j], res[i][k] + res[k][j]);
					}
				}
			}
			for (long long i = 0; i < vmax; i++)
				if (res[i][i] < 0) return false;
			return true;
		}
	};
}

