using Weight = ll;
using Flow = int;
struct Edge {
    int src, dst;
    Weight weight;
    Flow cap;
    Edge() : src(0), dst(0), weight(0) {}
    Edge(int s, int d, Weight w) : src(s), dst(d), weight(w) {}
};
using Edges = std::vector<Edge>;
using Graph = std::vector<Edges>;
using Array = std::vector<Weight>;
using Matrix = std::vector<Array>;

void add_edge(Graph &g, int a, int b, Weight w = 1) {
    g[a].emplace_back(a, b, w);
    g[b].emplace_back(b, a, w);
}
void add_arc(Graph &g, int a, int b, Weight w = 1) { g[a].emplace_back(a, b, w); }

Matrix WarshallFloyd(const Graph &g) {
    auto const INF = std::numeric_limits<Weight>::max() / 8;
    int n = g.size();
    Matrix d(n, Array(n, INF));
    rep(i, n) d[i][i] = 0;
    rep(i, n) for (auto &e : g[i]) d[e.src][e.dst] = std::min(d[e.src][e.dst], e.weight);
    rep(k, n) rep(i, n) rep(j, n) {
        if (d[i][k] != INF && d[k][j] != INF) d[i][j] = std::min(d[i][j], d[i][k] + d[k][j]);
    }
    return d;
}

void solve(long long N, std::vector<std::vector<long long>> A) {
    Graph g(N);
    rep(i, N) {
        rep(j, N) {
            if (i == j) continue;
            add_arc(g, i, j, A[i][j]);
        }
    }
    Matrix B = WarshallFloyd(g);
    ll res = 0;
    bool minus = false;
    // rep(i, N) {
    //     rep(j, N) { cout << i << " " << j << " " << B[i][j] << endl; }
    // }
    rep(i, N) {
        rep(j, N) {
            if (i <= j) break;
            bool flg = true;
            rep(k, N) {
                if (i == k || j == k) continue;
                if (A[i][j] > B[i][k] + B[k][j]) minus = true;
                if (A[i][j] == B[i][k] + B[k][j]) flg = false;
            }
            if (flg) res += B[i][j];
        }
    }
    if (minus)
        cout << "-1" << endl;
    else
        cout << res << endl;
}

int main() {
    long long N;
    scanf("%lld", &N);
    std::vector<std::vector<long long>> A(N, std::vector<long long>(N));
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            scanf("%lld", &A[i][j]);
        }
    }
    solve(N, std::move(A));
    return 0;
}

