int main() {
    int n;
    auto m = 10000000000ll, ret = 0ll;
    std::cin >> n;
    std::vector<std::vector<long long>> a(n, std::vector<long long>(n));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            std::cin >> a[i][j];
            if (i != j) m = std::min(m, a[i][j]);
        }
    }
    auto cost(a);
    std::set<std::tuple<long long, int, int>> s;
    for (int i = 0; i < n; i++) for (int j = 0; j < n; j++) if (i != j) cost[i][j] = 10000000000ll;
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            if (a[i][j] > 2 * m) {
                s.insert(std::make_tuple(a[i][j], i, j));
                continue;
            }
            cost[i][j] = a[i][j];
            cost[j][i] = a[i][j];
            ret += a[i][j];
        }
    }

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            for (int k = 0; k < n; k++) {
                cost[j][k] = std::min(cost[j][k], cost[j][i] + cost[i][k]);
            }
        }
    }

    for (auto& tpl : s) {
        auto c = std::get<0>(tpl);
        int i = std::get<1>(tpl), j = std::get<2>(tpl);
        if (c == cost[i][j]) continue;
        if (c > cost[i][j]) {
            std::cout << -1 << std::endl;
            return 0;
        }
        cost[i][j] = c;
        ret += c;
        for (auto k = 0; k < n; k++) {
            cost[i][k] = std::min(cost[i][k], cost[i][j] + cost[j][k]);
            cost[k][i] = cost[i][k];
            cost[j][k] = std::min(cost[j][k], cost[j][i] + cost[i][k]);
            cost[k][j] = cost[j][k];
        }
    }

    std::cout << ret << std::endl;

    return 0;
}

