constexpr const std::int_fast64_t INF = std::numeric_limits<std::int_fast64_t>::max();

constexpr std::int_fast64_t safe_sum(const std::int_fast64_t a, const std::int_fast64_t b) {
  return a == INF || b == INF ? INF : a + b;
}

std::vector<std::vector<std::int_fast64_t>> warshall_floyd(const std::vector<std::vector<std::int_fast64_t>>& expected) {
  const std::int_fast64_t n = expected.size();

  std::vector<std::vector<std::int_fast64_t>> actual = expected;
  for (std::int_fast64_t k = 0; k < n; ++k) {
    for (std::int_fast64_t i = 0; i < n; ++i) {
      for (std::int_fast64_t j = 0; j < n; ++j) {
        actual[i][j] = std::min(actual[i][j], safe_sum(actual[i][k], actual[k][j]));
      }
    }
  }
  return actual;
}

std::int_fast64_t calc_answer(const std::vector<std::vector<std::int_fast64_t>>& actual) {
  const std::int_fast64_t n = actual.size();

  std::int_fast64_t answer = 0;
  for (std::int_fast64_t i = 0; i < n; ++i) {
    for (std::int_fast64_t j = 0; j < n; ++j) {
      if (i >= j) continue;

      std::int_fast64_t alternative_distance = INF;
      for (std::int_fast64_t k = 0; k < n; ++k) {
        if (k == i || k == j) continue;
        alternative_distance = std::min(alternative_distance, safe_sum(actual[i][k], actual[k][j]));
      }

      if (actual[i][j] < alternative_distance) answer += actual[i][j];
    }
  }
  return answer;
}

int main() {
  std::int_fast64_t n;
  std::cin >> n;
  std::vector<std::vector<std::int_fast64_t>> a(n, std::vector<std::int_fast64_t>(n));
  for (std::int_fast64_t i = 0; i < n; ++i) {
    for (std::int_fast64_t j = 0; j < n; ++j) {
      std::int_fast64_t a_ij;
      std::cin >> a_ij;
      a[i][j] = a_ij;
    }
  }

  std::cout << (a == warshall_floyd(a) ? calc_answer(a) : -1) << std::endl;
  return 0;
}

