#include <bits/stdc++.h>
using namespace std;

using ll = long long;

// ワ―シャルフロイド法 O(V^3)
void warshall_floyd(vector<vector<ll>> &M) { // 隣接行列Mを書き換える
  int n = M.size();
  for (int i = 0; i < n; i++) // 経由する頂点
    for (int j = 0; j < n; j++) // 始点
      for (int k = 0; k < n; k++) // 終点
        M[j][k] = min(M[j][k], M[j][i] + M[i][k]);
}

int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);

  int n;
  cin >> n;

  vector<vector<ll>> a(n, vector<ll>(n));
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < n; j++) {
      cin >> a.at(i).at(j);
    }
  }

  vector<vector<ll>> b = a;
  warshall_floyd(b);
  if (a != b) {
    cout << "-1\n";
    return 0;
  }

  ll sum = 0;
  for (int i = 0; i < n; i++) {
    for (int j = i + 1; j < n; j++) {
      sum += a.at(i).at(j);
    }
  }

  for (int i = 0; i < n; i++) {
    for (int j = i + 1; j < n; j++) {
      for (int k = 0; k < n; k++) {
        if (k == i || k == j) continue;
        if (a.at(i).at(j) == a.at(i).at(k) + a.at(k).at(j)) {
          sum -= a.at(i).at(j);
          break;
        }
      }
    }
  }

  cout << sum << '\n';
}

