vector<vector<ll>> d;

void warshall_floyd(){
	for(ll k = 0; k < n; k++){
		for(ll i = 0; i < n; i++){
			for(ll j = 0; j < n; j++){
				if(i == j){
					d[i][j] = 0;
					d[j][i] = 0;
				}else{
					d[i][j] = min(d[i][j], d[i][k] + d[k][j]);
				}
			}
		}
	}
}
std::vector<ll> dij;

void dijkstra(const Graph &G, ll s){
	std::priority_queue<P, std::vector<P>, std::greater<P>> que;
	for(ll i = 0; i < n; i++) dij[i] = INF;
	dij[s] = 0;
	que.push(P(0, s));

	while(!que.empty()){
		P p = que.top(); que.pop();
		ll v = p.second;
		if(dij[v] < p.first) continue;
		for(ll i = 0; i < G[v].size(); i++){
			Edge e = G[v][i];
			if(dij[e.to] > dij[v] + e.cost){
				dij[e.to] = dij[v] + e.cost;
				que.push(P(dij[e.to], e.to));
			}
		}
	}
}
int solve() {
	cin >> n;
	G.resize(n);
	a.resize(n, vl(n));
	d.resize(n, vl(n, INF));
	dij.resize(n);
	REP(i, n){
		REP(j, n){
			cin >> a[i][j];
			if(i != j){
				Edge e = {i, j, a[i][j]};
				G[i].push_back(e);
				d[i][j] = a[i][j];
			}else{
				Edge e = {i, j, 0};
				G[i].push_back(e);
			}
		}
	}
	vll d(n);
	REP(i, n){
		dijkstra(G, i);
		REP(j, n){
			d[i].push_back(dij[j]);
		}
	}
	bool flag = true;
	ll mi = INF;
	REP(i, n){
		REP(j, n){
			if(a[i][j] != d[i][j]){
				flag = false;
				break;
			}
			mi = min(mi, d[i][j]);
		}
