template<typename T> vector<vector<T>> pre_warshall_floyd(int n, T inf) {
    vector<vector<T>> g(n, vector<T>(n, inf));
    REP(i, n) g[i][i] = 0;
    return g;
}

template<typename T> T warshall_floyd(vector<vector<T>>& g) {
    ll needless = 0;
    int n = sz(g);
    REP(k, n) REP(i, n) REP(j, n) {
        if (g[i][j] == g[i][k] + g[k][j] && i != k && k != j) needless += g[i][j];
        chmin(g[i][j] ,g[i][k] + g[k][j]);
    }
    return needless;
}

void solve() {
    int n;
    cin >> n;
    vector<vector<ll>> g = pre_warshall_floyd(n, LINF);
    ll a;
    REP(i, n) REP(j, n) {
        cin >> a;
        if (i == j) continue;
        g[i][j] = a;
    }

    vector<vector<ll>> org = g;
    ll needless = warshall_floyd(g);

    ll ans = 0;
    REP(i, n) REP(j, n) {
        if (g[i][j] != org[i][j]) {
            cout << -1 << EOL;
            return;
        }
        ans += g[i][j];
    }

    cout << (ans - needless) / 2 << EOL; 
}

