    d[i][j] = INF*INF;
    mind[i][j] = dist;
    que.push(road({i, j, dist}));
  }

  long res = 0;
  bool canDo = true;
  while (!que.empty()) {
    road v = que.top();
    que.pop();

    if (v.from >= v.to) continue;
    if (v.dist < d[v.from][v.to]) {
      res += v.dist;
      d[v.from][v.to] = v.dist;
      d[v.to][v.from] = v.dist;
      rep(i, n) rep(j, n) {
        d[i][j] = min(d[i][j], d[i][v.from] + d[v.from][j]);
        d[i][j] = min(d[i][j], d[i][v.to] + d[v.to][j]);
      }
    } else if (v.dist > d[v.from][v.to]) {
      canDo = false;
      break;
    }
  }

  cout << (canDo?res:-1) << endl;
}

