void WF(ll N){      // nは頂点数
  // 経路復元の初期化
  rep(k,N){           // 経由する頂点
    rep(i,N){       // 開始頂点
      if(dp[i][k]==LINF){
        continue;
      }
      rep(j,N){   // 終端 
        if(dp[k][j]==LINF){
          continue;
        }
        if(dp[i][j]>dp[i][k]+dp[k][j]){
          dp[i][j] = min (dp[i][j],dp[i][k]+dp[k][j]);
        }
        if(dp[i][j]==dp[i][k]+dp[k][j]&& i!=k && k!=j){
          C[i][j]=1;
        }
      }
    }
  } 
}

