vector<vector<ll> > floyd(vector<vector<ll> > G) {
    vector<vector<ll> > F = G;
    for (int k = 0; k < N; k++) {
        for (int i = 0; i < N; i++) {
            if (F[i][k] == INF) continue;
            for (int j = 0; j < N; j++) {
                if (F[k][j] == INF) continue;
                F[i][j] = min(F[i][j], F[i][k] + F[k][j]);
            }
        }
    }
    return F;
