template<class T>
T read()
{
    T value;
    std::cin >> value;
    return value;
}

template<class F>
void times_do(size_t n, F func)
{
    for(size_t i = 0; i < n; ++i) func();
}

template<class T>
vector<T> reads(size_t n)
{
    vector<T> a;
    a.reserve(n);
    times_do(n, [&](){
        a.push_back(read<T>());
    });
    return a;
}

int main(){
    const int n = read<int>();

    vector<vector<int64_t>> mat;
    mat.reserve(n);

    times_do(n, [&](){
        mat.push_back(reads<int64_t>(n));
    });

    int64_t total = 0;

    for(int i = 0; i < n; ++i)
    for(int j = (i+1); j < n; ++j)
    {
        bool is_needed = true;
        for(int k = 0; k < n; ++k)
        {
            if(k == i || k == j) continue;
            int64_t d = mat[i][j] - (mat[i][k] + mat[k][j]);
            if(d > 0)
            {
                cout << "-1\n";
                return 0;
            }
            else if(d == 0)
            {
                is_needed = false;
            }
        }
        if(is_needed)
            total += mat[i][j];
    }
    cout << total << '\n';

    return 0;
}

