vector<vector<ll>> a(334, vector<ll>(334, 0));
vector<vector<ll>> dist(334, vector<ll>(334, inf));

void floyd(){
    rep(k, N){
        rep(i, N){
            if(dist[i][k] == inf) continue;
            rep(j, N){
                if(dist[k][j] == inf) continue;
                chmin(dist[i][j], dist[i][k] + dist[k][j]);
            }
        }
    }
}

