using Cost = int64_t;
using DistMat = std::vector< std::vector<Cost> >;

/**
 * Refine A by warshall-floyd.
 * \param A input distance matrix
 * \param out refined distance matrix
 * \param directs i->j is still direct after refinement(0: yes, -1: no)
 */
void warshall_floyd(
    const DistMat &A,
    DistMat &out,
    DistMat &directs)
{
  int N = (size_t) A.size();
  out.resize(N);
  directs.resize(N);
  for(int i=0; i<N; i++) {
    out[i].resize(N);
    directs[i].resize(N);
    for(int j=0; j<N; j++) {
      out[i][j] = A[i][j];
    }
  }

  // step
  for(int k=0; k<N; k++) {
    for(int i=0; i<N; i++) {
      for(int j=i+1; j<N; j++) {
        Cost d_prev = out[i][j], d_new = out[i][k] + out[k][j];
        if(d_new < d_prev) {  // impossible case
          out[i][j] = d_new;
          // std::cout << i << "->" << j << " impossible: " << d_new << " @k=" << k << std::endl;
        } else if(k != 0 && k != i && k != j && d_new == d_prev) {
          directs[i][j] = -1;
          // std::cout << i << "->" << j << " indirect: " << d_new << " @k=" << k << std::endl;
        } // in default, reserve outt[i][j]

        out[j][i] = out[i][j];
        directs[j][i] = directs[i][j];
      }
    }
  }
}

int main()
{
  // assume every path is direct
  // and then cut useless path

  // read input
  int N;
  std::cin >> N;

  DistMat A(N);
  for(int i=0; i<N; i++) {
    A[i].assign(N, 0);
    for(int j=0; j<N; j++) {
      std::cin >> A[i][j];
    }
  }

  DistMat mat_dists_wf;
  DistMat mat_directs;
  warshall_floyd(A, mat_dists_wf, mat_directs);

  // possibility and total costs
  Cost ret = 0;
  for(int i=0; i<N; i++) {
    for(int j=i+1; j<N; j++) {
      if(mat_dists_wf[i][j] < A[i][j]) {
        ret = -1;
        goto END;
      } else if(mat_directs[i][j] == 0) {
        // std::cout << i << ", " << j << ": " << A[i][j] << std::endl;
        ret += A[i][j];
      }
    }
  }

END:
  std::cout << ret << std::endl;
  return 0;
}

