		mincost[i] =INF;
		used[i] = false;
	}
	mincost[1]=0;

	while (1)
	{
		int	v=-1;
		for (int u = 1; u <= N; u++)
		{
			if(!used[u] && (v==-1||mincost[v]>mincost[u])){
				v = u;
			}
		}
		if(v==-1) break;

//		printf("%d,%d \n",v,total);
		used[v] = true;
		total += mincost[v];

		for (int i = 1; i <= N; i++)
		{
			mincost[i] = min(mincost[i], A[v][i]);
