void warshall_floyd(int v,vector<vector<ll> >& d){
    /*頂点の個数、コスト:d[u][v]はe=(u,v)のコスト(存在しない場合はINF,ただしd[i][j]=0とする)*/

    for(int k = 0;k < v;k++){
        for(int i = 0;i < v;i++){
            for(int j = 0;j < v;j++){
                if(i == k || k == j || i == j){
                    continue;
                }
                d[i][j]= min(d[i][j],d[i][k]+d[k][j]);
            }
        }
    }
}


