    using TYPE = pair<ll, P>;
    class CompareFirst{ public:
        bool operator()(TYPE n1, TYPE n2) {
            return n1.first > n2.first; //>:昇順　pairのfirst同士を比較する
            // return n1.first < n2.first; // 降順
        }
    };
    priority_queue<TYPE, vector<TYPE>, CompareFirst> q;

    rep(i, N){rep(j, N){
        if (i <= j){continue;}
        q.push(make_pair(wf[i][j], make_pair(i, j)));
    }}

    ll tmp = 0;
    bool global_flag = true;
    while (q.size() > 0){
        ll cost = q.top().first;
        ll i = q.top().second.first;
        ll j = q.top().second.second;
        q.pop();

        if (wf[i][j] != A[i][j]){global_flag = false; break;}

        bool flag = true;
        rep(k, N){
            if ((result[i][k] != INF) && (result[k][j] != INF) && (result[i][k] + result[k][j] <= cost)){ // edge exists!
                flag = false; break;
            }
        }
        // cout << i << " " << j << " " << flag << endl;

        if (flag){
            result[i][j] = cost;
            result[j][i] = cost;
            tmp += cost;
        }
    }

    ll ans = global_flag ? tmp : -1;
    cout << ans << endl;
}

