// typedef
typedef vector<int> vint;
typedef pair<int,int> pint;
typedef vector<pint> vpint;
typedef vector<vint> Matrix;



bool bellman_ford(Matrix graph, int n, int s) { // nは頂点数、sは開始頂点
    // 戻り値がtrueなら負の閉路を含む
    vint dist = vint(n, INF);
    dist[s] = 0; // 開始点の距離は0
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            for (int k = 0; k < n; k++) {
                if (j == k) continue;
                int cost = graph[j][k];
                if (dist[j] != INF && dist[k] > dist[j] + cost) {
                    dist[k] = dist[j] + cost;
                    if (i == n - 1) return true; // n回目にも更新があるなら負の閉路が存在
                }
            }
        }
    }
    return false;
}

Matrix warshall_floyd(Matrix d, int n) { // nは頂点数
    // d[i][j] : i,j間の最短距離
    // ﾖi d[i][i] < 0 -> 負の閉路が存在
    for (int i = 0; i < n; i++)      // 経由する頂点
        for (int j = 0; j < n; j++)    // 開始頂点
            for (int k = 0; k < n; k++)  // 終端
                d[j][k] = min(d[j][k], d[j][i] + d[i][k]);
    return d;
}

