    REP(i, N)REP(j, N)cin >> A[i][j];

    Matrix B = warshall_floyd(A, N);
    REP(i, N)REP(j, N){
            if(B[i][j] < A[i][j]){
                cout << -1;
                return 0;
            }
        }

    int suma = 0;
    REP(i, N)REP(j, N){
            suma += A[i][j];
        }

    int sum = 0;
    REP(i, N)REP(j, N){
            REP(w, N){
                if(w == i || w == j)continue;
                if(B[i][w] + B[w][j] == B[i][j]){
                    sum += B[i][j];
                    break;
                }
            }
        }
    cout << (suma - sum) / 2;

    return 0;
}

