namespace NyaGadget {}

namespace NyaGadget
{
	/***** 不要な辺を削除してグラフを最適化するライブラリ *****/

	struct GT_NyaaEdgeOptimization
	{
		static void Run(std::vector<std::vector<long long>>& mg)
		{	// 隣接行列から不要な辺を削除して返す
			auto size = (long long)mg.size();
			for (auto m = 0LL; m < size; ++m) for (auto l = 0LL; l < size; ++l) for (auto r = 0LL; r < size; ++r)
			{
				if (m == l || r == m) continue;
				if (mg[l][m] == 0 || mg[m][r] == 0) continue;
				if (mg[l][r] == mg[l][m] + mg[m][r]) mg[l][r] = 0;
			}
		}
	};
}

namespace NyaGadget
{
	/***** ワーシャルフロイド法ライブラリ *****/

	struct GT_WarshallFloyd
	{	// 結果を格納する変数
		std::vector<std::vector<long long>> res;

		/**
		@brief 全点対間最短路を求める
		@param mg 隣接行列
		@param inf 存在しない辺の値
		@note
		計算量O(V^3)なので隣接行列にしか適用できない。
		存在しない経路のコストは「LLONG_MAX」を返す。
		自己ループ（v[i]→v[i]）のコストはゼロとして返す。
		負の閉路がある場合falseを返す。
		**/
		bool Run(const std::vector<std::vector<long long>>& mg, long long inf)
		{
			const long long INF = LLONG_MAX;
			long long vmax = (long long)mg.size();

			res = mg;
			for (auto i = 0LL; i < vmax; ++i) for (auto j = 0LL; j < vmax; ++j)
			{
				if (i == j) res[i][j] = 0;
				if (res[i][j] == inf) res[i][j] = INF;
			}

			for (auto k = 0LL; k < vmax; k++)
			{
				for (auto i = 0LL; i < vmax; i++)
				{
					if (res[i][k] == INF) continue;
					for (auto j = 0LL; j < vmax; j++)
					{
						if (res[k][j] == INF) continue;
						res[i][j] = std::min(res[i][j], res[i][k] + res[k][j]);

					}
				}
			}
			for (auto i = 0LL; i < vmax; i++) if (res[i][i] < 0) return false;
			for (auto i = 0LL; i < vmax; i++) res[i][i] = 0;
			return true;
		}
	};
}

