template<class T> bool chmax(T &a, const T &b) { if (a<b) { a=b; return 1; } return 0; }
template<class T> bool chmin(T &a, const T &b) { if (a>b) { a=b; return 1; } return 0; }
int dy[]={-1,1,0,0};
int dx[]={0,0,-1,1};


struct UnionFind{
  vector<int> par;

  UnionFind(int N): par(N){
    for(int i=0;i<N;i++) par[i]=i;
  }

  int root(int x){
    if(par[x]==x) return x;
    else return par[x]=root(par[x]);
  }

  void unite(int x,int y){
    int rx=root(x);
    int ry=root(y);
    if(rx!=ry) par[rx]=ry;
  }

  bool sameroot(int x,int y){
    return root(x)==root(y);
  }

};

int N;
vector<pair<ll,int>> dists;
vector<pair<ll,int>> tonari[310];

int calc(int a,int b){
    vector<bool> det(N, false);
    vector<ll> dist(N,INF);
    priority_queue<pair<int,int>,vector<pair<int,int>>,greater<>> pq;
    dist[a]=0;
    pq.push(make_pair(0,a));
    while(!pq.empty()){
        int d=pq.top().first,node=pq.top().second;
        pq.pop();
        if(det[node]) continue;
        det[node]= true;
        for(auto tsugi:tonari[node]){
            if(det[tsugi.second]) continue;
            if(chmin(dist[tsugi.second],dist[node]+tsugi.first)){
                pq.push(make_pair(dist[tsugi.second],tsugi.second));
            }
        }
        //if(det[b]) return dist[b];
    }
    return dist[b];
}

int main() {
    cin>>N;
    int inp;
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            cin>>inp;
            if(i<j) dists.push_back(make_pair(inp,i*1000+j));
        }
    }
    sort(dists.begin(),dists.end());
    UnionFind uf(N);
    ll ans=0ll;
    for (auto itr:dists) {
        int d=itr.first, a=itr.second/1000, b=itr.second%1000;
        if(!uf.sameroot(a,b)){
            ans+=(ll)d;
            tonari[a].push_back(make_pair(d,b));
            tonari[b].push_back(make_pair(d,a));
            uf.unite(a,b);
        }else{
            int val=calc(a,b);
            //printf("%d,%d => %d %d \n",a,b,d,val);
            if(val>d){
                ans+=(ll)d;
                tonari[a].push_back(make_pair(d,b));
                tonari[b].push_back(make_pair(d,a));
            }else if(val<d){
                cout<<-1<<endl;
                return 0;
            }
        }
        //cout<<ans<<endl;
    }
    cout<<ans<<endl;
    return 0;
}

