using namespace std;

class DisjointSet
{
public:
    DisjointSet(int size) : fathers_(size, -1) {}

    void Unite(int a, int b);

    bool SameGroup(int a, int b);

private:
    int GetRoot(int node);

    vector<int> fathers_;
};

int DisjointSet::GetRoot(int node)
{
    if (fathers_[node] == -1) {
        return node;
    }
    return fathers_[node] = GetRoot(fathers_[node]);
}

void DisjointSet::Unite(int a, int b)
{
    auto root_a = GetRoot(a);
    auto root_b = GetRoot(b);

    if (root_a != root_b) {
        fathers_[root_b] = root_a;
    }
}

bool DisjointSet::SameGroup(int a, int b)
{
    return GetRoot(a) == GetRoot(b);
}

using Graph = vector<vector<int64_t>>;

int64_t Solve(const Graph &g)
{
    int64_t cost = 0;
    int n = g.size();

    for (int i = 0; i < n; i += 1) {
        for (int j = i + 1; j < n; j += 1) {
            auto direct_edge = true;
            for (int k = 0; k < n; k += 1) {
                if (i == j || i == k || j == k) {
                    continue;
                }
                if (g[i][k] + g[k][j] < g[i][j]) {
                    return -1;
                } else if (g[i][k] + g[k][j] == g[i][j]) {
                    direct_edge = false;
                }
            }
            if (direct_edge) {
                cost += g[i][j];
            }
        }
    }
    return cost;
}

