bool bellman(int start)
{
    fill(d, d + N, INF);
    d[start] = 0;
    priority_queue<pint, vector<pint>, greater<pint>> q;
    q.push(pint(0, start));
    while (q.size())
    {
        pint p = q.top();
        q.pop();
        int v = p.second;
        if (d[v] < p.first)
            continue;
        rep(i, N)
        {
            if (d[i] > d[v] + data[v][i])
            {
                d[i] = d[v] + data[v][i];
                q.push(pint(d[i], i));
            }
        }
    }
    rep(j, N)
    {
        if (data[start][j] != d[j])
        {
            return false;
        }
    }
    return true;
}

