struct LLPair {
	ll a = 0;
	ll b = 0;
	ll c = 0;
	LLPair() {}
	LLPair(ll a, ll b, ll c) {
		this->a = a;
		this->b = b;
		this->c = c;
	}
};

int main() {
	ll N;
	cin >> N;
	vvll graph(N, vll(N, INF)); //N頂点の隣接行列
	rep(i, N) rep(j, N) {
		cin >> graph[i][j];
	}

	//◆--↓--全頂点間の距離を求めるワーシャルフロイド法:O(N^3)--↓--
	//vvll dist(N, vll(N, INF));
	//rep(j, N) rep(i, N) {
	//	if (i == j) {
	//		dist[i][j] = 0;
	//	}
	//	else {
	//		dist[j][i] = graph[j][i];
	//	}
	//}

	////全頂点間の距離を求めるO(N^3)
	//rep(i, N) rep(j, N) rep(k, N) { // 経由する頂点-開始頂点-終端
	//	if (dist[j][i] == INF || dist[i][k] == INF) { //負の距離が含まれている場合は必要
	//		continue;
	//	}
	//	dist[j][k] = min(dist[j][k], dist[j][i] + dist[i][k]);
	//}
	//--↑--ワーシャルフロイド--↑--

	vector<LLPair> e(0);
	reps(i, 0, N - 1) reps(j, i + 1, N - 1) {
		e.emplace_back(LLPair(i, j, graph[i][j]));
	}
	std::sort(e.begin(), e.end(), [](const LLPair &a, const LLPair &b) {
		return a.c > b.c; //降順にするには > とする
	});

	ll numEdge = (ll)e.size();
	ll result = 0;
	rep(i, numEdge) {
		bool needed = true;

		//e[i].a -> e[i].b のコストと、他の任意のノードを経由するコストを比較
		rep(j, N) {
			if (j == e[i].a || j == e[i].b) {
				continue;
			}

			if (graph[e[i].a][j] == INF || graph[j][e[i].b] == INF) {
				continue;
			}

			ll cost = graph[e[i].a][j] + graph[j][e[i].b];

			if (graph[e[i].a][e[i].b] == cost) {
				//取り除きOK
				needed = false;
				break;
			}
			else if (graph[e[i].a][e[i].b] < cost){
				//必要
			}
			else {
				//矛盾
				cout << -1 << endl;
				return 0;
			}
		}

		if (needed) {
			result += graph[e[i].a][e[i].b];
		}
		else {
			graph[e[i].a][e[i].b] = INF;
			graph[e[i].b][e[i].a] = INF;
		}
	}

	cout << result << endl;

	return 0;
}

