            ll a;
            cin>>a;
            if(i>=j) que.emplace(-a,i,j);
        }
    }
    ll ans=0;
    while(!que.empty()){
        auto now=que.top(); que.pop();
        ll v;
        int i,j;
        tie(v,i,j)=now;
        v*=-1;
        if(d.query(i,j)>v){
            ans+=v;
            d.adbuild(i,j,v);
            d.adbuild(j,i,v);
        }else if(d.query(i,j)==v){
            continue;
        }else{
            cout<<-1<<endl;
            return 0;
        }
    }
    cout<<ans<<endl;
