ll A[MAX_N][MAX_N], warshall[MAX_N][MAX_N];

int main() {
    int N;
    cin >> N;
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            cin >> A[i][j];
            warshall[i][j] = A[i][j];
        }
    }
    // ワーシャルフロイドで実際の最短距離の表を作成
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            for (int k = 0; k < N; k++) {
                warshall[i][j] = min(warshall[i][j], warshall[i][k] + warshall[j][k]);
            }
        }
    }
    // 実際の表とワーシャルフロイドで求めた表が異なるかチェック
    for (int i = 0; i < N; i++ ) {
        for (int j = 0; j < N; j++) {
            if (A[i][j] != warshall[i][j]) {
                cout << -1 << endl;
                return 0;
            }
        }
    }
    // もう一度ワーシャルフロイド
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            for (int k = 0; k < N; k++) {
                if (i == k || j == k) continue;
                if (A[i][j] == A[i][k] + A[k][j]) {
                    is_checked[i][j] = true;
                }
            }
        }
    }
    ll ans = 0;
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            if (!is_checked[i][j]) {
                ans += A[i][j];
                is_checked[i][j] = is_checked[j][i] = true;
            }
        }
