    void unite(int x, int y) {
        x = find(x);
        y = find(y);
        if(x==y)return;
        if(r[x]<r[y])swap(x,y);
        if(r[x] == r[y])r[x]++;
        p[y] = x;
    }
    bool same(int x, int y){
        return find(x) == find(y);
    }
};

struct edge {
    ll to, cost;
};

int V;
vector<edge> G[MAX_V];
ll dmin[MAX_V];

void dijkstra(int s) {
    priority_queue<P, vector<P>, greater<P> > que;
    fill(dmin, dmin + V, LLINF);
    dmin[s] = 0;
    que.push(P(0, s));

    while (!que.empty()) {
        P p = que.top();
        que.pop();
        int v = p.second;
        if (dmin[v] < p.first)
            continue;
        for (int i = 0; i < G[v].size(); i++) {
            edge e = G[v][i];
            if (dmin[e.to] > dmin[v] + e.cost) {
                dmin[e.to] = dmin[v] + e.cost;
                que.push(P(dmin[e.to], e.to));
            }
        }
    }
}

ll solve(){
    vector<P3> es;
    REP(i,n){
        REP(j,n){
            if(i==j)continue;
            es.push_back(P3(d[i][j],{i,j}));
        }
    }
    sort(es.begin(),es.end());
    UF g;
    g.init(n);
    ll sum = 0;
    REP(i,es.size()){
        int u = es[i].second.first,v = es[i].second.second;
        if(!g.same(u,v)){
            sum += es[i].first;
            g.unite(u,v);
            G[u].push_back({v,es[i].first});
            G[v].push_back({u,es[i].first});
        }
        else{
            dijkstra(u);
            if(dmin[v]>d[u][v]){
                sum += es[i].first;
                G[u].push_back({v,es[i].first});
                G[v].push_back({u,es[i].first});
            }
        }
    }
    return sum;
}

