void dijkstra(ll start) {
  ll k;
  pll min;
  FOR(i, 0, n) {
	stt[i] = NOT;
	mini[i] = INF;
  }
  mini[start] = 0;
  pq2.push(make_pair(0, start));

  while (!pq2.empty()) {
	min = pq2.top();
	pq2.pop();
	m = min.second;
	stt[m] = COMP;

	if (mini[m] < min.first) continue;

	FOR(i, 0, edge2[m].size()) {
	  k = edge2[m][i].first;
	  if (stt[k] != COMP) {
		if (edge2[m][i].second + mini[m] < mini[k]) {
		  mini[k] = edge2[m][i].second + mini[m];
		  stt[k] = VIS;
		  pq2.push(make_pair(mini[k], k));
		}
	  }
	}
  }

}

