const int MAX_E = 300;
const int MAX_V = MAX_E * MAX_E;
const lint INF = 1e12;

struct edge{ int from, to; lint cost; };
vector<edge> G;
lint d[MAX_V];

int V, E;

bool cmp(const edge l, const edge r){
    return l.cost < r.cost;
}

void shortest_path(int s){
    for (int i = 0; i < V; i++) d[i] = INF;
    d[s] = 0;
    while(true){
        bool update = false;
        for (int i = 0; i < E; i++){
            edge e = G[i];
            if (d[e.from] != INF && d[e.to] > d[e.from] + e.cost){
                d[e.to] = d[e.from] + e.cost;
                update = true;
            }
        }
        if(!update) break;
    }
}

int main(){
    cin >> V;
    vector<edge> H;
    rep(i, V){
        rep(j, V){
            lint a; cin >> a;
            if(i == j) continue;
            H.push_back(edge{i, j, a});
        }
    }


    sort(all(H), cmp);
    rep(i, H.size()){
        edge e = H[i];
        E = G.size();
        shortest_path(e.from);
        if(d[e.to] > e.cost){
            G.push_back(e);
            G.push_back(edge{e.to, e.from, e.cost});
        }
        else if(d[e.to] < e.cost){
            cout << "-1" << endl;
            return 0;
        }
    }
    lint ans = 0;
    rep(i, G.size()){
        ans += G[i].cost;
    }
    ans /= 2; cout << ans << endl;
}

