ll dijkstra(int s,int g) {
  ll dis[330];
  for (int i = 0; i < N; i++) {
    dis[i] = INF;
  }
  priority_queue<pair<ll,ll>, vector<pair<ll,ll>>, greater<pair<ll,ll>>> Q;
  Q.push(make_pair(0,s));
  while (!Q.empty()) {
    pair<ll,ll> p = Q.top();
    Q.pop();
    if (p.F >= dis[p.S]) {
      continue;
    } else {
      dis[p.S] = p.F;
    }
    for (int i = 0; i < (int)Graph[p.S].size(); i++) {
      int w = Graph[p.S][i].F;
      if (dis[w] > p.F + Graph[p.S][i].S) {
        Q.push(make_pair(p.F + Graph[p.S][i].S,w));
      }
    }
  }
  return dis[g];
}

