//=============warshall_floyd============================
long long  warshall_floyd(long long V, vector<vector<long long>> d)
{
  map<pair<int, int>, int> made;
  long long neg_ans = 0;
  for (long long k = 0; k < V; ++k)
  {
    for (long long i = 0; i < V; ++i)
    {
      for (long long j = 0; j < V; ++j)
      {
        if (d[i][j] > d[i][k] + d[k][j])
        {
          return -1;
        }
        if (i != k && k != j)
        {
          if (d[i][j] == d[i][k] + d[k][j])
          {
            if (made[{i, j}] + made[{j, i}] == 0)
            {
              neg_ans += d[i][j];
              made[{i, j}] = 1;
              made[{j, i}] = 1;
            }
          }
        }
      }
    }
  }
  return neg_ans;
}
