  for (int i = 0; i < n; i++){
    for (int j = i + 1; j < n; j++){
      int tok = 1;
      for (int k = 0; k < n; k++){
        if (k != i && k != j && a[i][j] == a[i][k] + a[k][j])
          tok = 0;
        else if (a[i][j] > a[i][k] + a[k][j])
          ok = 0;
      }
      if (tok){
        res += a[i][j];
      }
    }
  }

  if (ok){
    cout << res << endl;
  }
  else {
    cout << -1 << endl;
  }

  return 0;
}

