#include <bits/stdc++.h>
using namespace std;
using ll = long long;

int N;
vector<vector<int>> A;
ll ans;

void warshall_floyd() {
  vector<vector<int>> B(A);
  for (int k = 0; k < N; k++) {
    for (int i = 0; i < N; i++) {
      for (int j = 0; j < N; j++) {
        B[i][j] = min(B[i][j], B[i][k] + B[k][j]);
      }
    }
  }

  for (int i = 0; i < N; i++) {
    for (int j = i + 1; j < N; j++) {
      if (ans == -1) break;
      if (A[i][j] > B[i][j]) {
        ans = -1;
      } else {
        bool ok = false;
        for (int k = 0; k < N; k++) {
          if (k != i && k != j && B[i][j] == B[i][k] + B[k][j]) ok = true;
        }
        if (!ok) ans += B[i][j];
      }
    }
  }
}

