using namespace std;

const int INF = std::numeric_limits<int>::max();

int main(void){
    int N;
    cin >> N;
    vector<vector<int>> A(N, vector<int>(N, 0));
    for(int i=0;i<N;i++){
        for(int j=0;j<N;j++){
            cin >> A[i][j];
        }
    }

    vector<vector<int>> w = A;
    for(int k=0;k<N;k++)
        for(int i=0;i<N;i++)
            for(int j=0;j<N;j++)
                w[i][j] = min(w[i][j], w[i][k]+w[k][j]);

    for(int i=0;i<N;i++){
        for(int j=0;j<N;j++){
            if(w[i][j] < A[i][j]){
                cout << "-1" << endl;
                return 0;
            }
        }
    }

    int ans = 0;
    for(int i=0;i<N;i++){
        for(int j=i+1;j<N;j++){
            bool need = true;
            for(int k=0;k<N;k++){
                if(k == i || k == j) continue;
                if(w[i][j] == w[i][k] + w[k][j]) need = false;
            }
            if(need) ans += w[i][j];
        }
    }

    cout << ans << endl;

    return 0;
}

