using namespace std;
using lli = long long int;

int main(){
  int n;
  std::cin >> n;
  vector<vector<lli> > adj(n, vector<lli>(n, 0));
  vector<vector<int> > mini;
  for (int i = 0; i < n; i++) {
    vector<int> tmp(3);
    for (int j = 0; j < n; j++) {
      std::cin >> adj[i][j];
      tmp[0] = adj[i][j], tmp[1] = i, tmp[2] = j;
      if(i < j)mini.push_back(tmp);
    }
  }
  sort(mini.begin(), mini.end());
  vector<vector<lli> > dist = adj;
  for (int k = 0; k < n; k++) {
    for (int i = 0; i < n; i++) {
      for (int j = 0; j < n; j++) {
        adj[i][j] = min(adj[i][j], adj[i][k] + adj[k][j]);
      }
    }
  }

  if(dist != adj){
    std::cout << -1 << std::endl;
    return 0;
  }
  dist = vector<vector<lli> >(n, vector<lli>(n, 2e9));
  for (int i = 0; i < n; i++) dist[i][i] = 0;
  lli ans = 0;
  for (int i = 0; i < mini.size(); i++) {
    int u = mini[i][1], v = mini[i][2];
    bool flag = false;
    for (int j = 0; j < n; j++) {
      for (int k = 0; k < n; k++) {
        lli md = dist[j][u] + adj[u][v] + dist[v][k];
        if(md < dist[j][k]){
          dist[j][k] = dist[k][j] = md;
          flag = true;
        }
      }
    }
    if(flag) ans += adj[u][v];
  }
  std::cout << ans << std::endl;
  return 0;
}

