#include <bits/stdc++.h>

using namespace std;

using ll = long long;

ll Solve() {
    int n;
    cin >> n;

    vector<vector<ll>> a(n, vector<ll>(n));
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            cin >> a[i][j];

    for (int k = 0; k < n; ++k)
        for (int i = 0; i < n; ++i)
            for (int j = 0; j < n; ++j)
                if (a[i][k] + a[k][j] < a[i][j]) return -1;

    struct Edge {
        int src, dst;
        ll w;
        Edge() {};
        Edge(int _s, int _d, ll _w) : src(_s), dst(_d), w(_w) {}
        bool operator<(const Edge &r) { return w > r.w; }
    };

    vector<Edge> edge;
    for (int i = 0; i < n; ++i)
        for (int j = i + 1; j < n; ++j)
            if (a[i][j] != 0) edge.emplace_back(Edge(i, j, a[i][j]));

    sort(edge.begin(), edge.end());
    for (auto e : edge) {
        if (a[e.src][e.dst] <= 0) continue;
        bool is_delete = false;
        for (int k = 0; k < n; ++k) {
            if (e.src != k && e.dst != k && a[e.src][k] != -1
                && a[k][e.dst] != -1 && a[e.src][k] + a[k][e.dst] == a[e.src][e.dst]) {
                is_delete = true;
                break;
            }
        }
        if (is_delete) {
            a[e.src][e.dst] = a[e.dst][e.src] = -1;
        }
    }

    ll len = 0;
    for (int i = 0; i < n; ++i)
        for (int j = i + 1; j < n; ++j) {
            if (a[i][j] != -1) len += a[i][j];
        }

    return len;
}

int main() {
    cin.tie(0); ios::sync_with_stdio(false);

    cout << Solve() << endl;

    return 0;
}

