typedef long long ll;

using namespace std;

typedef struct EDGE {
  int s,t;
  ll w;
} edge;

bool operator< ( const edge& x, const edge& y )
{
  if ( x.w != y.w ) return x.w < y.w;
  return x.s < y.s;
}

ll D[MAXN][MAXN];
bool F[MAXN][MAXN];
int N;
vector<edge> E;

bool warshal ( void )
{
  for ( int k = 0; k < N; ++k ) {
    for ( int i = 0; i < N; ++i ) {
      for ( int j = 0; j < N; ++j ) {
        ll tmp = D[i][j];
        D[i][j] = min( D[i][j], D[i][k]+D[k][j] );
        if ( tmp != D[i][j] ) return false;
      }
    }
  }

  return true;
}

ll cal ( void ) {
  if ( !warshal() ) return -1;

  ll ans = 0;
  sort(E.begin(), E.end() );

  for ( int i = 0; i < N; ++i ) for ( int j = 0; j < N; ++j ) F[i][j] = true;

  for ( auto it = E.begin(); it != E.end(); ++it ) {
    edge tmp = *it;
    //if ( !F[it->s][it->t] ) continue;
    for ( int i = 0; i < N; ++i ) {
      if ( tmp.t != i && tmp.w + D[tmp.t][i] == D[tmp.s][i] ) F[tmp.s][i] = F[i][tmp.s] = false;
      if ( tmp.s != i && tmp.w + D[tmp.s][i] == D[tmp.t][i] ) F[tmp.t][i] = F[i][tmp.t] = false;
    }
  }

  for ( int i = 0; i < N; ++i ) {
    for ( int j = 0; j < N; ++j ) {
      if ( F[i][j] ) ans += D[i][j];
    }
  }

  return ans/2;
}

