// ワーシャルフロイド法(全点間距離)
VVL d;//対角0,辺がないところはINF
void warshall_floyd(int n) {
  REP(k,n){       // 経由する頂点
    REP(i,n){    // 始点
      REP(j,n){  // 終点
        d[i][j] = min(d[i][j], d[i][k] + d[k][j]);
      }
    }
  }
}

void Main()
{
    int n;cin>>n;
    d.resize(n);
    VVL a(n);
    VVL b;
    REP(i,n){
        d[i].resize(n);
        a[i].resize(n);
        REP(j,n){
            LL t;cin>>t;
            d[i][j] = t;
            a[i][j] = t;
            b.PB({t,i,j});
        }
    }

    warshall_floyd(n);
    if(a != d){
        cout<<-1<<endl;
        return;
    }

    SORT_ASC(b);
    VVL dd(n);
    REP(i,n){
        dd[i].resize(n,INF_LL);
    }

    LL result = 0;
    for(auto x : b){
        LL dist = x[0];
        LL now = x[1];
        LL next = x[2];
        //cerr<<dist<<" "<<now<<" "<<next<<endl;

        bool f = true;
        if(dd[now][next] == dist){
            f = false;
        }
        REP(i,n){
            if(dd[now][i] + dd[i][next] == dist){
                f = false;
                break;
            }
        }

        if(f){
            result += dist;
            dd[now][next] = dist;
            dd[next][now] = dist;
            //dump(result)
        }
    }

    cout<<result<<endl;


	return;
}

