using namespace std;

long long n;
vector < pair<long long ,long long> > V[NM];
set < pair<long long, long long> > St;
long long M[NM][NM];

bool RF()
{
    long long i, j, k;
    for (k=1; k<=n; k++)
        for (i=1; i<=n; i++)
            for (j=1; j<=n; j++)
            {
                if (i==j || j==k || k==i) continue;
                if (M[i][j]>M[i][k]+M[j][k])
                    return 0;
            }
    return 1;
}

bool DJ(long long x)
{
    long long d[n+1], i, dist, nod, to, dt;
    for (i=1; i<=n; i++)
        d[i]=INF;
    St.insert(mp(0, x));
    d[1]=0;
    while (!St.empty())
    {
        dist=St.begin()->first;
        nod=St.begin()->second;
        St.erase(St.begin());
        for (i=1; i<=n; i++)
        {
            to=i;
            if (to==nod) continue;
            dt=M[nod][to];
            if (d[to]>dist+dt)
            {
                d[to]=dist+dt;
                St.insert(mp(M[nod][to], to));
            }
        }
    }
    for (i=1; i<=n; i++)
        if (M[x][i]!=d[i])
            return 0;
    return 1;
}

