        return 0;
    }
    for (i=1; i<=n; i++)
    {
        for (j=i+1; j<=n; j++)
        {
            long long aux=M[i][j];
            M[i][j]=INF;
            M[j][i]=INF;
            if (DJ(i))
            {
                M[i][j]=aux;
                M[j][i]=aux;
                sum+=M[i][j];
            }
        }
    }
    cout<<sum;
    return 0;
}

