#include "bits/stdc++.h"

using namespace std;

const long long INF = 1000000000000000000LL;

struct Edge {
    long long start;
    long long end;
    long long length;
};

bool comp(const Edge& e1, const Edge& e2) {
    return e1.length < e2.length;
}

void Main() {
    long long N;
    cin >> N;
    vector<vector<long long>> A(N, vector<long long>(N, -1LL));
    vector<Edge> edges;
    for (long long i = 0; i < N; ++i) {
        for (long long j = 0; j < N; ++j) {
            cin >> A[i][j];
            if (i < j) {
                Edge e;
                e.start = i;
                e.end = j;
                e.length = A[i][j];
                edges.push_back(e);
            }
        }
    }
    sort(edges.begin(), edges.end(), comp);

    vector<vector<long long>> loads(N, vector<long long>(N, INF));
    for (long long i = 0; i < N; ++i) {
        loads[i][i] = 0LL;
    }
    for (long long i = 0; i < edges.size(); ++i) {
        long long s = edges[i].start;
        long long e = edges[i].end;
        long long l = edges[i].length;
        bool redundant = false;
        for (long long r = 0; r < N; ++r) {
            if (r != s && r != e && loads[r][s] < INF && loads[r][e] < INF && loads[r][s] + loads[r][e] <= l) {
                redundant = true;
                break;
            }
        }
        if (redundant) {
            break;
        }
        else {
            loads[s][e] = l;
            loads[e][s] = l;
        }
    }
    vector<vector<long long>> loadsOrg = loads;

    for (long long i = 0; i < N; ++i) {
        for (long long j = 0; j < N; ++j) {
            for (long long k = 0; k < N; ++k) {
                loads[i][j] = min(loads[i][j], loads[i][k] + loads[k][j]);
            }
        }
    }

    bool ok = true;
    for (long long i = 0; i < N; ++i) {
        for (long long j = 0; j < N; ++j) {
            if (A[i][j] != loads[i][j]) {
                ok = false;
                break;
            }
        }
        if (!ok) {
            break;
        }
    }

    if (ok) {
        long long ans = 0LL;
        for (long long i = 0; i < N; ++i) {
            for (long long j = i + 1; j < N; ++j) {
                if (loadsOrg[i][j] < INF)
                ans += loadsOrg[i][j];
            }
        }
        cout << ans << endl;
    }
    else {
        cout << -1 << endl;
    }
}

int main() {
    std::cout << std::fixed << std::setprecision(15);
    Main();
    return 0;
}

