int main() {
	// 頂点i,j間の距離dp[i][j]=INFから更新していく。
	// ワーシャルフロイドのアルゴリズムのように，長さdの辺(u,v)を追加した際にdp[i][j]をd,u,vを用いて更新する。
	// A[i][j] < dp[i][j] であるような(i,j)が存在した場合，構成不可
	// A[i][j] > dp[i][j] であるようなA[i][j]のうち最小のもの(複数あることがある)について，iとjは辺で直接結ばれていなければならない。そのような(i,j)は複数あることがあるが，いずれの組についても同様にいえる。どちらもA[i][j] > 0(i!=j)から従う。
	// A[i][j] = dp[i][j] であるような(i,j)につき，道路を追加する必要はない。
	// 0-ind
	const ll INF = 1e12 + 7;
	int N; cin >> N;
	vvi A(N, vi(N));
	rep(i, N) rep(j, N) cin >> A[i][j];
	vvl dp(N, vl(N, INF)); rep(i, N) dp[i][i] = 0;
	priority_queue<ti3, vector<ti3>, greater<ti3>> q;
	rep(i, N - 1) rep2(j, i + 1, N) q.push(ti3(A[i][j], i, j));	// i < j
	ll ans = 0;
	while (!q.empty()) {
		int d, u, v; tie(d, u, v) = q.top(); q.pop(); // d = (A[u][v], u, v)
		// db3l(d,u,v);
		if (dp[u][v] != INF and d > dp[u][v]) {
			ans = -1;
			break;
		} else if (d < dp[u][v]) {
			ans += d; // u-v間に長さA[u][v]の道路追加
			/*
			rep(i, N - 1) rep2(j, 1, N) {
				dp[j][i] = dp[i][j] = min({ dp[i][j], dp[i][u] + d + dp[u][j], dp[i][v] + d + dp[u][j] });
			}
			*/
			rep(i, N) rep(j, N) {
				dp[j][i] = dp[i][j] = min({ dp[i][j], dp[i][u] + d + dp[u][j], dp[i][v] + d + dp[u][j] });			
			}
		}
		// dbvv(dp);
	}
	dbout(ans);	
}

