int main()
{
	std::ios::sync_with_stdio(false);

	int N;
	cin >> N;

	vector<vector<int>> A;
	resize(A, N, N);
	for (int i = 0; i < N; ++i) {
		for (int j = 0; j < N; ++j) {
			cin >> A[i][j];
		}
	}

	udvgraph_m graph(N);
	for (int i = 0; i < N; ++i) {
		for (int j = i; j < N; ++j) {
			graph.addEgde(i, j, (ull)A[i][j]);
		}
	}

	graph.warshallFloyd();
	vector<vector<ull>> distMapOrigin = graph.getMinimumDistMap();

	// 非存在チェック
	for (int i = 0; i < N; ++i) {
		for (int j = i; j < N; ++j) {
			if (distMapOrigin[i][j] < A[i][j]) {
				cout << -1 << endl;
				return 0;
			}
		}
	}

	// 必要な道だけ残す
	for (int i = 0; i < N; ++i) {
		for (int j = i; j < N; ++j) {
			ull cost = graph.getCostMap()[i][j];
			graph.removeEgde(i, j);
			graph.dijkstraSearch(i);
			const vector<ull>& dist = graph.getMinimumDists();
			if (dist[j] > A[i][j]) {
				// 距離が遠くなったときだけ道を復活
				graph.addEgde(i, j, cost);
			}
		}
	}

	// 残った道の距離の総和を計算
	ull sum = 0;
	for (auto a : graph.getNodes()) {
		for (auto b : a.getEgde()) {
			ull cost = b.first.getCost();
			sum += cost;
		}
	}
	sum /= 2; // 往復分が入っているので２で割る

	cout << sum << endl;
	getchar();
	getchar();

}

