long long warshallFloyd(int m[MAX_V][MAX_V], int n, bool f){
	rep(k,n){
		rep(i,n){
			rep(j,n){
				if(f){
					if(m[i][k] == INF || m[k][j] == INF) continue;
					if(i == k || j == k) continue;
					if(m[i][j] == m[i][k] + m[k][j]){
						m[i][j] = INF;
					}
				}else{
					m[i][j] = min(m[i][j], m[i][k] + m[k][j]);
				}
			}
		}
	}

	long long cnt = 0;
	rep(i,n){
		rep(j,n){
			if(m[i][j] != INF) cnt += m[i][j];
		}
	}
	return cnt / 2;
}

