int main() {
  int N;
  cin >> N;
  int a[N][N];
  for (int i = 0; i < N; i++) {
    for (int j = 0; j < N; j++) {
      scanf("%d", a[i] + j);
    }
  }

  ll dist[N][N];
  for (int i = 0; i < N; i++) {
    for (int j = 0; j < N; j++) {
      dist[i][j] = a[i][j];
    }
  }

  // ワーシャルフロイド
  for (int k = 0; k < N; k++) {
    for (int i = 0; i < N; i++) {
      for (int j = 0; j < N; j++) {
        dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j]);
      }
    }
  }

  // 題意の道路の形状が存在するかどうか判定
  bool flag = true;
  for (int i = 0; i < N; i++) {
    for (int j = 0; j < N; j++) {
      if (dist[i][j] != a[i][j]) flag = false;
    }
  }

  // グラフ内の三角形全てにおいて、辺を消しても最短距離が変わらない箇所があればグラフから消す
  ll ans = -1;
  if (flag) {
    bool need[N][N];
    fill(need[0], need[N-1], true);
    for (int i = 0; i < N; i++) {
      for (int j = 0; j < N; j++) {
        for (int k = 0; k < N; k++) {
          if (k == i || k == j || i == j) continue;
          if (dist[i][j] == dist[i][k] + dist[k][j]) {
            need[i][j] = false;
          }
        }
      }
    }

    ans = 0;
    for (int i = 0; i < N; i++) {
      for (int j = i; j < N; j++) {
        if (!need[i][j]) continue;
        ans += dist[i][j];
      }
    }
  }

  // 解答
  cout << ans << endl;

  return 0;
}

