const int MAX_N = 305;
const long long INF = (long long)1000000000 * MAX_N * 2;

struct Info {
    int from;
    int to;
    long long dist;
};

bool compare (const Info& i1, const Info& i2) {
    return i1.dist < i2.dist;
}

int N;
long long A[MAX_N][MAX_N];

long long C[MAX_N][MAX_N];

int main(int argc, char **argv) {
    std::cin >> N;
    for (int i = 1; i <= N; i++) {
        for (int j = 1; j <= N; j++) {
            std::cin >> A[i][j];
        }
    }

    std::vector<Info> infos;
    for (int i = 1; i <= N; i++) {
        for (int j = i + 1; j <= N; j++) {
            Info in;
            in.from = i;
            in.to = j;
            in.dist = A[i][j];
            infos.push_back(in);
        }
    }
    std::sort(infos.begin(), infos.end(), compare);

    for (int i = 1; i <= N; i++) {
        for (int j = 1; j <= N; j++) {
            C[i][j] = INF;
        }
        C[i][i] = 0;
    }

    long long ret = 0;
    for (auto info : infos) {
        if (C[info.from][info.to] < info.dist) {
            std::cout << -1 << std::endl;
            return 0;
        } else if (info.dist < C[info.from][info.to]) {
            C[info.from][info.to] = info.dist;
            C[info.to][info.from] = info.dist;
            ret += info.dist;
            for (int i = 1; i <= N; i++) {
                C[i][info.to] = std::min(C[i][info.to], C[i][info.from] + C[info.from][info.to]);
                C[i][info.from] = std::min(C[i][info.from], C[i][info.to] + C[info.to][info.from]);

                C[info.to][i] = C[i][info.to];
                C[info.from][i] = C[i][info.from];
            }
        }
    }

    std::cout << ret << std::endl;
    return 0;

}

