/* warshall_floyd.cpp
    ワーシャルフロイド法を用いて、全点間最短路を求める。

    初期化：dis[i][j] = iからjへの距離(辺がなければINF) (i≠j)
            dis[i][i] = 0
            prev[i][j] = i

    負閉路の検出：dis[i][i] < 0 となる i が存在するか

    verified:
        http://judge.u-aizu.ac.jp/onlinejudge/description.jsp?id=GRL_1_C&lang=ja
*/

#include <bits/stdc++.h>
using namespace std;
const long long INF = 1e17;

void warshall_floyd(vector<vector<long long>> &dis, vector<vector<long long>> &prev) {
    int V = dis.size();
    for (int k = 0; k < V; k++) {
        for (int i = 0; i < V; i++) {
            for (int j = 0; j < V; j++) {
                if (dis[i][k] + dis[k][j] < dis[i][j]) {
                    dis[i][j] = dis[i][k] + dis[k][j];
                    prev[i][j] = prev[k][j];
                }
            }
        }
    }
}
void back_warshall_floyd(vector<vector<long long>> &dis) {
    int V = dis.size();
    for (int k = 0; k < V; k++) {
        for (int i = 0; i < V; i++) {
            for (int j = 0; j < V; j++) {
                if (i != k && k != j && j != i && dis[i][k] + dis[k][j] == dis[i][j]) {
                    dis[i][j] = INF;
                }
            }
        }
    }
}

/* get_path(prev, s, t)
    入力：warshall_floyd で得た prev, スタート s, ゴール t
    出力：s から t への最短路のパス
*/
vector<int> get_path(const vector<vector<long long>> &prev, int s, int t) {
    vector<int> path;
    for (int cur = t; cur != s; cur = prev[s][cur]) {
        path.push_back(cur);
    }
    path.push_back(s);
    reverse(path.begin(), path.end());
    return path;
}

/* is_negative(dis)
    入力：warshall_floyd で得た dis
    出力：負の有向路を含むかどうか
*/
bool is_negative(const vector<vector<long long>> &dis) {
    int V = dis.size();
    for (int i = 0; i < V; i++) {
        if (dis[i][i] < 0) {
            return true;
        }
    }
    return false;
}

