};

template< typename T >
using Edges = vector< edge< T > >;
template< typename T >
using WeightedGraph = vector< Edges< T > >;
using UnWeightedGraph = vector< vector< int > >;
template< typename T >
using Matrix = vector< vector< T > >;

template< typename T >
pair<vector< T >, vector<int>> dijkstra(vector<int> &shortest, WeightedGraph< T > &g, int s) {
    const auto INF = numeric_limits< T >::max();
    vector< T > dist(g.size(), INF);
    vector<int> remove;

    using Pi = pair< T, int >;
    priority_queue< Pi, vector< Pi >, greater< Pi > > que;
    dist[s] = 0;
    que.emplace(dist[s], s);
    while(!que.empty()) {
        T cost;
        int idx;
        tie(cost, idx) = que.top();
        que.pop();
        if(dist[idx] < cost) continue;
        for(auto &e : g[idx]) {
            auto next_cost = cost + e.cost;
            if(dist[e.to] < next_cost) continue;
            if (dist[e.to] == next_cost) {
                if (dist[e.to] == shortest[e.to] && e.src != s) {
                    remove.push_back(shortest[e.to]);
                }
                continue;
            }
            dist[e.to] = next_cost;
            if (shortest[e.to] > dist[e.to] && e.to != s) remove.push_back(-1);
            que.emplace(dist[e.to], e.to);
        }
    }
    return {dist, remove};
}


