            return os;
        }
    };
    struct Vertex {
        ll cost{(ll)1e9 + 1};
        explicit Vertex(const ll& _cost) : cost(_cost) { }
        friend std::ostream& operator <<(std::ostream& os, const Vertex& v) { os << "cost : " << v.cost; return os; }
    };
    const Type edge_type;
    std::vector<Vertex> vertices;
    std::vector<std::map<int, std::shared_ptr<Edge>>> edges;
    Graph(const int&  num_vertex,
          const Type& edge_type,
          const ll& vertex_init_cost = (ll)1e9 + 1) :
        edge_type(edge_type),
        vertices(num_vertex, Vertex(vertex_init_cost)),
        edges(num_vertex) { }
    void setCostToAllVertex(const ll& val) {
        std::fill(vertices.begin(), vertices.end(), Vertex(val));
    };
    void addEdge(const int& src, const int& dst, const ll& cost = 1) {
        auto edge = std::make_shared<Edge>(src, dst, cost);
        edges[src].emplace(dst, edge);
        if(edge_type == Type::Undirected) edges[dst].emplace(src, edge);
    }
    friend std::ostream& operator <<(std::ostream& os, const Graph& g) {
        os << std::endl
           << "--- Vertex Information ---" << std::endl;
        for(size_t i = 0; i < g.vertices.size(); i++) { os << "[[" << i << "] " << g.vertices[i] << "]" << std::endl; }
        os << "---- Edge Information ----" << std::endl;
        for(const auto& ee : g.edges) { for(const auto& e : ee) { os << "[" << e.second << "]" << std::endl; }}
        os << "--------------------------";
        return os;
    }
};

/**
 *  全頂点間の最短距離を求める(Warshall-Floyd法)
 *  NOTE: 計算量O(|V|^3)
 *  @Return: array[i][j] :: 頂点iから頂点jまでの最短距離
 */
// 使用例(グラフの直径)
// auto table    = warshall_floyd(g);
// auto diameter = 0;
// REP(i, g.vertices.size()) {
//     REP(j, g.vertices.size()) {
//         if(j <= i) continue;
//         chmax(diameter, table[j][i]);
//     }
// }
std::vector<std::vector<ll>> warshall_floyd(const Graph& g,
                                            const ll& inf_val = (ll)1e18 + 1) {
    std::vector<std::vector<ll>> dp(g.vertices.size(), std::vector<ll>(g.vertices.size(), inf_val));
    for(const auto& ee : g.edges) for(const auto& e : ee) dp[e.second->src][e.second->dst] = e.second->cost;
    for(size_t i = 0; i < g.vertices.size(); i++)
        for(size_t j = 0; j < g.vertices.size(); j++)
            for(size_t k = 0; k < g.vertices.size(); k++)
                dp[j][k] = std::min(dp[j][k], dp[j][i] + dp[i][k]);
    return dp;
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    ll N;
    std::cin >> N;

    Graph g(N, Graph::Type::Undirected);

    vector<vector<ll>> A(N, vector<ll>(N, 0));
    REP(i, N) {
        REP(j, N) {
            std::cin >> A[i][j];
            if(i <= j) continue;
            g.addEdge(i, j, A[i][j]);
        }
    }

    auto dp = warshall_floyd(g);

    ll ans = 0;
    [&]() {
        REP(i, N) {
            REP(j, N) {
                if(i <= j) continue;
                if(dp[i][j] < A[i][j]) {
                    ans = -1;
                    return;
                }
                bool direct = true;
                REP(k, N) {
                    if(k == i || k == j) continue;
                    if(dp[i][j] == A[i][k] + A[k][j]) {
                        direct = false;
                        break;
                    }
                }
                if(direct) ans += dp[i][j];
            }
        }
    }();

    std::cout << ans << std::endl;

    return 0;
}

