#define INF 2147483647
#define KNUM 10

int main() {
    // 
    int nVertex;
    cin >> nVertex;
    // 
    vector<vector<int>> a(nVertex, vector<int>(nVertex));
    for (int i = 0; i < nVertex; i++){
        for (int j = 0; j < nVertex; j++){    
            cin >> a.at(i).at(j);
        }
    }

    // ワーシャルフロイド法を逆に使う　
    vector<vector<int>> dp(nVertex, vector<int>(nVertex));
    for (int i = 0; i < nVertex; i++){
        for (int j = 0; j < nVertex; j++){
            dp[i][j] = a[i][j];
        }
    }

    for (int k = 0; k < nVertex; k++){
        for (int i = 0; i < nVertex; i++){
            for (int j = 0; j < nVertex; j++){
                if (i == j || j == k || k == i || dp[i][k] == -1 || dp[k][j] == -1){        // k を経由地としないと、以下の if 文で道路ない判定されてしまう
                    continue;
                }
                if (a[i][j] == dp[i][k] + dp[k][j]){                                        // 条件設定ミス dp[i][j] -> a[i][j]
                    dp[i][j] = -1;
                }
                else if(a[i][j] > dp[i][k] + dp[k][j]){
                    cout << -1 << endl;
                    return 0;
                }
            }
        }        
    }

    // 
    long lenSum = 0; 
    for (int i = 0; i < nVertex; i++){
        for (int j = i + 1; j < nVertex; j++){
            if (dp[i][j] != -1){
                lenSum += (long)dp[i][j];
            }
        }
    }

    cout << lenSum << endl;

    return 0;
}

