using Edge = pair<ll, pii>; // cost,from,to
using vl = vector<vector<ll>>;
vl d;
int n;

// O(|E| log |V|)
using Dist = ll; using Vertex = int;
using Pair = pair<Dist, Vertex>;
struct edge { Vertex to; Dist cost; };
using Graph = vector<vector<edge>>;
vector<Dist> dijkstra(const Graph& G, Vertex s) {
    priority_queue<Pair, vector<Pair>, greater<Pair>> pq;
    vector<Dist> d(n, INFLL); d[s] = 0;
    pq.push(Pair(0, s));
    while (pq.size()) {
        Pair p = pq.top(); pq.pop();
        Vertex v = p.second;
        if (d[v] < p.first) continue;
        for (const edge& e : G[v]) {
            Dist nd = d[v] + e.cost;
            if (d[e.to] > nd) {
                d[e.to] = nd;
                pq.push(Pair(d[e.to], e.to));
            }
        }
    }
    return d;
}

int main() {
    cin.tie(0), ios::sync_with_stdio(0);
    cin >> n;
    d.assign(n, vector<ll>(n, INFLL));
    rep(i, n) rep(j, n) cin >> d[i][j];
    vl t = d;
    rep(k, n) rep(i, n) rep(j, n) {
        chmin(d[i][j], d[i][k] + d[k][j]);
    }
    if (d != t) {
        cout << -1 << endl; return 0;
    }

    vector<Edge> es;
    rep(i, n) rep(j, n) if (i != j) {
        es.push_back(make_pair(d[i][j], pii{i,j}));
    }
    sort(es.begin(), es.end());

    ll ans = 0;
    Graph G(n);
    for (Edge& e : es) {
        ll cost = e.first;
        int u = e.second.first, v = e.second.second;
        auto nd = dijkstra(G, u);
        if (nd[v] != d[u][v]) {
            ans += cost;
            G[u].push_back(edge{v,cost});
            G[v].push_back(edge{u,cost});
        }
    }
    cout << ans << "\n";

    return 0;
}

