typedef vector<vector<int> > Matrix;
Matrix d,m;

void warshall_floyd(int n) { // nは頂点数
  for (int i = 0; i < n; i++)      // 経由する頂点
    for (int j = 0; j < n; j++)    // 開始頂点
      for (int k = 0; k < n; k++)  // 終端
        m[j][k] = min(m[j][k], m[j][i] + m[i][k]);
}

int main() {
  int N, i,j,k;
  long long ans;
  cin >> N;
  d = Matrix(N, vector<int>(N));
  m = Matrix(N, vector<int>(N));

  for (i = 0; i < N; i++){
    for (j = 0; j < N; j++){
          cin >> d[j][i];
          m[j][i]=d[j][i];
    }
  }

  warshall_floyd(N);

  for(int i = 0; i < N; i++){
    for(int j = 0; j < N; j++){
      if(i<j)ans+=m[j][i];

      //条件の判定
      if(m[j][i]!=d[j][i]){
          cout<<-1<<endl;
          return 0;
      }
      //存在しない道を取り除く
      for(int k = 0; k < N; k++){
        if(k == i || k == j) continue;
		if(m[j][i] == m[j][k]+m[k][i] && i < j){
            ans -= m[j][i];
            break;
        }
      }
    }
  }
  cout<<ans<<endl;
  return 0;
}

