    for(int k=0;k<n;k++){
        for(int i=0;i<n;i++){
            for(int j=0;j<n;j++){
                if(d[i][j] > d[i][k]+d[k][j]){
                    update = true;
                }else if(d[i][j] == d[i][k]+d[k][j] && k != i && k != j){
                    need[i][j] = false;
                }
            }
        }
    }
    if(!update){
        ll sum = 0;
        for(int i=0;i<n;i++){
            for(int j=i+1;j<n;j++){
                if(need[i][j]) sum += d[i][j];
            }
        }
        cout << sum << endl;
    }else{
        cout << -1 << endl;
    }
    return 0;
}

