  int to;
  long dist;

  bool operator>(road other) const {
    return dist > other.dist;
  }
};

long d[MAX_V][MAX_V];
long mind[MAX_V][MAX_V];

int main()
{
  cin.tie(0);
  ios::sync_with_stdio(false);

  int n;
  cin >> n;

  priority_queue<road, vector<road>, greater<road>> que;

  rep(i, n) rep(j, n) {
    long dist;
    cin >> dist;

    d[i][j] = INF*INF;
    mind[i][j] = dist;
    que.push(road({i, j, dist}));
  }

  long res = 0;
  bool canDo = true;
  while (!que.empty()) {
    road v = que.top();
    que.pop();

    if (v.from >= v.to) continue;
    if (v.dist < d[v.from][v.to]) {
      res += v.dist;
      d[v.from][v.to] = v.dist;
      d[v.to][v.from] = v.dist;
      rep(k, n) rep(i, n) rep(j, n) {
        d[i][j] = min(d[i][j], d[i][k] + d[k][j]);
      }
    } else if (v.dist > d[v.from][v.to]) {
      canDo = false;
      break;
    }
  }

  cout << (canDo?res:-1) << endl;
}

