struct WarshallFloyd{
    int V;
    vector<vector<long long>> d;
    vector<vector<long long>> to;
    WarshallFloyd(int n){
        start(n);
    }
    void start(int x){
        V=x;
        vector<vector<long long>> e(x,vector<long long>(x,INF));
        vector<vector<long long>> e2(x,vector<long long>(x));
        for(int i=0;i<x;i++){
            e[i][i]=0;
            for(int j=0;j<x;j++){
                e2[i][j]=j;
            }
        }
        swap(d,e);
        swap(to,e2);
    }
    void add1(int x,int y,long long c){
        d[x][y]=c;
    }
    void add2(int x,int y,long long c){
        d[x][y]=c;
        d[y][x]=c;
    }
    void build(){
        for(int k=0;k<V;k++){
            for(int i=0;i<V;i++){
                for(int j=0;j<V;j++){
                    if(d[i][j]>d[i][k]+d[k][j]){
                        d[i][j]=d[i][k]+d[k][j];
                        to[i][j]=to[i][k];
                    }
                }
            }
        }
    }
    long long dist(int x,int y){
        return d[x][y];
    }
    vector<int> route(int x,int y){
        vector<int> path;
        for(int i=x;i!=y;i=to[i][y]){
            path.emplace_back(i);
        }
        path.emplace_back(y);
        return path;
    }
};

