    priority_queue<P, vector<P>, greater<P> > que;
    fill(d1, d1+V, INF);
    d1[s] = 0LL;
    que.push(P(0LL, s));

    while(!que.empty()){
        P p = que.top(); que.pop();
        ll v = p.second;
        if(d1[v] < p.first) continue;
        for(ll i = 0; i < G1[v].size(); i++){
            edge e = G1[v][i];
            if(d1[e.to] > d1[v] + e.cost){
                d1[e.to] = d1[v] + e.cost;
                que.push(P(d1[e.to], e.to));
            }
        }
    }
}


