using Dist = ll;
const int VMAX = 303;
Dist cost[VMAX][VMAX];
vector<Dist> dijkstra(int s) {
    vector<Dist> d(n, INFLL); d[s] = 0;
    vector<int> used(n, 0);
    while (1) {
        int v = -1;
        for (int to = 0; to < n; to++) if (!used[to] && (v == -1 || d[to] < d[v])) v = to;
        if (v == -1) break;
        used[v] = 1;
        for (int to = 0; to < n; to++) {
            Dist nd = d[v] + cost[v][to];
            if (nd < d[to]) d[to] = nd;
        }
    }
    return d;
}

