const int inf = 1e9+9;
const int maxv = 310;
int N, G[maxv][maxv], G_[maxv][maxv], rm[maxv][maxv], dist[maxv];

int shortest(const int src, const int tgt)
{
    FOR(i,0,N)
        dist[i] = inf;
    dist[src] = 0;
    queue<int> Q; Q.push(src);
    while (Q.size()) {
        const int u = Q.front(); Q.pop();
        FOR(v,0,N) if (u != v && !rm[u][v]) {
            const int d = dist[u]+G[u][v];
            if (d < dist[v]) {
                dist[v] = d; Q.push(v);
            }
        }
    }
    return dist[tgt];
}

