    vector<optional<T>> v;
    ov(int i = 0, T val = 0):v(i, val){}
    template<class U>ov(const U& rhs){v.resize(sz(rhs));for (int i  = 0; i  < sz(rhs); i ++)v[i].set(rhs[i]);}
    optional<T> &operator()(int i) {if (i < 0 || sz(v) <= i) {emp.reset();return emp;} else { return v[i]; }}
