template<class T> inline bool chmax(T& a, T b) { if (a < b) { a = b; return true; } return false; }
template<class T> inline bool chmin(T& a, T b) { if (a > b) { a = b; return true; } return false; }

const long long INF = 1e18;

int n;
vector< vector<long long> > a(330, vector<long long>(330, 0));
vector< vector<long long> > dp(330, vector<long long>(330, INF));

int main() {
    cin >> n;
    for(int i = 0; i < n; ++i) {
        for(int j = 0; j < n; ++j) {
            cin >> a.at(i).at(j);
        }
    }

    for(int k = 0; k < n; ++k) {
        for(int i = 0; i < n; ++i) {
            for(int j = 0; j < n; ++j) {
                chmin(dp[i][j], a[i][k]+a[k][j]);
            }
        }
    }

    bool flg = true;
    long long ans = 0;
    for(int i = 0; i < n; ++i) {
        for(int j = i+1; j < n; ++j) {
            if(a[i][j] > dp[i][j]) {
                flg = false;
                break;
            }else {
                long long alen = INF;
                for(int k = 0; k < n; ++k) {
                    if(i != k && j != k) {
                        chmin(alen, a[i][k]+a[k][j]);
                    }
                }
                if(alen > dp[i][j]) {
                    ans += dp[i][j];
                }
            }
        }
    }

    if(flg) cout << ans << endl;
    else cout << -1 << endl;
}

