constexpr ll N_MAX = 300;
constexpr ll I_MAX = 1000000000;

ll N;
ll A[N_MAX][N_MAX];
ll cost[N_MAX][N_MAX];
void warshall_floyd(vector<vector<ll>> &d) {
	ll N=d.size();
	for (ll k=0; k<N; k++) {
		for (ll i=0; i<N; i++) {
			for (ll j=0; j<N; j++){
				if(d[i][k] != INF && d[k][j] != INF && d[i][k] + d[k][j] < d[i][j]){
					d[i][j] = d[i][k] + d[k][j];
				}
			}
		}
	}
}

void input() {
	scanf("%lld", &N);
	rep(i, N) rep(j, N) scanf("%lld", &A[i][j]);
}

void solve() {

	vector<vector<ll>> d(N, vector<ll>(N, 0));
	for(ll i=0; i<N; i++) {
		for(ll j=0; j<N; j++) {
			d[i][j] = A[i][j];
			cost[i][j]=0;
		}
	}

	warshall_floyd(d);
	rep(i,N) for(ll j=i+1;j<N;j++){
		if(A[i][j]!=d[i][j]){p(-1);exit(1);}
	}


	ll t=0;
	rep(i,N) for(ll j=i+1;j<N;j++){
		bool a=true;
		rep(k,N){
			if(k==i||k==j)continue;
			if(d[i][j]==d[i][k]+d[k][j]){
				cost[i][k]=d[i][k];
				cost[k][j]=d[k][j];
				a=false;
			}
		}
		if(a)cost[i][j]=d[i][j];
	}
	rep(i,N) for(ll j=i+1;j<N;j++){
		t+=cost[i][j];
	}
	p(t);
}

signed main() {
	input();
	solve();
	return 0;
}

