// 返り値は与えられた最短距離行列が正しいか
bool warshall_floyd(int n) {
  for (int i = 0; i < n; ++i) {
    for (int j = 0; j < n; ++j) {
      for (int k = 0; k < n; ++k) {
        dist[j][k] = min(dist[j][k], dist[j][i] + dist[i][k]);
      }
    }
  }
  for (int j = 0; j < n; ++j) {
    for (int k = 0; k < n; ++k) {
      if (aa[j][k] > dist[j][k]) return false;
    }
  }
  return true;
}

