template <class... ARGS>
struct inputWithParam {
	tuple<ARGS...> param;
	inputWithParam() {}
	inputWithParam(tuple<ARGS...>&& param_) : param(param_) { }

	template <int N>
	struct Expand {
		template <typename F, typename Tuple, typename... Args>
		static F apply(Tuple& t, Args&... args)
		{
			return Expand<N - 1>::apply<F>(t, std::get<N - 1>(t), args...);
		}
	};

	template <>
	struct Expand<0> {
		template <typename F, typename Tuple, typename... Args>
		static F apply(Tuple& t, Args&... args)
		{
			return F(args...);
		}
	};

	template <typename F, typename Tuple>
	F apply(Tuple& t)
	{
		return Expand<tuple_size<Tuple>::value>::apply<F>(t);
	}

	operator int() { return apply<in_int>(param); }
	operator double() { return apply<in_base<double>>(param); }
	operator string() { return apply<in_base<string>>(param); }
	operator char() { return apply<in_base<char>>(param); }

	template <class A, class B>
	operator pr<A, B>() { return apply<in_pr<A, B>>(param); }

	template <class T>
	operator arr<T>() { return apply<in_arr<T>>(param); }

	template <class A, class B>
	operator dic<A, B>() { return apply<in_dic<A, B>>(param); }

	template <class T>
	operator arr2<T>() { return apply<in_arr2<T>>(param); }

};

struct input {
	operator int() { return inputWithParam<>(); }
	operator double() { return inputWithParam<>(); }
	operator string() { return inputWithParam<>(); }
	operator char() { return inputWithParam<>(); }

	template <class A, class B>
	operator pr<A, B>() { return inputWithParam<>(); }

	template <class... ARGS>
	inputWithParam<ARGS...> operator()(ARGS&&... args) {
		inputWithParam<ARGS...> holder = forward_as_tuple(args...);
		return holder;
	}
} in;

