ll cost[305][305];
ll dist[305][305];
ll num[305][305];

int main(void){
    int n;
    cin>>n;
    for(int i=0;i<n;i++){
        for(int j=0;j<n;j++){
            cin>>cost[i][j];
            dist[i][j]=cost[i][j];
            num[i][j]=1;
        }
    }
    for(int i=0;i<n;i++){
        priority_queue<P,vector<P>,greater<P>>que;
        que.push(P(i,0));
        while(!que.empty()){
            P p=que.top();
            que.pop();
            int now=p.first;
            ll c_now=p.second;
            //cout<<now<<" "<<c_now<<endl;
            for(int j=0;j<n;j++){
                if(i==j)continue;
                ll c=cost[now][j];
                if(c>0){
                    ll d=c_now+c;
                    if(dist[i][j]>d){
                        cout<<-1<<endl;
                        return 0;
                    }
                    if(dist[i][j]==d){
                        if(num[i][j]==1){
                            num[i][j]++;
                            que.push(P(j,d));
                        }
                        else{
                            cost[i][j]=0;
                        }
                    }
                }
            }
        }
    }
    ll ans=0;
    for(ll i=0;i<n;i++){
        for(ll j=i;j<n;j++){
            ans+=cost[i][j];
        }
    }
    cout<<ans<<endl;
    return 0;
}

