using Edge = struct{
  int a;
  int b;
  int len;
};
using Path = struct{
  int to;
  int len;
};
vector<Edge> edge;
vector<Path> path[300];
long res;
bool used[300];

bool acs_len(const Edge &left, const Edge &right) {
  return left.len < right.len;
}

void dfs(int s, int e, long dis) {
  if (s==e) {
    if (res == -1) {
      res = dis;
      return ;
    }
    res = min(res, dis);
    return ;
  }
  if (!used[s]) {
    used[s] = true;
    for (auto &p: path[s]) {
      int to = p.to, len = p.len;
      if (to == s)
        continue;
      dfs(to, e, dis+len);
    }
    used[s] = false;
  }
  return ;
}

int main() {
