      if (i<j)
        edge.push_back({i, j, A});
    }
  }
  sort(edge.begin(), edge.end(), acs_len);
  int ne = edge.size();
  long ans = 0;
  for (int i=0; i<ne; i++) {
    res = -1;
    for (int i=0; i<N; i++)
      used[i] = false;
    int a = edge[i].a, b = edge[i].b, l = edge[i].len;
    dfs(a, b, 0);
    if (res == -1 || res > l) {
      path[a].push_back({b, l});
      path[b].push_back({a, l});
      ans += l;
    } else if (res < l) {
      cout << -1 << endl;
      return 0;
    }
  }
