const int MAX = 300;
const int INF = 999999999;

long long solve(int N, int graph[MAX][MAX]) {

	for (int i = 0; i < N; i++) {
		for (int j = 0; j < N; j++) {
			for (int k = 0; k < N; k++) {
				if (graph[j][k] > graph[j][i] + graph[i][k])return -1;
			}
		}
	}

	for (int i = 0; i < N; i++) {
		for (int j = 0; j < N; j++) {
			for (int k = 0; k < N; k++) {
				if (i == j || i == k)continue;
				if (graph[j][k] == graph[j][i] + graph[i][k])graph[j][k] = INF;
			}
		}
	}

	long long ans = 0;
	for (int i = 0; i < N; i++) {
		for (int j = i + 1; j < N; j++) {
			if (graph[i][j] != INF)ans += graph[i][j];
		}
	}

	return ans;
}

int main() {
