	int graph[MAX][MAX];

	cin >> N;
	for (int i = 0; i < N; i++) {
		for (int j = 0; j < N; j++) {
			cin >> graph[i][j];
		}
	}

	cout << solve(N, graph) << endl;

	return 0;
}

