int main(void)
{

    int N;
    if (scanf("%d", &N) < 1) return 0;

    array<array<int, 300>, 300> dist;

    for (int i = 0; i < N; i++)
        for (int j = 0; j < N; j++)
            if (scanf("%d", &dist[i][j]) < 1) return 0;

    long long int total = 0L;

    // Warshall-Floyd
    for (int i = 0; i < N; i++)
    {
        for (int j = i + 1; j < N; j++)
        {
            bool flg = false;
            for (int k = 0; k < N; k++)
            {
                if (k == i || k == j) continue;
                if (dist[i][k] + dist[k][j] < dist[i][j])
                {
                        printf("%d\n", -1);
                        return 0;
                }
                else if (dist[i][k] + dist[k][j] == dist[i][j])
                {
                    flg = true;
                    break;
                }
            }
            if (!flg) total += dist[i][j];
        }
    }

    printf("%lld\n", total);
    return 0;
}

