// ワーシャル-フロイド法　O(V^3)
// 隣接行列でd[i][i] == 0, 辺がないときd[i][j] == INFである
void Warshall_Floyd(ll l, ll r){
    for(ll k = l; k < r; k++)
        for(ll i = l; i < r; i++)
            for(ll j = l; j < r; j++)
                d[i][j] = min(d[i][j], d[i][k] + d[k][j]);
}

