ll solve() {
    int N; cin >> N;
    vector<vector<int>> A(N, vector<int>(N));
    vector<vector<int>> B(N, vector<int>(N));
    rep(i, 0, N) rep(j, 0, N) {
        int a; cin >> a;
        A[i][j] = B[i][j] = a;
    }
    rep(k, 0, N) rep(i, 0, N) rep(j, 0, N) {
        B[i][j] = min(B[i][j], B[i][k] + B[k][j]);
    }
    rep(i, 0, N) rep(j, 0, N) if(A[i][j] != B[i][j]) return -1;
    vector<vector<int>> need(N, vector<int>(N, 1));
    rep(k, 0, N) rep(i, 0, N) rep(j, 0, i) {
        if(B[i][j] == B[i][k] + B[k][j] && i != k && j != k) need[i][j] = 0;
    }
    ll ans = 0;
    rep(i, 0, N) rep(j, 0, i) if(need[i][j]) ans += B[i][j];
    return ans;
}

