const LL mod = 1000000007ll;
const int mod_int = 1000000007;

LL N;
vector<vector<LL>> A;

LL ans = 0;

void solve(){
	vector<vector<LL>> A_shortest(A);
	//ワーシャルフロイド
	//A_shortestには各点同士の最短経路の長さが入る
	for(int k=1;k<=N;k++){
		for(int i=1;i<=N;i++){
			for(int j=1;j<=N;j++){
				A_shortest[i][j] = min(A_shortest[i][j],A_shortest[i][k]+A_shortest[k][j]);
			}
		}
	}
	for(int i=1;i<=N;i++){
		for(int j=i+1;j<=N;j++){
			//点iとjの距離について見ていく
			//1つでもA[i][j]==A_shortest[i][k]+A_shortest[k][j]
			//を満たすようなkが存在すれば点iとj間の距離はノーカンにする
			bool add_flag = true;
			for(int k=1;k<=N;k++){
				if(A[i][j]==A_shortest[i][k]+A_shortest[k][j] && (i!=k && j!=k))add_flag = false;
				if(A[i][j]>A_shortest[i][k]+A_shortest[k][j]){
					ans = -1;
					return;
				}
			}
			if(add_flag) ans+=A[i][j];
		}
	}
}

