ll solve() {
	for (int k = 0; k < n; k++) {
		for (int i = 0; i < n; i++) {
			for (int j = 0; j < n; j++) {
				if (k == i || k == j || i == j || dp[i][k] == INF || dp[k][j] == INF) {
					continue;
				}

				if (dp[i][k] + dp[k][j] == a[i][j]) {
					dp[i][j] = INF;
