struct edge {
    ll from, to, cost;

    edge(ll from, ll to, ll cost) : from(from), to(to), cost(cost) {};
};

class WarshallFloyd {
public:
    int V; // 頂点数
    int E; // 辺の数
    vector<vector<ll> > d; // 最短頂点間距離
    vector<edge> es;

    WarshallFloyd() = default;

    WarshallFloyd(int v) {
        V = v;
        d.resize(v);
        rep(i, v) d[i].resize(v);
        rep(i, v)rep(j, v)d[i][j] = inf;
        rep(i, v) d[i][i] = 0;
    };

    void add(int u, int v, int cost) {
        d[u][v] = cost;
        if (u > v) es.eb(edge(u, v, cost));
    }

    // v: 頂点数, d: 頂点間距離
    void solve() {
        rep(k, V)rep(i, V)rep(j, V) d[i][j] = min(d[i][j], d[i][k] + d[k][j]);
    }

    ll calc() {
        ll ans = 0;
        vector<vector<bool>> notplus(V, vector<bool>(V));
        rep(k, V) rep(i, V) rep(j, V) {
                    if (i == k || k == j) continue;
                    if (d[i][j] == d[i][k] + d[k][j]) {
                        notplus[i][j] = true;
                    }
                }
        rep(i, V) rep(j, V) {
                if (j > i && !notplus[i][j]) ans += d[i][j];
            }
        return ans;
    }
};


void solve() {
    ll n;
    cin >> n;
    WarshallFloyd graph(n);
    vvl a(n, vl(n));
    rep(i, n) {
        rep(j, n) {
            ll tmp;
            cin >> tmp;
            graph.add(i, j, tmp);
            a[i][j] = tmp;
        }
    }
    graph.solve();
    vvl d = graph.d;
