  rep(i,N) if (A[i][i]!=0) { cout << -1 << endl; return 0; }
  rep(i,N) rep(j,N) if (A[i][j]!=A[j][i]) { cout << -1 << endl; return 0; }

  vector<vector<int>> omit;
  for (int i=0; i<N; i++) {
    for (int j=i+1; j<N; j++) {
      for (int k=j+1; k<N; k++) {
        ll load[3] = {A[i][j], A[j][k], A[i][k]};
