          if (load[0]+load[1]==load[2]) {
            if (A[i][j]>=A[j][k] && A[i][j]>=A[i][k]) omit.push_back({i,j});
            else if (A[j][k]>=A[i][j] && A[j][k]>=A[i][k]) omit.push_back({j,k});
            else omit.push_back({i,k});
          }
        }
      }
    }
  }

  ll result = 0;
  for (int i=0; i<N; i++) for (int j=i+1; j<N; j++) result += A[i][j];
  sort(omit.begin(), omit.end());
  omit.erase(unique(omit.begin(), omit.end()), omit.end());
  for (auto x: omit) result -= A[x[0]][x[1]];
