void dijkstra(int s){
  priority_queue< pii, vector<pii>, greater<pii> > q;
  fill(d,d+V,INF);
  d[s]=0;
  q.push(pii(0,s));

  while(!q.empty()){
    pii p=q.top();q.pop();
    int v=p.second;
    if(d[v]<p.first)continue; //更新されていたら何もしない
    for(int i=0;i<G[v].size();i++){
      edges e=G[v][i];
      if(d[e.to]>d[v]+e.cost){
	d[e.to]=d[v]+e.cost;
	q.push(pii(d[e.to],e.to));
      }
    }
  }
}



