template <typename T>
struct edge {
  int from, to;
  T cost;

  edge(const int from, const int to)
      : from(from), to(to), cost(static_cast<T>(1)) {}

  edge(const int from, const int to, const T cost)
      : from(from), to(to), cost(cost) {}

  friend std::ostream& operator<<(std::ostream& os, const edge& e) {
    os << e.from << "->" << e.to << "cost: " << e.cost;
    return os;
  }
  friend std::istream& operator>>(std::istream& is, edge& e) {
    is >> e.from >> e.to >> e.cost;
    return is;
  }
};

template <typename T>
using Edges = std::vector<edge<T>>;


template <typename T>
std::vector<std::vector<T>> warshall_floyd(const Edges<T> &edges, const int n) {
  const T DINF = std::numeric_limits<T>::max();
  std::vector<std::vector<T>> dist(n, std::vector<T>(n, DINF));
  for (auto &e : edges) {
    dist[e.from][e.to] = e.cost;
  }
  for (int i = 0; i < n; ++i) dist[i][i] = 0;
  for (int k = 0; k < n; ++k) {
    for (int i = 0; i < n; ++i) {
      for (int j = 0; j < n; ++j) {
        if (dist[i][k] == DINF || dist[k][j] == DINF)
          continue;
        else
          dist[i][j] = std::min(dist[i][j], dist[i][k] + dist[k][j]);
      }
    }
  }

  return dist;
}

