struct UnionFind {
    vector<ll> data;

    explicit UnionFind(ll size) : data(size, -1) {}

    bool unionSet(ll x, ll y) {
        x = root(x);
        y = root(y);
        if (x != y) {
            if (data.at(y) < data.at(x)) swap(x, y);
            data.at(x) += data.at(y);
            data.at(y) = x;
        }
        return x != y;
    }

    bool findSet(ll x, ll y) {
        return root(x) == root(y);
    }

    int root(ll x) {
        return data.at(x) < 0 ? x : data.at(x) = root(data.at(x));
    }

    int size(ll x) {
        return -data.at(root(x));
    }
};

struct Edge {
    ll from;
    ll to;
    ll cost;

    explicit Edge(ll from, ll to, ll cost) : from(from), to(to), cost(cost) {}

    bool operator<(const Edge e) const {
        return cost < e.cost;
    }
};

struct Node {
    ll id;
    vector<pair<ll, ll>> adjacent_edges{}; // (cost, to)
    explicit Node(ll id) : id(id) {}
};

// O(NlogN)
ll dijkstra(vector<Node> &v, ll start_node, ll end_node) {
    priority_queue<pair<ll, ll>, vector<pair<ll, ll>>, greater<>> pq;
    vector<ll> costs((ll) v.size(), numeric_limits<ll>::max());
    costs.at(start_node) = 0;
    pq.push(make_pair(costs.at(start_node), start_node));
    while (!pq.empty()) {
        ll cost, now;
        tie(cost, now) = pq.top();
        pq.pop();
        for (auto &&p: v.at(now).adjacent_edges) {
            ll c, next;
            tie(c, next) = p;
            ll alt = costs.at(now) + c;
            if (costs.at(next) > alt) {
                costs.at(next) = alt;
                pq.push(make_pair(costs.at(next), next));
            }
        }
    }
    return costs.at(end_node);
}


