void up(ll x){
    ll s = x;
    vector<ll> d (n+1, INF),  p (n+1);
    d[s] = 0;
    vector<char> u (n+1);
    for (ll i=1; i<=n; ++i) {
        ll v = -1;
        for (ll j=1; j<=n; ++j)
            if (!u[j] && (v == -1 || d[j] < d[v]))
                v = j;
        if (d[v] == INF)
            break;
        u[v] = true;

        for (ll j=1; j <= n; ++j){
            ll to = j;
            ll len = de[v][j];
            if (d[v] + len < d[to]) {
                d[to] = d[v] + len;
                p[to] = v;
            }
        }
    }

    for (ll i = 1; i <= n; i++) {
        de[x][i] = min(de[x][i], d[i]);
        de[i][x] = de[x][i];
    }
}

