using namespace std;

#define INF 1e+16
#define MAX_V 10000

struct edge {
    int to;
    int cost;
};

// <最短距離, 頂点の番号>
using P = pair<int, int>;

int V;
vector<edge> G[MAX_V];
long long int d[MAX_V];
 　　
void dijkstra(int s) {
    priority_queue<P, vector<P>, greater<P> > que;
    fill(d, d+V, INF);
    d[s] = 0;
    que.push(P(0, s));

    while (!que.empty()) {
        P p = que.top();
        que.pop();
        int v = p.second;
        if (d[v] < p.first) continue;

        for (int i=0; i<G[v].size(); ++i){
            edge e = G[v][i];
            if (d[e.to] > d[v] + e.cost) {
                d[e.to] = d[v] + e.cost;
                que.push(P(d[e.to], e.to));
            }
        }
    }
}

int main() {
	cin >> V;
  	long long int ans = 0;
  	long long int adj[V][V];
  	for(int i=0;i<V;i++) for(int j=0; j<V;j++) cin >> adj[i][j];
  	priority_queue<
      	tuple<int,int,int>,
  		vector<tuple<int,int,int>>,
  		greater<tuple<int,int,int>>
    > q;
  	for(int i=0;i<V;i++) for(int j=i+1; j<V;j++) q.push(make_tuple(adj[i][j],i,j));
    while(!q.empty()){
        int c = get<0>(q.top()), b = get<1>(q.top()),  a = get<2>(q.top());
      	q.pop();
      	dijkstra(b);
      	if(d[a] < c){cout << -1 << endl; return 0;}
      	else if(d[a] > c){
        	ans = ans + c;
          	edge e1 = {a,c}, e2 = {b,c};
        	G[a].push_back(e2);
          	G[b].push_back(e1);
        }
    }

   	cout << ans << endl;
  	return 0;
}

