static const int MAX = 300;
static const long long INFTY = (1LL<<32);

int n;
long long d[MAX][MAX];  //d[i][j]の最短コストを記録するDPテーブル

void floyd() {

  for( int k = 0; k < n; k++){         //経由する頂点数
    for(int i = 0; i < n; i++){         //始点
      if( d[i][k] == INFTY ) continue;

      for(int j = 0; j < n; j++){       //終点
      if( d[k][j] == INFTY ) continue;

      d[i][j] = min(d[i][j], d[i][k] + d[k][j]);
      //i -> j   i -> k -> j //iからｊへの最短経路を示す
      }
    }
  }
}


int main(){
  cin >> n;

  int a[n][n];
  //d[][]に入力
  REP(i,n)REP(j,n) cin >> a[i][j];
  REP(i,n)REP(j,n) d[i][j] =  a[i][j];
  floyd();

  //条件を満たさない場合
  REP(i,n)REP(j,n){
    if(d[i][j] < a[i][j]){
      cout << -1 << endl;
      return 0;
    }
  }




  //必要のない経路を削除する
  //どこかを経由する最短経路が存在するならば， 直接つなぐ道路はカットできる．connect[i][j]　で管理
  //存在しないならば， 直接接続する道路は残す

  bool ex[n][n];
  REP(i,n)REP(j,n) ex[i][j] = true;

  for( int k = 0; k < n; k++){         //経由する頂点数
    for(int i = 0; i < n; i++){         //始点
      for(int j = 0; j < n; j++){       //終点
        if(i == j || j == k || k == i) continue;
        if(a[i][j] == a[i][k]+a[k][j]){
          ex[i][j] = false;
        }
      }
    }
  }

  ll sum = 0;
  REP(i,n)REP(j,n){
    if(ex[i][j]) sum += a[i][j];
  }

  cout << sum/2 << endl;
  return 0;
}

