    if (Path[e.s][e.t] < e.c) {
      ans = -1;
      break;
    }
    else if (Path[e.s][e.t] == e.c) {
      continue;
    }
    else {
      Path[e.s][e.t] = e.c;
      Path[e.t][e.s] = e.c;
