	//cout << e.s << " ~ " << i << ": " << Path[e.s][i] << endl;
	//cout << Path[e.s][i] << " vs " << Path[e.s][e.t] + Path[e.t][i] << endl;
	Path[e.s][i] = min(Path[e.s][e.t] + Path[e.t][i],
			   Path[e.s][i]);
	Path[i][e.s] = Path[e.s][i];
      }
