const long long INF = 1000000000000000000;

vector<long long> ufparent(310, 0);
vector<long long> ufrank(310, 0);

void init(long long n) {
    for (long long i = 0; i < ufparent.size(); ++i) {
        ufparent[i] = i;
        ufrank[i] = 0LL;
    }
}

long long find(long long x) {
    if (ufparent[x] == x) {
        return x;
    }
    else {
        return ufparent[x] = find(ufparent[x]);
    }
}

void unite(long long x, long long y) {
    x = find(x);
    y = find(y);
    if (x == y) return;
    if (ufrank[x] < ufrank[y]) {
        ufparent[x] = y;
    }
    else {
        ufparent[y] = x;
        if (ufrank[x] == ufrank[y]) {
            ++ufrank[x];
        }
    }
}

bool same(long long x, long long y) {
    return find(x) == find(y);
}

void Main() {
    long long N;
    cin >> N;
    vector<vector<long long>> A(N, vector<long long>(N, 0LL));
    priority_queue<pair<long long, pair<long long, long long>>
        , vector<pair<long long, pair<long long, long long>>>
        , greater<pair<long long, pair<long long, long long>>>> q;
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            cin >> A[i][j];
            if (i < j) {
                q.push(make_pair(A[i][j], make_pair(i, j)));
            }
        }
    }
    init(N + 10);

    vector<vector<long long>> path(N, vector<long long>(N, INF));
    for (int i = 0; i < N; ++i) {
        path[i][i] = 0;
    }

    while (!q.empty()) {
        auto top = q.top();
        q.pop();
        long long town1 = top.second.first;
        long long town2 = top.second.second;
        path[town1][town2] = top.first;
        path[town2][town1] = top.first;
        unite(town1, town2);
        bool connected = true;
        for (long long i = 1; i < N; ++i) {
            if (!same(0, i)) {
                connected = false;
                break;
            }
        }
        if (connected) {
            break;
        }
    }
    vector<vector<long long>> pathOrg = path;

    for (long long k = 0; k < N; ++k) {
        for (long long i = 0; i < N; ++i) {
            for (long long j = 0; j < N; ++j) {
                path[i][j] = min(path[i][j], path[i][k] + path[k][j]);
            }
        }
    }

    bool ok = true;
    for (long long i = 0; i < N; ++i) {
        for (long long j = 0; j < N; ++j) {
            if (path[i][j] != A[i][j]) {
                ok = false;
            }
        }
