// Warshall-Floyd
// O(V^3)

// 最終的にiからjの最小コストはcost[i][j]となる。
vvll cost;
vvll pre;

void warshall_floyd(ll V, vvll& cost) {
  for (int k = 0; k < V; k++) {
    for (int i = 0; i < V; i++) {
      for (int j = 0; j < V; j++) {
        if (i == k || j == k || i == j) {
          continue;
        }
        ll cand = cost[i][k] + cost[k][j];
        if (cost[i][j] >= cand) {
          cost[i][j] = cand;
          pre[i][j] = 1;
        }
      }
    }
  }
}

signed main() {
  cin.tie(0);
  ios::sync_with_stdio(false);
  cout << fixed << setprecision(20);

  ll n;
  cin >> n;

  vvll mp = vvll(n, vll(n));
  cost = vvll(n, vll(n));
  pre = vvll(n, vll(n));

  rep(y, n) {
    rep(x, n) {
      cin >> mp[y][x];
      // pre[y][x] = x;
    }
  }

  cost = mp;

  warshall_floyd(n, cost);

  rep(y, n) {
    rep(x, n) {
      if (mp[y][x] != cost[y][x]) {
        cout << -1 << endl;
        return 0;
      }
    }
  }

  ll ans = 0;
  rep(y, n) {
    for (ll x = y; x < n; x++) {
      if (pre[y][x] == 0) {
        ans += cost[y][x];
      }
    }
  }

  cout << ans << endl;

  return 0;
}

