#include <bits/stdc++.h>

using namespace std;

using ll = long long;
constexpr ll INF = 1145141919810LL;

void dijkstra(int N, int s, vector<vector<ll>> &D)
{
    using P = pair<ll, int>;
    priority_queue<P, vector<P>, greater<P>> pq;
    pq.push(P(0, s));

    vector<ll> dmin(N, INF);
    dmin[s] = 0;

    while (!pq.empty()) {
        P p = pq.top(); pq.pop();
        int v = p.second;

        for (int i = 0; i < N; i++) {
            if (v == i) continue;
            if (D[v][i] == INF) continue;

            ll d = dmin[v] + D[v][i];
            if (d < dmin[i]) {
                dmin[i] = d;
                pq.push(P(d, i));
            }
        }
    }

    for (int i = 0; i < N; i++) {
        D[s][i] = D[i][s] = dmin[i];
    }
}

int main()
{    
    int N;
    cin >> N;

    vector<vector<ll>> A(N, vector<ll>(N));
    vector<tuple<ll, int, int>> X;
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            cin >> A[i][j];
            if (i < j) X.emplace_back(A[i][j], i, j);
        }
    }

    sort(X.begin(), X.end());

    vector<vector<ll>> D(N, vector<ll>(N, INF));
    for (int i = 0; i < N; i++) {
        D[i][i] = 0;
    }
    ll sum = 0;
    for (auto &x : X) {
        ll d;
        int i, j;

        tie(d, i, j) = x;
        if (D[i][j] == d) continue;

        D[i][j] = D[j][i] = d;
        sum += d;

        dijkstra(N, i, D);
        dijkstra(N, j, D);
    }

    if (A == D) {
        cout << sum << endl;
    } else {
        cout << -1 << endl;
    }
    return 0;
}

