		pq.pop();
		ds = p.first;
		is = p.second;
		if (d[is] < ds) {
			continue;
		}
		for (i = 0; i < g[is].size(); i++) {
			nis = g[is][i].first;
			nco = g[is][i].second;
			if (d[nis] > ds + nco) {
				d[nis] = ds + nco;
				pq.push(Pl(d[nis], nis));
			}
		}
	}
}

