class UnionFind {
    std::vector<int> p;

public:
    UnionFind(int n) : p(n, -1) {}

    int root(int x) { return p[x] < 0 ? x : p[x] = root(p[x]); }

    bool same(int x, int y) { return root(x) == root(y); }

    bool unite(int x, int y) {
        x = root(x);
        y = root(y);
        if (x == y) return false;
        if (p[y] < p[x]) std::swap(x, y);
        if (p[x] == p[y]) --p[x];
        p[y] = x;
        return true;
    }
};


void solve(long long N, std::vector<std::vector<long long>> A) {
    auto B = A;
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            for (int k = 0; k < N; k++) {
                B[j][k] = min(B[j][i] + B[i][k], B[j][k]);
            }
        }
    }
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            if (A[i][j] != A[j][i]) {
                B = {};
            }
        }
    }
    if (A != B) {
        cout << -1 << endl;
        return;
    }
    long long ans = 0;
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            for (int k = 0; k < N; k++) {
                if (i != j && j != k && i != k) {
                    if (A[j][i] + A[i][k] == A[j][k]) {
                        B[j][k] = 0;
                    }
                }
            }
        }
    }
    for(int i = 0 ; i < N ; i++){
        for(int j = 0 ; j < i ; j++){
            ans += B[i][j];
        }
    }
    cout << ans << endl;


}

