  Matrix<ll> a(n, vec<ll>(n));
  Matrix<bool> checked(n, vec<bool>(n));
  rep(i, 0, n) rep(j, 0, n) scanf("%lld", &a[i][j]);

  if (!warshall_floyd(a, checked)) {
    cout << -1 << endl;
    return 0;
  }

  ll ans = 0;
  rep(i, 0, n) rep(j, i + 1, n) {
    if (checked[i][j]) continue;
    ans += a[i][j];
  }
  cout << ans << endl;

  return 0;
}

