//グラフのテンプレート
template<typename T>
struct edge {
	int from, to;
	T cost;

  edge(int to,T cost):from(0),to(to),cost(cost){}
	edge(int from, int to, T cost) :from(from), to(to), cost(cost) {}
};

//Union-Findtree
struct UF {
	vector<int>par;//親
	vector<int>Rank;//木の深さ

    UF(int n){init(n);}

	//初期化
	void init(int n) {
		par.resize(n); Rank.resize(n);
		for (int i = 0; i < n; i++) {
			par[i]= i;
			Rank[i] = 0;
		}
	}

	//木の根を求める
	int find(int x) {
		if (par[x] == x) {
			return x;
		}
		else {
			return par[x] = find(par[x]);
		}
	}

	//xとyの属する集合を併合
	bool unite(int x, int y) {
		x = find(x);
		y = find(y);
		if (x == y)return false;//すでに同じ集合に属している

		if (Rank[x] < Rank[y]) {//高さが小さい方を下に
			par[x] = y;
		}
		else {
			par[y] = x;
			if (Rank[x] == Rank[y])Rank[x]++;//同じだとrankが変わらないままになるので増やす（それ以外は大きい方のrankが採用される）
		}
        return true;
	}

	//xとyが同じ集合に属するかを判定
	bool same(int x, int y) {
		return find(x) == find(y);
	}
};

template<typename T>
T kruskal(vector<edge<T>> &e,int v){//クラスカル法(最小全域木における最小の重みを判定)
    //v頂点からなる重み付き辺集合e
    sort(e.begin(),e.end(),[](const edge<T> &e1,const edge<T> &e2){
        return e1.cost<e2.cost;//ラムダ式を使ってedge.costが小さい順にソート
    });
    UF tree(v);
    T sum=0;
    for(auto &es:e){
        if(tree.unite(es.from,es.to)){
          sum+=es.cost;//同じ連結成分にないため、辺を追加
          d[es.from][es.to]=es.cost;
          d[es.to][es.from]=es.cost;
        }
    }
    return sum;
}


void warshall_floyd(int V){//Vは頂点数
	for(int k=0;k<V;++k){//経由する頂点
		for(int i=0;i<V;++i){//始点となる頂点
			for(int j=0;j<V;++j)//目的地の頂点
      d[i][j]=min(d[i][j],d[i][k]+d[k][j]);
		}
	}
}



