================================================*/
typedef ll COST_TYPE;
#define NMAX (301)
#define INF ((ll)1e18)
vector<pair<COST_TYPE, int> > G[NMAX];
COST_TYPE cost[NMAX];
bool done[NMAX] = { false };

void dijkstra(int root)
{
	priority_queue<pair<COST_TYPE, int>, vector<pair<COST_TYPE, int> >, greater<pair<COST_TYPE, int> > > PQ;
	pair<COST_TYPE, int> current;	/* first: cost, second: index */
	COST_TYPE next_cost;
	int current_index, next_index, size;

	rep(i, NMAX) {
		done[i] = false;
		cost[i] = INF;
	}

	cost[root] = 0;
	PQ.push(make_pair(0, root));

	while (!PQ.empty()) {
		current = PQ.top();
		PQ.pop();

		current_index = current.second;

		if (done[current_index]) continue;
		done[current_index] = true;

		size = (int)G[current_index].size();
		rep(i, size) {
			next_index = G[current_index][i].second;
			next_cost = G[current_index][i].first;

			if ((!done[next_index])
				&& (cost[next_index] > cost[current_index] + (COST_TYPE)next_cost)) {
				cost[next_index] = cost[current_index] + (COST_TYPE)next_cost;
				PQ.push(make_pair(cost[next_index], next_index));
			}
		}
	}
}

int main()
{
	int N, num = 0;
	ll ans = 0;

	cin >> N;
	repc(i, 1, N) repc(j, 1, N) cin >> A[i][j];

	repc(i, 1, N - 1) repc(j, i + 1, N) {
		C[num] = p(A[i][j], p(i, j));
		num++;
	}

	sort(C, C + num);

	rep(i, num) {
		ll dis = C[i].first;
		int src = C[i].second.first;
		int dest = C[i].second.second;

		dijkstra(src);

		if (cost[dest] > dis) {
			G[src].push_back(p(dis, dest));
			G[dest].push_back(p(dis, src));
			ans += dis;
		}
		else if (cost[dest] < dis) {
			ans = -1;
			break;
		}
	}

	cout << ans << endl;

	return 0;
}

