void solve()
{
	int n;
	scanf("%d", &n);
	vector<pair<int, pair<int, int> > > z;
	int i, j;
	for (i = 0; i < n; i++) {
		for (j = 0; j < n; j++) {
			scanf("%d", &d[i][j]);
			if(i<j) z.push_back(make_pair(d[i][j], make_pair(i, j)));
		}
	}
	sort(z.begin(), z.end());

	ll sum = 0;
	for (i = 0; i < (int)z.size(); i++) {
		int dist=z[i].first;
		int p = z[i].second.first;
		int q = z[i].second.second;
		ll min = LINF;
		for (j = 0; j < n; j++) {
			if (j == p || j == q) continue;
			if (d[p][j] + d[j][q] < dist) {
				printf("-1\n"); return;
			}
			min = MIN(min, d[p][j] + d[j][q]);
		}
		if (min > dist) {
			sum += dist;
		}
	}
	printf("%lld", sum);
	return;
}


