typedef long long ll;
const ll MAX_N=10^5;
vector<pair<ll, ll> > edge;
ll N, M;
ll par[MAX_N];  //親
ll sizes[MAX_N]; //木の深さ
ll element[MAX_N];
void init(ll n)
{
    for (ll i = 0; i < n; i++)
    {
        par[i] = i;
        sizes[i] = 1;
    }
}
//木の根を求める
ll find(ll x)
{
    if (par[x] == x)
    {
        return x;
    }
    else
    {
        return par[x] = find(par[x]);
    }
}
//併合
void unite(ll x, ll y)
{
    x = find(x);
    y = find(y);
    if(x==y) return;
    if (par[x] > par[y]) swap(x, y); // merge technique
    par[y] =x;
    sizes[x] += sizes[y];
    }

bool same(int x,int y){
    return find(x)==find(y);
}

void solve(){
    init(N);
    ll ans[MAX_N];
    ans[M-1]=N*(N-1)/2;
    memset(element,0,N);
    for(ll i=M-1;i>0;i--){
        ll a=edge[i].first;
        ll b=edge[i].second;
        if(!same(a,b)){
        ans[i-1]=ans[i]-sizes[find(a)]*sizes[find(b)];
        unite(a,b);
        }
        else ans[i-1]=ans[i];
    }
    for(int i=0;i<M;i++)cout<<ans[i]<<'\n';
}
