// #define INF 1e9
const ll INF = 1LL << 60;

bool warshallFloyd(vector<vector<ll>>& g){
  int n = g.size();
  bool flag = false;
  REP(k, n){
    REP(i, n){
      REP(j, n){
        if(g[i][k] == INF || g[k][j]==INF) continue;
        if(g[i][k] + g[k][j] < g[i][j]){
          flag = true;
          g[i][j] = g[i][k] + g[k][j];
        }
      }
    }
  }
  return flag;
}
void reWarshallFloyd(vector<vector<ll>>& g){
  int n = g.size();
  REP(k, n){
    REP(i, n){
      REP(j, n){
        if(i==k || k == j) continue;
        if(g[i][k]+g[k][j] == g[i][j]){
          g[i][j] = INF;
