struct UnionFind {
    vector<int> p;
    UnionFind(int n) : p(n, -1) {};
    bool unite(int u, int v) {
        if ((u = root(u)) == (v = root(v))) return false;
        if (p[u] > p[v]) swap(u, v);
        p[u] += p[v]; p[v] = u;
        return true;
    }
    bool find(int u, int v) { return root(u) == root(v); }
    int root(int u) { return p[u] < 0 ? u : p[u] = root(p[u]); }
    int size(int u) { return -p[root(u)]; }
};


using Edge = pair<ll, pii>; // cost,from,to
using vl = vector<vector<ll>>;
vl d;
int n;

// O(|E| log |V|)
using Dist = ll; using Vertex = int;
using Pair = pair<Dist, Vertex>;
struct edge { Vertex to; Dist cost; };
using Graph = vector<vector<edge>>;
vector<Dist> dijkstra(const Graph& G, Vertex s) {
    priority_queue<Pair, vector<Pair>, greater<Pair>> pq;
    vector<Dist> d(n, INFLL); d[s] = 0;
    pq.push(Pair(0, s));
    while (pq.size()) {
        Pair p = pq.top(); pq.pop();
        Vertex v = p.second;
        if (d[v] < p.first) continue;
        for (const edge& e : G[v]) {
            Dist nd = d[v] + e.cost;
            if (d[e.to] > nd) {
                d[e.to] = nd;
                pq.push(Pair(d[e.to], e.to));
            }
        }
    }
    return d;
}

