int64_t kruskal(int V) {
    int E = es.size();
    sort(es.begin(), es.end(), comp);
    UnionFind uft(V);
    rep(i, pp.size()){
        uft.unite(pp[i].first, pp[i].second);
    }
    int64_t res = 0;
    for(int i = 0; i < E; ++i) {
        edge e = es[i];
        if(!uft.same(e.u, e.v)) {
            uft.unite(e.u, e.v);
            res += e.cost;
        }
    }
    return res;
}

