const int VMAX=310;
vector<pair<int,int>> edge[VMAX];
long long b[VMAX][VMAX];

void dijkstra(int start){
    long long dist[VMAX]; rep(to,VMAX) dist[to]=LINF;
    dist[start]=0;
    bool used[VMAX]; rep(v,VMAX) used[v]=false;
    priority_queue<pair<long long,int>,vector<pair<long long,int>>,greater<pair<long long,int>>> q;
    q.push({0,start});
    while(q.size()){
        pair<long long,int> p=q.top(); q.pop();
        long long d=p.first;
        int from=p.second;
        if(used[from]) continue;
        used[from]=true;
        for(auto e:edge[from]){
            long long to=e.first,cost=e.second;
            if(d+cost<dist[to]){
                dist[to]=d+cost;
                q.push({dist[to],to});
            }
        }
    }
    rep(to,VMAX){
        b[start][to]=min(b[start][to],dist[to]);
        b[to][start]=min(b[to][start],dist[to]);
    }
}

