struct WarshallFloyd{
  VV d;
  ll N;
  WarshallFloyd(ll n){
    N = n;
    d.resize(N, VI(N, inf));
    rep(i, N) d[i][i] = 0;
  }
  // 双方向
  void register_edge2(ll a, ll b, ll c){
    d[a][b] = c;
    d[b][a] = c;
  }
  void calc(){
    rep(i, N){ // 経由点
      rep(j, N){ // 始点
         rep(k, N){ // 終点
          d[j][k] = min(d[j][k], d[j][i] + d[i][k]);
        }
      }
    }
  }
  ll distance(ll a, ll b){
    return d[a][b];
  }
};

struct UnionFind{
    vector<ll> parent;
    UnionFind(ll sz){
        parent.resize(sz);
        reset();
    }

    void reset(){
        FOR(i, 0, parent.size()){
            parent[i] = i;
        }
    }

    void unite(ll a, ll b){
        if(a>b){
            swap(a, b);
        }
        ll rootA = findRoot(a);
        ll rootB = findRoot(b);
        if(rootA>rootB){
            swap(rootA, rootB);
        }
        if(rootA==rootB){
            return;
        }else{
            // 小さい方を親にする
            parent[rootB] = rootA;
        }
    }

    ll findRoot(ll a){
        if(parent[a]==a){
            return a;
        }else{
            return parent[a] = findRoot(parent[a]);
        }
    }

    map<ll, vector<ll> > getGroups(){
        map<ll, vector<ll> > G;
        FOR(i, 0, parent.size()){
            ll r = findRoot(i);
            G[r].push_back(i);
        }
        return G;
    }

    bool is_same_group(ll a, ll b){
        ll rootA = findRoot(a);
        ll rootB = findRoot(b);
        if(rootA==rootB){
            return true;
        }else{
            return false;
        }
    }
};

