    for(int i = 1;i <= n;i++)
    {
        for(int j = 1;j <= n;j++)
            scanf("%I64d",&board[i][j]);
    }
    int ans = 0;
    for(int i = 1;i <= n;i++)
    {
        for(int j = 1;j <= n;j++)
        {
            if(i == j)
                continue;
            bool found = false;
            for(int z = 1;z <= n;z++)
            {
                if(z == i || z == j)
                    continue;
                if(board[i][z] + board[z][j] == board[i][j])
                {
                    if(!taken[i][z])
                    {
                        ans += board[i][z];
                        taken[i][z] = taken[z][i] = true;
                        adjList[i].insert(z);
                        adjList[z].insert(i);
                    }
                    if(!taken[z][j])
                    {
                        ans += board[z][j];
                        taken[z][j] = taken[j][z] = true;
                        adjList[z].insert(j);
                        adjList[j].insert(z);
                    }
                    found = true;
                    break;
                }
            }
            if(!found)
                adjList[i].insert(j),adjList[j].insert(i);
        }
    }
    for(int i = 1;i <= n;i++)
    {
        shortestPath(i,n);
