    for(int i = 1;i <= n;i++)
    {
        for(set<int>::iterator j = adjList[i].begin();j != adjList[i].end();j++)
        {
            if(!visited[i][*j])
            {
                realsum += board[i][*j];
                visited[i][*j] = visited[*j][i] = true;
            }
        }
    }
    cout << realsum;
    return 0;
}

