using namespace std;

#define rep(i,n) for(int i=0;i<(n);++i)
const int INF = 1e9+7;
using ll = long long;
using pii = pair<int, int>;
using vi = vector<int>;
using vvi = vector<vi>;
using pipii = pair<int, pii>;


int main() {
  cin.tie(0); ios::sync_with_stdio(false);
  int N; cin >> N;
  vvi edge(N, vi(N, INF));

  int A[N][N];
  ll ans = 0;
  priority_queue<pipii, vector<pipii>, greater<pipii>> q;
  rep(i, N) rep(j, N) {
    cin >> A[i][j];
    if (i < j)
      q.push(make_pair(A[i][j], make_pair(i, j)));
  }

  // 1. まず何も張ってない状態にする
  // 2. 一番短い最短距離から調べていく
  //     2. 経路がある
  //         i. 最短でなければ張る
  //         ii. 同じなら張らない
  //         iii. 経路のほうが短いなら-1
  // 3. 張った辺のそれぞれの両端で、その辺以外を見ていく
  // 4. (見ている辺+張った辺)のところがまだ辺がなければ張る ((見ている辺+張った辺) < ショトカはありえない)

  while (!q.empty()) {
    int i = q.top().second.first, j = q.top().second.second;
    q.pop();

    if (edge[i][j] == INF) {
      // そもそも経路がなければ張る
      edge[i][j] = edge[j][i] = A[i][j];
      ans += A[i][j];
    } else {
      if (edge[i][j] > A[i][j]) {
        // 最短でなければ張る
        edge[i][j] = edge[j][i] = A[i][j];
        ans += A[i][j];
      } else if (edge[i][j] == A[i][j]) {
        // 同じなら張らない
        continue;
      } else if (edge[i][j] < A[i][j]) {
        // 経路のほうが短いなら-1
        cout << -1 << endl;
        return 0;
      }
    }
    // 経路の更新
    rep(k, N) {
      if (edge[k][i] != INF)
        edge[k][j] = edge[j][k] = min(edge[k][j], edge[k][i] + edge[i][j]);
      if (edge[k][j] != INF)
        edge[k][i] = edge[i][k] = min(edge[k][i], edge[k][j] + edge[j][i]);
    }
  }
  cout << ans << endl;

  return 0;
}

