ll dist[MAXN][MAXN];

void warshall_floyd() {
  for (int i=0;i<n;i++) {
    for (int j=0;j<n;j++) {
      dist[i][j] = a[i][j];
    }
  }
  for (int k=0;k<n;k++) {
    for (int i=0;i<n;i++) {
      for (int j=0;j<n;j++) {
        dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j]);
      }
    }
  }
}

void solve() {
  warshall_floyd();
  for (int i=0;i<n;i++) {
    for (int j=0;j<n;j++) {
      if (dist[i][j] < a[i][j]) {
        cout << -1 << endl;
        return;
      }
    }
  }
  ll sum = 0;
  for (int i=0;i<n;i++) {
    for (int j=i+1;j<n;j++) {
      bool need = true;
      for (int k=0;k<n;k++) {
        if (i != k && k != j && dist[i][k] + dist[k][j] == dist[i][j]) {
          need = false;
        }
      }
      if (need) {
        sum += a[i][j];
      }
    }
  }
  cout << sum << endl;
}

