        return 0;
    }
    REP(i, V) REP(j, V) if(A[i][j] != A[i][j]) {
        cout << -1 << endl;
        return 0;
    }
    vector<pair<int, pair<int, int> > > edges;
    REP(i, V) FOR(j, i, V) {
        edges.pb(make_pair(A[i][j], make_pair(i, j)));
    }
    sort(edges.begin(), edges.end());
    for(auto x: edges) {
        int cost = x.first;
        int start = x.second.first;
        int end = x.second.second;
        dijkstra(start);
        if (d[end] < cost) {
            cout << -1 << endl;
            return 0;
        } else if (d[end] > cost) {
            G[start].pb(edge{end,cost});
            G[end].pb(edge{start,cost});
        }
    }
    ll ans = 0;
    REP(i, V) {
        for(auto x: G[i]) {
            ans += x.cost;
        }
    }
    cout << ans / 2 << endl;

    return 0;
}

