    pq.push(mp(a[i][j], mp(i, j)));
  }

  int res = 0;
  while(!pq.empty()){
    auto p = pq.top();
    pq.pop();
    int cost = p.fi;
    auto comb = p.se;
    if (cost < d[comb.fi][comb.se]){  // costを小さくしなければいけない。
