struct edge {
    int from, to;
    ll cost;
    //比較演算子のオーバーロード
    bool operator<(const edge& e1) const
    {
        return cost < e1.cost;
    }
    bool operator>(const edge& e1) const
    {
        return cost > e1.cost;
    }
};

const ll MOD = 1E+09 + 7;
const ll INF = 1E18;
const int MAX_N = 300;

int N;

priority_queue<edge, vector<edge>, greater<edge>> que;

ll d[MAX_N + 1][MAX_N + 1], dt[MAX_N + 1][MAX_N + 1];
ll restore();

int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> N;

    for (int i = 1; i <= N; i++) {
        for (int j = 1; j <= N; j++) {
            cin >> d[i][j];
        }
    }

    bool exist = true;
    for (int i = 1; i <= N; i++) {
        for (int j = i; j <= N; j++) {
            ll lmin = INF;
            for (int k = 1; k <= N; k++) {
                lmin = min(d[i][k] + d[k][j], lmin);
            }
            if (d[i][j] != lmin) {
                exist = false;
            }
        }
    }

    ll ans = 0;
    if (exist) {
        for (int i = 1; i <= N; i++) {
            for (int j = i + 1; j <= N; j++) {
                edge es = { i, j, d[i][j] };
                que.push(es);
            }
        }
        fill(dt[0], dt[N + 1], INF);
        for (int i = 1; i <= N; i++) {
            dt[i][i] = 0;
        }
        ans = restore();
    } else {
        ans = -1;
    }

    /*
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            cout << "i = " << i << ", j = " << j << ", dp = " << dp[i][j] << "\n";
        }
    }
    */

    cout << ans << "\n";

    return 0;
}

ll restore()
{
    ll res = 0;
    while (!que.empty()) {
        edge e = que.top();
        que.pop();

        bool update = false;
        if (dt[e.from][e.to] > e.cost) {
            dt[e.from][e.to] = e.cost;
            dt[e.to][e.from] = e.cost;
            update = true;
        }
        for (int j = 1; j <= N; j++) {
            if (dt[e.from][e.to] + dt[e.to][j] < dt[e.from][j]) {
                dt[e.from][j] = dt[e.from][e.to] + dt[e.to][j];
                update = true;
            }
        }
        for (int j = 1; j <= N; j++) {
            if (dt[j][e.from] + dt[e.from][e.to] < dt[j][e.to]) {
                dt[j][e.to] = dt[j][e.from] + dt[e.from][e.to];
                update = true;
            }
        }
        for (int j = 1; j <= N; j++) {
            if (dt[j][e.to] + dt[e.to][e.from] < dt[j][e.from]) {
                dt[j][e.from] = dt[j][e.to] + dt[e.to][e.from];
                update = true;
            }
        }
        for (int j = 1; j <= N; j++) {
            if (dt[e.to][e.from] + dt[e.from][j] < dt[e.to][j]) {
                dt[e.to][j] = dt[e.to][e.from] + dt[e.from][j];
                update = true;
            }
        }
        if (update) {
            res += e.cost;
        }
    }
    return res;
}

