using namespace std;

long long dist(vector<vector<pair<int, int>>>& g, int from, int to){
    vector<long long> d(g.size(), numeric_limits<long long>::max());
    d[from]=0;
    using T=pair<long long, int>;
    priority_queue<T, vector<T>, greater<T>> pq;
    pq.push({d[from], from});
    while(!pq.empty()){
        int u=pq.top().second; pq.pop();
        for(auto& v : g[u]){
            long long dd=d[u]+v.second;
            if(dd>=d[v.first]) continue;
            d[v.first]=dd;
            pq.push({dd, v.first});
        }
    }
    return d[to];
}

int main(){
    int n; cin >> n;
    vector<vector<int>> amat(n, vector<int>(n));
    for(int i=0; i<n; ++i){
        for(int j=0; j<n; ++j){
            cin >> amat[i][j];
        }
    }
    vector<pair<long long, pair<int, int>>> min_ds;
    for(int i=0; i<n; ++i){
        for(int j=0; j<i; ++j){
            min_ds.push_back({amat[i][j], {i, j}});
        }
    }
    sort(min_ds.begin(), min_ds.end());
    vector<vector<pair<int, int>>> g(n);
    long long ans=0;
    for(auto& p : min_ds){
        int d=p.first, from=p.second.first, to=p.second.second;
        auto dd=dist(g, from, to);
        if(dd==d) continue;
        else if(dd==numeric_limits<long long>::max()){
            g[from].push_back({to, d});
            g[to].push_back({from, d});
            ans+=d;
        } else if(dd>p.first){
            g[from].push_back({to, d});
            g[to].push_back({from, d});
            ans+=d;
        } else{
            ans=-1;
            break;
        }
    }
    cout << ans << endl;
    return 0;
}

