template <typename T>
ll dijkstra(T s,T g){     

  using P = pair<T, int>;
  priority_queue<P,vector<P>,greater<P> > q;
  d[s][s]=0;
  q.emplace(d[s][s],s);//最短距離、ゴール頂点番号

  while(!q.empty()){
    ll spath=q.top().first;
    int v=q.top().second;
    q.pop();
    if(d[s][v]<spath) continue;
    for(auto& i:e[v]){//1)
      int u=i.first;//頂点番号
      T c=i.second;//最短距離
      if(d[s][u]>d[s][v]+c){
        d[s][u]=d[s][v]+c;
        q.emplace(d[s][u],u);
      }
    }
  }

  return d[s][g];
}

