// # 方針
// 一旦 $K_{n}$ の完全グラフを作り、そこから「不要な辺」を削っていくことで、辺コストの総和を最小にすることを目指す。
// 「不要な辺」とは、 「v-u 間の最短経路」と「v-i 間の最短経路 + i-u 間の最短経路」が等しくなる頂点 i が存在するときの $E_{v,u}$
int main() {
    int n;
    cin >> n;
    vector<vector<int>> a(n, vector<int>(n));
    long long sum = 0;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            cin >> a[i][j];
            // 完全グラフを仮定して、二重辺を作らないように注意しながらコストの総和を計算する
            if (i < j)sum += a[i][j];
        }
    }

    for (int v = 0; v < n - 1; v++) {
        for (int u = v + 1; u < n; u++) {
            if (a[v][u] != a[u][v])invalid(); // v-u間の最短経路とu-v間の最短経路が同じでない無向グラフは明らかに存在しない
            for (int i = 0; i < n; i++) {
                if (i == v || i == u)continue;
                if (a[v][u] > a[v][i] + a[i][u])invalid(); // v-u間の最短経路よりv-i間最短経路+i-u間の最短経路の方が短くなるグラフは明らかに存在しない
                if (a[v][u] == a[v][i] + a[i][u]){
                    sum -= a[v][u];
                    break;
                }
            }
        }
    }
    cout << sum << endl;
}

