        else if (i != k && j != k && path[i][j] == path[i][k] + path[k][j] && !check[i][j]) {
            ans -= path[i][j];
            check[i][j] = check[j][i] = true;
        }
    }
    cout << (f?ans:-1) << endl;
}

int main(void){
  solve();
  return 0;
}

