    d.resize(n,vector<ll>(n,INFTY));
    vector<vector<ll>>a(n,vector<ll>(n));
    rep(i,n){
        rep(j,n){
            cin>>a[i][j];
            d[i][j]=a[i][j];
        }
    }
    warshall_floyd(n);
    rep(i,n){
        rep(j,n){
            if(d[i][j]<a[i][j]){
                cout<<-1<<endl;
                return;
            }
            rep(k,n){
                if((k==i)||(k==j))continue;
                if(d[i][k]+d[k][j]==d[i][j]){
                    d[i][j]=INF/2;
                }
            }
        }
    }
    ll ans=0;
    rep(i,n){
        REP(j,i+1,n){
            if(d[i][j]==INF/2)continue;
            ans+=d[i][j];
        }
    }
    cout<<ans<<endl;
}


