int solve(int n, vvi a) {
  vector<pair<int, pii>> dists;
  rep(i, n - 1)rep(j, i + 1, n)dists.push_back(mp(a[i][j], mp(i, j)));
  SORT(dists);
  vvi ca(n, vi(n, INF));
  rep(i, n)ca[i][i] = 0;
  int ans = 0;
  each(dist, dists) {
    int d = dist.first, row = dist.second.first, col = dist.second.second;
    if(ca[row][col] < d)return -1;
    if(ca[row][col] == d)continue;
    ans += d;
    ca[row][col] = d;
    ca[col][row] = d;
    bool ok = true;
    rep(i, n - 1)rep(j, i + 1, n) {
      amin(ca[i][j], ca[i][row] + d + ca[j][col]);
      amin(ca[i][j], ca[i][col] + d + ca[j][row]);
      ca[j][i] = ca[i][j];
      if(ca[i][j] != a[i][j])ok = false;
    }
    if(ok)return ans;
  }
  return -1;
}


