ll path(const vector<vector<ll>> &edges, vector<bool> &vis, int s, int g){
  vis[s] = true;
  if(edges[s][g] != -1)
    return edges[s][g];
  ll ret = 0;
  for(int i=0; i<edges.size(); i++){
    if(vis[i]) continue;
    if(edges[s][i] != -1){
      ll tmp = path(edges, vis, i, g);
      if(tmp != 0)
        ret += tmp + edges[s][i];
    }
  }
  return ret;
}

int main(int argc, const char * argv[]) {
  int N; cin >> N;
  vector<vector<ll>> A(N, vector<ll>(N));
  for(int i=0; i<N; i++)
    for(int j=0; j<N; j++)
      cin >> A[i][j];

  ll ans = 0;
  vector<vector<ll>> edges(N, vector<ll>(N, -1));
  vector<int> v(N-1), u1, u2;
  queue<tuple<int, vector<int>>> Q;
  iota(v.begin(), v.end(), 1);
  Q.emplace(0,v);
  while(Q.size()){
    int i;
    u1.clear(); u2.clear();
    tie(i, v) = Q.front(); Q.pop();

    // 最小の距離をもつ点は直接連結している
    ll minEi = v[0];
    for(auto vi: v)
      if(A[i][vi] < A[i][minEi]) minEi = vi;

    // 和とグラフを更新
    ans += A[i][minEi];
    edges[i][minEi] = A[i][minEi];
    edges[minEi][i] = A[i][minEi];

    // 未確定ノードの振り分け
    for(auto vi: v){
      if(vi == minEi) continue;
      if(A[i][vi] == A[i][minEi] + A[minEi][vi]) u1.push_back(vi);
      else u2.push_back(vi);
    }

    // 空でないならpush
    if(u1.size()) Q.emplace(minEi, u1);
    if(u2.size()) Q.emplace(i, u2);
  }

  // 矛盾がないか確認
  vector<bool> vis(N);
  for(int i=0; i<N; i++){
    for(int j=0; j<N; j++){
      if(i == j) continue;
      vis.assign(N, false);
      ll tmp = path(edges, vis, i, j);
      if(tmp != A[i][j]) {
        ans = -1;
        break;
      }
    }
  }

  cout << ans << endl;
  return 0;
}

