using namespace std;
typedef long long ll;

struct edge{ll to, cost;}; //edgeパラメータ
typedef pair<ll,ll> P;
struct graph{
  ll N; //ノードの個数
  vector<vector<edge> > G; //G[辺の元]((.to辺の先,.costコスト),...)
  vector<ll> d; // dist[n] = ノードnまでのの重み
  vector<ll> parent;

  graph(ll n){ //グラフ生成時
    N = n;
    G.resize(N); //Edge情報
    d.resize(N); //Node情報,ans
    parent.resize(N);
    rep(i,N){d[i] = INF;}
  }

  void add_edge(ll s, ll t, ll cost){
    G[s].emplace_back((edge){t, cost});
  }

  ll dijkstra(ll s, ll goal){
    rep(i,N){d[i] = INF;}
    d[s] = 0;
    priority_queue<P,vector<P>, greater<P> > que; //ansが小さい順に出る
    que.push(P(0,s)); // P < ans , Node >
    while(!que.empty()){
      P p = que.top(); que.pop(); //pに <ans,Node> 入れる
      ll v = p.second; //vに Node 入れる
      if(d[v] < p.first) continue; //すでに良い数値が入っているならパス
      rep(i,G[v].size()){
        edge& E = G[v][i];
        if(d[E.to] > d[v] + E.cost){ //更新するなら
          d[E.to] = d[v]+ E.cost;
          parent[E.to] = v; //親を記録,goalから遡れば道順
          que.push(P(d[E.to], E.to));
        }
      }
    }
    return d[goal];
  }
};

void Main(){

  int N;

  cin>>N;

  vector<tuple<int,int,int>> tp;

  rep(i,N){
    rep(j,N){
      int a; cin>>a;
      if(i==j or i>j) continue;
      tp.emplace_back(a,i,j);
    }
  }

  SORT(tp);

  graph g(N);
  ll ans=0;

  for(auto& x:tp){
    int x0=get<0>(x);
    int x1=get<1>(x);
    int x2=get<2>(x);

    ll dist=g.dijkstra(x1,x2);
    if(x0==dist) continue;
    if(x0>dist){
      cout<< -1 <<"\n";
      return;
    }
    else{
      g.add_edge(x1,x2,x0);
      g.add_edge(x2,x1,x0);
      ans+=x0;
    }
  }

  cout<< ans<<"\n";

}

