using Cost = int64_t;
using DistMat = std::vector< std::vector<Cost> >;


/**
 * return minmum cost path from->(somewhere)->to.
 * Path has least 1 node to arrive(from -> some_point -> to).
 *
 * \param [in] A distance mat. -1 means "no path".
 * return -1 if cost is larger then "max".
 */
Cost find_non_direct_min_path(
    const DistMat &A,
    int from, int to,
    Cost max)
{
  // find min costs by dijikstra
  // std::cout << __FUNCTION__ << ": " << from << " -> " << to << " max=" << max << std::endl;

  int N = (int)A.size();
  std::multimap<Cost, int> costs_id; // cost map to retrieve next step
  std::vector<Cost> costs;
  costs.assign(N, -1);
  costs[from] = 0;
  costs_id.insert(std::make_pair(0, from));

  std::vector<int> prev;
  prev.assign(N, -1);
  bool directs = true;

  while(!costs_id.empty()) {
    auto tgt = costs_id.begin();
    Cost cost_frm = tgt->first;
    auto frm = tgt->second;
    costs_id.erase(tgt);

    if(costs[frm] < cost_frm) {
      // std::cout << frm << " skip cost[frm],cost_frm = " << costs[frm] << "," << cost_frm << std::endl;
      continue;
    }

    // see all node because of full mesh graph
    for(int nxt=0; nxt<N; nxt++) {
      auto cost_frm_nxt = A[frm][nxt];
      if(nxt == frm || cost_frm_nxt < 0) {
        // std::cout << frm << "->" << nxt << " skip cfn=" << cost_frm_nxt << std::endl;
        continue; // no path
      }
      if(directs && nxt == to) {
        directs = false;
        continue;
      }
      // std::cout << "frm: " << frm << " nxt: " << nxt << " cfn: " << cost_frm_nxt << std::endl;

      auto new_cost = cost_frm + cost_frm_nxt;
      // std::cout << "cost_frm: " << cost_frm << " cost_frm_nxt: " << cost_frm_nxt << std::endl;
      if((0 <= costs[nxt] &&
          costs[nxt] < new_cost) ||
         max < new_cost) {
        // std::cout << frm << "->" << nxt << " skip new_cost=" << new_cost << std::endl;
        continue;
      }

      // std::cout << "costs[" << nxt << "]: " << new_cost << std::endl;
      costs[nxt] = new_cost;
      prev[nxt] = frm;
      costs_id.insert(std::make_pair(costs[nxt], nxt));
    }
  }

  return costs[to];
}


int main()
{
  // assume every path is direct
  // and then cut useless path

  // read input
  int N;
  std::cin >> N;

  DistMat A(N);
  for(int i=0; i<N; i++) {
    A[i].assign(N, 0);
    for(int j=0; j<N; j++) {
      std::cin >> A[i][j];
    }
  }

  // cut useless edge
  bool impossible = false;
  for(int i=0; i<N; i++) {
    for(int j=i+1; j<N; j++) {
      auto min_cost = A[i][j];
      if(min_cost < 0) continue;

      auto alt_cost = find_non_direct_min_path(A, i, j, min_cost);
      // std::cout << "(" << i << "," << j << "): alt_cost = " << alt_cost << std::endl;
      if(0 < alt_cost && alt_cost < min_cost) {
        // std::cout << i << "->" << j << ": illegal alt:min = " << alt_cost << ":" << min_cost << std::endl;
        impossible = true;
        goto END;
      }
      if(alt_cost == min_cost) { // cat drop direct path
        // std::cout << i << "->" << j << ": drop" << std::endl;
        A[i][j] = A[j][i] = -1;
      }
    }
  }

END:
  Cost ret = 0;
  if(impossible) {
    ret = -1;
  } else {
    for(int i=0; i<N; i++) {
      for(int j=i+1; j<N; j++) {
        if(A[i][j] > 0) {
          ret += A[i][j];
        }
      }
    }
  }

  std::cout << ret << std::endl;
  return 0;
}

