ll a[MAXN][MAXN];
ll dist[MAXN][MAXN];

void solve() {
  vector<PP> v;
  for (int i=0;i<n;i++) {
    for (int j=i+1;j<n;j++) {
      if (a[i][i] != 0 || a[i][j] != a[j][i]) {
        cout << -1 << endl;
        return;
      }
      v.push_back(PP(a[i][j], P(i, j)));
    }
  }
  sort(v.begin(), v.end());
  for (int i=0;i<n;i++) {
    for (int j=0;j<n;j++) {
      dist[i][j] = INF;
    }
    dist[i][i] = 0;
  }
  ll sum = 0;
  for (int i=0;i<v.size();i++) {
    ll d = v[i].first;
    P p = v[i].second;
    ll curDist = dist[p.first][p.second];
    if (curDist < d) {
      cout << -1 << endl;
      return;
    }
    if (curDist > d) {
      sum += d;
      dist[p.first][p.second] = dist[p.second][p.first] = d;
      for (int i=0;i<n;i++) {
        dist[p.first][i] = min(dist[p.first][i], d + dist[p.second][i]);
        dist[p.second][i] = min(dist[p.second][i], d + dist[p.first][i]);
        dist[i][p.first] = min(dist[i][p.first], dist[i][p.second] + d);
        dist[i][p.second] = min(dist[i][p.second], dist[i][p.first] + d);
      }
    }
  }
  cout << sum << endl;
}

