class UnionFind {
public:
    // 親の番号を格納する。親だった場合-size
    vector<int> parents;

    UnionFind(int n) {
        parents = vector<int>(n, -1);
    }

    // aがどのグループに属しているか
    int root(int a) {
        if (parents[a] < 0) {
            return a;
        }
        return parents[a] = root(parents[a]);
    }

    int size(int a) {
        return -parents[root(a)];
    }

    // aとbをくっつける
    bool connect(int a, int b) {
        int ra = root(a);
        int rb = root(b);
        if (ra == rb) {
            return false;
        }
        // 大きいほうにA
        if (size(ra) < size(rb)) {
            swap(ra, rb);
        }
        parents[ra] += parents[rb];
        parents[rb] = ra;
        return true;
    }

    bool is_union(int a, int b) {
        int ra = root(a);
        int rb = root(b);
        return ra == rb;
    }
};

struct Road {
    int from, to;
    ll cost;
};

class WarchallFloyd {

    int n;

public:
    vector<vector<ll>> distances;

    WarchallFloyd(int n) : n(n), distances(n, vector<ll>(n, INF)) {
        rep(i, n) distances[i][i] = 0;
    };

    void warshall_floyd() {
        for (int k = 0; k < n; k++) {       // 経由する頂点
            for (int i = 0; i < n; i++) {    // 始点
                for (int j = 0; j < n; j++) {  // 終点
                    if (distances[i][j] == INF && (distances[i][k] == INF || distances[k][j] == INF)) {
                        distances[i][j] = INF;
                    } else {
                        distances[i][j] = min(distances[i][j], distances[i][k] + distances[k][j]);
                    }
                }
            }
        }
    }

    ll distance(int from, int to) {
        return distances[from][to];
    }

    void add(int from, int to, ll cost) {
        distances[from][to] = cost;
    }


    friend std::istream &operator>>(std::istream &in, WarchallFloyd &o) {
        int from, to;
        ll c;
        cin >> from >> to >> c;
        from--;
        to--;

        o.distances[from][to] = c;
        o.distances[to][from] = c;
        return in;
    }


};


int main() {
    int n;
    cin >> n;

    vector<vector<ll>> costs(n, vector<ll>(n));
    rep(y, n)rep(x, n) cin >> costs[y][x];

    WarchallFloyd wf(n);
    rep(y, n) rep(x, n) wf.add(y, x, costs[y][x]);
    wf.warshall_floyd();

    if (wf.distances != costs) {
        cout << -1 << endl;
        ret();
    }

    vector<Road> v;
    rep(y, n) rep(x, n) {
            if (y <= x) continue;
            v.push_back({y, x, costs[y][x]});
        }

    sort(v.begin(), v.end(), [](Road r1, Road r2) {
        return r1.cost < r2.cost;
    });

    ll ans = 0;
    for (Road r : v) {
        bool b = [&] {
            rep(i, n) {
                if (i == r.from || i == r.to) continue;
                if (costs[r.from][i] + costs[i][r.to] <= r.cost) return false;
            }
            return true;
        }();
        if (!b) continue;
        ans += r.cost;
    }

    cout << ans << endl;

}

