  for(int i=0; i<N; i++){
    for(int j=0; j<N; j++){
      cin >> A[i][j];
      B[i][j] = A[i][j];
    }
  }

  warshall_floyd(N, B);

  ll ans = 0;
  for(int i=0; i<N; i++){
    for(int j=i+1; j<N; j++){
      if(A[i][j] != B[i][j]){
        ans = -1;
        break;
      }
      ll minVia = INF;
      for(int k=0; k<N; k++){
        if(k == i || k == j) continue;
        minVia = min(B[i][k] + B[k][j], minVia);
      }
      if(minVia > B[i][j])
        ans += B[i][j];
    }
    if(ans == -1) break;
  }

  cout << ans << endl;

  return 0;
}

