class UnionFind {
public:
  vector <ll> par;
  vector <ll> siz;
  UnionFind(ll sz_): par(sz_), siz(sz_, 1LL) {
	for (ll i = 0; i < sz_; ++i) par[i] = i;
  }
  void init(ll sz_) {
	par.resize(sz_);
	siz.assign(sz_, 1LL);
	for (ll i = 0; i < sz_; ++i) par[i] = i;
  }
  ll root(ll x) {
	while (par[x] != x) {
	  x = par[x] = par[par[x]];
	}
	return x;
  }
	bool merge(ll x, ll y) {
		x = root(x);
		y = root(y);
		if (x == y) return false;
		if (siz[x] < siz[y]) swap(x, y);
		siz[x] += siz[y];
		par[y] = x;
		return true;
	}
	bool issame(ll x, ll y) {
		return root(x) == root(y);
	}
	ll size(ll x) {
		return siz[root(x)];
	}
};

int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
	int N; cin >> N;
	vector<vector<ll>> A(N, vector<ll>(N));
	rep(i,N) rep(j,N) cin >> A[i][j];

	priority_queue<tuple<ll, int, int>, vector<tuple<ll, int, int>>, greater<tuple<ll, int, int>>> pq;
	rep(i,N-1) for (int j = i+1; j < N; j++) pq.emplace(A[i][j],i,j);

	vector<vector<ll>> G(N, vector<ll>(N,1e15));
	UnionFind uf(N);
	bool ok = true;
	rep(i,N) G[i][i] = 0;
	ll ans = 0;
	while(!pq.empty()) {
		ll l; int p,q;
		tie(l,p,q) = pq.top(); pq.pop();
		if (uf.issame(p,q)) {
			if (l > G[p][q]) {
				ok = false;
				break;
			} else if (l < G[p][q]){
				G[p][q] = G[q][p] = l;
                ans += l;
				rep(i,N) {
					rep(j,N) {
						chmin(G[i][j], G[i][p] + l + G[q][j]);
						chmin(G[i][j], G[i][q] + l + G[p][j]);
						G[j][i] = G[i][j];
					}
				}
			}
		} else {
			uf.merge(p,q);
			G[p][q] = G[q][p] = l;
			ans += l;
			rep(i,N) {
				rep(j,N) {
					chmin(G[i][j], G[i][p] + l + G[q][j]);
					chmin(G[i][j], G[i][q] + l + G[p][j]);
					G[j][i] = G[i][j];
				}
			}
		}
	}

	cout << (ok ? ans : -1) << endl;
}

