// ワーシャルフロイド法で全点間の距離を求める

const ll INF = (1LL<<32);
vector<vector<ll> > d;  // グラフの距離を格納した2次元配列（隣接行列）
// d[u][v]は辺e=(u,v)のコスト（辺が存在しない場合はINF、ただしd[i][i]=0）

void warshall_floyd(int n){  // nは頂点数
  for(int i = 0; i < n; i++){  // 経由する頂点
    for(int j = 0; j < n; j++){  // 開始頂点
      if(d[j][i] == INF) continue;
      for(int k = 0; k < n; k++){  // 終端
        if(d[i][k] == INF) continue;
        d[j][k] = min(d[j][k], d[j][i] + d[i][k]);
      }
    }
  }
}

int main(){
  ios::sync_with_stdio(false);
  cin.tie(0);
  int N; cin >> N;
  d.assign(N, vector<ll>(N, INF));
  REP(i, N){
    REP(j, N){
      cin >> d[i][j];
    }
  }
  vector<vector<ll> > A = d;
  warshall_floyd(N);
  bool flag1 = true;
  ll ans = 0;
  REP(i, N){
      for(int j = i+1; j < N; j++){
      if(A[i][j] > d[i][j]){
        flag1 = false;
      }else{
        bool flag2 = true;
        REP(k, N){
          if(i == k || j == k) continue;
          if(d[i][k] + d[k][j] == d[i][j]){
            flag2 = false;
            break;
          }
        }
        if(flag2) ans += d[i][j];
      }
      if(!flag1){
        cout << -1 << endl;
        return 0;
      }
    }
  }
  cout << ans << endl;
}

