bool disable[305][305];

template<size_t N>
int hoge(MatrixGraph<N> &G, int V) // {{{
{
    for (int k = 0; k < V; ++k) {
        for (int i = 0; i < V; ++i) {
            if (G[i][k] >= LINF) continue;
            for (int j = 0; j < V; ++j) {
                if (G[k][j] >= LINF) continue;
                if (i != j && j != k && i != k) {
                    if (G[i][j] == G[i][k] + G[k][j]) {
                        disable[i][j] = disable[j][i] = true;
                    } else if (G[i][j] > G[i][k] + G[k][j]) {
                        return -1;
                    }
                }
            }
        }
    }

    return 0;
}
// }}}

