struct UnionFind{
    vector<int> par;
    UnionFind(int n){
        REP(i,n)par.pb(i);
    }
    int root(int x){
        if(par[x] == x)return x;
        return par[x] = root(par[x]);
    }
    void unite(int x, int y){
        x = root(x);
        y = root(y);
        if(x == y)return;
        par[x] = y;
    }
    bool same(int x, int y){
        return root(x) == root(y);
    }
};

