vector<vector<ll>> Wa_Fl(wGraph G,ll N){
    vector<vector<ll>> d(N);
    for (int j = 0; j < N; ++j) {
        d[j] = vector<ll>(N);
        for (int i = 0; i < N; ++i) {
            if(j == i){
                d[j][i] = 0;
            }else{
                d[j][i] = (1ll << 50);
            }
        }
    }
    for (int i = 0; i < G.size(); ++i) {
        for (int j = 0; j < G[i].size(); ++j) {
            d[i][G[i][j].first] = G[i][j].second;
            d[G[i][j].first][i] = G[i][j].second;
        }
    }
    for (int k = 0; k < N; ++k) {
        for (int i = 0; i < N; ++i) {
            for (int j = 0; j < N; ++j) {
                if(d[i][j] > d[i][k] + d[k][j]){
                    d[i][j] = d[i][k] + d[k][j];
                    d[j][i] = d[i][k] + d[k][j];
                }
            }
        }
    }
    return d;
}


