using namespace std;
class UnionFind{
	int32_t *par;
	int32_t *rank;
private:
	int32_t root(int32_t num){
		if(par[num]==num){
			return num;
		}else{
			return par[num]=root(par[num]);
		}
	}
public:
	UnionFind(const int32_t size){
		par = new int32_t[size];
		rank=new int32_t[size];
		for(int32_t i=0;i<size;i++){
			par[i]=i;
			rank[i]=0;
		}
	}
	bool same(int32_t a,int32_t b){
		return root(a)==root(b);
	}
	void unite(int32_t a,int32_t b){
		if(root(a)==root(b)){
			return;
		}
		a=root(a);
		b=root(b);
		if(rank[a]<rank[b]){
			par[a]=b;
		}else if(rank[a]==rank[b]){
			par[a]=b;
			rank[b]++;
		}else{
			par[b]=a;
		}

	}
	virtual ~UnionFind(){
		delete[] par;
		delete[] rank;
	}
};
struct edge{
	int32_t v1;
	int32_t v2;
	int32_t cost;
};
bool operator<(const edge& a,const edge& b){
	return a.cost<b.cost;
}
int main() {
	int32_t n;
	cin>>n;
	vector<edge> e;
	e.reserve(n);
	int32_t **cost_matrix=new int32_t*[n];
	for(int32_t i1=0;i1<n;i1++){
		cost_matrix[i1]=new int32_t[n];
		for(int32_t i2=0;i2<n;i2++){
			int32_t temp;
			cin>>temp;
			cost_matrix[i1][i2]=temp;
			if(i1<i2){
				e.push_back(edge{i1,i2,temp});
			}
		}
	}
	sort(e.begin(),e.end());
	UnionFind l(n);
	int64_t cost=0;
	bool possible=true;
	for(auto i=e.begin();i!=e.end();i++){
		if(l.same(i->v1,i->v2)){
			bool under=false;
			bool equal=false;
			for(int32_t i2=0;i2<n;i2++){
				if(i2==i->v1||i2==i->v2){
					continue;
				}
				if(cost_matrix[i->v1][i2]+cost_matrix[i2][i->v2]<i->cost){
					under=true;
				}else if(cost_matrix[i->v1][i2]+cost_matrix[i2][i->v2]==i->cost){
					equal=true;
				}

			}
			if(under){
				possible=false;
				goto END;
			}else if(!equal){
				cost+=i->cost;
			}
		}else{
			l.unite(i->v1,i->v2);
			cost+=i->cost;
		}
	}
	END:
	if(possible){
		cout<<cost<<endl;
	}else{
		cout<<-1<<endl;
	}

}

