int N;
LLI ans;
int as[300][300];
int ds[300][300];
priority_queue<Pair> que;

int main() {
  scanf("%d", &N);
  for (int i=0; i<N; i++) {
    for (int j=0; j<N; j++) {
      scanf("%d", &as[i][j]);
      ds[i][j] = as[i][j];
      if (i < j) {
        ans += ds[i][j];
        que.push(Pair(ds[i][j], Data(i, j)));
      }
    }
  }

  for (int k=0; k<N; k++) {
    for (int i=0; i<N; i++) {
      for (int j=0; j<N; j++) {
        as[i][j] = min(as[i][j], as[i][k] + as[k][j]);
      }
    }
  }

  for (int i=0; i<N; i++) {
    for (int j=0; j<N; j++) {
      if (as[i][j] != ds[i][j]) {
        puts("-1");
        return 0;
      }
    }
  }

  while (!que.empty()) {
    Pair p = que.top(); que.pop();
    int md = p.first;
    int u, v;
    tie(u, v) = p.second;
    ds[u][v] = ds[v][u] = INF;
