#include <bits/stdc++.h>
using namespace std;

bool warshall_floyd(const int n,
                    vector<vector<int64_t>>& cost,
                    vector<vector<int64_t>>& updated) {
    for (auto i = 0; i < n; i++) cost[i][i] = 0;

    for (auto k = 0; k < n; k++) {
        for (auto i = 0; i < n; i++) {
            for (auto j = 0; j < n; j++) {
                if(i == k or j == k) continue;
                if(cost[i][j] == cost[i][k] + cost[k][j]) {
                    updated[i][j] = (1LL << 60);
                }
                if(cost[i][j] > cost[i][k] + cost[k][j]) {
                    return false;
                }
            }
        }
    }
    return true;
}

int main(){
    int n;
    cin >> n;

    vector<vector<int64_t>> a(n, vector<int64_t>(n, (1LL << 60)));
    for (auto i = 0; i < n; i++) {
        for (auto j = 0; j < n; j++) cin >> a[i][j];
    }

    vector<vector<int64_t>> b = a;
    bool flg = warshall_floyd(n, a, b);
    if(not flg) {
        cout << -1 << endl; return 0;
    }

    int64_t ans = 0;
    for (auto i = 0; i < n; i++) {
        for (auto j = 0; j < n; j++) {
            if(j < i and b[i][j] != (1LL << 60)) ans += b[i][j];
        }
    }
    cout << ans << endl;
    return 0;
}

