template<typename T>
struct WarshallFloyd {
    vector<vector<T>> ds;
    vector<vector<int>> next;
    WarshallFloyd() = default;
    WarshallFloyd(int n) : ds(n, vector<T>(n, numeric_limits<T>::max())), next(n, vector<int>(n)){
        for(int i = 0;i < n;++i) ds[i][i] = 0;
        for(int i = 0;i < n;++i) for(int j = 0;j < n;++j) next[i][j] = j;
    }
    void addEdge(int u, int v, T c){
        ds[u][v] = c;
    }
    void build(){
        int n = ds.size();
        for(int k = 0;k < n;++k) for(int i = 0;i < n;++i){
            if(ds[i][k] == numeric_limits<T>::max()) continue;
            for(int j = 0;j < n;++j){
                if(ds[k][j] == numeric_limits<T>::max()) continue;
                if(ds[i][j] > ds[i][k]+ds[k][j]) ds[i][j] = ds[i][k]+ds[k][j], next[i][j] = next[i][k];
            }
        }
    }
    const vector<T>& operator[](int n) const { return ds[n]; }
    vector<int> restore(int from, int to){
        vector<int> res;
        while(from != to) res.push_back(from), from = next[from][to];
        res.push_back(to);
        return res;
    }
    bool negativeCycle(){
        int n = ds.size();
        for(int i = 0;i < n;++i) if(ds[i][i] < 0) return true;
        return false;
    }
};


