        int f_toshi = pq.top().second.first;
        int t_toshi = pq.top().second.second;
        check[f_toshi] = true;
        list[f_toshi] = now_cost;
        pq.pop();
        for (int i = 0; i < n; i++) {
            if (check[i] == false) {
                pq.push(make_pair(table[f_toshi][i], make_pair(f_toshi, i)));
            }
        }
    }

    int cost = 0;
    for (int i = 0; i < n; i++) {
        cost += list[i];
    }
    return cost;
}


