	for (int i = 1; i <= N; i++) {
		for (int j = 1; j <= N; j++) { cin >> dp[i][j]; dist[i][j] = dp[i][j]; }
	}
	for (int k = 1; k <= N; k++) {
		for (int i = 1; i <= N; i++) {
			for (int j = 1; j <= N; j++) dp[i][j] = min(dp[i][j], dp[i][k] + dp[k][j]);
		}
	}

	vector<tuple<int, int, int>> tup;
	UnionFind UF; UF.init(N + 2);
	long long ret = 0;

	for (int i = 1; i <= N; i++) {
		for (int j = 1; j <= N; j++) {
			if (dist[i][j] != dp[i][j]) {
				cout << "-1" << endl;
				return 0;
			}
			if (i != j) {
				bool flag = false;
				for (int k = 1; k <= N; k++) {
					if (i == k || j == k) continue;
					if (dp[i][k] + dp[k][j] == dp[i][j]) flag = true;
				}
				if (flag == true) {
					tup.push_back(make_tuple(dist[i][j], i, j));
				}
				else {
					if (i < j) {
						ret += 1LL * dp[i][j];
						UF.unite(i, j);
					}
				}
			}
		}
	}
	sort(tup.begin(), tup.end());

	for (int i = 0; i < tup.size(); i++) {
		int pos1 = get<1>(tup[i]), pos2 = get<2>(tup[i]);
		if (UF.same(pos1, pos2) == false) {
			ret += 1LL * get<0>(tup[i]);
			UF.unite(pos1, pos2);
		}
	}
	cout << ret << endl;
	return 0;
}

