vector<pair<int, int>> pathrec(int start, int goal) {
    int cur = start;
    vector<pair<int, int>> path;
    while(cur != goal) {
        for(int i = 0; i < V; i++)
            if(i != cur && g[cur][i] + d[i][goal] == d[cur][goal]) {
                path.push_back(make_pair(cur, i));
                cur = i;
                break;
            }
    }
    return path;
}

