    d[s]=0;
    priority_queue<P,vector<P>,greater<P>> task;
    task.push(P(0,s));
    for(int i=0;i<es[s].size();i++)task.push(P(es[s][i].cost,es[s][i].to));
    while(!task.empty()){
        P p=task.top();
        task.pop();
        int v=p.second;
        if(d[v]<p.first)continue;
        for(int i=0;i<es[v].size();i++){
            edge e=es[v][i];
            if(d[e.to]>d[v]+e.cost){
                d[e.to]=d[v]+e.cost;
                task.push((P(d[e.to],e.to)));
            }
        }
    }
}
