using namespace std;


vector<vector<int>> warshallFloyd(vector<vector<int>> ary, int N){
	vector<vector<int>> v(ary);
	for (size_t k = 0; k < N; k++) {
		for (size_t i = 0; i < N; i++) {
			for (size_t j = 0; j < N; j++) {
				v[i][j] = min(v[i][j] , v[i][k] + v[k][j]);
			}
		}
	}
	return v;
}


int main(int argc, char const *argv[]) {
	int N,temp;
	cin >> N;
	vector<vector<int>> v;
	v.resize(N);
	for (size_t i = 0; i < N; i++) {
		for (size_t j = 0; j < N; j++) {
			std::cin >> temp;
			v[i].push_back(temp);
		}
	}

	// warshall Floyd法により各点から各点への最小距離を出す
	vector<vector<int>> ideal(warshallFloyd(v,N));

	// とりあえず入力が本当に最小距離だったのか判定
	for (size_t i = 0; i < N; i++) {
		for (size_t j = 0; j < N; j++) {
			// 入力が最小距離じゃなかったら終了
			if (v[i][j] > ideal[i][j]) {
				std::cout << -1 << '\n';
				return -1;
			}
		}
	}


	bool flag;
	unsigned long long ans = 0;
	for (size_t i = 0; i < N; i++) {
		for (size_t j = 0; j < N; j++) {
			flag = true;
			for (size_t k = 0; k < N; k++) {
				if (k != i && k != j) {
					if (ideal[i][j] == ideal[i][k] + ideal[k][j]) {
						flag = false;
					}
				}
			}
			if (flag) {
				ans += ideal[i][j];
			}
		}
	}

	std::cout << ans/2 << '\n';

	return 0;
}

