            return x;
        else {
            par[x] = root(par[x]);
            return par[x];
        }
    }

    void unite(int x, int y) {
        x = root(x), y = root(y);
        if (x == y) return;
        if (rank[x] < rank[y])
            swap(x, y);
        else if (rank[x] == rank[y])
            rank[y]++;
        par[y] = x;
        count[x] += count[y];
        return;
    }

    int size(int x) {
        return count[root(x)];
    }

    bool issame(int x, int y) {
        return root(x) == root(y);
    }
};
using UF = struct UnionFind;

template <typename T>
vector<T> dijkstra(vector<vector<pair<ll, T>>> &G, ll start){
    using P = pair<T, ll>;
    const T inf = numeric_limits<T>::max();
    ll N = G.size();
    vector<T> dist(N, inf);
    vector<ll> route(N, -1);
    priority_queue<P, vector<P>, greater<P>> pq;
    dist[start] = 0;

    pq.emplace(dist[start], start);
    while(!pq.empty()){
        P p = pq.top();
        pq.pop();
        T c;ll from;
        tie(c, from) = p;
        if (dist[from] < c) continue;
        for(auto& e:G[from]){
            ll to;T cost;
            tie(to,cost) = e;
            if(dist[to]>dist[from]+cost){
                dist[to] = dist[from] + cost;
                route[to] = from;
                pq.emplace(dist[to], to);
            }
        }
    }
    // 各頂点までの最小コスト
    return dist;
    // 始点から各頂点へのルート
    // return route;
}
