    using TU = tuple<ll, ll, ll>;
    priority_queue<TU, vc<TU>, greater<TU>> pq;
    rep(i,N-1)repe(j,i+1,N){
        pq.emplace(A[i][j], i, j);
    }

    vvc<pair<ll, ll>> G(N);
    bool isok = true;
    while(!pq.empty()){
        ll cost, a, b;
        tie(cost, a, b) = pq.top(), pq.pop();
        if(uf.issame(a,b)){
            vl dist = dijkstra(G, a);
            if(dist[b]<cost){
                isok=false;
                break;
            }
            else if(dist[b]>cost){
                G[a].eb(b, cost);
                G[b].eb(a, cost);
                uf.unite(a, b);
            }
        }else{
            G[a].eb(b, cost);
            G[b].eb(a, cost);
            uf.unite(a, b);
        }
    }

    if(!isok){
