	}

	void makeTree(int r) {
		root = r;
		p = make_v<int>(size);
		p[root] = -1;
		depth = make_v<int>(size);
		mtdfs(root, 0);
		// count leaf node
		auto idxs = make_v<int>(size);
		iota(all(idxs), 0);
		leaf_idx = set<int>(all(idxs));
		FOR(i, 1, size)
			leaf_idx.erase(p[i]);
	}

	void makeEulerTour() {
		assert(root >= 0);
		et_begin = make_v<int>(size);
		et_end = make_v<int>(size);
		tmp_k = 0;
		etdfs(root, -1);
	}

	int size, root;
	vector<int> p; // parent for each node. parent of root = -1
	vector<int> depth; // for each node. depth of root node = 0
	vector<int> euler_tour;
	vector<int> et_begin, et_end;
	set<int> leaf_idx;

	int tmp_k;
private:	
	void mtdfs(int c, int d) {
		depth[c] = d;
		REP(i, to[c].size()) {
			int next = to[c][i];
			if (p[c] == next) continue;
			p[next] = c;
			mtdfs(next, d + 1);
		}
	}
	void etdfs(int vidx, int pidx) {
		et_begin[vidx] = tmp_k;
		euler_tour.push_back(vidx);
		tmp_k++;
		REP(i, to[vidx].size()) {
			if (to[vidx][i] != pidx) {
				etdfs(to[vidx][i], vidx);
				euler_tour.push_back(vidx);
				tmp_k++;
			}
		}
		et_end[vidx] = tmp_k;
	}
};

template <typename T>
class BinaryIndexedTree {
public:
	int size;
	vector<T> data;

	BinaryIndexedTree(int s, T initial_value = T(0)) {
		size = s;
		data = make_v<T>(size+1);
		fill_v(data, initial_value);
	}

	void add(int idx, T value) {
		while (idx <= size) {
			data[idx] += value;
			idx += idx & -idx;
		}
	}

	T sum(int idx) {
		T s = 0;
		while (idx > 0) {
			s += data[idx];
			idx -= idx & -idx;
		}
		return s;
	}
};



