void _main()
{
    int N;
    cin >> N;
    vector<vector<ll>> A(N, vector<ll>(N));
    rep(i, 0, N) rep(j, 0, N) cin >> A[i][j];
    vector<tuple<ll, int, int>> v;
    rep(i, 0, N)
    {
        rep(j, i + 1, N)
        {
            v.push_back(make_tuple(A[i][j], i, j));
        }
    }
    sort(v.begin(), v.end());

    UnionFind uf(N);

    ll distSum = 0;

    vector<vector<ll>> B(N, vector<ll>(N));
    rep(i, 0, N) rep(j, 0, N)
    {
        if (i == j) B[i][j] = 0;
        else B[i][j] = 100000000000000;
    }

    for (const auto& t : v)
    {
        ll dist;
        int i, j;
        tie(dist, i, j) = t;

        if (uf.Same(i, j))
        {
            if (B[i][j] < dist)
            {
                cout << -1 << endl;
                return;
            }
            else if (B[i][j] > dist)
            {
                distSum += dist;
                B[i][j] = B[j][i] = dist;
            }
        }
        else
        {
            uf.Unite(i, j);

            distSum += dist;

            B[i][j] = B[j][i] = dist;
        }

        rep(k, 0, N)
        {
            if (i == k || j == k) continue;

            if (uf.Same(i, k))
            {
                if (chmin(B[i][k], dist + B[j][k]))
                {
                    B[k][i] = B[i][k];
                }
            }

            if (uf.Same(j, k))
            {
                if (chmin(B[j][k], dist + B[i][k]))
                {
                    B[k][j] = B[j][k];
                }
            }
        }
    }

    cout << distSum << endl;
}

def restoring_road_network(N: int, A: list)->int:
    total = 0
    for i in range(N):
        for j in range(i+1, N):
            ok = True
            for k in range(N):
                if i == k or k == j:
                    continue
                if A[i][k] + A[k][j] < A[i][j]:
                    return -1
                if A[i][k] + A[k][j] == A[i][j]:
                    ok = False
            if ok:
                total += A[i][j]

    return total


