int main(){
    int n;
    cin >> n;

    vector<vector<long long int>> a(n, vector<long long int>(n));
    vector<pair<long long int, pair<int, int>>> data;
    for(int i=0; i<n; i++){
        for(int j=0; j<n; j++){
            cin >> a[i][j];
            if(i < j) data.push_back({a[i][j], {i, j}});
        }
    }
    sort(data.begin(),data.end());

    // Warshall-Floyd
    vector<vector<long long int>> d = a;// d[i][j] = shortest distances between i and j
    for(int k=0; k<n; k++){// potential relay points
        for(int i=0; i<n; i++){
            for(int j=0; j<n; j++){
                d[i][j] = min(
                    d[i][j],// without going through k
                    d[i][k] + d[k][j]// with going through k
                );
            }
        }
    }

    for(int i=0; i<n; i++){
        for(int j=i+1; j<n; j++){
            if(a[i][j] > d[i][j]){
                cout << -1 << endl;
                return 0;
            }
        }
    }

    long long int ans = 0;
    for(int i=0; i<n; i++){
        for(int j=i+1; j<n; j++){
            ans += a[i][j];
            for(int k=0; k<n; k++){// potential relay points
                if(i != k && j != k && d[i][j] == d[i][k] + d[k][j]){
                    ans -= a[i][j];
                    break;
                }
            }
        }
    }
    cout << ans << endl;
    return 0;
}

