    }
  }

  std::vector< std::vector<uint64_t> > B(A);
  for (uint64_t n = 0; n < N; ++n) {
    for (uint64_t m = 0; m < N; ++m) {
      if (n == m) continue;

      for (uint64_t l = 0; l < N; ++l) {
        if (B[n][m] > B[n][l] + B[l][m]) {
          B[n][m] = B[n][l] + B[l][m];
        }
      }
    }
  }

  for (uint64_t n = 0; n < N; ++n) {
    for (uint64_t m = 0; m < N; ++m) {
      if (A[n][m] > B[n][m]) {
        std::cout << -1 << std::endl;
        return 0;
      }
    }
  }

  uint64_t S = 0;

  for (uint64_t n = 0; n < N; ++n) {
