using Tup = tuple<ll, ll, ll>;

void solve() {
    ll N;
    cin >> N;
    vector<Vl> dist(N, Vl(N));
    for (ll i = 0; i < N; i++) {
        for (ll j = 0; j < N; j++) {
            cin >> dist[i][j];
        }
    }

    vector<Tup> bds;
    for (ll i = 0; i < N; i++) {
        for (ll j = 0; j < N; j++) {
            bds.emplace_back(dist[i][j], i, j);
        }
    }
    sort(bds.begin(), bds.end());

    bool ok = true;
    ll ans = 0;

    set<Pii> used;

    for (const auto& bd : bds) {
        ll d, idx1, idx2;
        tie(d, idx1, idx2) = bd;
        ll mn = L_INF;
        for (ll i = 0; i < N; i++) {
            if (used.find({idx1, i}) == used.end()) continue;
            if (used.find({idx2, i}) == used.end()) continue;
            mn = min(mn, dist[idx1][i] + dist[i][idx2]);
        }

        if (mn < d) {
            ok = false;
            break;
        }

        if (mn > d) {
            ans += d;
            used.emplace(idx1, idx2);
            used.emplace(idx2, idx1);
        }
    }

    if (ok) {
        cout << ans << endl;
    }
    else {
        cout << -1 << endl;
    }
}

