#include<bits/stdc++.h>
using namespace std;

using LL = long long;

vector<vector<LL>> WarshallFloyd(auto A) {
  const auto N = A.size();
  for(auto k=0; k<N; ++k) for(auto i=0; i<N; ++i) for(auto j=0; j<N; ++j) A[i][j] = min(A[i][j], A[i][k] + A[k][j]);
  return A;
}

LL solve(const auto& A) {
  if(A!=WarshallFloyd(A)) return -1;

  const auto N = A.size();
  LL sum = 0;
  for(auto i=0; i<N; ++i) for(auto j=0; j<N; ++j) {
    auto p = false;
    for(auto k=0; k<N; ++k) if(k!=i&&k!=j) p |= A[i][j] == A[i][k]+A[k][j];
    if(!p) sum += A[i][j];
  }
  return sum/2;
}

int main() {
  int N;
  cin >> N;
  vector<vector<LL>> A(N, vector<LL>(N));
  for(auto &i: A) for(auto& j: i) cin >> j;
  cout << solve(A) << endl;
}

