using namespace std;
typedef long long ll;

// ダイクストラ法
// http://nocotan.github.io/%E3%82%A2%E3%83%AB%E3%82%B4%E3%83%AA%E3%82%BA%E3%83%A0/2017/01/26/dijkstra-copy.html
using P = pair<ll, ll>;	// <最短距離, 頂点の番号>
void dijkstra(vector<vector<ll>> &g, vector<ll> &dist, ll s) {
    priority_queue<P, vector<P>, greater<P> > que;
    dist.assign(dist.size(), 1LL << 60);
    dist[s] = 0;
    que.push(P(0, s));
    while (!que.empty()) {
        P p = que.top();
        que.pop();
        ll v = p.second;
        if (dist[v] < p.first) continue;
        for (ll i=0; i<g[v].size(); ++i) {
            ll cost = g[v][i];
            if (dist[i] > dist[v] + cost) {
                dist[i] = dist[v] + cost;
                que.push(P(dist[i], i));
            }
        }
    }
}

int main() {
	int n;
	cin >> n;
	vector<vector<ll>> g(n, vector<ll>(n));
	rep(i, n) rep(j, n) cin >> g[i][j];
	bool ok = true;
	ll ans = 0;
	const ll INF = 1LL << 60;
	rep(i, n-1) {
		for (int j = i+1; j < n; j++) {
			// i to j
			ll tmp = g[i][j];
			// g[i][j]の削除
			g[i][j] = INF;
			g[j][i] = INF;
			// 最短距離が変わらなかったら、その辺は不要
			vector<ll> dist(n);
			dijkstra(g, dist, i);
			if(dist[j] < tmp) ok = false;
			else if (dist[j] != tmp) ans += tmp;
			g[i][j] = tmp;
			g[j][i] = tmp;
		}
	}

	if (ok) cout << ans << endl;
	else cout << -1 << endl;
	return 0;
}

