// 方針
/*
 * 1.   まだ登録されていない経路のうち，最も距離が小さい経路をグラフから取り出す．
 * 2.   既に決定されたグラフ上で，その経路の距離をダイクストラ法で計算する
 * 3.   計算された距離を，1で取り出した経路の距離と比較
 * 4-a. 取り出した経路のほうが短ければ，短い経路をグラフに登録する
 * 4-b. グラフから得た経路のほうが短ければ，スキップ
 * 5.   1に戻る
 *
 * O(n) * ダイクストラ = O(n) * O(n^2) = O(n^3)
 * (10^2)^3 = 10^6 : OK
 */

#include <iostream>
