void Warshall_Floyd(ll d[MAX][MAX], int n) {
	for (int k=0; k<n; k++) {
		for (int i=0; i<n; i++) {
			if (d[i][k] == INF) continue;
			for (int j=0; j<n; j++) {
				if (d[k][j] == INF) continue;
				d[i][j] = min(d[i][j], d[i][k] + d[k][j]);
			}
		}
	}
}

