int N;
long long g[300][300];

// O(V^3)
long long warshall_floyd(int n) {
    long long ret = 0;

    // check
    for(int k = 0; k < n; ++k)
        for(int i = 0; i < n; ++i)
            for(int j = 0; j < n; ++j) 
                if(g[i][j] > g[i][k] + g[k][j]) return -1;

    // calc
    for(int k = 0; k < n; ++k) 
        for(int i = 0; i < n; ++i) 
            for(int j = 0; j < n; ++j) {
                if(g[i][j] == 0 || g[i][k] == 0 || g[k][j] == 0) continue;
                if(g[i][j] == g[i][k] + g[k][j]) g[i][j] = 0; 
            }

    for(int i=0; i < n; ++i) 
        for(int j=0; j < n; ++j) 
            ret += g[i][j];

    return ret / 2;
}

