        if(i<j) pq.push({a[i][j],{i,j}});
    }
    rep(i,n)rep(j,n) b[i][j]=(i==j?0:LINF);
    long long ans=0;
    while(pq.size()){
        auto e=pq.top(); pq.pop();
        long long cost=e.first,from=e.second.first,to=e.second.second;
        if(b[from][to]>cost){
            ans+=cost;
            b[from][to]=b[to][from]=cost;
            edge[from].push_back({to,cost});
            edge[to].push_back({from,cost});
            dijkstra(from);
            dijkstra(to);
        }
        // rep(i,n){
