typedef long long ll;

ll g[305][305];
ll minG[305][305];
int n;

bool isPossible() {
  REP(i, n) REP(j, n) {
    minG[i][j] = g[i][j];
  }
  REP(k, n) REP(i, n) REP(j, n) {
    minG[i][j] = min(minG[i][j], minG[i][k] + minG[k][j]);
  }
  REP(i, n) REP(j, n) {
    if(minG[i][j] != g[i][j]) {
      return false;
    }
  }
  return true;
}

struct K {
  int a, b;
  ll c;
};
bool operator>(const K& a, const K& b) {
  return a.c > b.c;
}

int main(void) {
  scanf("%d", &n);
  REP(i, n) REP(j, n) {
    scanf("%lld", &g[i][j]);
  }
  if(!isPossible()) {
    puts("-1");
    return 0;
  }

  ll res = 0;
  priority_queue<K, vector<K>, greater<K> > q;
  REP(i, n) REP(j, n) {
    q.push((K){i, j, g[i][j]});
  }
  while(!q.empty()) {
    K cur = q.top(); q.pop();
    bool needed = true;
    REP(k, n) {
      if(k != cur.a && k != cur.b) {
        if(g[cur.a][k] + g[k][cur.b] == cur.c) {
          needed = false;
          break;
        }
      }
    }
    if(needed) {
      // cerr << "needed: " << cur.a << " " << cur.b << " " << cur.c << endl;
      res += cur.c;
    }
  }

  printf("%lld\n", res / 2);
  return 0;
}

