template <typename T>
vector<vector<T>> v2init(int y_len, int x_len)
{
    vector<vector<T>> vec(y_len, vector<T>(x_len, 0));
    return vec;
}
template <typename T>
vector<vector<T>> v2sort(vector<vector<T>> vec, int index)
{
    sort(vec.begin(), vec.end(), [index](const vector<T> a, const vector<T> b) { return (a[index] > b[index]); });
    return vec;
}
template <typename T>
void v2show(vector<vector<T>> vec)
{
    for (int i = 0; i < vec.size(); i++)
    {
        for (int j = 0; j < vec[0].size(); j++)
        {
            cout << vec[i][j] << " ";
        }
        cout << endl;
    }
}
template <typename T>
ll v2sum(vector<vector<T>> vec)
{
    ll ans = 0;
    for (int i = 0; i < vec.size(); i++)
    {
        for (int j = 0; j < vec[0].size(); j++)
        {
            ans += vec[i][j];
        }
    }
    return ans;
}
int main()
{
    int N;
    cin >> N;
    auto d = v2init<ll>(N, N);
    auto input = v2init<ll>(N, N);

    // warshall-floyd >>>
    // can be used if N <= 200
    rep(i, N)
    {
        rep(j, N)
        {
            if (i == j)
            {
                d[i][j] = 0;
            }
            else
            {
                d[i][j] = INF;
            }
        }
    }
    // warshall-floyd input >>>
    rep(i, N)
    {
        rep(j, N)
        {
            cin >> d[i][j];
            input[i][j] = d[i][j];
        }
    }
    // warshall-floyd input <<<
    for (int k = 0; k < N; k++)
        for (int i = 0; i < N; i++)
            for (int j = 0; j < N; j++)
                if (d[i][j] > d[i][k] + d[k][j])
                {
                    d[i][j] = d[i][k] + d[k][j];
                }
    // warshall-floyd <<<
    rep(i, N)
    {
        rep(j, N)
        {
            if (d[i][j] != input[i][j])
            {
                cout << -1 << endl;
                return 0;
            }
        }
    }
    rep(i, N)
    {
        rep(j, N)
        {
            // for each d[i][j]
            rep(k, N)
            {
                if (k != i && k != j)
                {
                    if (d[k][i] != 0 && d[k][j] != 0)
                    {

                        if (d[i][j] == d[k][i] + d[k][j])
                        {
                            d[i][j] = INF;
                            d[j][i] = INF;
                            break;
                        }
                    }
                }
            }
        }
    }
    ll ans = 0;
    FOR(i, 0, N){
        FOR(j, i+1, N){
            if(d[i][j] != INF){
                ans += d[i][j];
            }
        }
    }
    out(ans);
    return 0;
}

