template< typename T >
void warshall_floyd(vector<vector<T>> &g, T INF) {
  size_t n = g.size();
  for(int k = 0; k < n; k++) {
    for(int i = 0; i < n; i++) {
      for(int j = 0; j < n; j++) {
        if(g[i][k] == INF || g[k][j] == INF) continue;
        g[i][j] = min(g[i][j], g[i][k] + g[k][j]);
      }
    }
  }
}

int solve(int n, vvi a) {
  vvi wf(n, vi(n));
  rep(i, n)rep(j, n)wf[i][j] = a[i][j];
  warshall_floyd(wf, INF);
  int ans = 0;
  rep(i, n - 1)rep(j, i + 1, n) {
    if(i == j)continue;
    if(wf[i][j] != a[i][j])return -1;
    bool ok = true;
    rep(k, n)if((i - k) * (k - j) != 0 && a[i][j] == a[i][k] + a[k][j])ok = false;
    if(ok)ans += a[i][j];
  }
  return ans;
}


