using namespace std;

const ll INFTY=(numeric_limits<ll>::max())/2;
vector<vector<ll>>d;//d[u][v]は辺uvのコスト、ただし存在しないときINFTY,d[i][i]=0,d.resize(V,vector<int>(V,INFTY));とすること

void warshall_floyd(int V){//Vは頂点数
	for(int k=0;k<V;++k){//経由する頂点
		for(int i=0;i<V;++i){//始点となる頂点
			for(int j=0;j<V;++j)//目的地の頂点
      d[i][j]=min(d[i][j],d[i][k]+d[k][j]);
		}
	}
}

void solve(){
    int n;
    cin>>n;
    d.resize(n,vector<ll>(n,INFTY));
    vector<vector<ll>>a(n,vector<ll>(n));
    rep(i,n){
        rep(j,n){
            cin>>a[i][j];
            d[i][j]=a[i][j];
        }
    }
    warshall_floyd(n);
    set<pair<int,int>>ng;
    rep(i,n){
        REP(j,i+1,n){
            if(d[i][j]<a[i][j]){
                cout<<-1<<endl;
                return;
            }
            rep(k,n){
                if((k==i)||(k==j))continue;
                if(d[i][k]+d[k][j]==d[i][j]){
                    ng.emplace(i,j);
                }
            }
        }
    }
    ll ans=0;
    rep(i,n){
        REP(j,i+1,n){
            if(ng.count(make_pair(i,j)))continue;
            ans+=d[i][j];
        }
    }
    cout<<ans<<endl;
}


int main(){
    ios::sync_with_stdio(false);
    cin.tie(0);
    cout<<fixed<<setprecision(15);
    solve();
    return 0;
}

