vvi edge;
// dijkstra
int dijkstra(int start, int end, int N) {
  ll cost[N];
  priority_queue<pair<ll, int>, vector<pair<ll, int>>, greater<pair<ll, int>> > q;
  fill(cost, cost + N, INF); cost[start] = 0;
  q.push(make_pair(0, start));

  while (!q.empty()) {
    pair<ll, int> p = q.top(); q.pop();
    int u = p.second;
    ll cur_cost = p.first;

    if (cost[u] < cur_cost)
      continue;
    for (int v = 0; v < N; ++v) {
      if (edge[u][v] == INF)
        continue;
      if (cost[v] > cost[u] + edge[u][v]) {
        cost[v] = cost[u] + edge[u][v];
        q.push(make_pair(cost[v], v));
      }
    }
  }
  return cost[end];
}

int main() {
  cin.tie(0); ios::sync_with_stdio(false);
  int N; cin >> N;
  edge.resize(N, vi(N, INF));

  int A[N][N];
  ll ans = 0;
  priority_queue<pair<int, pair<int, int>>> q;
  rep(i, N) rep(j, N) {
    cin >> A[i][j];
    if (i != j) {
      edge[i][j] = A[i][j];
    }
    if (i < j) {
      q.push(make_pair(A[i][j], make_pair(i, j)));
      ans += A[i][j];
    }
  }
  while (!q.empty()) {
    int i = q.top().second.first, j = q.top().second.second;
    q.pop();
    edge[i][j] = INF;
    int new_shortest = dijkstra(i, j, N);
    if (new_shortest == A[i][j])
      ans -= A[i][j];
    else if (new_shortest < A[i][j]) {
      cout << -1 << endl;
      return 0;
    } else {
      edge[i][j] = A[i][j];
    }
  }
  cout << ans << endl;

  return 0;
}

