// 後者の方が短い場合は -1, 全ての場合について前者の方が短い場合は length += A[i][j] 
long long length( int N )
{
    long long length = 0;
    for( int i = 0; i < N; ++i ){
        for( int j = i+1; j < N; ++j ){
            bool allLong = true;
            for( int k = 0; k < N; ++ k ){
                if( i != k and j != k){
                    if( A[i][j] > A[i][k] + A[k][j] ) return -1;
                    if( A[i][j] == A[i][k] + A[k][j] ) allLong = false;
                }
            }
            if( allLong ) length += A[i][j];
        }
    }
    return length;
}



