const long INF = 1e15;

struct edge{long to, cost; };
typedef pair<long, long> P;

long n, m, t;

vector<long> dijkstra(vector<vector<edge>> G){

    priority_queue<P, vector<P>, greater<> > que;
    vector<long> d(n,INF);
    d[0] = 0;
    que.push(P(0,0));

    while(!que.empty()){
        P tmp = que.top(); que.pop();
        long v = tmp.second;
        if(d[v] < tmp.first) continue;
        for(long i=0; i<G[v].size(); i++){
            edge e = G[v][i];
            if(d[e.to] > d[v] + e.cost){
                d[e.to] = d[v] + e.cost;
                que.push(P(d[e.to], e.to));
            }
        }
    }
    return d;
}

