struct edge{/*重み付き,有向*/
    int to , cost;/*toは接続先*/
    edge(ll to_ ,ll cost_ = 1){ to=to_; cost=cost_; };/*全てのcost=1 <=> 無向グラフ*/
};
ll n;
bool operator<(edge e1 ,edge e2){return e1.cost < e2.cost; }
bool operator>(edge e1 ,edge e2){return e1.cost > e2.cost; }
using graph =  vector< vector<edge> >;
graph g;
vector<PLL> ck;
matrix warshall_floyd(graph _g){
    matrix dis(_g.size()+1,vector<ll>(_g.size()+1,INF));
    rep(i,dis.size())dis[i][i]=0;
    rep(i,_g.size()){
        rep(j,_g[i].size()){
            edge e = _g[i][j];
            dis[i][e.to] = e.cost;
        }
    }
    rep(i,_g.size()){
        rep(j,_g.size()){
            rep(k,_g.size()){
                chmin(dis[j][k],dis[j][i]+dis[i][k]);
            }
        }
    }
    return dis;
}

ll prim(graph gg){//gg/{0}のmstを求める
    Vi vert;//int the tree?
    ll lgt=0;//length
    graph mst(gg.size());//mst
    vert.pb(1);
    p_queue(edge) q;
    rep(i,gg[1].size()){
        q.push(gg[1][i]);
    }
    while(vert.size()!=gg.size()-1){
        edge id = q.top();
        q.pop();
        bool ck = true;
        rep(i,vert.size()){
            if(id.to==vert[i]){
                ck = false;
                break;
            }
        }
        if(ck){
            vert.pb(id.to);
            lgt += id.cost;
            rep(i,gg[id.to].size()){
                q.push(gg[id.to][i]);
                mst[id.to].pb(gg[id.to][i]);
            }
        }
    }
    return lgt;//mst's length
}

