std::vector<ll> dij;

void dijkstra(const Graph &G, ll s){
	std::priority_queue<P, std::vector<P>, std::greater<P>> que;
	for(ll i = 0; i < n; i++) dij[i] = INF;
	dij[s] = 0;
	que.push(P(0, s));

	while(!que.empty()){
		P p = que.top(); que.pop();
		ll v = p.second;
		if(dij[v] < p.first) continue;
		for(ll i = 0; i < G[v].size(); i++){
			Edge e = G[v][i];
			if(dij[e.to] > dij[v] + e.cost){
				dij[e.to] = dij[v] + e.cost;
				que.push(P(dij[e.to], e.to));
			}
		}
	}
}
