int n; 
void warshall_floyd(bool rep_pre = true) {
    if(rep_pre) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                pre[i][j] = i;
            }
        }
    }
    for (int k = 0; k < n; k++) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int a = d[i][j];
                d[i][j] = min(d[i][j], d[i][k] + d[k][j]);
                if(rep_pre && a != d[i][j]) {
                    pre[i][j] = pre[k][j]; //iからjへの最短経路でjの前の点
                }
            }
        }
    }
}

vector<int> get_path(int s, int t) {
    vector<int> ans;
    while (t != s) {
        ans.push_back(t);
        t = pre[s][t];
    }
    ans.push_back(s);
    return ans;
}

