// 方針
/*
 * 1.   まだ登録されていない経路のうち，最も距離が小さい経路をグラフから取り出す．
 * 2.   既に決定されたグラフ上で，その経路の距離をダイクストラ法で計算する
 * 3.   計算された距離を，1で取り出した経路の距離と比較
 * 4-a. 取り出した経路のほうが短ければ，短い経路をグラフに登録する
 * 4-b. グラフから得た経路のほうが短ければ，スキップ
 * 5.   1に戻る
 *
 * O(n) * ダイクストラ = O(n) * O(n^2) = O(n^3)
 * (10^2)^3 = 10^6 : OK
 */

#include <iostream>
#include <vector>

#include <tuple>
#include <queue>
#include <algorithm>

#define REP(i, n) for(int i = 0;i < n;i++)
#define REPR(i, n) for(int i = n;i >= 0;i--)
#define FOR(i, m, n) for(int i = m;i < n;i++)
#define FORR(i, m, n) for(int i = m;i >= n;i--)
#define SORT(v, n) sort(v, v+n);
#define VSORT(v) sort(v.begin(), v.end());
#define ALL(a) (a).begin(), (a).end()

#define INF (1<<(sizeof(int)*8-2))

using namespace std;

long dijkstra(int from, int to, const vector<vector<long>> &determined_graph)
{
    int N = determined_graph.size();
    // distance_from_fromVertex, vertexId
    priority_queue<pair<int, int>, vector<pair<int, int>>, greater<>> q;
    vector<long> distance;
    distance.resize(N);
    fill(ALL(distance), INF);

    q.emplace(0, from);

    while(!q.empty())
    {
        auto [dist, id] = q.top(); q.pop();

        if( distance[id] < dist ) continue;

        REP(i, N)
        {
            int dist_via_id = dist + determined_graph[id][i];

            if( dist_via_id < distance[i] )
            {
                distance[i] = dist_via_id;
                q.emplace(dist_via_id, i);
            }
        }
    }

    return distance[to];
}

int main()
{
    int N;
    cin >> N;

    vector<vector<int>> A;
    A.resize(N);
    for( auto &arr : A )
        arr.resize(N);

    REP(i, N)
    {
        REP(j, N)
        {
            cin >> A[i][j];
        }
    }

    vector<tuple<int, int, int>> path_list;

    REP(i, N)
    {
        REP(j, N)
        {
            if( A[i][j] == 0 ) continue;

            path_list.emplace_back(A[i][j], i, j);
        }
    }

    VSORT(path_list);

    vector<vector<long>> determined_graph;
    determined_graph.resize(N);
    for( auto &arr : determined_graph ) arr.resize(N);

    REP(i, N)
    {
        REP(j, N)
        {
            if( i == j ) determined_graph[i][j] = 0;
            else determined_graph[i][j] = INF;
        }
    }

    for(auto path : path_list)
    {
        auto [given_cost, from, to] = path;
        int dij_cost = dijkstra(from, to, determined_graph);

//        cout << "dij_cost:" << dij_cost << endl;
//        cout << "given_cost:" << given_cost << endl;

        if( dij_cost < given_cost )
        {
            // FAIL
            cout << -1 << endl;
            return 0;
        }
        else if( given_cost < dij_cost )
        {
            // OK
            // given_cost == dij_cost => 経路を作成する必要なし

            determined_graph[from][to] = given_cost;
            determined_graph[to][from] = given_cost;
        }
    }

    unsigned long long sum = 0;
    REP(i, N)
    {
        REP(j, N)
        {
            if( determined_graph[i][j] != INF )
            {
                // connected
                sum += determined_graph[i][j];
            }

            //cout << determined_graph[i][j] << " ";
        }
        //cout << endl;
    }

    cout << sum / 2 << endl;

    return 0;
}

