typedef long long ll;
const int N = 300;
const ll INF = 1e18;

int n;
bool edgeUsed[N][N];
ll minLen[N][N];
vector<pair<int, int>> conn[N];
bool valid = true;

ll sum;

// Djikstra to check if it's correct
void dijkstra(int v) {
	vector<ll> dist(n, INF), parent(n, -1), teo(n, INF);
	vector<bool> used(n, false);
	dist[v] = 0;

	for (int i = 0; i < n; ++i) {
		int c = -1;
		for (int j = 0; j < n; ++j) {
			if (!used[j] && (c == -1 || dist[j] < dist[c] || (dist[j] == dist[c] && teo[j] < teo[c])))
				c = j;
		}

		used[c] = true;
		if (parent[c] != -1 && !edgeUsed[c][parent[c]]) {
			sum += teo[c];
			edgeUsed[c][parent[c]] = true;
			edgeUsed[parent[c]][c] = true;
		}
		for (auto edge : conn[c]) {
			ll to = edge.first, len = edge.second;
			if (dist[c] + len < dist[to] || (dist[c] + len == dist[to] && len < teo[to])) {
				dist[to] = dist[c] + len;
				parent[to] = c;
				teo[to] = len;
			}

		}
	}

	for (int i = 0; i < n; ++i) {
		if (minLen[v][i] != dist[i]) valid = false;
	}
}

int main() {
	cin.sync_with_stdio(0); cin.tie(0);
	cin >> n;
	for (int i = 0; i < n; ++i) {
		for (int j = 0; j < n; ++j) {
			int len; cin >> len;
			minLen[i][j] = len;
			if (i <= j) continue;
			conn[i].push_back({j, len});
			conn[j].push_back({i, len});
		}
	}

	 for (int i = 0; i < n; ++i) {
		 dijkstra(i);
	 }

	valid ? cout << sum : cout << -1;
}

