    vector<vector<ll>> A(N, vector<ll>(N));
    vector<vector<bool>> direct(N, vector<bool>(N, true));
    rep(i, N) rep(j, N) cin >> A[i][j];

    for(int k = 0; k < N; ++k) {
        for(int i = 0; i < N; ++i) {
            for(int j = 0; j < N; ++j) {
                if (i != k && j != k && A[i][j] == A[i][k] + A[k][j]) direct[i][j] = false;
            }
        }
    }

    ll ans = 0;
    rep(i, N) rep(j, N) dp[i][j] = 10000000000000000;
    rep(i, N) rep(j, N) {
        if (i != j && direct[i][j] == true) {
            dp[i][j] = A[i][j];
            if (i > j) ans += A[i][j];
        }
    }

    for(int k = 0; k < N; ++k) {
        for(int i = 0; i < N; ++i) {
            for(int j = 0; j < N; ++j) dp[i][j] = min(dp[i][j], dp[i][k] + dp[k][j]);
        }
    }

    bool ok = true;
    rep(i, N) rep(j, N) {
        if (i != j && dp[i][j] != A[i][j]) ok = false;
    }
    if (ok) cout << ans << endl;
    else cout << -1 << endl;
}

