			std::cout << -1 << std::endl;
			return 0;
		}
		if (D[c] > (LL)a) {
			list[b].push_back(edge{ c, (LL)a });
			list[c].push_back(edge{ b, (LL)a });
			ans += (LL)a;
		}
	}
	std::cout << ans << std::endl;
	return 0;
}

