            if (i == k || j == k) continue;
            if (d > a[i][k] + a[k][j]) {
                print(-1);
                return 0;
            }

            f &= d < a[i][k] + a[k][j];
        }

        if(f) p[i][j] = a[i][j];
    }

    ll ans = 0;
    REP(i, n) REP(j, n) ans += p[i][j];

    print(ans / 2);
}

