int main(){

	scanf("%d",&N);

	for(int row = 0; row < N; row++){
		for(int col = 0; col < N; col++){

			scanf("%lld",&input_table[row][col]);
			min_dist[row][col] = input_table[row][col];
		}
	}

	for(int mid = 0; mid < N; mid++){
		for(int start = 0; start < N; start++){
			for(int goal = 0; goal < N; goal++){

				if(min_dist[start][goal] > min_dist[start][mid]+min_dist[mid][goal]){

					min_dist[start][goal] =  min_dist[start][mid]+min_dist[mid][goal];
				}
			}
		}
	}

	ll sum = 0;

	for(int row = 0; row < N; row++){
		for(int col = 0; col < N; col++){

			if(input_table[row][col] > min_dist[row][col]){
				printf("-1\n");
				return 0;
			}
			sum += input_table[row][col];
		}
	}

	sum /= 2;

	//不要な辺を除去する
	bool FLG;

	for(int from = 0; from < N-1; from++){
		for(int to = from+1; to < N; to++){
			if(input_table[from][to] == 0)continue;

			FLG = false;

			//他の辺の組み合わせで最短距離が実現可能なら、不要
			for(int mid = 0; mid < N; mid++){
				if(mid == from || mid == to)continue;

				if(min_dist[from][mid]+min_dist[mid][to] == input_table[from][to]){
					FLG = true;
					break;
				}
			}

			if(FLG){

				sum -= input_table[from][to];
			}
		}
	}

	printf("%lld\n",sum);

	return 0;
}

