const int maxn = 310;
int dist[maxn][maxn], n;
bool vis[maxn][maxn];

int main(void) {
    while(~scanf("%d", &n)) {
        for(int i = 0; i < n; ++i) {
            for(int j = 0; j < n; ++j) {
                scanf("%d", dist[i] + j);
                vis[i][j] = 0;
            }
        }
        bool flag = true;
        for(int k = 0; k < n && flag; ++k) {
            for(int i = 0; i < n && flag; ++i) {
                for(int j = 0; j < n & flag; ++j) {
                    if(k == i || k == j || i == j) continue;
                    if(dist[i][k] + dist[k][j] < dist[i][j]) {
                        flag = false;
                        break;
                    }
                    if(dist[i][k] + dist[k][j] == dist[i][j]) vis[i][j] = true;
                }
            }
        }
        if(!flag) {
            puts("-1");
            continue;
        }
        ll ans = 0;
        for(int i = 0; i < n - 1; ++i) {
            for(int j = i + 1; j < n; ++j)
                if(!vis[i][j]) ans += (ll)dist[i][j];
        }
        printf("%lld\n", ans);
    }
}

