struct edge
{
	int to;
	LL cost;
};
std::vector<edge> list[310];


void dset(int N) {
	for (int i = 0; i < N; i++) {
		D[i] = 1 << 30;
	}
}
int main() {
	std::cin >> N;
	dset(N);
	for (int i = 0; i < N; i++) {
		for (int j = 0; j < N; j++) {
			LL tmp;
			std::cin >> tmp;
			if (i >= j)continue;
			A.push_back(TT{ tmp,i,j });
		}
	}
	std::sort(A.begin(), A.end());
	std::unique(A.begin(), A.end());
	for (int jj = 0; jj < (int)A.size(); jj++) {
		dset(N);
		std::priority_queue<PP, std::vector<PP>, std::greater<PP>> pq;
		LL a;
		int b, c;
		std::tie(a, b, c) = A[jj];
		D[b] = 0;
		pq.push({ D[b],b });
		while (!pq.empty()) {
			PP p = pq.top();
			pq.pop();
			if (D[p.second] < p.first)continue;
			for (int k = 0; k < (int)list[p.second].size(); k++) {
				edge e = list[p.second][k];
				if (D[e.to] <= D[p.second] + e.cost)continue;
				D[e.to] = D[p.second] + e.cost;
				pq.push({ D[e.to],e.to });
			}
		}
		if (D[c] < a) {
			std::cout << -1 << std::endl;
			return 0;
		}
		if (D[c] > a) {
			list[b].push_back(edge{ c, a });
			list[c].push_back(edge{ b, a });
			ans += a;
		}
	}
	std::cout << ans << std::endl;
	return 0;
}

