	template<typename T>
	vector<vector<T>> WarshalFloyd(vector<vector<T>>& path,T inf) {
		int n = path.size();
		vector<vector<T>> res = path;
		vector<vector<int>> next(n, vector<int>(n, 0));
		for (int i = 0; i < n; ++i) {
			res[i][i] = 0;
		}
		for (int i = 0; i < n; ++i) {
			for (int j = 0; j < n; ++j) {
				next[i][j] = j;
			}
		}
		// Warshal Floyd
		for (int k = 0; k < n; ++k) {
			for (int i = 0; i < n; ++i) {
				for (int j = 0; j < n; j++) {
					if (res[i][k] != inf && res[k][j] != inf && (res[i][j] == inf || res[i][j] > res[i][k] + res[k][j])) {
						res[i][j] = res[i][k] + res[k][j];
						next[i][j] = next[i][k];
					}
				}
			}
		}
		/*bool negative_cycle = false;
		for (int k = 0; k < n; ++k) {
			for (int i = 0; i < n; ++i) {
				for (int j = 0; j < n; j++) {
					if (res[i][k] != inf && res[k][j] != inf && (res[i][j] == inf || res[i][j] > res[i][k] + res[k][j])) {
						negative_cycle = true;
						res[i][j] = -inf;
					}
					if (res[i][k] == -inf || res[k][j] == -inf) {
						res[i][j] = -inf;
					}
				}
			}
		}*/
		// iからjへの経路を復元
		/*vector<vector<vector<int>>> res(n, vector<vector<int>>(n));
		for (int i = 0; i < n; i++) {
			for (int j = 0; j < n; ++j) {
				for (int cur = i; cur != j; cur = next[cur][j]) {
					res.push_back(cur);
				}
			}
		}*/
		return res;
	}

	void solve() {
		IOS;
		int n;
		cin >> n;
		ll inf = LLONG_MAX / 2;
		vector<vector<ll>> path(n, vector<ll>(n, inf));
		/*REP(i, n) {
			path[i][i] = 0;
		}*/
		REP(i, n) {
			REP(j, n) {
				cin >> path[i][j];
			} 
		}
		/*REP(i, m) {
			int a, b, t;
			cin >> a >> b >> t;
			a--, b--;
			path[a][b] = t;
			path[b][a] = t;
		}*/
		vector<int> val(n* n);
		REP(i, n) {
			REP(j, n) {
				val[i * n + j] = path[i][j];
			}
		}
		sort(all(val));
		int ng = -1, ok = n * n;
		auto tmp = path;
		while (abs(ok - ng) > 1) {
			int mid = (ok + ng) / 2;
			REP(i, n) {
				REP(j, n) {
					if (val[mid] >= path[i][j]) {
						tmp[i][j] = path[i][j];
					} else {
						tmp[i][j] = inf;
					}
				}
			}
			auto d = WarshalFloyd(tmp, inf);
			if (d != path) {
				ng = mid;
			} else {
				ok = mid;
			}
		}
		if (ok == n * n) {
			put(-1);
		} else {
			ll res = 0;
			REP(i, n) {
				REP(j, n) {
					if (val[ok] >= path[i][j]) {
						res += path[i][j];
					}
				}
			}
			put(res/2);
		}
	}
} // namespace idaten

