long long com(long long n, long long k) {
	if(n < 0 || k < 0) return -1;
	if(n < k) return comb[n][k] = 0;
	if(comb[n][k] != -1) return comb[n][k];
	ll res;
	if(n - k < k)
		res = com(n, n - k);
	else if(k == 0)
		res = 1;
	else
		res = com(n - 1, k - 1) + com(n - 1, k);
	comb[n][k] = res;
	return res;
}

long long com2(long long n, long long k) {
	if(n < 0 || k < 0) return -1;
	if(n < k) return comb[n][k] = 0;
	ll res;
	if(n - k < k)
		res = com(n, n - k);
	else if(k == 0)
		res = 1;
	else
		res = com(n - 1, k - 1) + com(n - 1, k);
	return res;
}
