int main() {
	// A[i][j]を昇順に見ながら，頂点i,j間の距離dp[i][j]をINFから更新していく。	
	// まだ見ていないA[i][j](<dp[i][j])のうち最小のもの(複数あることがある)について，iとjは辺で直接結ばれていなければならない。そのような(i,j)は複数あることがあるが，いずれの組についても同様にいえる。どちらもA[i][j] > 0(i!=j)から従う。
	// そのような長さd=A[i][j]の辺(u,v)をグラフに追加し，ワーシャルフロイドのアルゴリズムのように，d,u,vを用いてdpを更新する。
	// 更新後のdpと昇順にソートしたA[i][j]を順次比較していく。
	// A[i][j] = dp[i][j] であるような(i,j)につき，道路を追加する必要はない(し，問が最小値を求めていることから，追加してはならない。)。
	// A[i][j] > dp[i][j] であるような(i,j)が見付かった場合，構成不可
	// 0-ind
	int N; cin >> N;
	vvi A(N, vi(N));
	rep(i, N) rep(j, N) cin >> A[i][j];
	vvl dp(N, vl(N, INF)); rep(i, N) dp[i][i] = 0;
	priority_queue<ti3, vector<ti3>, greater<ti3>> q;
	rep(i, N - 1) rep2(j, i + 1, N) q.push(ti3(A[i][j], i, j));	// i < j
	// dbvv(A);
	ll ans = 0;
	while (!q.empty()) {
		int d, u, v; tie(d, u, v) = q.top(); q.pop(); // d = (A[u][v], u, v)
		// dbs(d, u, v); dbvv(dp); 
		if (dp[u][v] != INF and d > dp[u][v]) {
			ans = -1;
			break;
		} else if (d < dp[u][v]) {
			ans += d; // u-v間に長さA[u][v]の道路追加
			rep(i, N - 1) rep2(j, 1, N) {
				chmin(dp[i][j], min(dp[i][u] + d + dp[v][j], dp[i][v] + d + dp[v][j]));
				dp[j][i] = dp[i][j];
			}
		}
		// dbl(ans);
	}
	print(ans);
}

