void wf(long long cost[Nmax][Nmax], long long output[Nmax][Nmax], int N){
  for(int i=0; i<N; i++)
    for(int j=0; j<N; j++)
      output[i][j] = cost[i][j];

  for(int k=0; k<N; k++)
    for(int i=0; i<N; i++)
      for(int j=0; j<N; j++)
        output[i][j] = min(output[i][j], output[i][k] + output[k][j]);
}

bool is_needed(long long cost[Nmax][Nmax], int N, int i, int j){
  for(int k=0; k<N; k++){
    if(k != i && k != j &&
       cost[i][j] == cost[i][k] + cost[k][j])
      return false;
  }
  return true;
}

