    }
    vector<vector<ll>> source = graph;
    warshall_floyd::solve(graph);
    rep(i, n) {
        rep(j, n) {
            if (source[i][j] != graph[i][j]) {
                cout << -1 << endl;
                return 0;
            }
        }
    }
    ll sum = 0;
    rep(i, n) {
        rep(j, i) {
            ll lower = INF;
            rep(k, n) {
                if (i == k || j == k) continue;
                chmin(lower, graph[i][k] + graph[j][k]);
            }
            if (lower > graph[i][j]) {
                sum += graph[i][j];
            }
        }
    }
    cout << sum << endl;
    return 0;
}

