const long long inf = 1LL << 62;

int warshall_floyd(int n, vector<vector<long long>> &d, vector<vector<long long>> &GG) {
	for (int k = 0; k < n; k++) {       // 経由する頂点
		for (int i = 0; i < n; i++) {    // 始点
			if (d[i][k] == inf) { continue; }
			for (int j = 0; j < n; j++) {  // 終点
				if (d[k][j] == inf) { continue; }
				if (i == j) { continue; }

				if (GG[i][j] > d[i][k] + d[k][j]) {
					cout << -1 << endl;
					//cout << i << j << k << endl;
					return -1;
				}
				if (GG[i][j] == d[i][k] + d[k][j]) {
					d[i][j] = inf;
				}
				//				d[i][j] = min(d[i][j], d[i][k] + d[k][j]);

			}
		}
	}
	return 0;
}


int main() {

	int v; //頂点数
	cin >> v ;

	vector<vector<long long>> G(v, vector<long long>(v, inf));
	int in1;
	for (int i = 0; i < v; i++) {
		for (int j = 0; j < v; j++) {
			cin >> in1;
			G[i][j] = in1;
			if (i == j) { G[i][j] = inf; }
		}
	}
	vector<vector<long long>> GG(v, vector<long long>(v, inf));
	GG = G;
	if (warshall_floyd(v, G,GG) == -1) {
		return 0;
	}

	//こっからはこの問題専用。
	long long res = 0;
	for (int i = 0; i < v; i++) {
		for (int j = 0; j < v; j++) {
			if (G[i][j]!=inf) {
				res += G[i][j];
			}
		}
	}

	cout << res/2 << endl;

	return 0;

}

