	scanf("%d", &N);
	for (u = 1; u <= N; u++) {
		for (w = 1; w <= N; w++) scanf("%d", &(dist[u][w]));
	}
	for (v = 1; v <= N; v++) {
		for (u = 1; u < N; u++) {
			for (w = u + 1; w <= N; w++) {
				if (dist[u][v] + dist[v][w] == dist[u][w]) flag[u][w]++;
