typedef long long int int64;

#define MAX(a,b) ((a)>(b)?(a):(b))
#define MIN(a,b) ((a)<(b)?(a):(b))
#define ABS(a) ((a)>(0)?(a):-(a))

#define POS(i,j) ((i)*n+(j))

void run(void){
  int n;
  scanf("%d",&n);
  int *a=(int *)malloc(sizeof(int)*n*n);
  int *dp=(int *)malloc(sizeof(int)*n*n);
  int64 cost=0;
  int i,j;
  for(i=0;i<n;i++){
    for(j=0;j<n;j++){
      scanf("%d",a+POS(i,j));
      dp[POS(i,j)]=a[POS(i,j)];
      if(i<j) cost+=a[POS(i,j)];
    }
  }

  int k;
  for(i=0;i<n;i++){
    for(j=0;j<n;j++){
      for(k=0;k<n;k++){
	if(a[POS(i,j)]>a[POS(i,k)]+a[POS(k,j)]){
	  printf("-1\n");
	  return;
	} else if(i!=j && j!=k && k!=i && dp[POS(i,j)]==a[POS(i,j)] && a[POS(i,j)]==a[POS(i,k)]+a[POS(k,j)]){
	  cost-=dp[POS(i,j)];
	  dp[POS(i,j)]=dp[POS(j,i)]=0;
	}
      }
    }
  }
  printf("%lld\n",cost);
}

int main(void){
  run();
  return 0;
}

