				}
			}
		}
	}
	for (i = 0; i < N; i++) {
		for (j = i + 1; j < N; j++) {
			if (!kawariwaaru[i][j]) asumikana += A[i][j];
		}
	}
	printf("%" PRId64 "\n", asumikana);
