    ll ans=0,cnt=0;
    cin(&n);
    // scanf("%s",s);
    rep(i,0,n){
        rep(j,0,n){
            cin(&a[i][j]);
            if(i<j){
                heap[cnt].y=i;
                heap[cnt].x=j;
                push_strHeap(a[i][j],cnt++,0);
            }
        }
    }
    rep(i,0,n) rep(j,0,n) det[i][j]=INF;
    while(cnt){
        ll y=heap[0].y;
        ll x=heap[0].x;
        ll p=pop_strHeap(cnt--,0);
        cur=p+1;
        dfs(y,x,0);
        if(cur<p){
            printf("-1\n"); return 0;
        }
        if(cur>p){
            r[y][x]=p;
            det[y][x]=p;
            det[x][y]=p;
        }
    }
    rep(i,0,n){
        rep(j,0,n){
            ans+=r[i][j];
        }
    }
    printf("%lld\n",ans);
    return 0;
}

