            rep(j, 1, n+1){
                if(b[i][j] > b[i][k] + b[k][j]){
                    b[i][j] = b[i][k] + b[k][j];
                }
            }
        }
    }
    int f = 1;
    rep(i, 1, n+1){
        rep(j, 1, n+1){
            if(b[i][j] != a[i][j]){
                f = 0;
            }
        }
    }
    if(f){
        node road[n*(n-1) / 2];
        int len = 0;
        rep(i, 1, n){
            rep(j, i+1, n+1){
                road[len].value = a[i][j];
                road[len].x = j;
                road[len].y = i;
                len++;
            }
        }
        qsort(road, len, sizeof(node), cmpAsc);
        rep(i, 1, n+1){
            rep(j, 1, n+1){
                b[i][j] = 3000000000000;
                if(i == j){
                    b[i][j] = 0;
                }
            }
        }
