        rep(l, 0, len){
            if(b[road[l].y][road[l].x] <= road[l].value){
                continue;
            }
            b[road[l].y][road[l].x] = road[l].value;
            b[road[l].x][road[l].y] = road[l].value;
            ans += road[l].value;
            rep(k, 1, n+1){
                rep(i, 1, n+1){
                    rep(j, 1, n+1){
                        if(b[i][j] > b[i][k] + b[k][j]){
                            b[i][j] = b[i][k] + b[k][j];
                        }
                    }
                }
            }
