            rep(i, 1, n+1){
                rep(j, 1, n+1){
                    if(b[i][j] != a[i][j]){
                        sf = 0;
                    }
                }
            }
            if(sf){
                break;
            }
        }
        printf("%lld", ans);
    }else{
        printf("-1");
    }

    return 0;
}

