// 道路の和を取得
long long
fGetSum(
)
{
	int i, j, k;

	// 各道路をチェック
	long long llSum = 0;
	for (i = 0; i < siCCnt - 1; i++) {
		for (j = i + 1; j < siCCnt; j++) {

			// 接続チェック
			for (k = 0; k < siCCnt; k++) {
				if (k == i) {
					continue;
				}
				if (k == j) {
					continue;
				}

				// 距離合計
				int liLen = si2Table[i][k] + si2Table[j][k];
				if (si2Table[i][j] == liLen) {
					break;
				}
				else if (si2Table[i][j] > liLen) {
					return -1;
				}
			}
			if (k < siCCnt) {
				continue;
			}

			// 距離加算
			llSum += (long long)si2Table[i][j];
		}
	}

	return llSum;
}

