/*-----------priorityqueue(strurct)---------------*/
// kind = max?1:0
ll HeapValue(ll a){return a?-INF:INF;}
ll Heapcmp(ll a, ll b, ll kind){return kind ? (a<b?1:0) : (a>b?1:0);}

typedef struct{ 
    ll y,x;
    ll cost; 
}str_Heap;

str_Heap heap[MAX_N];
void str_swap(str_Heap *a,str_Heap *b){ str_Heap c;c=*b;*b=*a;*a=c; }

void push_strHeap(ll val, ll len , ll kind){
    ll i=len; heap[i].cost=val;
    while(i!=0){
        if( Heapcmp( heap[i].cost, heap[(i-1)/2].cost , llabs(kind-1) )  ) str_swap(&heap[i],&heap[(i-1)/2]);
        i--;i/=2;
    }
}
ll pop_strHeap(ll len, ll kind){
    ll i=0; ll val=heap[0].cost;  heap[0].cost=HeapValue(kind);
    str_swap(&heap[0],&heap[len-1]);
    while(len>i*2+1){
        if(i*2+2<len && Heapcmp(heap[i].cost,heap[i*2+2].cost,kind) && Heapcmp(heap[i*2+1].cost,heap[i*2+2].cost,kind) ){
            str_swap(&heap[i],&heap[i*2+2]);
            i*=2;i+=2;
        }else{
            if( Heapcmp(heap[i].cost,heap[i*2+1].cost,kind) ){
                str_swap(&heap[i],&heap[i*2+1]);
                i*=2;i++;
            }else break;
        }
    }
    return val;
}
/*---------------------------------------------*/

void dfs(ll y, ll x, ll cost){
    if(cost>=cur) return;
    if(y==x){
        cur=cost; return;
    }
    d[y]=1;
    rep(i,0,n){
        if(i==y) continue;
        if(d[i]) continue;
        if(det[y][i]>1e15) continue;
        dfs(i,x,cost+det[y][i]);
    }
    d[y]=0;
    return;
}



