#define VERTEX_MAX 300

int main(void) {
    int cities;
    int graph[VERTEX_MAX][VERTEX_MAX];
    int roads[VERTEX_MAX][VERTEX_MAX];
    memset(roads, 0x7f, sizeof(int)*VERTEX_MAX*VERTEX_MAX);
    cities = get_int();

    int i, j, k;
    for(i = 0; i < cities; i++) {
        fget_array(graph[i], cities);
    }

    // Warshall Floyd (connect step)
    for(k = 0; k < cities; k++) {
        for(i = 0; i < cities; i++) {
            if(i == k) continue;
            for(j = 0; j < cities; j++) {
                if(i == j || j == k) continue;
                // < 2-billion
                int new = graph[i][k] + graph[k][j];
                // ensure that all roads are shortest path
                if(new < graph[i][j]) {
                    printf("-1\n");
                    return 0;
                }
                // building 2 roads are more convenient
                if(new == graph[i][j]) {
                    roads[i][k] = graph[i][k];
                    roads[k][j] = graph[k][j];
                }
            }
        }
    }

    // Warshall Floyd (remove step)
    for(k = 0; k < cities; k++) {
        for(i = 0; i < cities; i++) {
            if(i == k) continue;
            for(j = 0; j < cities; j++) {
                // ensure that i, j and k are all different
                if(i == j || j == k) continue;
                // < 2-billion
                int new = graph[i][k] + graph[k][j];
                // i<->j can be removed because of more convenient paths between i and j.
                if(new == graph[i][j]) {
                    roads[i][j] = 0;
                }
            }
        }
    }

    // we can't help building road
    for(i = 0; i < cities; i++) {
        for(j = 0; j < cities; j++) {
            if(roads[i][j] == COST_MAX) {
                roads[i][j] = graph[i][j];
            }
        }
    }

    uint64_t ans = 0;
    for(i = 0; i < cities; i++) {
        for(j = i+1; j < cities; j++) {
#ifdef DEBUG
            printf("%d, %d -> %d\n", i,j,roads[i][j]);
#endif
            ans += (uint64_t)roads[i][j];
        }
    }
    printf("%llu\n", ans);
    return 0;
}

