import java.util.PriorityQueue

fun main(args: Array<String>) {
    val INF = 10e15.toLong()
    val N = readInputLine().toInt()
    val AArr = Array(N) { readInputLine().split(" ").map { it.toLong() }.toLongArray() }
    val unusedEdges = PriorityQueue<Triple<Int, Int, Long>>(N * (N - 1)) { x, y -> x.third.compareTo(y.third) }
    val usedEdges = Array(N) { mutableListOf<Pair<Int, Long>>() }

    for (i in 0 until N) {
        for (j in i + 1 until N) {
            unusedEdges.add(Triple(i, j, AArr[i][j]))
        }
    }

    var ans = 0L

    while (unusedEdges.isNotEmpty()) {
        val (s, g, d) = unusedEdges.poll()!!

        val costArray = LongArray(N) { INF }
        costArray[s] = 0L

        val queue = PriorityQueue<Pair<Int, Long>>(N) { x, y -> x.second.compareTo(y.second) }
        queue.add(Pair(s, 0L))

        while (queue.isNotEmpty()) {
            val (src, cost) = queue.poll()!!
            if (costArray[src] < cost) {
                continue
            }
            for ((dst, eCost) in usedEdges[src]) {
                if (costArray[dst] > costArray[src] + eCost) {
                    costArray[dst] = costArray[src] + eCost
                    queue.add(Pair(dst, costArray[dst]))
                }
            }
        }

        if (costArray[g] > d) {
            usedEdges[s].add(Pair(g, d))
            usedEdges[g].add(Pair(s, d))
            ans += d
        } else if (costArray[g] < d) {
            println(-1)
            return
        }
    }

    println(ans)
}

