fun repeatedModPow(a: Long, n: Long, mod: Long): Long = 
	when {
		n == 0L -> 1L
		n == 1L -> a % mod
		n % 2L == 1L -> (a * repeatedModPow(a, n-1L, mod)) % mod
		else -> {
			val tmp = repeatedModPow(a, n / 2L, mod)
			(tmp * tmp) % mod
		}
	}

