        }

        boolean[][] direct = new boolean[N][N];
        for (int i = 0; i < N-1 ; i++) {
            for (int j = i+1; j < N ; j++) {
                int a = A[i][j];
                long d = distWithoutEdge(i, j, edges);
                if( a < d ) {
                    direct[i][j] = true;
                } else if( a == d ) {
                    direct[i][j] = false;
                } else {
                    // おかしい
                    return -1;
                }
            }
        }

        long ans = 0;

        for (int i = 0; i < N-1 ; i++) {
            for (int j = i+1; j < N ; j++) {
                if( direct[i][j] ) {
                    ans += A[i][j];
                }
            }
        }

        return ans;
    }

    static long distWithoutEdge(int i, int j, List<Dijkstra.Edge> edges) {
        long[] dist = Dijkstra.calcDistances(N, i, edges.stream().filter(e -> !(e.a == i && e.b == j)));
        return dist[j];
    }

    static class Dijkstra {

        // node: 0-origin
        static long[] calcDistances(int n, int from, Stream<Edge> edges) {
            List<Edge>[] adjList = calcAdjList(n, edges);

            long[] distance = new long[n];
            Arrays.fill(distance, Long.MAX_VALUE);
            distance[from] = 0;

            Queue<Point> q = new PriorityQueue<>();
            q.add(new Point(from, 0));

            while( !q.isEmpty() ) {
                Point p = q.poll();
                if( distance[p.node] < p.cost ) {
                    continue;
                }

                distance[p.node] = p.cost;

                for (Edge edge : adjList[p.node]) {
                    int to = edge.to(p.node);
                    q.add( new Point(to, p.cost + edge.cost) );
                }
            }
            return distance;
        }

        static class Point implements Comparable<Point> {
            private final int node;
            private final long cost;

            public Point(int node, long cost) {
                this.node = node;
                this.cost = cost;
            }

            @Override
            public int compareTo(Point o) {
                return Long.compare(cost, o.cost);
            }
        }

        static class Edge {
            final int a;
            final int b;
            final int cost;

            public Edge(int a, int b, int cost) {
                this.a = a;
                this.b = b;
                this.cost = cost;
            }

            int to(int node) {
                if( node == a ) return b;
                else if( node == b ) return a;
                throw new RuntimeException("wtf : " + a + " " + b + " " + node);
            }
        }

        static List<Edge>[] calcAdjList(int n, Stream<Edge> edges) {
            @SuppressWarnings("unchecked")
            List<Edge>[] array = new List[n];
            for (int i = 0; i < n; i++) {
                array[i] = new ArrayList<>();
            }

            edges.forEach(e -> {
                array[e.a].add(e);
                array[e.b].add(e);
            });
            return array;
        }
    }
}

import java.util.*;

public class Main {
    static ArrayList<Distance>[] graph;
	public static void main (String[] args) {
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();
		ArrayList<Distance> list = new ArrayList<>();
		for (int i = 0; i < n; i++) {
		    for (int j = 0; j < n; j++) {
		        int x = sc.nextInt();
		        if (i < j) {
		            list.add(new Distance(i, j, x));
		        }
		    }
		}
		Collections.sort(list);
		graph = new ArrayList[n];
		for (int i = 0; i < n; i++) {
		    graph[i] = new ArrayList<Distance>();
		}
		long total = 0;
		long[] costs = new long[n];
		for (Distance d : list) {
		    Arrays.fill(costs, Long.MAX_VALUE);
		    search(d.from, costs, 0);
		    if (costs[d.to] > d.cost) {
		        total += d.cost;
		        graph[d.from].add(d);
		        graph[d.to].add(d);
		    } else if (costs[d.to] < d.cost) {
		        System.out.println(-1);
		        return;
		    }
		}
        System.out.println(total);
   }

   static class Distance implements Comparable<Distance> {
       int from;
       int to;
       int cost;

       public Distance(int from, int to, int cost) {
           this.from = from;
           this.to = to;
           this.cost = cost;
       }

       public int compareTo(Distance another) {
           return cost - another.cost;
       }
   }

   static void search(int idx, long[] costs, long total) {
       if (costs[idx] <= total) {
           return;
       }
       costs[idx] = total;
       for (Distance next : graph[idx]) {
           int nextIdx;
           if (next.from == idx) {
               nextIdx = next.to;
           } else {
               nextIdx = next.from;
           }
           search(nextIdx, costs, total + next.cost);
       }
   }
}

