public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        LightScanner in = new LightScanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        DRestoringRoadNetwork solver = new DRestoringRoadNetwork();
        solver.solve(1, in, out);
        out.close();
    }

    static class DRestoringRoadNetwork {
        public void solve(int testNumber, LightScanner in, PrintWriter out) {
            int n = in.ints();
            int[][] a = in.ints(n, n);
            long ans = 0;
            for (int j = 0; j < n; j++) {
                for (int k = 0; k < n; k++) {
                    boolean r = true;
                    for (int i = 0; i < n; i++) {
                        if (a[j][k] > a[j][i] + a[i][k]) {
                            out.println(-1);
                            return;
                        } else if (i != j && i != k && a[j][k] == a[j][i] + a[i][k]) {
                            r = false;
                        }
                    }
                    if (r) {
                        ans += a[j][k];
                    }
                }
            }
            out.println(ans / 2);
        }

    }

    static class LightScanner {
        private BufferedReader reader = null;
        private StringTokenizer tokenizer = null;

        public LightScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
        }

        public String string() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int ints() {
            return Integer.parseInt(string());
        }

        public int[] ints(int length) {
            return IntStream.range(0, length).map(x -> ints()).toArray();
        }

        public int[][] ints(int height, int width) {
            return IntStream.range(0, height).mapToObj(x -> ints(width)).toArray(int[][]::new);
        }

    }
}

import java.util.Scanner;
import java.util.stream.IntStream;

/**
 * 解説通りに実装したソースコード
 */
public class Main {

	public static void main(String[] args) {
		try (Scanner scanner = new Scanner(System.in)) {
			int n = scanner.nextInt();
			// 町と町の間の移動最短距離
			int[][] a = new int[n][n];
			IntStream.range(0, n).forEach(i -> IntStream.range(0, n).forEach(j -> a[i][j] = scanner.nextInt()));
			if (!warshallFloyd(a, n)) {
				System.out.println(-1);
				return;
			}
			System.out.println(IntStream.range(0, n)
					.mapToLong(i -> IntStream.range(i + 1, n).mapToLong(j -> getResult(i, j, a, n)).sum()).sum());
		}
	}

	/**
	 * 町と町の間の移動最短距離をワーシャル–フロイド法で計算する
	 * 
	 * @param d 町と町の間の移動最短距離の配列
	 * @param n 町の数
	 * @return すでに最短距離であるかどうか
	 */
	private static boolean warshallFloyd(int[][] d, int n) {
		for (int k = 0; k < n; k++) {
			for (int j = 0; j < n; j++) {
				for (int i = 0; i < n; i++) {
					if (d[i][k] + d[k][j] < d[i][j]) {
						return false;
					}
				}
			}
		}
		return true;
	}

	/**
	 * @param u 始点の町
	 * @param v 終点の町
	 * @param a 町の町の間の最短距離
	 * @param n 町の数
	 * @return uとvの間に道路が存在する場合、その長さ。存在しない場合は0
	 */
	private static long getResult(final int u, final int v, final int[][] a, final int n) {
		if (u == v) {
			return 0L;
		}
		for (int i = 0; i < n; i++) {
			if ((i != u) && (i != v) && (a[u][i] + a[i][v] == a[u][v])) {
				return 0L;
			}
		}
		return a[u][v];
	}
}

import java.util.Comparator;
import java.util.PriorityQueue;
import java.util.Scanner;

public class Main 
{
	static class C implements Comparator<Entry>
	{

		@Override
		public int compare(Entry o1, Entry o2) 
		{
			long val = o1.dis-o2.dis;
			if(val<0)return -1;
			else if(val > 0)return 1;
			else return 0;
		}

	}

	static class Entry
	{
		long dis;
		int node;
		int ori;

		public Entry(int o, int n, long d)
		{
			ori = o;
			dis = d;
			node = n;
		}
	}

	public static void main(String[] args) 
	{
		Scanner sc = new Scanner(System.in);

		int n = sc.nextInt();

		long[][] indis = new long[n][n];
		long[][] dis = new long[n][n];

		long[][] pdis = new long[n][n];

		long sum = 0;
		for(int i = 0; i < n; i++)
		{
			for(int j = 0; j < n; j++)
			{
				indis[i][j] = sc.nextLong();
				if(i>j)sum+=indis[i][j];
			}
			dis[i] = indis[i].clone();
			pdis[i] = indis[i].clone();
		}

		for(int k = 0; k < n; k++)
			for(int i = 0; i < n; i++)
				for(int j = 0; j < n; j++)
				{
					if(dis[i][j] > dis[i][k] + dis[k][j])
					{
						System.out.println(-1);
						return;
					}
					else if(dis[i][j] == dis[i][k] + dis[k][j] && j != k && i != k && i > j)
					{
						sum-=dis[i][j];
					}
				}

		for(int i = 0; i < n; i++)
			for(int j = 0; j < n; j++)
			{
				if(i!=j)
					pdis[i][j] = 999999999999999l;
				else pdis[i][j] = 0;
			}


//		System.out.println(sum);

		C c = new C();
		PriorityQueue<Entry> q = new PriorityQueue<>(c);
		q.add(new Entry(0,0,0));
		long br = 0;

		boolean[] inprim = new boolean[n];
		while(!q.isEmpty())
		{
			Entry e = q.poll();
			if(inprim[e.node])continue;

			//add node n
			pdis[e.ori][e.node] = Math.min(pdis[e.ori][e.node], e.dis);
			pdis[e.node][e.ori] = Math.min(pdis[e.node][e.ori], e.dis);
			inprim[e.node] = true;
			br += e.dis;
//			System.out.println("add " + e.ori + " " + e.node);

			for(int i = 0; i < n; i++)
			{
				if(pdis[i][e.node] > pdis[i][e.ori] + pdis[e.ori][e.node])
				{
					pdis[i][e.node] = pdis[i][e.ori] + pdis[e.ori][e.node];
					pdis[e.node][i] = pdis[i][e.node];
				}
			}

			//see unsatisfieds
			boolean unsat = true;
			while(unsat)
			{
				unsat = false;
				PriorityQueue<Entry> q2 = new PriorityQueue<>(c);
				for(int i = 0; i < n; i++)
				{
					if(pdis[i][e.node] > indis[i][e.node] && inprim[i])
					{
						q2.add(new Entry(i, e.node, indis[i][e.node]));
						unsat = true;
					}
				}

				if(!q2.isEmpty())
				{
					Entry en = q2.poll();
					pdis[en.ori][en.node] = indis[en.ori][en.node];
					pdis[en.node][en.ori] = indis[en.ori][en.node];
					br += en.dis;

					for(int i = 0; i < n; i++)
					{
						if(pdis[i][en.node] > pdis[i][en.ori] + pdis[en.ori][en.node])
						{
							pdis[i][en.node] = pdis[i][en.ori] + pdis[en.ori][en.node];
							pdis[en.node][i] = pdis[i][en.node];
						}
					}
				}
			}

			//consider edges out of n
			for(int j = 0; j < n; j++)
			{
				q.add(new Entry(e.node, j, indis[e.node][j]));
			}



		}

		System.out.println(br);
	}

}

