            for (int j = 0; j < n; j++) {
                if(a[i][j]!=dist[i][j]) flag = false;
            }
        }
        long sum = 0;
        if(flag){
            for (int i = 0; i < n; i++) {
                for (int j = i; j < n; j++) {
                    if(!via[i][j]) sum += dist[i][j];
                }
            }
        }else sum = -1;
        out.println(sum);
    }

    public static void main(String[] args) throws Exception{
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);
        solve(in, out);
        out.close();
    }
