        // -----------------------------------------
        // -----------------------------------------
        // 重み付きグラフの始点からの最短経路を求める　←　有向・無方向どちらも大丈夫
        // 優先度付きキューを使った版（速い）
        final int INF = 1000000010;
        final int WHITE = 0, GRAY = 1, BLACK = 2;
    													// グラフの隣接リスト(頂点と辺の長さ）
//        Map<Integer, List<PP>> map = new HashMap<Integer, List<PP>>();
        GraphWith G = new GraphWith();
														// 辺の長さの短い順で並ぶ、優先度付きキュー
    	PriorityQueue<PP> PQ = new PriorityQueue<PP>(comparing(PP::getKey));

        int N;											// 頂点の数
    	int[] d;										// d[3] なら 頂点３ から始点までの最短コストを記録する
    	int[] color;									// 白：未処理　黒：処理済み　グレー：

        // 先頭の頂点番号を指定する　０～
        void dijkstra(int s) {
        	Arrays.fill(d, INF);						// 変数の初期化
        	Arrays.fill(color, WHITE);
        	d[s] = 0;									// 先頭は　０
        	PQ.add(new PP(0,s));						// 優先度付きキューにいれるのは　辺の長さと頂点のペア（並びに注意）
        	int u, v;
        	PP p;
        	while(!PQ.isEmpty()) {
        		p = PQ.poll();							// 始点に一番近い頂点を取り出して、消す
        		u = p.getVal();							// 頂点の番号
        		color[u] = BLACK;

        		// 最小値を取り出して、それが最短でなければ無視
        		if(d[u] < p.getKey())	continue;

        		if(G.contains(u)) {
	        		for(PP wk : G.get(u)) {
	        			v = wk.getKey();					// u につながる頂点
	        			if(color[v] == BLACK)	continue;	// 処理済みなら　次へ
	        			if(d[v] > d[u] + wk.getVal()) {		// wk.getVal() が辺の長さ
	        				d[v] = d[u] + wk.getVal();
	        				PQ.add(new PP(d[v], v));
	        			}
	        		}
        		}
        	}
        }
        public void solve() {
        	N = ni();
        	d = new int[N];
        	color = new int[N];
        	int[][] A = new int[N][N];
        	for (int i = 0; i < N; i++) {
				for (int j = 0; j < N; j++) {
					A[i][j] = ni();
					G.add(i, new PP(j, A[i][j]));
				}
			}
        	int sv, t;
        	for (int i = 0; i < N; i++) {
				if(!G.contains(i))	continue;
        		for(PP wk : G.get(i)) {
					t = wk.getKey();
					if(t < i)	continue;
					wk.setVal(INF);
					G.get(t).get(i).setVal(INF);
					dijkstra(i);
//					prn(" " + i + " --> " + t + " = " + d[t] + "  A = " + A[i][t]);
					if(d[t] < A[i][t]) {
						prn(-1);
						return;
					}
					if(d[t] > A[i][t]) {
						wk.setVal(A[i][t]);
						G.get(t).get(i).setVal(A[i][t]);
					}
        		}
        	}
        	long ans = 0;
        	for (int i = 0; i < N; i++) {
				if(!G.contains(i))	continue;
        		for(PP wk : G.get(i)) {
        			if(wk.getKey() < i)	continue;
//        			prn(" calc : i = " + i + "  val = " + wk.getVal());
        			if(wk.getVal() != INF)	ans += wk.getVal();
				}
        	}
        	prn(ans);
        }

