import java.io.*;
import java.util.StringTokenizer;

public class Main {

    FastScanner in;
    PrintWriter out;

    public static void main(String[] args) {
        new Main().run();
    }

    long solve() {
        long result = 0;
        int N = in.nextInt();
        int[][] graph = new int[N][N];
        boolean[][] check = new boolean[N][N];
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                graph[i][j] = in.nextInt();
                check[i][j] = true;
            }
        }

        for (int k = 0; k < N; k++) {
            for (int i = 0; i < N; i++) {
                for (int j = 0; j < N; j++) {
                    if (graph[i][j] > graph[i][k] + graph[k][j]) {
                        return -1;
                    } else if (i != j && i != k && j != k && graph[i][j] == graph[i][k] + graph[k][j]) {
                        check[i][j] = false;
                    }
                }
            }
        }

        for (int i = 0; i < N; i++) {
            for (int j = i; j < N; j++) {
                if (check[i][j]) {
                    result += graph[i][j];
                }
            }
        }
        return result;
    }

    void run() {
        in = new FastScanner();
        out = new PrintWriter(System.out);
        System.out.println(solve());
        out.close();
    }

    public class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public FastScanner(String s) {
            try {
                br = new BufferedReader(new FileReader(s));
            } catch (FileNotFoundException e) {
                e.printStackTrace();
            }
        }

        public String nextToken() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(nextToken());
        }

        public long nextLong() {
            return Long.parseLong(nextToken());
        }

        public double nextDouble() {
            return Double.parseDouble(nextToken());
        }
    }

}

import java.util.Scanner;

public class Main {
	public static void main(String[] args) {
		long ans = solve();
		System.out.println(ans);
	}

	public static long solve() {
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();

		int[][] dist = new int[n + 1][n + 1];
		int[][] odist = new int[n + 1][n + 1];
		for (int i = 0; i < n + 1; i++) {
			for (int j = 0; j < n + 1; j++) {
				dist[i][j] = odist[i][j] = Integer.MAX_VALUE;
				if (i == j) dist[i][j] = odist[i][j] = 0;

			}
		}

		for (int row = 1; row <= n; row++) {
			for (int col = 1; col <= n; col++) {
				int cost = sc.nextInt();
				dist[row][col] = odist[row][col] = cost;
			}
		}

		sc.close();

		long total = 0;
		for (int k = 1; k < n + 1; k++) {
			for (int i = 1; i < n + 1; i++) {
				for (int j = 1; j < n + 1; j++) {
					if (k == i || k == j || i == j) continue;
					odist[i][j] = Math.min(odist[i][j], odist[i][k] + odist[k][j]);
					if (dist[i][j] == dist[i][k] + dist[k][j]) {
						total -= dist[i][j];
					}
				}
			}
		}

		for (int i = 1; i < n + 1; i++) {
			for (int j = 1; j < n + 1; j++) {
				if (dist[i][j] != odist[i][j]) {
					return -1;
				}
				total += dist[i][j];
			}
		}
		return total / 2;

	}
}

