public class Main {
    long data[][];

    public void main(Scanner sc) {
        int n = sc.nextInt();
        data = new long[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                data[i][j] = sc.nextInt();
            }
        }

        long e1, e2, e3;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                for (int k = j + 1; k < n; k++) {
                    e1 = data[i][j];
                    e2 = data[i][k];
                    e3 = data[j][k];

                    if (e1 + e2 == e3) {
                        data[k][j] = 0;
                    } else if (e1 + e3 == e2) {
                        data[k][i] = 0;
                    } else if (e2 + e3 == e1) {
                        data[j][i] = 0;
                    }
                }
            }
        }

        for (int i = 0; i < n; i++) {
            dijkstra(i, n);
        }

        long sum = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < i; j++) {
                sum += data[i][j];
            }
        }
        System.out.println(sum);
    }

    private void dijkstra(int start, int n) {
        long mins[] = new long[n];
        boolean fix[] = new boolean[n];

        Arrays.fill(mins, 1145141919);
        mins[start] = 0;

        Queue<Integer> queue = new PriorityQueue<>((o1, o2) -> Long.compare(mins[o1], mins[o2]));
        queue.add(start);
        while (!queue.isEmpty()) {
            int src = queue.poll();
            fix[src] = true;

            for (int dst = 0; dst < n; dst++) {
                if (!fix[dst]) {
                    mins[dst] =
                        Math.min(mins[dst], mins[src] + Math.max(data[src][dst], data[dst][src]));
                    queue.add(dst);
                }
            }
        }

        for (int i = start; i < n; i++) {
            if (data[start][i] != mins[i]) {
                System.out.println(-1);
                System.exit(0);
            }
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        new Main().main(sc);
        sc.close();
    }
}

import java.util.Scanner;

public class Main{
 public static void main(String[] args){
  Scanner scanner=new Scanner(System.in);
  int n=scanner.nextInt();
  long[][] a=new long[n][n];
  int[][] order=new int[n*(n-1)/2][2];
  int last=0;
  for(int i=0;i<n;i++){
   for(int j=0;j<n;j++){
    int distance=scanner.nextInt();
    a[i][j]=distance;
    if((i==j&&a[i][j]!=0)||(i>j&&a[i][j]!=a[j][i])){
     System.out.println("-1");
     return;
    }
    if(j>i){
     order[last]=new int[]{i,j};
     for(int k=last;k>0&&distance<a[order[k-1][0]][order[k-1][1]];k--){
      int[] swap=order[k-1];
      order[k-1]=order[k];
      order[k]=swap;
     }
     last++;
    }
   }
  }
  scanner.close();
  long[][] connection=new long[n][n];
  long[][] shortest=new long[n][n];
  for(int[] pair:order){
   int i=pair[0];
   int j=pair[1];
   if(shortest[i][j]==0||a[i][j]<shortest[i][j]){// unconnected or too far
    connection[i][j]=a[i][j];
    connection[j][i]=a[i][j];
    shortest[i][j]=a[i][j];
    shortest[j][i]=a[i][j];
    for(int x=0;x<n;x++){
     if(x!=i&&shortest[x][i]==0) continue;
     for(int y=x+1;y<n;y++){
      if(y!=j&&shortest[j][y]==0) continue;
      long path=shortest[x][i]+shortest[i][j]+shortest[j][y];
      if(shortest[x][y]==0||path<shortest[x][y]){
       shortest[x][y]=path;
       shortest[y][x]=path;
      }
     }
    }
    for(int x=0;x<n;x++){
     if(x!=j&&shortest[x][j]==0) continue;
     for(int y=x+1;y<n;y++){
      if(y!=i&&shortest[i][y]==0) continue;
      long path=shortest[x][j]+shortest[j][i]+shortest[i][y];
      if(shortest[x][y]==0||path<shortest[x][y]){
       shortest[x][y]=path;
       shortest[y][x]=path;
      }
     }
    }
   }else if(a[i][j]>shortest[i][j]){
    System.out.println("-1");
    return;
   }
  }
  long sum=0;
  for(int i=0;i<n;i++){
   for(int j=i+1;j<n;j++){
    sum+=connection[i][j];
   }
  }
  System.out.println(sum);
 }
 protected static String matrix(int[][] matrix,int n){
  StringBuffer stringBuffer=new StringBuffer();
  for(int i=0;i<n;i++){
   for(int j=0;j<n;j++){
    stringBuffer.append(matrix[i][j]+" ");
   }
   stringBuffer.append("\n");
  }
  return stringBuffer.toString();
 }
}

