    static void solve(InputReader in, PrintWriter out){
        int n = in.ni();
        int[][] a = new int[n][n];
        int[][] dist = new int[n][n];
        boolean[][] via = new boolean[n][n];
        for (int i = 0; i < n; i++){
            for (int j = 0; j < n; j++) {
                a[i][j] = in.ni();
                dist[i][j] = a[i][j];
                via[i][j] = false;
            }
        }
        for (int k = 0; k < n; k++) {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if(k==i||k==j) continue;
                    if(dist[i][j]>=dist[i][k]+dist[k][j]){
                        dist[i][j] = dist[i][k]+dist[k][j];
                        via[i][j] = true;
                    }
                }
            }
        }
        boolean flag = true;
        out:for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if(a[i][j]!=dist[i][j]){
                    flag = false;
                    break out;
                }
            }
        }
        long sum = 0;
        if(flag){
            for (int i = 0; i < n; i++) {
                for (int j = i; j < n; j++) {
                    if(!via[i][j]) sum += dist[i][j];
                }
            }
        }else sum = -1;
        out.println(sum);
    }

