        final int MAX_COST = 1000000001;

        while (sc.hasNextInt()) {
            int N = sc.nextInt();
            int t[][] = new int[N][N];
            int backup[][] = new int[N][N];

            for (int i = 0; i < N; i++) {
                for (int j = 0; j < N; j++) {
                    t[i][j] = sc.nextInt();
                    backup[i][j] = t[i][j];
                }
            }

            for (int k = 0; k < N; k++) {
                for (int i = 0; i < N; i++) {
                    for (int j = 0; j < N; j++) {
                        if (i == j) {
                            continue;
                        }
                        t[i][j] = Math.min(t[i][j], t[i][k] + t[k][j]);
                    }
                }
            }

            boolean exists = true;
            for (int i = 0; exists && i < N; i++) {
                for (int j = 0; j < N; j++) {
                    if (t[i][j] != backup[i][j]) {
                        exists = false;
                        break;
                    }
                }
