import java.io.*;
import java.util.*;

class Solver {
  private enum EdgeType {
    REQUIRED,
    UNNECESSARY,
    INVALID
  }

  final int n;
  final int[][] am;

  Solver(int n, int[][] am) {
    this.n = n;
    this.am = am;
  }

  private EdgeType calculateEdgeType(int i, int j) {
    EdgeType edgeType = EdgeType.REQUIRED;
    for (int k = 0; k < n; k++) {
      if (k == i || k == j) {
        continue;
      }
      if (am[i][k] + am[k][j] < am[i][j]) {
        return EdgeType.INVALID;
      } else if (am[i][k] + am[k][j] == am[i][j]) {
        edgeType = EdgeType.UNNECESSARY;
      }
    }
    return edgeType;
  }

  public long solve() {
    long totalCost = 0;
    for (int i = 0; i < n; i++) {
      for (int j = i+1; j < n; j++) {
        switch (calculateEdgeType(i, j)) {
        case REQUIRED:
          totalCost += am[i][j];
          break;
        case INVALID:
          return -1;
        }
      }
    }
    return totalCost;
  }
}

public class Main {
  private static void execute(ContestReader reader, PrintWriter out) {
    int n = reader.nextInt();
    int[][] am = reader.nextIntMatrix(n, n);
    out.println(new Solver(n, am).solve());
  }

  public static void main(String[] args) {
    ContestReader reader = new ContestReader(System.in);
    PrintWriter out = new PrintWriter(System.out);
