		for (int i = 0; i < n; i++)
			for (int j = 0; j < n; j++) {
				int w = sc.nextInt();
				aa[i][j] = dd[i][j] = w;
				ee[m++] = new E(i, j, w);
			}
		for (int k = 0; k < n; k++)
			for (int i = 0; i < n; i++)
				for (int j = 0; j < n; j++)
					dd[i][j] = Math.min(dd[i][j], dd[i][k] + dd[k][j]);
