class Graph {
    private static final int INF = Integer.MAX_VALUE / 2;

    int V;
    int[][] d;

    Graph(int N, MyReader in) {
        this.V = N;
        d = new int[V][V];

        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                d[i][j] = in.i();
            }
        }
    }

    long WarshallFloyd() {
        int[][] l = new int[V][V];
        Arrays.setAll(l, i -> d[i].clone());
        for (int k = 0; k < V; k++) {
            for (int i = 0; i < V; i++) {
                if (i == k) continue;
                for (int j = 0; j < V; j++) {
                    if (j == k) continue;
                    int t = d[i][k] + d[k][j];
                    if (t < d[i][j]) {
                        return -1;
                    } else if (t == d[i][j]) {
                        l[i][j] = 0;
                    }
                }
            }
        }

        long len = 0;
        for (int i = 0; i < V; i++) {
            for (int j = i + 1; j < V; j++) {
                len += l[i][j];
            }
        }
        return len;
    }
}


