		// graph
		class Graph {
			int numNode;
			int numEdge;
			boolean directed;
			Edge edges[];
			Node nodes[];
			Node reversedNodes[];

			Graph(int numNode, int numEdge, Edge edges[], boolean directed) {
				this.numNode = numNode;
				this.numEdge = numEdge;
				this.directed = directed;
				this.edges = edges;
				nodes = new Node[numNode];
				reversedNodes = new Node[numNode];
				for(int i = 0; i < numNode; i ++) {
					nodes[i] = new Node(i);
					reversedNodes[i] = new Node(i);
				}

				for(Edge edge : edges) {
					nodes[edge.source].add(edge.target, edge.cost);
					if(directed) {
						reversedNodes[edge.target].add(edge.source, edge.cost);
					}else {
						nodes[edge.target].add(edge.source, edge.cost);
					}
				}
			}

			void clearNodes() {
				for(Node n : nodes) { n.clear(); }
				for(Node n : reversedNodes) { n.clear(); }
			}
		}

		class Node {
			int id;
			ArrayList<Edge> edges = new ArrayList<Edge>();

			Node(int id) {
				this.id = id;
			}
			void add(int target, long cost) {
				edges.add(new Edge(id, target, cost));
			}
			void clear() {
				edges.clear();
			}
		}

		class Edge implements Comparable<Edge> {
			int source;
			int target;
			long cost;
			Edge(int source, int target, long cost) {
				this.source = source;
				this.target = target;
				this.cost = cost;
			}

			@Override
			public int compareTo(Edge e) {
				return Long.compare(this.cost, e.cost);
			}
		}

public void solve() {
	int num = ni();
	long aa[][] = nl(num, num);
	List<Edge> edgesList = new ArrayList<>();
	for(int i = 0; i < num; i ++) {
		for(int j = i + 1; j < num; j ++) {
			boolean ok = true;
			for(int k = 0; k < num; k ++) {
				if(i == k || j == k) { continue; }
				ok &= aa[i][k] + aa[k][j] != aa[i][j];
			}
			if(ok) {
				edgesList.add(new Edge(i, j, aa[i][j]));
			}
		}
	}
	int numNode = num;
	int numEdge = edgesList.size();
	Edge edges[] = new Edge[numEdge];
	long ans = 0;
	for(int i = 0; i < numEdge; i ++) {
		int a = edgesList.get(i).source;
		int b = edgesList.get(i).target;
		long c = edgesList.get(i).cost;
		ans += c;
		edges[i] = new Edge(a, b, c);
		errprtln(a, b, c);
	}
	Graph g = new Graph(numNode, numEdge, edges, false);
	long dist[][] = warshallFloyd(numNode, g.directed, g.edges);
	boolean ok = true;
	for(int i = 0; i < num; i ++) {
		for(int j = 0; j < num; j ++) {
			ok &= aa[i][j] == dist[i][j];
		}
	}
	prtln(ok ? ans : -1);
}

long[][] warshallFloyd(int numNode, boolean directed, Edge[] edges) { // O(V^3)
	long dist[][] = new long[numNode][numNode];
	fill(dist, INF);
	for(int i = 0; i < numNode; i ++) {
		dist[i][i] = 0;
	}
	for(Edge e : edges) {
		dist[e.source][e.target] = e.cost;
		if(!directed) { dist[e.target][e.source] = e.cost; }
	}

	for(int k = 0; k < numNode; k ++) {
		for(int i = 0; i < numNode; i ++) {
			for(int j = 0; j < numNode; j ++) {
				dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j]);
			}
		}
	}

	return dist;
}

	}
