        public void solve() {
        	int N = ni();
        	long[][] A = new long[N][N];
        	for (int i = 0; i < N; i++) {
        		for (int j = 0; j < N; j++) {
        			A[i][j] = nl();
        		}
        	}
        	for (int i = 0; i < N; i++) {
        		for (int j = i+1; j < N; j++) {
        			for (int j2 = j+1; j2 < N; j2++) {
        				if((A[i][j] > (A[i][j2] + A[j][j2]) )
            					|| (A[i][j2] > (A[i][j] + A[j][j2]))
            					|| (A[j][j2] > (A[i][j] + A[i][j2]))) {
        					prn(-1);
        					return;
        				}
					}
        		}
        	}
        	for (int i = 0; i < N; i++) {
        		for (int j = i+1; j < N; j++) {
        			for (int j2 = j+1; j2 < N; j2++) {
        				if(A[i][j] == (A[i][j2] + A[j][j2])) {
        					A[i][j] = 0;
        				} else if(A[i][j2] == (A[i][j] + A[j][j2])) {
        					A[i][j2] = 0;
        				} else if(A[j][j2] == (A[i][j] + A[i][j2])) {
        					A[j][j2] = 0;
        				}
					}
        		}
        	}
        	long ans = 0;
        	for (int i = 0; i < N; i++) {
        		for (int j = i+1; j < N; j++) {
        			ans += A[i][j];
        		}
        	}
        	prn(ans);
        }
