        }
        public void Init(int n) {
            E = n + 1;
            G = new long[E, E];
            BefG = new long[E, E];
            for (int i = 0; i < E; ++i)
                for (int j = 0; j < E; ++j) {
                    G[i, j] = INF;
                    BefG[i, j] = INF;
                }
            for (int i = 0; i < E; ++i) {
                G[i, i] = 0;
                BefG[i, i] = 0;
            }
        }
        public void AddPath(int f, int t, long c) {
            if (isNonDir) {
                G[f, t] = c; G[t, f] = c;
                BefG[f, t] = c; BefG[t, f] = c;
            } else {
                G[f, t] = c;
                BefG[f, t] = c;
            }
        }
        public void AddPath(int[] f, int[] t) {
            for (int i = 0; i < f.Length; ++i)
                AddPath(f[i], t[i], 1);
