            G = MinCostArr();
        }
        public long[,] MinCostArr() {
            for (int i = 0; i < E; ++i)
                for (int j = 0; j < E; ++j)
                    for (int k = 0; k < E; ++k)
                        G[j, k] = Math.Min(G[j, k], G[j, i] + G[i, k]);
            return G;
        }
