                for (int i = 1; i < E; ++i) {
                    if (BefG[cur, i] + G[i, to] == G[cur, to]) {
                        if (i == cur) continue;
                        cur = i;
                        break;
                    }
                }
            }
            ret.Add(cur);
            return ret.ToArray();
        }
        public bool isMinPath(int a, int b, long c) {
