struct Pair : IEquatable<Pair>, IComparable<Pair>
{
    public int i;
    public int j;
    public Pair(int[] arr) : this(arr[0], arr[1]) { }
    public Pair(int x, int y)
    {
        this.i = x;
        this.j = y;
    }

    [System.ComponentModel.EditorBrowsable(System.ComponentModel.EditorBrowsableState.Never)]
    public void Deconstruct(out int v1, out int v2) { v1 = i; v2 = j; }
    public static implicit operator Pair(Tuple<int, int> tuple) => new Pair(tuple.Item1, tuple.Item2);
    public int CompareTo(Pair other)
    {
        var xd = this.i.CompareTo(other.i);
        if (xd != 0) return xd;
        return this.j.CompareTo(other.j);
    }

    public bool Equals(Pair other) => this.i == other.i && this.j == other.j;
    public override bool Equals(object obj) => obj is Pair && Equals((Pair)obj);
    public override int GetHashCode() => ((i << 5) + i) ^ j;
    public override string ToString() => $"({i}, {j})";
}

