            long orig = 0;
            for (int i = 1; i < E; ++i)
                for (int j = i+1; j < E; ++j) {
                    bool isOrig = true;
                    for (int k = 1; k < E; ++k) {
                        if (k == i || k == j) continue;
                        if (G[i, j] == G[i, k] + G[k, j]) {
                            isOrig = false;break;
                        }
                    }
                    if(isOrig)
                        orig += BefG[i, j];
                }
            return orig;
        }
    }
    class UnionFind {
        public long[] parent; public long[] depth; private int I;
        public void Init(int n) { I = n + 1; parent = new long[I]; depth = new long[I]; I.REP(i => parent[i] = i); }
        public long Find(long x) { return (parent[x] == x) ? x : parent[x] = Find(parent[x]); }
        public void Unite(long x, long y) {
            x = Find(x); y = Find(y); if (x == y) return;
            if (depth[x] < depth[y]) parent[x] = y; else { parent[y] = x; if (depth[x] == depth[y]) depth[x]++; }
        }
        public bool Same(int a, int b) { return Find(a) == Find(b); }
        public long Size(int x) { return depth[Find(x)]; }
    }
    class Kruskal : ShortestPath {
        public long Run() {
            var L = new List<Tuple<int, int, long>>();
            for (int i = 0; i < I; ++i)
                foreach (var t in Adj[i])
                    L.Add(Tuple.Create(i, t.Item1, t.Item2));
            L = L.OrderBy(t => t.Item3).ToList();
            var uf = new UnionFind();
            uf.Init(V); long ret = 0;
            foreach (var t in L)
                if (!uf.Same(t.Item1, t.Item2)) {
                    ret += t.Item3;
                    uf.Unite(t.Item1, t.Item2);
                }
            return ret;
        }

    }

