using System;
using System.Collections.Generic;
using System.Linq;
using System.IO;
using static System.Console;
using static System.Convert;
using static System.Math;
//using static System.Globalization.CultureInfo;
using System.Text;
class Program
{
    private static void chmin<T>(ref T num, T val) where T : IComparable<T>
        => num = num.CompareTo(val) == 1 ? val : num;
    private static void chmax<T>(ref T num, T val) where T : IComparable<T>
        => num = num.CompareTo(val) == -1 ? val : num;
    static void Main(string[] args)
    {
        var pr = new Program();
        var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
        Console.SetOut(sw);
        pr.Solve();
        Console.Out.Flush();
    }
    void Solve()
    {
        var num = Input.num;
        var ar = Input.arL2D(num);
        var v = Enumerable.Repeat(0, num).Select(_ => new long[num]).ToArray();
        for (var i = 0; i < num; i++)
            for (var j = 0; j < num; j++)
                v[i][j] = ar[i][j];
        for (var k = 0; k < num; k++)
            for (var i = 0; i < num; i++)
                for (var j = 0; j < num; j++)
                    chmin(ref v[i][j], v[i][k] + v[k][j]);
        for(var i=0;i<num;i++)
            for(var j=0;j<num;j++)
                if(v[i][j]!=ar[i][j])
                { WriteLine(-1);goto END; }
        var res = 0L;
        for (var i = 0; i < num; i++)
            for (var j = i + 1; j < num; j++) {
                var b = false;
                for (var k = 0; k < num; k++)
                    if (i != k && j != k)
                        b |= ar[i][j] == ar[i][k] + ar[k][j];
                if (!b) res += ar[i][j];
            }
        WriteLine(res);
        END:;
    }
}

