        static long GetDistance(int start, int goal, Node[] nodes)
        {
            var posQueue = new Queue<int>();
            var dists = new long[nodes.Length];
            for(int i = 0; i < dists.Length; i++)
            {
                dists[i] = long.MaxValue;
            }
            posQueue.Enqueue(start);
            dists[start] = 0;
            while (posQueue.Count > 0)
            {
                int now = posQueue.Dequeue();
                for(int i = 0; i < nodes[now].edges.Count; i++)
                {
                    long d = dists[now] + nodes[now].edges[i].distance;
                    if (d < dists[nodes[now].edges[i].toIndex])
                    {
                        dists[nodes[now].edges[i].toIndex] = d;
                        posQueue.Enqueue(nodes[now].edges[i].toIndex);
                        //Console.WriteLine("Set " +i+ " "+ + d);
                    }
                }
            }
            return dists[goal];
        }

