    class UnionFind
    {
        public int[] Parents;
        public int[] Rank;
        public UnionFind(int n)
        {
            this.Parents = Enumerable.Repeat(-1, n).ToArray();
            this.Rank = new int[n];
        }
        public int Find(int x)
        {
            if (this.Parents[x] < 0) return x;
            this.Parents[x] = Find(this.Parents[x]);
            return this.Parents[x];
        }
        public int Size(int x)
        {
            return -this.Parents[this.Find(x)];
        }
        public bool Same(int x, int y)
        {
            return this.Find(x) == this.Find(y);
        }
        public bool Union(int x, int y)
        {
            x = this.Find(x);
            y = this.Find(y);
            if (x == y) return false;

            if (this.Rank[x] < this.Rank[y])
            {
                var tmp = x;
                x = y;
                y = tmp;
            }
            if (this.Rank[x] == this.Rank[y]) this.Rank[x]++;
            this.Parents[x] += this.Parents[y];
            this.Parents[y] = x;
            return true;
        }
        public int GetGroupCount()
        {
            return this.Parents.Count(p => p < 0);
        }
    }
