	static class Program
	{
		public static void Solve(Scanner cin)
		{
			int n = cin.ReadInt();
			var a = new long[n][];
			for (int i = 0; i < n; i++)
			{
				a[i] = cin.ReadLongArray(n);
			}
			var e = new List<Pair<long, Pair<long, long>>>();
			for (int i = 0; i < n; i++)
			{
				for (int j = i + 1; j < n; j++)
				{
					e.Add(new Pair<long, Pair<long, long>>(a[i][j], new Pair<long, long>(i, j)));
				}
			}

			e.Sort();
			var mindist = new long[n][];
			for (int i = 0; i < n; i++)
			{
				mindist[i] = Enumerable.Repeat((long)int.MaxValue * 1000000, n).ToArray();
				mindist[i][i] = 0;
			}
			long ans = 0;

			foreach (var item in e)
			{
				var cost = item.First;
				var u = item.Second.First;
				var v = item.Second.Second;

				if (mindist[u][v] < cost)
				{
					Console.WriteLine(-1);
					return;
				}
				if (mindist[u][v] == cost) continue;
				if (mindist[u][v] > cost)
				{
					ans += cost;
					mindist[u][v] = cost;
					mindist[v][u] = cost;
					for (int i = 0; i < n; i++)
					{
						for (int j = i + 1; j < n; j++)
						{
							mindist[i][j] = mindist[j][i] = Math.Min(mindist[i][j], mindist[i][u] + cost + mindist[v][j]);
							mindist[i][j] = mindist[j][i] = Math.Min(mindist[i][j], mindist[i][v] + cost + mindist[u][j]);
						}
					}
				}
			}

			Console.WriteLine(ans);
		}

		public static void Main(string[] args)
		{
			var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
			Console.SetOut(sw);
			var cin = new Scanner();
			Solve(cin);
			Console.Out.Flush();
		}

