namespace AtCoder
{
    partial class Program
    {
        static long mod = 1000000007;
        static void Swap<T>(ref T a, ref T b) { T temp = a; a = b; b = temp; }
        static void Main()
        {
            Console.SetOut(new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false });
            Solve();
            Console.Out.Flush();
            Console.ReadKey();
        }

        //ここから
        static void Solve()
        {
            int N = GetInt();
            var A = GetLongJaggedArray(N);
            var list =new List<Tuple<long, Tuple<int, int>>>();
            for(int i = 0; i < N; i++)
            {
                for(int j = 0; j < i; j++)
                {
                    list.Add(new Tuple<long, Tuple<int, int>>(A[i][j], new Tuple<int, int>(i, j)));
                }
            }
            list = list.OrderBy(o => o.Item1).ToList();

            long sum = 0;
            foreach(var edge in list)
            {
                var ok = true;
                var same = false;
                for(int i = 0; i < N; i++)
                {
                    if (edge.Item2.Item1 == i || edge.Item2.Item2 == i) continue;
                    if (A[edge.Item2.Item1][i] + A[i][edge.Item2.Item2] < edge.Item1) ok = false;
                    if (A[edge.Item2.Item1][i] + A[i][edge.Item2.Item2] == edge.Item1) same = true;
                }
                if (ok == false)
                {
                    Console.WriteLine(-1);
                    return;
                }
                if (same == false) sum += edge.Item1;
            }
            Console.WriteLine(sum);
        }
    }

