using System;

class ABC074D
{
	static public void Main(string[] args)
	{
		int N = int.Parse(Console.ReadLine());
		int[,] A = new int[N+1,N+1];
		string[] vals;
		for(int i=1; i<=N; i++)
		{
			vals = Console.ReadLine().Split(' ');
			for(int j=1; j<=N; j++)
			{
				A[i,j] = int.Parse(vals[j-1]);
			}
		}

		bool[,] direct = new bool[N+1, N+1];
		for(int i=1; i<=N; i++)
			for(int j=1; j<=N; j++)
				direct[i,j] = true;

		for(int i=1; i<=N-1; i++)
		{
			for(int j=i+1; j<=N; j++)
			{
				for(int k=1; k<=N; k++)
				{
					if(k == i || k == j)
						continue;
					if(A[i,j] > A[i,k] + A[k, j])
					{
						Console.WriteLine("-1");
						return;
					}
					else if(A[i,j] == A[i,k] + A[k,j])
					{
						direct[i,j] = false;
					}
				}
			}
		}

		long ans = 0;
		for(int i=1; i<=N-1; i++)
		{
			for(int j=i+1; j<=N; j++)
			{
				if(direct[i,j] == true)
					ans += A[i,j];
			}
		}
		Console.WriteLine(ans);
	}
}

