                var q = new PQ<long, int>();
                q.Push(0, (int)s);
                while (q.Count > 0)
                {
                    var u = q.Pop().Item2;
                    foreach (var path in vtxPath[u])
                    {
                        var v = path.Key;
                        var alt = dist[u] + path.Value;
                        if (dist[v] > alt)
                        {
                            dist[v] = alt;
                            pred[v] = u;
                            q.Push(alt, v);
                        }
                    }
                }
                return Tuple.Create(dist, pred);
