            int H = map.GetLength(0);
            int W = map.GetLength(1);
            Console.WriteLine("-------------------------");
            for (int i = 0; i < H; i++) {
                for (int j = 0; j < W; j++) {
                    Console.Write(map[i, j] + " ");
                }
                Console.WriteLine();
            }
            Console.WriteLine("-------------------------");
        }
        static void Show<T>(IEnumerable<T> ts) {
            foreach (var item in ts) {
                Console.Write(item + " ");
            }
            Console.WriteLine();
        }
        static void Main() {
            int N = int.Parse(Console.ReadLine());
            int[,] Route = new int[N, N];
            bool[,] hasDirectRoute = new bool[N, N];
            for (int i = 0; i < N; i++) {
                var Key = getKeys(' ');
                for (int j = i + 1; j < N; j++) {
                    Route[i, j] = Key[j];
                    Route[j, i] = Key[j];
                    hasDirectRoute[i, j] = true;
                    hasDirectRoute[j, i] = true;
                }
            }
            for (int from = 0; from < N; from++) {
                for (int to = from + 1; to < N; to++) {
                    for (int i = 0; i < N; i++) {//経由地を1つ選ぶ。
                        if (i != from && i != to) {//始点・終点とも違うところ。
                            if (Route[from, to] == Route[from, i] + Route[i, to]) {
                                hasDirectRoute[from, to] = false;
                                hasDirectRoute[to, from] = false;
                            }
                            if (Route[from, to] > Route[from, i] + Route[i, to]) {
                                hasDirectRoute[from, to] = false;
                                hasDirectRoute[to, from] = false;
                                Console.WriteLine(-1);
                                return;
                            }
                        }
                    }
                }
            }
            long Sum = 0;
            for (int i = 0; i < N; i++) {
                for (int j = i + 1; j < N; j++) {
                    if (hasDirectRoute[i, j]) Sum += Route[i, j];
                }
            }
            Console.WriteLine(Sum);
        }
    }
}

