    class WarshallFloyd {
        private int E;
        private bool isNonDir;
        public long INF = (long)1e15;
        public long[,] BefG;
        public long[,] G;
        public WarshallFloyd(bool isNonDir = true) {
            this.isNonDir = isNonDir;
        }
        public void Init(int n) {
            E = n + 1;
            G = new long[E, E];
            BefG = new long[E, E];
            for (int i = 0; i < E; ++i)
                for (int j = 0; j < E; ++j) {
                    G[i, j] = INF;
                    BefG[i, j] = INF;
                }
            for (int i = 0; i < E; ++i) {
                G[i, i] = 0;
                BefG[i, i] = 0;
            }
        }
        public void AddPath(int f, int t, long c) {
            if (isNonDir) {
                G[f, t] = c; G[t, f] = c;
                BefG[f, t] = c; BefG[t, f] = c;
            } else {
                G[f, t] = c;
                BefG[f, t] = c;
            }
        }
        public void AddPath(int[] f, int[] t) {
            for (int i = 0; i < f.Length; ++i)
                AddPath(f[i], t[i], 1);
        }
        public void AddPath(int[] f, int[] t, long[] c) {
            for (int i = 0; i < f.Length; ++i)
                AddPath(f[i], t[i], c[i]);
        }
        public void Run() {
            G = MinCostArr();
        }
        public long[,] MinCostArr() {
            for (int i = 0; i < E; ++i)
                for (int j = 0; j < E; ++j)
                    for (int k = 0; k < E; ++k)
                        G[j, k] = Math.Min(G[j, k], G[j, i] + G[i, k]);
            return G;
        }
        public int[] MinPath(int from, int to) {//TODO:test
            var ret = new List<int>();
            var cur = from;
            while (cur != to) {
                ret.Add(cur);
                for (int i = 1; i < E; ++i) {
                    if (BefG[cur, i] + G[i, to] == G[cur, to]) {
                        if (i == cur) continue;
                        cur = i;
                        break;
                    }
                }
            }
            ret.Add(cur);
            return ret.ToArray();
        }
        public bool isMinPath(int a, int b, long c) {
            for (int i = 1; i < E; ++i)
                if (G[i, a] + c == G[i, b])
                    return true;
            return false;
        }
        public long orignCost() {//test
            long orig = 0;
            for (int i = 1; i < E; ++i)
                for (int j = i+1; j < E; ++j) {
                    bool isOrig = true;
                    for (int k = 1; k < E; ++k)
                        if (k!=i&&k!=j&&G[i, j] == G[i, k] + G[k, j]) {
                            isOrig = false;   
                        }
                    if(isOrig)
                        orig += BefG[i, j];
                }
            return orig;
        }
    }
    class UnionFind {
        public long[] parent; public long[] depth; private int I;
        public void Init(int n) { I = n + 1; parent = new long[I]; depth = new long[I]; I.REP(i => parent[i] = i); }
        public long Find(long x) { return (parent[x] == x) ? x : parent[x] = Find(parent[x]); }
        public void Unite(long x, long y) {
            x = Find(x); y = Find(y); if (x == y) return;
            if (depth[x] < depth[y]) parent[x] = y; else { parent[y] = x; if (depth[x] == depth[y]) depth[x]++; }
        }
        public bool Same(int a, int b) { return Find(a) == Find(b); }
        public long Size(int x) { return depth[Find(x)]; }
    }
    class Kruskal : ShortestPath {
        public long Run() {
            var L = new List<Tuple<int, int, long>>();
            for (int i = 0; i < I; ++i)
                foreach (var t in Adj[i])
                    L.Add(Tuple.Create(i, t.Item1, t.Item2));
            L = L.OrderBy(t => t.Item3).ToList();
            var uf = new UnionFind();
            uf.Init(V); long ret = 0;
            foreach (var t in L)
                if (!uf.Same(t.Item1, t.Item2)) {
                    ret += t.Item3;
                    uf.Unite(t.Item1, t.Item2);
                }
            return ret;
        }

    }

