public class Program
{
    [System.Diagnostics.DebuggerBrowsable(System.Diagnostics.DebuggerBrowsableState.Never)] private ConsoleReader cr;

    public Program(ConsoleReader consoleReader) { this.cr = consoleReader; }
    static void Main() => Console.WriteLine(new Program(new ConsoleReader(Console.OpenStandardInput())).Result());
    #endregion
    public string Result() { var obj = Calc(); if (obj is bool) return (bool)obj ? "Fennec" : "Snuke"; if (obj is double) return ((double)obj).ToString("0.####################"); return obj.ToString(); }
    private object Calc()
    {
        var N = cr.Int;
        var arrs = cr.Repeat(N).Select(cr => cr.Repeat(N).Long);
        var gb = new WGraphBuilder(N, false);
        for (int i = 0; i < N; i++)
            for (int j = i + 1; j < N; j++)
                gb.Add(i, j, arrs[i][j]);
        var graph = gb.ToArray();
        var wf = WarshallFloyd(graph);
        for (int i = 0; i < N; i++)
            for (int j = 0; j < N; j++)
                if (wf[i][j] != arrs[i][j])
                    return -1;

        return graph.Kruskal().SelectMany(n => n.children).Sum(n => n.value) / 2;
    }


    long[][] WarshallFloyd(WNode[] graph)
    {
        var res = NewArray(graph.Length, graph.Length, 0L);
        for (var i = 0; i < graph.Length; i++)
        {
            for (var j = 0; j < graph.Length; j++)
            {
                res[i][j] = long.MaxValue / 2;
            }
            res[i][i] = 0;
            foreach (var next in graph[i].children)
                res[i][next.to] = next.value;
        }
        for (var k = 0; k < graph.Length; k++)
            for (var i = 0; i < graph.Length; i++)
                for (var j = 0; j < graph.Length; j++)
                    if (res[i][j] > res[i][k] + res[k][j])
                        res[i][j] = res[i][k] + res[k][j];
        return res;
    }

