static class 最小全域木
{
    public static WNode[] Kruskal(this WNode[] graph)
    {
        var gb = new WGraphBuilder(graph.Length, false);
        var uf = new UnionFind(graph.Length);
        var edges = new List<Tuple<int, int, long>>();
        foreach (var node in graph)
            foreach (var next in node.children)
                edges.Add(Tuple.Create(node.index, next.to, next.value));
        edges.Sort(Comparer<Tuple<int, int, long>>.Create((t1, t2) => t1.Item3.CompareTo(t2.Item3)));
        foreach (var e in edges)
        {
            if (!uf.IsSameSet(e.Item1, e.Item2))
            {
                uf.UnionSet(e.Item1, e.Item2);
                gb.Add(e.Item1, e.Item2, e.Item3);
            }
        }
        return gb.ToArray();
    }

    [System.Diagnostics.DebuggerDisplay("Count = {" + nameof(Count) + "}")]
    class PriorityQueue<TKey, TValue>
    {
        private readonly List<KeyValuePair<TKey, TValue>> data;
        private readonly IComparer<TKey> comparer;
        public PriorityQueue() : this(Comparer<TKey>.Default) { }
        public PriorityQueue(int capacity) : this(capacity, Comparer<TKey>.Default) { }
        public PriorityQueue(IComparer<TKey> comparer) { this.data = new List<KeyValuePair<TKey, TValue>>(); this.comparer = comparer; }
        public PriorityQueue(int capacity, IComparer<TKey> comparer) { this.data = new List<KeyValuePair<TKey, TValue>>(capacity); this.comparer = comparer; }

        public int Count => data.Count;
        public KeyValuePair<TKey, TValue> Peek => data[0];

        public void Add(TKey key, TValue value)
        {
            data.Add(new KeyValuePair<TKey, TValue>(key, value));
            UpdateUp(data.Count - 1);
        }
        public KeyValuePair<TKey, TValue> Dequeue()
        {
            var res = data[0];
            data[0] = data[data.Count - 1];
            data.RemoveAt(data.Count - 1);
            UpdateDown(0);
            return res;
        }

        private void UpdateUp(int i)
        {
            if (i > 0)
            {
                var p = (i - 1) >> 1;
                if (comparer.Compare(data[i].Key, data[p].Key) < 0)
                {
                    var tmp = data[p];
                    data[p] = data[i];
                    data[i] = tmp;
                    UpdateUp(p);
                }
            }
        }
        private void UpdateDown(int i)
        {
            var n = data.Count;
            var child = 2 * i + 1;
            if (child < n)
            {
                if (child != n - 1 && comparer.Compare(data[child].Key, data[child + 1].Key) > 0)
                    child++;
                if (comparer.Compare(data[i].Key, data[child].Key) > 0)
                {
                    var tmp = data[child];
                    data[child] = data[i];
                    data[i] = tmp;
                    UpdateDown(child);
                }
            }
        }

#pragma warning disable IDE0051
        [System.Diagnostics.DebuggerBrowsable(System.Diagnostics.DebuggerBrowsableState.RootHidden)] private KeyValuePair<TKey, TValue>[] Items => data.ToArray().Sort((a, b) => comparer.Compare(a.Key, b.Key));

    }



    class UnionFind
    {
        int[] data;
        public UnionFind(int size)
        {
            this.data = NewArray(size, -1);
        }

        public int Root(int x)
        {
            if (data[x] < 0) return x;
            return data[x] = Root(data[x]);
        }
        public int Count(int x) => -data[Root(x)];
        public void UnionSet(int x, int y) => TryUnionSet(x, y);
        public bool TryUnionSet(int x, int y)
        {
            var xRoot = Root(x);
            var yRoot = Root(y);
            if (xRoot == yRoot) return false;
            else if (data[yRoot] < data[xRoot])//y側の方が多い場合は逆にする
            {
                var tmp = yRoot;
                yRoot = xRoot;
                xRoot = tmp;
            }
            data[xRoot] += data[yRoot];
            data[yRoot] = xRoot;
            return true;
        }
        public bool IsSameSet(int x, int y) => Root(x) == Root(y);
    }

    public static WNode[] Prim(this WNode[] graph)
    {
        var sumi = new bool[graph.Length];
        var pq = new PriorityQueue<long, Tuple<int, int>>();
        var gb = new WGraphBuilder(graph.Length, false);
        sumi[0] = true;
        foreach (var next in graph[0].children)
            pq.Add(next.value, Tuple.Create(0, next.to));
        for (int i = 1; i < graph.Length; i++)
        {
            var t = pq.Dequeue();
            if (sumi[t.Value.Item2]) { --i; continue; }
            sumi[t.Value.Item2] = true;
            gb.Add(t.Value.Item1, t.Value.Item2, t.Key);
            foreach (var next in graph[t.Value.Item2].children)
                if (!sumi[next.to])
                    pq.Add(next.value, Tuple.Create(t.Value.Item2, next.to));
        }
        return gb.ToArray();
    }
}

