		public static void Solve(Scanner cin)
		{
			int n = cin.ReadInt();
			var a = new int[n][];
			for (int i = 0; i < n; i++)
			{
				a[i] = cin.ReadIntArray(n);
			}
			var e = new List<Pair<int, Pair<int, int>>>();
			for (int i = 0; i < n; i++)
			{
				for (int j = i + 1; j < n; j++)
				{
					e.Add(new Pair<int, Pair<int, int>>(a[i][j], new Pair<int, int>(i, j)));
				}
			}

			e.Sort();
			var mindist = new long[n][];
			for (int i = 0; i < n; i++)
			{
				mindist[i] = Enumerable.Repeat((long)int.MaxValue, n).ToArray();
				mindist[i][i] = 0;
			}
			long ans = 0;

			foreach (var item in e)
			{
				var cost = item.First;
				var u = item.Second.First;
				var v = item.Second.Second;

				if(mindist[u][v] < cost)
				{
					Console.WriteLine(-1);
					return;
				}
				if (mindist[u][v] == cost) continue;
				if(mindist[u][v] > cost)
				{
					ans += cost;
					mindist[u][v] = cost;
					mindist[v][u] = cost;
					for (int i = 0; i < n; i++)
					{
						if (i == u || i == v) continue;
						mindist[u][i] = mindist[i][u] = Math.Min(mindist[i][u], mindist[i][v] + cost);
						mindist[v][i] = mindist[i][v] = Math.Min(mindist[i][v], mindist[i][u] + cost);
					}
				}
			}

			Console.WriteLine(ans);
