public class Solver
{
	private int N;
	private long[,] A;

	public Solver()
	{
		N = GetInt();
		A = new long[N, N];
		for(int i = 0; i < N; i++)
			for(int j = 0; j < N; j++)
				A[i, j] = GetLong();
	}

	public void Solve()
	{
		for(int i = 0; i < N; i++)
		{
			for(int j = i + 1; j < N; j++)
			{
				for(int k = 0; k < N; k++)
				{
					if(k == i || k == j)
						continue;

					if(A[i, j] > A[i, k] + A[k, j])
					{
						Console.WriteLine(-1);
						return;
					}
				}
			}
		}

		long[,] d = new long[N, N];
		for(int i = 0; i < N; i++)
			for(int j = 0; j < N; j++)
				d[i, j] = A[i, j];

		warshall_floyd(ref d);

		long ans = 0;
		for(int i = 0; i < N; i++)
		{
			for(int j = i + 1; j < N; j++)
			{
				bool flag = true;
				for(int k = 0; k < N; k++)
				{
					if(k == i || k == j)
						continue;

					if(d[i, j] == d[i, k] + d[k, j])
					{
						flag = false;
						break;
					}
				}
				if(flag)
					ans += A[i, j];
			}
		}

		Console.WriteLine(ans);
	}

	private static void warshall_floyd(ref long[,] d)
	{
		int V = d.GetLength(0);
		for(int k = 0; k < V; k++)
			for(int i = 0; i < V; i++)
				for(int j = 0; j < V; j++)
					d[i, j] = Math.Min(d[i, j], d[i, k] + d[k, j]);
	}
}


