const INF = 1 << 50

func (con *contest) main() error {
	var N int
	con.Scan(&N)
	A := make([][]int, N)
	B := make([][]int, N)
	for i := 0; i < N; i++ {
		A[i] = make([]int, N)
		B[i] = make([]int, N)
		for j := 0; j < N; j++ {
			con.Scan(&A[i][j])
			B[i][j] = A[i][j]
		}
	}
	for k := 0; k < N; k++ {
		for i := 0; i < N; i++ {
			for j := 0; j < N; j++ {
				x := A[i][k] + A[k][j]
				if x < A[i][j] {
					A[i][j] = x
				}
			}
		}
	}
	ng := false
	for i := 0; i < N; i++ {
		for j := i + 1; j < N; j++ {
			if A[i][j] != B[i][j] {
				ng = true
			}
		}
	}
	if ng {
		con.Println(-1)
		return nil
	}
	for k := 0; k < N; k++ {
		for i := 0; i < N; i++ {
			if i == k {
				continue
			}
			for j := i + 1; j < N; j++ {
				if j == k {
					continue
				}
				if A[i][k]+A[k][j] == A[i][j] {
					A[i][j] = INF
					A[j][i] = INF
					break
				}
			}
		}
	}
	L := 0
	for i := 0; i < N; i++ {
		for j := i + 1; j < N; j++ {
			if A[i][j] != INF {
				L += A[i][j]
			}
		}
	}
	con.Println(L)
	return nil
}

