func getScanner(fp *os.File) *bufio.Scanner {
	scanner := bufio.NewScanner(fp)
	scanner.Split(bufio.ScanWords)
	scanner.Buffer(make([]byte, 500001), 500000)
	return scanner
}

func getNextString(scanner *bufio.Scanner) string {
	scanner.Scan()
	return scanner.Text()
}

func getNextInt(scanner *bufio.Scanner) int {
	i, _ := strconv.Atoi(getNextString(scanner))
	return i
}

func getNextInt64(scanner *bufio.Scanner) int64 {
	i, _ := strconv.ParseInt(getNextString(scanner), 10, 64)
	return i
}

func main() {
	fp := os.Stdin
	if len(os.Args) > 1 {
		fp, _ = os.Open(os.Args[1])
	}

	scanner := getScanner(fp)
	writer := bufio.NewWriter(os.Stdout)

	n := getNextInt(scanner)

	var aa [300][300]int
	for i := 0; i < n; i++ {
		for ii := 0; ii < n; ii++ {
			aa[i][ii] = getNextInt(scanner)
		}
	}
	ans := solve(n, aa)

	fmt.Fprintln(writer, ans)

	writer.Flush()
}

func solve(n int, aa [300][300]int) int64 {
	var ans int64
	var min [300][300]int
	for r := 0; r < n; r++ {
		for l := 0; l < r; l++ {
			min[l][r] = int(1e9 + 1)
		}
	}
	for m := 0; m < n; m++ {
		for r := 0; r < n; r++ {
			for l := 0; l < r; l++ {
				if m == l || m == r {
					continue
				}
				if aa[l][r] > aa[l][m]+aa[m][r] {
					return -1
				}
				if min[l][r] > aa[l][m]+aa[m][r] {
					min[l][r] = aa[l][m] + aa[m][r]
				}
			}
		}
	}

	for r := 0; r < n; r++ {
		for l := 0; l < r; l++ {
			if min[l][r] > aa[l][r] {
				ans += int64(aa[l][r])
			}
		}
	}

	return ans
}

