import "fmt"

const inf = 1 << 60

func solve() {
	var n int
	fmt.Scan(&n)

	dist := make([][]int, n)
	edges := make([][]int, n)
	for i := 0; i < n; i++ {
		dist[i] = make([]int, n)
		edges[i] = make([]int, n)
		for j := 0; j < n; j++ {
			var weight int
			fmt.Scan(&weight)
			dist[i][j] = weight
			edges[i][j] = weight
		}
	}

	ok := true
	for k := 0; k < n; k++ {
		for i := 0; i < n; i++ {
			for j := 0; j < n; j++ {
				if k == i || k == j || i == j {
					continue
				}
				via := dist[i][k] + dist[k][j]
				if via < dist[i][j] {
					ok = false
				} else if via == dist[i][j] {
					edges[i][j] = inf
				}
			}
		}
	}

	if !ok {
		fmt.Println(-1)
		return
	}

	sum := 0
	for i := 0; i < n; i++ {
		for j := 0; j < n; j++ {
			if edges[i][j] == inf {
				continue
			}
			sum += edges[i][j]
		}
	}
	fmt.Println(sum / 2)
}

