		values := strings.Split(line, " ")
		for j, v := range values {
			vInt, _ := strconv.Atoi(v)
			a[i][j] = vInt
			total += vInt
		}
	}

	no_need := 0
	for k := 0; k < N; k++ {
		// from
		for i := 0; i < N; i++ {
			// to
			for j := 0; j < N; j++ {
				// compare from-to / from-経由地点-to
				if i == k || j == k {
					continue
				}
				d := a[i][k] + a[k][j]
				if a[i][j] > d {
					fmt.Println(-1)
					return
				} else if a[i][j] == d {
					// 経由して同じであれば必要ない
					no_need += d
				}
			}
		}
	}
	//  対称なので半分にする
	fmt.Println((total - no_need) / 2)
}

