// Main
const MOD = int(1e+9) + 7
const INF = 1 << 60

func main() {
	sc := NewScanner()
	wtr := bufio.NewWriter(os.Stdout)
	defer wtr.Flush()
	N := sc.nextInt()
	A := make([][]int, N)
	for i := 0; i < N; i++ {
		A[i] = make([]int, N)
		for j := 0; j < N; j++ {
			A[i][j] = sc.nextInt()
		}
	}
	B := make([][]int, N)
	// C[i][j]: i,jの経路で他の辺を経由するか
	C := make([][]bool, N)
	for i := 0; i < N; i++ {
		B[i] = make([]int, N)
		C[i] = make([]bool, N)
		for j := 0; j < N; j++ {
			if i != j {
				B[i][j] = INF
			}
		}
	}
	for k := 0; k < N; k++ {
		for i := 0; i < N; i++ {
			for j := 0; j < N; j++ {
				if A[i][k]+A[k][j] < B[i][j] {
					B[i][j] = A[i][k] + A[k][j]
				}
			}
		}
	}
	ok := true
	for i := 0; i < N; i++ {
		for j := 0; j < N; j++ {
			if A[i][j] != B[i][j] {
				ok = false
			}
		}
	}
	if !ok {
		fmt.Fprintln(wtr, -1)
		return
	}
	for k := 0; k < N; k++ {
		for i := 0; i < N; i++ {
			for j := 0; j < N; j++ {
				// k経由でもi, jに最短経路で到達可能
				if B[i][k]+B[k][j] == B[i][j] {
					if i != k && k != j {
						//fmt.Fprintln(wtr, "in loop", i, j, k)
						C[i][j] = true
					}
				}
			}
		}
	}
	ans := 0
	for i := 0; i < N; i++ {
		for j := i; j < N; j++ {
			if !C[i][j] {
				ans += B[i][j]
			}
		}
	}

	fmt.Fprintln(wtr, ans)
}

