					b[i][j] = b[i][k] + b[k][j]
				} else if b[i][j] == b[i][k]+b[k][j] {
					// 経由しても距離が同じなら、ルートを消去
					if i != k && j != k {
						n[i][j] = -1
					}
				}
			}
		}
	}

