				if b[i][j] > b[i][k]+b[k][j] {
					b[i][j] = b[i][k] + b[k][j]
					ans = -1
					break LOOP
				} else if b[i][j] == b[i][k]+b[k][j] {
					// 経由しても距離が同じなら、ルートを消去
					if i != k && j != k {
