	for k := 0; k < n; k++ {
		for i := 0; i < n; i++ {
			for j := 0; j < n; j++ {
				b[i][j] = smaller(b[i][j], b[i][k]+b[j][k])
			}
		}
	}
	ans := 0
	for i := 0; i < n; i++ {
		for j := i + 1; j < n; j++ {
			f := false
			for k := 0; k < n; k++ {
				if k != i && k != j {
					if b[i][k]+b[j][k] == a[i][j] {
						f = true
					} else if b[i][k]+b[j][k] < a[i][j] {
						ans = -1
					}
				}
			}
			if ans == -1 {
				break
			}
			if !f {
				ans += a[i][j]
			}
		}
		if ans == -1 {
			break
		}
	}
