  foreach (i; 0..n) a[i] = readln.split.to!(long[]);

  auto t = 0L;
  foreach (i; 0..n)
    foreach (j; 0..n)
      t += a[i][j];

  auto dist = a.map!(i => i.dup).array;

  foreach (k; 0..n)
    foreach (i; 0..n)
      foreach (j; 0..n)
        if (dist[i][j] > dist[i][k] + dist[k][j])
          dist[i][j] = dist[i][k] + dist[k][j];

  foreach (i; 0..n)
    if (dist[i] != a[i]) {
      writeln(-1);
