    }

  auto v = new bool[][](n, n);

  foreach (k; 0..n)
    foreach (i; 0..n)
      foreach (j; 0..n)
        if (i != k && j != k && !v[i][j] && a[i][j] == a[i][k] + a[k][j]) {
          t -= a[i][j];
          v[i][j] = true;
        }

  writeln(t/2);
