def dijkstra(G, start = 0):

    d_ = [INF for i in range(len(G))]
    d_[start] = 0

    que = []
    heappush(que, (0, start))

    while len(que) != 0:
        p = heappop(que)
        v = p[1]

        if d_[v] < p[0]:
            continue

        for u in range(len(G[v])):
            if G[v][u]==0:continue
            if d_[u] > d_[v] + G[v][u]:
                d_[u] = d_[v] + G[v][u]
                heappush(que, (d_[u], u))

    return d_

