class Tree:
  def __init__(s, N):
    s.T = [-1] * N
  def root(s, x):
    if s.T[x] < 0:
      return x, -s.T[x]
    r, d = s.root(s.T[x])
    s.T[x] = r
    return r, d
  def merge(s, a, b):
    ar, ad = s.root(a)
    br, bd = s.root(b)
    if ar == br:
      return True
    if ad < bd:
      s.T[ar] = -max(ad, bd + 1)
      s.T[br] = ar
    else:
      s.T[br] = -max(bd, ad + 1)
      s.T[ar] = br
    return False

