def solve(V, G):
    for i in range(V):
        G[i][i] = float("inf")
    for k in range(V):
        for i in range(V):
            for j in range(V):
                if G[i][k] + G[k][j] < G[i][j] < float("inf"):
                    return False, G
                elif G[i][j] == G[i][k] + G[k][j]:
                    G[i][j] = float("inf")
    return True, G


def dist(V, G):
    ans = 0
    for i in range(V):
        for j in range(i, V):
            if G[i][j] < float("inf"):
                ans += G[i][j]
    return ans


