import sys
from itertools import combinations
from heapq import heappush, heappop, heapify
from numba import njit
import numpy as np


def dijkstra(s, t, links):
    heap = list(links[s])
    heapify(heap)
    visited = set()
    while heap:
        cost, node = heappop(heap)
        if node == t:
            return cost
        if node in visited:
            continue
        visited.add(node)
        for cost2, node2 in links[node]:
            if node2 not in visited:
                heappush(heap, (cost + cost2, node2))
    return float("inf")


@njit("b1(i8[:,:],i8)", cache=True)
def existed(a, n):
    for i in range(n):
        for j in range(n):
            for k in range(n):
                if a[j][k] > a[j][i] + a[i][k]:
                    return False
    return True


