for i in range(N):
    for j in range(N):
        if(i==j):
            continue
        Edges.append([A[i][j],i,j])
heapify(Edges)

res=0
while Edges:
    cost,fr,to=heappop(Edges)
    if not same(fr,to):
        union(fr,to)
        G[fr].append((cost,to))
        G[to].append((cost,fr))
        res+=cost
    else:
        di=dijkstra(G,fr,to,N)
        if di[to]>cost:
            G[fr].append((cost,to))
            G[to].append((cost,fr))
            res+=cost
print(res)

