#!/usr/bin/env python3
import sys

def solve(N: int, A: "List[List[int]]"):
    for i in range(N-1):
        for j in range(i+1,N):
            for k in range(N):
                if i == k or j == k or A[i][k] == 0 or A[j][k] == 0:
                    continue

                if A[i][j] == A[i][k]+A[j][k]:
                    A[i][j] = 0
                    A[j][i] = 0
                    break
                elif A[i][j] > A[i][k]+A[j][k]:
                    print(-1)
                    return

    answer = 0
    for i in range(N):
        answer += sum(A[i])
    print(answer//2)

    return


def main():
    def iterate_tokens():
        for line in sys.stdin:
            for word in line.split():
                yield word
    tokens = iterate_tokens()
    N = int(next(tokens))  # type: int
    A = [[int(next(tokens)) for _ in range(N)] for _ in range(N)]  # type: "List[List[int]]"
    solve(N, A)

if __name__ == '__main__':
    main()

