class UnionFind:
    def __init__(self, size: int):
        self.__size = size
        self.__root = [-1] * size

    def find(self, x: int)->int:
        if self.__root[x] < 0:
            return x

        root = self.find(self.__root[x])
        self.__root[x] = root
        return root

    def union(self, x: int, y: int):
        rx, ry = self.find(x), self.find(y)
        if rx == ry:
            return

        if self.__root[ry] < self.__root[rx]:
            rx, ry = ry, rx

        self.__root[rx] += self.__root[ry]
        self.__root[ry] = rx

    def same(self, x: int, y: int)->bool:
        return self.find(x) == self.find(y)


def kruskal(V: int, edges: list)->list:
    uf = UnionFind(V)

    new_edges = []
    for u, v, c in sorted(edges, key=lambda x: x[2]):
        if not uf.same(u, v):
            new_edges.append((u, v, c))
            uf.union(u, v)
    return new_edges


