def WarshallFloyd(Map):
    Dist=copy.deepcopy(Map)
    l=len(Dist)
    for k in range(l):
        for i in range(l):
            for j in range(l):
                Dist[i][j]=min(Dist[i][j],Dist[i][k]+Dist[k][j])
    return Dist

