    costs = []
    for i in range(N):
        for j in range(i + 1, N):
            costs.append(dp[i][j])
    costs.sort()
    duplicated = set()
    for i in range(len(costs) - 1):
        if costs[i] in duplicated:
            continue
        for j in range(i + 1, len(costs)):
            if costs[j] in duplicated:
                continue
            index = bisect.bisect_left(costs, costs[i] + costs[j])
            if index < len(costs) and costs[index] == costs[i] + costs[j]:
                duplicated.add(costs[index])
    print(sum([cost for cost in costs if cost not in duplicated]))

