def solve():
    N = int(input())
    A = np.zeros((N,N))
    for i in range(N):
        line = list(map(int, input().split(' ')))
        for j in range(N):
            A[i][j] = line[j]
    D = np.copy(A) 
    for i in range(N):
        for j in range(N):
            for k in range(N):
                D[j][k] = min(D[j][k], D[j][i]+D[i][k])
    dis_sum = 0
    for i in range(N-1):
        for j in range(i+1, N):
            if D[i][j] != A[i][j]:
                return -1
            found = False
            for k in range(N):
                if k != i and k != j and D[i][j] == D[i][k] + D[k][j]:
                    found = True
                    break
            if not found:
                dis_sum += D[i][j]
    return int(dis_sum)

