def warshall_floyd2(s, d, V):
    for i in range(V):
        for j in range(V):
            d[i][j] = min(d[i][j], d[i][s] + d[s][j])
    for k in range(V):
        for j in range(V):
            d[s][j] = min(d[s][j], d[s][k] + d[k][j])
    for k in range(V):
        for i in range(V):
            d[i][s] = min(d[i][s], d[i][k] + d[k][s])
    return d # d[i][j]に頂点i, j間の最短距離を格納

