class Tree:
  def __init__(s, N):
    s.T = [-1] * N
  def root(s, x):
    if s.T[x] < 0:
      return x, -s.T[x]
    r, d = s.root(s.T[x])
    s.T[x] = r
    return r, d
  def merge(s, a, b):
    ar, ad = s.root(a)
    br, bd = s.root(b)
    if ar == br:
      return True
    if ad < bd:
      s.T[ar] = -max(ad, bd + 1)
      s.T[br] = ar
    else:
      s.T[br] = -max(bd, ad + 1)
      s.T[ar] = br
    return False

class Data():
  class Node():
    def __init__(s):
      s.R = {}
      s.reset()
    def reset(s):
      s.done = False
      s.cos = -1
    def set(s, a, x):
      s.R[a] = x

  def __init__(s, N):
    s.nodes = [s.Node() for _ in range(N)]
  def set(s, a, b, x):
    s.nodes[a].set(b, x)
    s.nodes[b].set(a, x)
  def dist(s, a, b, f):
    if f:
      s.dijk(a)
    return s.nodes[b].cos
  def dijk(s, a):
    for n in s.nodes:
      n.reset()
    s.nodes[a].cos = 0
    while True:
      dn = None
      for n in s.nodes:
        if n.done or n.cos < 0: continue
        if dn == None or n.cos < dn.cos:
          dn = n
      if dn == None:
        break
      dn.done = True
      for k, v in dn.R.items():
        n = s.nodes[k]
        if n.done: continue
        if n.cos == -1 or n.cos > dn.cos + v:
          n.cos = dn.cos + v
