INF = float('inf')

def dijkstra(s, g, key):
    dist = [INF for i in range(n)]
    dist[s] = 0
    hq2 = [(0, s)]
    while hq2:
        cost, node = heapq.heappop(hq2)
        if cost > dist[node]:
            continue
        for v_next, d_next in enumerate(graph[node]):
            if d_next == INF:
                continue
            d = d_next + cost
            if d < dist[v_next]:
                dist[v_next] = d
                heapq.heappush(hq2, (dist[v_next], v_next))
    if dist[g] == INF:
        graph[s][g] = key
        graph[g][s] = key
        return key
    elif dist[g] == key:
        return 0
    else:
        return -1

