fn solve(mut aa: Vec<Vec<i64>>) -> i64 {
    let n = aa.len();

    for i in 0..n {
        for j in 0..n {
            if i == j { continue }

            for k in 0..n {
                if i == k || j == k { continue }

                let ij = aa[i][j];
                let ik = aa[i][k];
                let jk = aa[j][k];

                if ij == -1 ||
                    ik == -1 ||
                    jk == -1 { continue }
                if ij + ik < jk {
                    return -1
                }

                if ij + ik == jk {
                    aa[j][k] = -1;
                    aa[k][j] = -1;
                }
            }
        }
    }

    aa.iter().map(|v| v.iter().filter(|&a| *a > 0).sum::<i64>()).sum::<i64>() / 2
}

fn main() {
    let n = parse_line!(usize);

    println!("{}", solve((0..n).map(|_| parse_vec!(i64)).collect()));
}

