            dp[f][t] = d;
            dp[t][f] = d;
            ans += d;
            calc(&dp, &mut dp2, n);
        }
    }

    for i in 0..n {
        for j in i + 1..n {
            if dp2[i][j] != INF_USIZE && dp2[i][j] != dist[i][j] {
                echo!(-1);
                return;
            }
        }
    }

