pub struct Dikstra {
    dist: Vec<i64>,
    start: usize,
}
impl Dikstra {
    pub fn new(g: &Vec<Vec<(i64, usize)>>, start: usize) -> Self {
        let mut d = Dikstra {
            dist: vec![INF_I64; g.len()],
            start: start,
        };
        d.calc(g);
        return d;
    }
    fn calc(&mut self, g: &Vec<Vec<(i64, usize)>>) {
        let mut used = vec![false; g.len()];
        let mut kouho = std::collections::BinaryHeap::new();
        kouho.push((0, self.start));
        while !kouho.is_empty() {
            let (_, k) = kouho.pop().unwrap();
            used[self.start] = true;
            self.dist[self.start] = 0;
            for i in 0..g[k].len() {
                let (d, p) = g[k][i];
                if used[p] {
                    continue;
                }
                if self.dist[p] > self.dist[k] + d as i64 {
                    self.dist[p] = self.dist[k] + d as i64;
                    kouho.push((self.dist[p] * -1, p));
                }
            }
        }
    }
    pub fn dist_to(&mut self, x: usize) -> i64 {
        return self.dist[x];
    }
}

fn main() {
    input! {
       N: usize,
       mut map_:[[i64;N];N],
    }
    let mut map = map_.clone();
    for i in 0..N {
        for j in i + 1..N {
            let d = map[i][j];
            if d == INF_I64 {
                continue;
            }
            let mut kouho = VecDeque::new();
            let mut used = vec![false; N];
            kouho.push_back((i, 0));
            used[i] = true;
            'outer: while !kouho.is_empty() {
                let (p, cost) = kouho.pop_front().unwrap();
                for k in 0..N {
                    if used[k] {
                        continue;
                    }
                    if p == i && k == j {
                        continue;
                    }
                    let c = map[p][k];
                    if k == j {
                        if d == cost + c {
                            map[i][j] = INF_I64;
                            map[j][i] = INF_I64;
                            break 'outer;
                        } else if d > cost + c {
                            echo!(-1);
                            return;
                        }
                        continue;
                    }
                    if cost + c >= d {
                        continue;
                    }
                    used[k] = true;
                    kouho.push_back((k, cost + c));
                }
            }
        }
    }
    let mut map2 = vec![vec![]; N];
    for i in 0..N {
        for j in 0..N {
            if i == j {
                continue;
            }
            map2[i].push((map[i][j], j));
            map2[j].push((map[j][i], i));
        }
    }
    let mut dik = Dikstra::new(&map2, 0);
    for i in 1..N {
        if dik.dist_to(i) != map_[0][i] {
            echo!(-1);
            return;
        }
    }

    let mut ans = 0;
    for i in 0..N {
        for j in i + 1..N {
            if map[i][j] != INF_I64 {
                ans += map[i][j];
            }
        }
    }

    echo!(ans);
}

use std::io::stdin;

fn read_line() -> Vec<String> {
    let mut line = String::new();
    stdin().read_line(&mut line).expect("Failed to read line");
    return line.trim().split_whitespace().map(|s| s.to_string()).collect();
}

struct Reader {
    v: Vec<String>,
    n: usize,
}

impl Reader {
    fn new() -> Reader {
        let v = read_line();
        return Reader { v: v, n: 0 };
    }
    fn next<T>(&mut self) -> T where T: std::str::FromStr, T::Err: std::fmt::Debug {
        if self.n == self.v.len() {
            self.v = read_line();
            self.n = 0;
        }
        let x = self.v[self.n].parse().unwrap();
        self.n += 1;
        return x;
    }
    fn nexts<T>(&mut self, n: usize) -> Vec<T>
    where T: std::str::FromStr, T::Err: std::fmt::Debug {
        let mut v = Vec::with_capacity(n);
        for _ in 0..n {
            v.push(self.next());
        }
        return v;
    }
}

fn main() {
    let mut r = Reader::new();
    let n: usize = r.next();
    let mut a: Vec<Vec<u64>> = Vec::with_capacity(n);
    for _ in 0..n {
        a.push(r.nexts(n));
    }

    let mut dist = a.clone();
    for k in 0..n {
        for i in 0..n {
            for j in 0..n {
                dist[i][j] = std::cmp::min(dist[i][j], dist[i][k]+dist[k][j]);
            }
        }
    }

    let mut ans: u64 = 0;
    for i in 0..n {
        for j in (i+1)..n {
            if dist[i][j] < a[i][j] {
                println!("-1");
                return;
            }
            let mut used = true;
            for k in 0..n {
                if k == i || k == j { continue };
                if dist[i][j] == dist[i][k]+dist[k][j] {
                    used = false;
                }
            }
            if used {
                ans += dist[i][j];
            }
        }
    }
    println!("{}", ans);
}

macro_rules! scan {
    () => {
        {
            let mut line: String = String::new();
            std::io::stdin().read_line(&mut line).unwrap();
            line.trim().to_string()
        }
    };
    (;;$n:expr) => {
        (0..$n).map(|_| scan!()).collect::<Vec<_>>()
    };
    ($t:ty) => {
        {
            let mut line: String = String::new();
            std::io::stdin().read_line(&mut line).unwrap();
            line.trim().parse::<$t>().unwrap()
        }
    };
    ($($t:ty),*) => {
        {
            let mut line: String = String::new();
            std::io::stdin().read_line(&mut line).unwrap();
            let mut iter = line.split_whitespace();
            (
                $(iter.next().unwrap().parse::<$t>().unwrap(),)*
            )
        }
    };
    ($t:ty;;) => {
        {
            let mut line: String = String::new();
            std::io::stdin().read_line(&mut line).unwrap();
            line.split_whitespace()
                .map(|t| t.parse::<$t>().unwrap())
                .collect::<Vec<_>>()
        }
    };
    ($t:ty;;$n:expr) => {
        (0..$n).map(|_| scan!($t;;)).collect::<Vec<_>>()
    };
    ($t:ty; $n:expr) => {
        (0..$n).map(|_|
                    scan!($t)
        ).collect::<Vec<_>>()
    };
    ($($t:ty),*; $n:expr) => {
        (0..$n).map(|_|
                    scan!($($t),*)
        ).collect::<Vec<_>>()
    };
}

fn main() {
    let n = scan!(i64);
    let graph = scan!(i64;;n);

    for k in 0..graph.len() {
        for i in 0..graph.len() {
            for j in 0..graph.len() {
                if graph[i][j] > graph[i][k] + graph[k][j] {
                    println!("{}", -1);
                    return;
                }
            }
        }
    }

    let mut ans = 0;
    for i in 0..graph.len() {
        for j in 0..graph.len() {
            let mut shortest = true;
            for k in 0..graph.len() {
                if k != i && k != j && graph[i][j] == graph[i][k] + graph[k][j] {
                    shortest = false;
                }
            }
            if shortest {
                ans += graph[i][j]
            }
        }
    }

    println!("{}", ans / 2);
}

