    let mut connected = vec![vec![true; N]; N];
    for k in 0..N {
        for i in 0..N {
            for j in 0..N {
                if i == j || i == k || j == k {
                    continue;
                }
                if A[i][j] == A[i][k] + A[k][j] {
                    connected[i][j] = false;
                } else if A[i][j] > A[i][k] + A[k][j] {
                    println!("-1");
                    return;
                }
            }
        }
    }
    let mut ans = 0;
    for i in 0..N-1 {
        for j in i+1..N {
            if connected[i][j] {
                ans += A[i][j];
            }
        }
    }
    println!("{}", ans);
}

