fn solve() {
    let n = get!(usize);
    let a = get!([usize]; n);

    for k in 0..n {
        for i in 0..n {
            for j in 0..n {
                if a[i][j] > a[i][k] + a[k][j] {
                    println!("-1");
                    return;
                }
            }
        }
    }
    let mut set = BTreeSet::new();
    for i in 0..n {
        for j in 0..n {
            set.insert((i,j,a[i][j]));
            set.insert((j,i,a[i][j]));
        }
    }
    loop {
        let mut updates = 0;
        for (i,j,v) in set.clone() {
            for k in 0..n {
                if k == i || k == j {
                    continue;
                }
                if a[i][j] == a[i][k] + a[k][j] {
                    set.remove(&(i,j,a[i][j]));
                    set.remove(&(j,i,a[i][j]));
                    set.insert((i,k,a[i][k]));
                    set.insert((k,i,a[i][k]));
                    set.insert((k,j,a[k][j]));
                    set.insert((j,k,a[k][j]));
                    updates += 1;
                }
            }
        }
        if updates == 0 {
            break;
        }
    }
    let sum = set.into_iter().map(|(_,_,v)| v).sum::<usize>()/2;
    println!("{}", sum);
}

