fn warshal_floyd(n: usize, v: &Vec<Vec<i64>>) -> Vec<Vec<(i64, bool)>> {
  let mut dist = vec![vec![(0, true); n]; n];

  for i in 0..n {
    for j in 0.. n{
      dist[i][j].0 = v[i][j];
    }
  }

  for k in 0..n {
    for i in 0..n {
      for j in 0..n {
        if dist[i][j].0 > dist[i][k].0 + dist[k][j].0 {
          dist[i][j].0 = dist[i][k].0 + dist[k][j].0;
