pub struct Dikstra {
    dist: Vec<i64>,
    start: usize,
}
impl Dikstra {
    pub fn new(g: &Vec<Vec<(i64, usize)>>, start: usize) -> Self {
        let mut d = Dikstra {
            dist: vec![INF_I64; g.len()],
            start: start,
        };
        d.calc(g);
        return d;
    }
    fn calc(&mut self, g: &Vec<Vec<(i64, usize)>>) {
        let mut used = vec![false; g.len()];
        let mut kouho = std::collections::BinaryHeap::new();
        kouho.push((0, self.start));
        while !kouho.is_empty() {
            let (_, k) = kouho.pop().unwrap();
            used[self.start] = true;
            self.dist[self.start] = 0;
            for i in 0..g[k].len() {
                let (d, p) = g[k][i];
                if used[p] {
                    continue;
                }
                if self.dist[p] > self.dist[k] + d as i64 {
                    self.dist[p] = self.dist[k] + d as i64;
                    kouho.push((self.dist[p] * -1, p));
                }
            }
        }
    }
    pub fn dist_to(&mut self, x: usize) -> i64 {
        return self.dist[x];
    }
}

