fn read_line() -> String {
    let mut buf = String::new();
    io::stdin().read_line(&mut buf).ok();
    buf
}

struct Scanner {
    buff: Vec<String>,
    pos: usize,
}


impl Scanner {
    pub fn new() -> Self {
        Scanner {
            buff: Vec::new(),
            pos: 0,
        }
    }

    pub fn next<T: FromStr>(&mut self) -> T {
        while self.buff.len() <= self.pos {
            self.pos = 0;
            self.buff = read_line().split_whitespace().map(|s| s.to_owned()).collect();
        }

        let result = self.buff[self.pos].parse::<T>();
        self.pos += 1;
        result.ok().unwrap()
    }

    pub fn next_line(&mut self) -> String {
        let result  = read_line().trim().to_owned();
        self.buff.clear();
        self.pos = 0;

        result
    }

    pub fn next_vec<T: FromStr>(&mut self) -> Vec<T> {
        self.buff.clear();
        self.pos = 0;
        read_line().trim().split_whitespace().map(|s| s.parse().ok().unwrap()).collect()
    }

    pub fn next_line_chars(&mut self) -> Vec<char> {
        let result  = read_line().trim().chars().collect();
        self.buff.clear();
        self.pos = 0;

        result
    }
}

fn func(a: &Vec<Vec<i64>>) -> Option<i64> {
    let mut es = Vec::new();
    let mut ans = 0;
    let n = a.len();
    for i in 0..n {
        for j in i+1..n {
            es.push((a[i][j], i, j));
        }
    }
    es.sort();
    let mut visited = vec![vec![false; n]; n];
    for &(v, i, j) in es.iter() {
        visited[i][j] = true;
        visited[j][i] = true;

        let mut flag = false;
        for k in 0..n {
            if k != i && k != j && visited[i][k] && visited[k][j] {
                if a[i][k] + a[k][j] < v {
                    return None;
                }
                if a[i][k] + a[k][j] == v {
                    flag = true;
                    break;
                }
            }
        }
        if !flag {
            ans += v;
        }
    }

    Some(ans)
}


