macro_rules! parse {
    ($it: ident) => {
        $it.next().unwrap().parse().unwrap()
    };
    ($it: ident,2) => {
        (parse!($it), parse!($it))
    };
    ($it: ident,3) => {
        (parse!($it), parse!($it), parse!($it))
    };
    ($it: ident,4) => {
        (parse!($it), parse!($it), parse!($it), parse!($it))
    };
    ($it: ident, $n: expr) => {
        (&mut $it).take($n).map(|e| e.parse().unwrap()).collect();
    };
}

fn solve(s: &str) {
    let mut it = s.split_whitespace();
    let n: usize = parse!(it);
    let a: Vec<Vec<usize>> = (0..n).map(|_| parse!(it, n)).collect();
    let mut used = vec![vec![true; n]; n];
    for i in 0..n {
        for j in (i + 1)..n {
            for k in (j + 1)..n {
                if a[i][j] > a[k][i] + a[j][k]
                    || a[j][k] > a[k][i] + a[i][j]
                    || a[k][i] > a[i][j] + a[j][k]
                {
                    println!("{}", -1);
                    return;
                }
                if a[i][j] == a[k][i] + a[j][k] {
                    used[i][j] = false
                }
                if a[j][k] == a[k][i] + a[i][j] {
                    used[j][k] = false
                }
                if a[i][k] == a[i][j] + a[j][k] {
                    used[i][k] = false
                }
            }
        }
    }
    let mut ret = 0;
    for i in 0..n {
        for j in (i + 1)..n {
            ret += (used[i][j] as usize) * a[i][j]
        }
    }
    println!("{}", ret);
}

