fn warshall_floyd(matrix: &[Vec<usize>]) -> Option<usize> {
    let mut updated = vec![vec![false; matrix.len()]; matrix.len()];
    for i in 0..matrix.len() {
        for j in 0..matrix.len() {
            if j == i {
                continue;
            }
            for k in 0..matrix.len() {
                if k == i || k == j {
                    continue;
                }
                if matrix[j][k] == matrix[j][i] + matrix[i][k] {
                    updated[j][k] = true;
                } else if matrix[j][k] > matrix[j][i] + matrix[i][k] {
                    return None;
                }
            }
        }
    }
    let mut sum = 0;
    for i in 0..matrix.len() {
        for j in (i + 1)..matrix.len() {
            if !updated[i][j] {
                sum += matrix[i][j];
            }
        }
    }
    Some(sum)
}
