        }
    }
    let mut min_dists = mat.clone();
    for k in 0..n {
        for i in 0..n {
            for j in 0..n {
                min_dists[i][j] = std::cmp::min(min_dists[i][j], min_dists[i][k] + min_dists[k][j]);
            }
        }
    }
    if mat != min_dists {
        println!("-1");
        return;
    }
    let mut ans = 0;
