fn calc(dp: &mut Vec<Vec<usize>>, n: usize) {
    for k in 0..n {
        for i in 0..n {
            for j in 0..n {
                let tmp = dp[i][k] + dp[k][j];
                if tmp < dp[i][j] {
                    dp[i][j] = tmp;
                }
            }
        }
    }
}

fn main() {
    input! {
       n: usize,
       dist :[[usize;n];n],
    }

    let mut ans: usize = 0;
    let mut edges = vec![];
    for i in 0..n {
        for j in i + 1..n {
            edges.push((i, j, dist[i][j]));
        }
    }

    edges.sort_by_key(|x| x.2);
    mydbg!(edges);
    let mut dp = vec![vec![INF_USIZE; n]; n];
    for i in 0..n {
        dp[i][i] = 0;
    }
    for i in 0..edges.len() {
        let (f, t, d) = edges[i];
        if dp[f][t] != d {
            dp[f][t] = d;
            dp[t][f] = d;
            ans += d;
            calc(&mut dp, n);
        }
    }

    for i in 0..n {
        for j in i + 1..n {
            if dp[i][j] != INF_USIZE && dp[i][j] != dist[i][j] {
                echo!(-1);
                return;
            }
        }
    }

    echo!(ans);
}

