    let mut dp = vec![vec![INF_I64; N]; N];
    for i in 0..N {
        for j in 0..N {
            dp[i][j] = map[i][j];
        }
    }
    for k in 0..N {
        for i in 0..N {
            for j in 0..N {
                dp[i][j] = min(dp[i][j], dp[i][k] + dp[k][j]);
            }
        }
    }


    for i in 0..N {
        for j in i + 1..N {
            if map[i][j] != 0 && map[i][j] > dp[i][j] {
                echo!(-1);
                return;
            }
            for k in 0..N {
                if i == k || j == k {
                    continue;
                } else if map[i][j] == 0 {
                    continue;
                }
                let d = map[i][j];
                let d2 = dp[i][k] + dp[k][j];
                if d == d2 {
                    map[i][j] = 0;
                    map[j][i] = 0;
                    break;
                }
            }
        }
    }

    let mut ans = 0;
    for i in 0..N {
        for j in i + 1..N {
            ans += map[i][j];
        }
    }

    echo!(ans);
}

