        fn to_charvec(&self) -> Vec<char> {
            self.to_string().chars().collect::<Vec<_>>()
        }
    }
}

use input::*;

fn main() {
    let n: usize;
    input!(n);
    let mut table = input_vector2d::<isize>(n);
    let mut flag = vec![vec![true; n]; n];

    for k in 0..n {
        for i in 0..n {
            for j in 0..n {
                if table[i][j] == table[i][k] + table[k][j] && i != k && j != k {
                    flag[i][j] = false;
                } else if table[i][j] > table[i][k] + table[k][j] {
                    p(-1);
                    return;
                }
            }
        }
    }

    let mut sum = 0_isize;

    for i in 0..n {
        for j in 0..n {
            if flag[i][j] {
                sum += table[i][j];
            }
        }
    }

    p(sum >> 1);
}

