            }
        }
    }
    let mut map2 = vec![vec![]; N];
    for i in 0..N {
        for j in 0..N {
            if i == j {
                continue;
            }
            map2[i].push((map[i][j], j));
            map2[j].push((map[j][i], i));
        }
    }
    let mut dik = Dikstra::new(&map2, 0);
    for i in 1..N {
        if dik.dist_to(i) != map_[0][i] {
            echo!(-1);
            return;
        }
    }

    let mut ans = 0;
    for i in 0..N {
        for j in i + 1..N {
            if map[i][j] != INF_I64 {
                ans += map[i][j];
            }
        }
    }

    echo!(ans);
}

