use proconio::input;
use std::cmp::*;
use std::collections::BinaryHeap;

const INF: i32 = std::i32::MAX / 2;

fn dijkstra(n: usize, i: usize, j: usize, g: &[Vec<i32>]) -> i32 {
    let mut h = BinaryHeap::new();
    let mut v = vec![INF; n];
    h.push(Reverse((0, i)));
    v[i] = 0;
    while let Some(Reverse((d, k))) = h.pop() {
        if v[k] >= d {
            for l in 0..n {
                if v[k] + g[k][l] < v[l] {
                    v[l] = v[k] + g[k][l];
                    h.push(Reverse((v[l], l)));
                }
            }
        }
    }
    v[j]
}

fn solve(n: usize, a: &[Vec<i32>]) -> i64 {
    let mut g = vec![vec![INF; n]; n];
    for i in 0..n {
        g[i][i] = 0;
    }
    let mut v = (0..n)
        .flat_map(|i| (0..i).map(move |j| (a[i][j], (i, j))))
        .collect::<Vec<_>>();
    v.sort();
    for &(d, (i, j)) in v.iter() {
        let d2 = dijkstra(n, i, j, &g);
        if d < d2 {
            g[i][j] = d;
            g[j][i] = d;
            //println!("{:?} ({}, {})", &g, i, j);
        }
    }
    let mut h = g.clone();
    for k in 0..n {
        for i in 0..n {
            for j in 0..n {
                h[i][j] = min(h[i][j], h[i][k] + h[k][j]);
            }
        }
    }
    //println!("{:?}", &h);
    //println!("{:?}", &a);
    if h == a {
        (0..n)
            .flat_map(|i| {
                let gg = &g;
                (0..i).map(move |j| gg[i][j])
            })
            .filter(|&d| d < INF)
            .map(|d| d as i64)
            .sum::<i64>()
    } else {
        -1
    }
}

fn main() {
    input! {
        n: usize,
        a: [[i32; n]; n],
    }
    let r = solve(n, &a);
    println!("{}", r);
}

