macro_rules ! chmin {($ base : expr , $ ($ cmps : expr ) ,+ $ (, ) * ) => {{let cmp_min = min ! ($ ($ cmps ) ,+ ) ; if $ base > cmp_min {$ base = cmp_min ; true } else {false } } } ; }

fn solve(a: &Vec<Vec<i64>>) -> i64 {
    let n = a.len();

    let mut dist = a.clone();
    for k in 0..n {
        for i in 0..n {
            for j in 0..n {
                chmin!(dist[i][j], dist[i][k] + dist[k][j]);
            }
        }
    }
    for i in 0..n {
        for j in 0..n {
            if a[i][j] > dist[i][j] {
                return -1;
            }
        }
    }

    let mut ret = 0;
    for i in 0..n {
        for j in i + 1..n {
            let mut dmin = std::i64::MAX;
            for k in 0..n {
                if k == i || k == j {
                    continue;
                }
                chmin!(dmin, a[i][k] + a[k][j]);
            }
            if a[i][j] < dmin {
                ret += a[i][j];
            }
        }
    }
    ret
}

